{
  "name": "MediTrack - Hospital Device Manager",
  "description": "Comprehensive medical device management system featuring inventory tracking, maintenance scheduling, contract supervision, AI-powered contract analysis, and QR code generation for device identification.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum DeviceStatus {
  ACTIVE = 'Active',
  MAINTENANCE = 'In Maintenance',
  BROKEN = 'Broken',
  RETIRED = 'Retired',
}

export enum MaintenanceType {
  PREVENTIVE = 'Preventive',
  CORRECTIVE = 'Corrective',
  CALIBRATION = 'Calibration',
}

export interface MaintenanceRecord {
  id: string;
  date: string;
  type: MaintenanceType;
  technician: string;
  description: string;
  nextScheduledDate?: string;
  completed: boolean;
}

export interface Contract {
  id: string;
  provider: string;
  contractNumber: string;
  startDate: string;
  endDate: string;
  coverageDetails: string;
  contactPhone: string;
  annualCost: number;
}

export interface DeviceFile {
  id: string;
  name: string;
  type: 'manual' | 'report' | 'image' | 'other';
  url: string; // In a real app, this is a storage URL. Here we might use placeholders.
  dateAdded: string;
}

export interface MedicalDevice {
  id: string;
  name: string;
  manufacturer: string;
  model: string;
  serialNumber: string;
  department: string;
  purchaseDate: string;
  status: DeviceStatus;
  image?: string;
  notes?: string;
  maintenanceHistory: MaintenanceRecord[];
  contracts: Contract[];
  files: DeviceFile[];
}

export type ViewState = 'DASHBOARD' | 'INVENTORY' | 'DEVICE_DETAIL' | 'ADD_DEVICE';

import { GoogleGenAI, Type } from "@google/genai";
import { Contract, MaintenanceType } from '../types';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found");
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Analyzes raw text from a service contract and extracts structured data.
 */
export const analyzeContractText = async (text: string): Promise<Partial<Contract>> => {
  try {
    const ai = getAiClient();

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Extract contract details from the following text: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            provider: { type: Type.STRING },
            contractNumber: { type: Type.STRING },
            startDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
            endDate: { type: Type.STRING, description: "YYYY-MM-DD format" },
            coverageDetails: { type: Type.STRING },
            contactPhone: { type: Type.STRING },
            annualCost: { type: Type.NUMBER },
          },
          required: ["provider", "coverageDetails"]
        }
      }
    });

    const result = response.text;
    if (!result) return {};
    return JSON.parse(result) as Partial<Contract>;
  } catch (error) {
    console.error("Error analyzing contract:", error);
    throw error;
  }
};

/**
 * Suggests a maintenance schedule based on device type.
 */
export const suggestMaintenanceSchedule = async (deviceName: string, model: string): Promise<{
  frequency: string;
  tasks: string[];
  recommendedType: string;
}> => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Suggest a maintenance schedule for a medical device. Device Name: ${deviceName}, Model: ${model}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            frequency: { type: Type.STRING, description: "e.g., Monthly, Quarterly, Annually" },
            tasks: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "List of specific maintenance tasks to perform"
            },
            recommendedType: { type: Type.STRING, description: "Preventive or Calibration" }
          }
        }
      }
    });

    const result = response.text;
    if (!result) throw new Error("No response from AI");
    return JSON.parse(result);
  } catch (error) {
    console.error("Error suggesting maintenance:", error);
    return { frequency: "Annually", tasks: ["General Inspection"], recommendedType: "Preventive" };
  }
};

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { MedicalDevice, DeviceStatus } from '../types';
import { Activity, AlertTriangle, CheckCircle, Wrench } from 'lucide-react';

interface DashboardProps {
  devices: MedicalDevice[];
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ devices }) => {

  const statusData = useMemo(() => {
    const counts = {
      [DeviceStatus.ACTIVE]: 0,
      [DeviceStatus.MAINTENANCE]: 0,
      [DeviceStatus.BROKEN]: 0,
      [DeviceStatus.RETIRED]: 0,
    };
    devices.forEach(d => counts[d.status]++);
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [devices]);

  const maintenanceUpcoming = useMemo(() => {
    const today = new Date();
    const nextMonth = new Date();
    nextMonth.setDate(today.getDate() + 30);

    return devices.filter(d => {
      const lastMaint = d.maintenanceHistory[0];
      if (!lastMaint?.nextScheduledDate) return false;
      const date = new Date(lastMaint.nextScheduledDate);
      return date >= today && date <= nextMonth;
    }).length;
  }, [devices]);

  const activeContracts = useMemo(() => {
    const today = new Date();
    return devices.reduce((acc, dev) => {
      const valid = dev.contracts.filter(c => new Date(c.endDate) > today);
      return acc + valid.length;
    }, 0);
  }, [devices]);

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Total Devices" 
          value={devices.length} 
          icon={<Activity className="w-6 h-6 text-blue-600" />} 
          color="bg-blue-50" 
        />
        <StatCard 
          title="Active Contracts" 
          value={activeContracts} 
          icon={<CheckCircle className="w-6 h-6 text-green-600" />} 
          color="bg-green-50" 
        />
        <StatCard 
          title="Upcoming Maintenance" 
          value={maintenanceUpcoming} 
          icon={<Wrench className="w-6 h-6 text-amber-600" />} 
          color="bg-amber-50" 
        />
        <StatCard 
          title="Issues Reported" 
          value={devices.filter(d => d.status === DeviceStatus.BROKEN).length} 
          icon={<AlertTriangle className="w-6 h-6 text-red-600" />} 
          color="bg-red-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Device Status Distribution</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {statusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Department Overview</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={getDepartmentData(devices)}
                layout="vertical"
                margin={{ top: 5, right: 30, left: 40, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                <XAxis type="number" />
                <YAxis dataKey="name" type="category" width={100} />
                <Tooltip />
                <Bar dataKey="count" fill="#3b82f6" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: { title: string, value: number, icon: React.ReactNode, color: string }) => (
  <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
    <div>
      <p className="text-sm font-medium text-slate-500">{title}</p>
      <p className="text-2xl font-bold text-slate-900 mt-1">{value}</p>
    </div>
    <div className={`p-3 rounded-full ${color}`}>
      {icon}
    </div>
  </div>
);

const getDepartmentData = (devices: MedicalDevice[]) => {
  const depts: Record<string, number> = {};
  devices.forEach(d => {
    depts[d.department] = (depts[d.department] || 0) + 1;
  });
  return Object.entries(depts)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);
};

export default Dashboard;

import React, { useState } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [contractText, setContractText] = useState('');

  // Maintenance Helpers
  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const suggestion = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion:\nType: ${suggestion.recommendedType}\nFreq: ${suggestion.frequency}\nTasks: ${suggestion.tasks.join(', ')}`);
    } catch (e) {
      alert("Failed to get suggestion.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Contract Helpers
  const handleAnalyzeContract = async () => {
    if (!contractText) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeContractText(contractText);
      const newContract: Contract = {
        id: crypto.randomUUID(),
        provider: result.provider || 'Unknown',
        contractNumber: result.contractNumber || 'N/A',
        startDate: result.startDate || new Date().toISOString().split('T')[0],
        endDate: result.endDate || new Date().toISOString().split('T')[0],
        coverageDetails: result.coverageDetails || '',
        contactPhone: result.contactPhone || '',
        annualCost: result.annualCost || 0
      };

      onUpdate({
        ...device,
        contracts: [...device.contracts, newContract]
      });
      setShowContractModal(false);
      setContractText('');
    } catch (e) {
      alert("Failed to analyze contract text.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  // QR Code Image URL (Using a public API for generation to simulate dynamic generation)
  // We encode a JSON payload or a deep link.
  const qrData = JSON.stringify({ id: device.id, name: device.name, serial: device.serialNumber });
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qrData)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start">
        <div>
          <button onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1">
            ← Back to Inventory
          </button>
          <h1 className="text-2xl font-bold text-slate-900">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1"><Box className="w-4 h-4" /> {device.model}</span>
            <span className="px-2 py-1 bg-slate-100 rounded-full text-xs font-medium">SN: {device.serialNumber}</span>
            <span className={`px-2 py-1 rounded-full text-xs font-medium ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button 
            onClick={() => setActiveTab('qr')}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700 transition"
           >
             <QrCode className="w-4 h-4" />
             View QR
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="Maintenance" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<FileText className="w-4 h-4" />} label="Contracts" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="QR Identity" />
      </div>

      {/* Content */}
      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-6">
              <Section title="General Information">
                <InfoRow label="Manufacturer" value={device.manufacturer} />
                <InfoRow label="Department" value={device.department} />
                <InfoRow label="Purchase Date" value={device.purchaseDate} />
                <InfoRow label="Location" value="Main Hospital, 3rd Floor" />
              </Section>

              <Section title="Notes">
                <p className="text-slate-600 text-sm leading-relaxed">
                  {device.notes || "No additional notes provided."}
                </p>
              </Section>
            </div>

            <div className="space-y-6">
               <Section title="Files & Manuals">
                 {device.files.length === 0 ? (
                   <div className="text-slate-400 text-sm italic py-4">No files attached.</div>
                 ) : (
                   <ul className="space-y-2">
                     {device.files.map(f => (
                       <li key={f.id} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-lg">
                         <div className="flex items-center gap-3">
                           <FileText className="w-5 h-5 text-blue-500" />
                           <div>
                             <p className="text-sm font-medium text-slate-800">{f.name}</p>
                             <p className="text-xs text-slate-500">{f.type.toUpperCase()} • {f.dateAdded}</p>
                           </div>
                         </div>
                         <button className="text-slate-400 hover:text-blue-600">
                           <Download className="w-4 h-4" />
                         </button>
                       </li>
                     ))}
                   </ul>
                 )}
                 <button className="mt-4 w-full py-2 border-2 border-dashed border-slate-300 rounded-lg text-slate-500 hover:border-blue-500 hover:text-blue-500 text-sm transition font-medium">
                   + Upload Document
                 </button>
               </Section>
            </div>
          </div>
        )}

        {activeTab === 'maintenance' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
               <h3 className="text-lg font-semibold text-slate-800">Maintenance History</h3>
               <button 
                 onClick={handleSuggestMaintenance}
                 disabled={isAnalyzing}
                 className="flex items-center gap-2 px-3 py-1.5 bg-violet-100 text-violet-700 rounded-lg text-sm font-medium hover:bg-violet-200"
               >
                 <Wand2 className="w-4 h-4" />
                 {isAnalyzing ? "Analyzing..." : "AI Suggest Schedule"}
               </button>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-4 rounded-lg border border-slate-200 flex flex-col md:flex-row gap-4 md:items-center justify-between">
                  <div className="flex gap-4">
                    <div className={`w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-100 text-green-600' : 'bg-amber-100 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-6 h-6" /> : <Activity className="w-6 h-6" />}
                    </div>
                    <div>
                      <h4 className="font-semibold text-slate-900">{record.type}</h4>
                      <p className="text-sm text-slate-500">{record.description}</p>
                      <p className="text-xs text-slate-400 mt-1">Tech: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-medium text-slate-900">{record.date}</p>
                    {record.nextScheduledDate && (
                      <p className="text-xs text-blue-600 mt-1">Next: {record.nextScheduledDate}</p>
                    )}
                  </div>
                </div>
              ))}
              {device.maintenanceHistory.length === 0 && (
                <div className="text-center py-10 text-slate-500">No maintenance records found.</div>
              )}
            </div>
            <button className="flex items-center gap-2 text-blue-600 hover:text-blue-700 font-medium text-sm">
              <Plus className="w-4 h-4" /> Schedule New Maintenance
            </button>
          </div>
        )}

        {activeTab === 'contracts' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-semibold text-slate-800">Service Contracts</h3>
              <button 
                onClick={() => setShowContractModal(true)}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
              >
                <Plus className="w-4 h-4" /> Add Contract
              </button>
            </div>

            <div className="grid grid-cols-1 gap-4">
              {device.contracts.map(contract => (
                <div key={contract.id} className="bg-white p-5 rounded-lg border border-slate-200 shadow-sm hover:shadow-md transition">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                       <h4 className="font-bold text-slate-800 text-lg">{contract.provider}</h4>
                       <span className="text-xs font-mono bg-slate-100 px-2 py-1 rounded text-slate-600">#{contract.contractNumber}</span>
                    </div>
                    <div className="text-right">
                       <p className="text-sm text-slate-500">Expires</p>
                       <p className="font-semibold text-slate-900">{contract.endDate}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4 text-sm mb-4">
                    <div>
                      <span className="text-slate-500 block">Coverage</span>
                      <span className="text-slate-800">{contract.coverageDetails}</span>
                    </div>
                    <div>
                      <span className="text-slate-500 block">Contact</span>
                      <span className="text-slate-800">{contract.contactPhone}</span>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                     <span className="text-sm font-medium text-slate-600">Annual Cost: ${contract.annualCost.toLocaleString()}</span>
                     <button className="text-red-500 hover:text-red-600 text-sm flex items-center gap-1">
                       <Trash2 className="w-3 h-3" /> Remove
                     </button>
                  </div>
                </div>
              ))}
            </div>

            {showContractModal && (
              <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-lg font-bold">Add Service Contract</h3>
                    <button onClick={() => setShowContractModal(false)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="space-y-4">
                    <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                      <p className="text-sm text-blue-800 font-medium mb-2 flex items-center gap-2">
                        <Wand2 className="w-4 h-4" /> AI Assistant
                      </p>
                      <p className="text-xs text-blue-600 mb-3">Paste the raw text from a PDF or email contract, and AI will extract the details.</p>
                      <textarea 
                        className="w-full h-32 p-3 text-sm border border-blue-200 rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
                        placeholder="Paste contract text here..."
                        value={contractText}
                        onChange={(e) => setContractText(e.target.value)}
                      />
                      <button 
                        onClick={handleAnalyzeContract}
                        disabled={isAnalyzing || !contractText}
                        className="mt-2 w-full py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 disabled:opacity-50"
                      >
                        {isAnalyzing ? "Extracting Data..." : "Auto-Fill with AI"}
                      </button>
                    </div>
                    <div className="relative">
                      <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                      <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-slate-500">Or enter manually</span></div>
                    </div>
                    {/* Simplified manual inputs for demo */}
                    <input type="text" placeholder="Provider Name" className="w-full p-2 border rounded text-sm" />
                    <button onClick={() => setShowContractModal(false)} className="w-full py-2 bg-slate-100 text-slate-700 rounded-md text-sm hover:bg-slate-200">Cancel</button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'qr' && (
          <div className="flex flex-col items-center justify-center h-full py-10 space-y-6 animate-fade-in">
            <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-100 flex flex-col items-center">
              <h3 className="text-xl font-bold text-slate-800 mb-6">{device.name}</h3>
              <div className="border-4 border-slate-900 p-2 rounded-lg">
                <img src={qrCodeUrl} alt="Device QR Code" className="w-48 h-48 object-contain" />
              </div>
              <p className="mt-6 text-sm text-slate-500 text-center max-w-xs">
                Scan this code to access full device history, maintenance logs, and manuals instantly.
              </p>
              <div className="mt-6 flex gap-3">
                 <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium">
                   <Download className="w-4 h-4" /> Save Image
                 </button>
                 <button 
                  onClick={() => window.open(qrCodeUrl, '_blank')}
                  className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 text-sm font-medium"
                 >
                   <ExternalLink className="w-4 h-4" /> Open Link
                 </button>
              </div>
            </div>
            <div className="text-center text-xs text-slate-400">
              ID: {device.id}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-4 py-4 text-sm font-medium border-b-2 transition-colors ${
      active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-700 hover:border-slate-300'
    }`}
  >
