import React, { useRef } from 'react';
import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, CheckCircle, Save } from 'lucide-react';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(devices, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `meditrack_backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (Array.isArray(jsonData)) {
          // Basic validation to ensure it looks like our data
          const isValid = jsonData.every(d => d.id && d.name && d.status);
          if (isValid) {
            if (window.confirm(`Found ${jsonData.length} devices in backup. This will overwrite your current data. Continue?`)) {
              onImport(jsonData);
              alert('Data imported successfully!');
            }
          } else {
            alert('Invalid backup file format.');
          }
        }
      } catch (error) {
        alert('Error reading backup file.');
        console.error(error);
      }
    };
    reader.readAsText(file);
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
      <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-3 bg-blue-100 rounded-lg">
            <Database className="w-6 h-6 text-blue-600" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Data Management</h2>
            <p className="text-sm text-slate-500">Manage your application data storage and portability</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Export Section */}
          <div className="p-6 border border-slate-200 rounded-xl bg-slate-50 hover:border-blue-200 transition">
            <h3 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
              <Download className="w-4 h-4 text-blue-600" /> Export Data
            </h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">
              Download a backup of all devices, maintenance history, and contracts. 
              Use this file to move your data to another computer.
            </p>
            <button 
              onClick={handleExport}
              className="w-full py-2.5 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-100 hover:text-slate-900 transition flex items-center justify-center gap-2"
            >
              <Save className="w-4 h-4" /> Download Backup
            </button>
          </div>

          {/* Import Section */}
          <div className="p-6 border border-slate-200 rounded-xl bg-slate-50 hover:border-blue-200 transition">
            <h3 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
              <Upload className="w-4 h-4 text-green-600" /> Import Data
            </h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">
              Restore data from a backup file. <span className="font-bold text-amber-600">Warning:</span> This will completely replace your current inventory.
            </p>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleImport} 
              accept=".json" 
              className="hidden" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full py-2.5 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2"
            >
              <Upload className="w-4 h-4" /> Select Backup File
            </button>
          </div>
        </div>
      </div>

      <div className="bg-amber-50 p-6 rounded-xl border border-amber-100 flex items-start gap-4">
        <AlertTriangle className="w-6 h-6 text-amber-600 shrink-0 mt-1" />
        <div>
          <h3 className="font-bold text-amber-900">About Data Persistence</h3>
          <p className="text-sm text-amber-800 mt-1 leading-relaxed">
            This application currently runs in your browser's local storage ("Offline Mode"). 
            To access your data on a different device, you must <strong>Export</strong> it from here and <strong>Import</strong> it on the new device. 
            Real-time cloud synchronization would require a dedicated backend server.
          </p>
        </div>
      </div>
    </div>
  );
};

