import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, Cloud, CheckCircle, Save, Link, LogOut } from 'lucide-react';
import { isSupabaseConfigured, getSupabaseConfig, saveSupabaseConfig, clearSupabaseConfig } from '../services/supabase';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [config, setConfig] = useState(getSupabaseConfig());
  const [inputUrl, setInputUrl] = useState(config.url || '');
  const [inputKey, setInputKey] = useState(config.key || '');
  const [showKey, setShowKey] = useState(false);

  useEffect(() => {
    const currentConfig = getSupabaseConfig();
    setConfig(currentConfig);
    setInputUrl(currentConfig.url || '');
    // Don't auto-fill key if it's from env for security visual, but fine for local storage
    if (!currentConfig.isEnv) {
      setInputKey(currentConfig.key || '');
    }
  }, []);

  const handleSaveCloudConfig = () => {
    if (!inputUrl || !inputKey) {
      alert("Please provide both the Supabase URL and Anon Key.");
      return;
    }
    saveSupabaseConfig(inputUrl, inputKey);
  };

  const handleDisconnectCloud = () => {
    if (window.confirm("Are you sure you want to disconnect? You will switch back to offline mode.")) {
      clearSupabaseConfig();
    }
  };

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(devices, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `meditrack_backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (Array.isArray(jsonData)) {
          const isValid = jsonData.every(d => d.id && d.name && d.status);
          if (isValid) {
            if (window.confirm(`Found ${jsonData.length} devices in backup. This will overwrite your current local data state. Continue?`)) {
              onImport(jsonData);
              alert('Data imported successfully!');
            }
          } else {
            alert('Invalid backup file format.');
          }
        }
      } catch (error) {
        alert('Error reading backup file.');
        console.error(error);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in pb-10">

      {/* Cloud Connection Card */}
      <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-3 mb-6">
          <div className={`p-3 rounded-lg ${isSupabaseConfigured ? 'bg-green-100' : 'bg-slate-100'}`}>
            {isSupabaseConfigured ? <Cloud className="w-6 h-6 text-green-600" /> : <Cloud className="w-6 h-6 text-slate-500" />}
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Cloud Connection</h2>
            <p className="text-sm text-slate-500">
              Connect to your Supabase database to sync data across devices.
            </p>
          </div>
        </div>

        <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
          {config.isEnv ? (
             <div className="flex items-center gap-3 text-green-700 bg-green-50 p-4 rounded-lg border border-green-200">
               <CheckCircle className="w-5 h-5" />
               <span className="font-medium">Connected via Environment Variables</span>
             </div>
          ) : (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Project URL</label>
                <input 
                  type="text" 
                  value={inputUrl}
                  onChange={(e) => setInputUrl(e.target.value)}
                  placeholder="https://your-project.supabase.co"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm text-slate-600 font-mono"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">API Key (anon / public)</label>
                <div className="relative">
                  <input 
                    type={showKey ? "text" : "password"}
                    value={inputKey}
                    onChange={(e) => setInputKey(e.target.value)}
                    placeholder="eyJh..."
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm text-slate-600 font-mono pr-20"
                  />
                  <button 
                    onClick={() => setShowKey(!showKey)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-slate-400 hover:text-slate-600 px-2"
                  >
                    {showKey ? "HIDE" : "SHOW"}
                  </button>
                </div>
              </div>

              <div className="pt-2 flex gap-3">
                {!isSupabaseConfigured ? (
                  <button 
                    onClick={handleSaveCloudConfig}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition flex items-center gap-2"
                  >
                    <Link className="w-4 h-4" /> Connect
                  </button>
                ) : (
                   <>
                    <button 
                      onClick={handleSaveCloudConfig}
                      className="px-4 py-2 bg-slate-800 text-white rounded-lg text-sm font-medium hover:bg-slate-900 transition flex items-center gap-2"
                    >
                      <Save className="w-4 h-4" /> Update Settings
                    </button>
                    <button 
                      onClick={handleDisconnectCloud}
                      className="px-4 py-2 bg-red-100 text-red-700 border border-red-200 rounded-lg text-sm font-medium hover:bg-red-200 transition flex items-center gap-2"
                    >
                      <LogOut className="w-4 h-4" /> Disconnect
                    </button>
                   </>
                )}
              </div>

              {!isSupabaseConfigured && (
                 <p className="text-xs text-slate-500 mt-2">
                   Don't have a project? <a href="https://supabase.com" target="_blank" className="text-blue-600 hover:underline">Create one for free</a>.
                 </p>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Manual Data Management */}
      <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-3 rounded-lg bg-blue-100">
            <Database className="w-6 h-6 text-blue-600" />
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-900">Backup & Restore</h2>
            <p className="text-sm text-slate-500">
              Manually export or import your data file (JSON).
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="p-6 border border-slate-200 rounded-xl bg-slate-50 hover:border-blue-200 transition">
            <h3 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
              <Download className="w-4 h-4 text-blue-600" /> Export Data
            </h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">
              Download a backup of all devices, maintenance history, and contracts. 
            </p>
            <button 
              onClick={handleExport}
              className="w-full py-2.5 bg-white border border-slate-300 text-slate-700 font-medium rounded-lg hover:bg-slate-100 hover:text-slate-900 transition flex items-center justify-center gap-2"
            >
              <Save className="w-4 h-4" /> Download Backup
            </button>
          </div>

          <div className="p-6 border border-slate-200 rounded-xl bg-slate-50 hover:border-blue-200 transition">
            <h3 className="font-semibold text-slate-900 mb-2 flex items-center gap-2">
              <Upload className="w-4 h-4 text-green-600" /> Import Data
            </h3>
            <p className="text-sm text-slate-600 mb-6 leading-relaxed">
              Restore data from a JSON backup file.
            </p>
            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleImport} 
              accept=".json" 
              className="hidden" 
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full py-2.5 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2"
            >
              <Upload className="w-4 h-4" /> Select Backup File
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import { createClient } from '@supabase/supabase-js';

// 1. Environment Variables (Highest Priority)
const envUrl = process.env.SUPABASE_URL;
const envKey = process.env.SUPABASE_KEY;

// 2. Local Storage (User Configured via Settings UI)
const storedUrl = typeof window !== 'undefined' ? localStorage.getItem('meditrack_supabase_url') : null;
const storedKey = typeof window !== 'undefined' ? localStorage.getItem('meditrack_supabase_key') : null;
const isDisabled = typeof window !== 'undefined' ? localStorage.getItem('meditrack_supabase_disabled') === 'true' : false;

// 3. Defaults (Hardcoded for this specific deployment)
const DEFAULT_URL = "https://cevixwidnxpjnctljfzs.supabase.co";
const DEFAULT_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImNldml4d2lkbnhwam5jdGxqZnpzIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjU3MzU1NTUsImV4cCI6MjA4MTMxMTU1NX0.22qlURNa9Hmwq68BPvWdihZ8KWgEDlLmuP_j_EXibp8";

const finalUrl = envUrl || storedUrl || DEFAULT_URL;
const finalKey = envKey || storedKey || DEFAULT_KEY;

// Create client only if not explicitly disabled and keys are present
export const supabase = (!isDisabled && finalUrl && finalKey) 
  ? createClient(finalUrl, finalKey) 
  : null;

export const isSupabaseConfigured = !!supabase;

export const getSupabaseConfig = () => ({
  url: finalUrl,
  key: finalKey,
  isEnv: !!(envUrl && envKey), // filtered boolean to know if it's locked by env
  isDisabled
});

export const saveSupabaseConfig = (url: string, key: string) => {
  localStorage.setItem('meditrack_supabase_url', url);
  localStorage.setItem('meditrack_supabase_key', key);
  localStorage.removeItem('meditrack_supabase_disabled'); // Re-enable if it was disabled
  window.location.reload(); // Reload to re-initialize the supabase client singleton
};

export const clearSupabaseConfig = () => {
  localStorage.removeItem('meditrack_supabase_url');
  localStorage.removeItem('meditrack_supabase_key');
  // We explicitly disable it so it doesn't fall back to the hardcoded DEFAULT_KEY immediately
  localStorage.setItem('meditrack_supabase_disabled', 'true');
  window.location.reload();
};

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [contractText, setContractText] = useState('');
  const [editingContractId, setEditingContractId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadingFile, setUploadingFile] = useState(false);

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  const initialContractForm = {
    name: '',
    provider: '',
    contractNumber: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    annualCost: '',
    coverageDetails: '',
    contactPhone: ''
  };

  const [manualContractForm, setManualContractForm] = useState(initialContractForm);

  // Maintenance Helpers
  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const suggestion = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion:\nType: ${suggestion.recommendedType}\nFreq: ${suggestion.frequency}\nTasks: ${suggestion.tasks.join(', ')}`);
    } catch (e) {
      alert("Failed to get suggestion.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSaveMaintenance = () => {
    if (!maintenanceForm.technician || !maintenanceForm.description) {
      alert("Please fill in Technician and Description fields");
      return;
    }

    const newRecord: MaintenanceRecord = {
      id: crypto.randomUUID(),
      date: maintenanceForm.date || new Date().toISOString().split('T')[0],
      type: maintenanceForm.type || MaintenanceType.PREVENTIVE,
      technician: maintenanceForm.technician,
      description: maintenanceForm.description,
      completed: maintenanceForm.completed || false,
      nextScheduledDate: maintenanceForm.nextScheduledDate || undefined
    };

    const updatedHistory = [newRecord, ...device.maintenanceHistory];

    // Optional: Update device status if maintenance is active (not completed)
    let updatedStatus = device.status;
    if (!newRecord.completed && newRecord.date <= new Date().toISOString().split('T')[0]) {
        updatedStatus = DeviceStatus.MAINTENANCE;
    } else if (newRecord.completed && device.status === DeviceStatus.MAINTENANCE) {
        updatedStatus = DeviceStatus.ACTIVE;
    }

    onUpdate({
      ...device,
      status: updatedStatus,
      maintenanceHistory: updatedHistory
    });

    setShowMaintenanceModal(false);
    setMaintenanceForm({
      date: new Date().toISOString().split('T')[0],
      type: MaintenanceType.PREVENTIVE,
      technician: '',
      description: '',
      completed: false,
      nextScheduledDate: ''
    });
  };

  // Contract Helpers
  const handleAnalyzeContract = async () => {
    if (!contractText) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeContractText(contractText);
      const newContract: Contract = {
        id: crypto.randomUUID(),
        provider: result.provider || 'Unknown',
        contractNumber: result.contractNumber || 'N/A',
        startDate: result.startDate || new Date().toISOString().split('T')[0],
        endDate: result.endDate || new Date().toISOString().split('T')[0],
        coverageDetails: result.coverageDetails || '',
        contactPhone: result.contactPhone || '',
        annualCost: result.annualCost || 0
      };

      onUpdate({
        ...device,
        contracts: [...device.contracts, newContract]
      });
      setShowContractModal(false);
      setContractText('');
    } catch (e) {
      alert("Failed to analyze contract text.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleEditContract = (contract: Contract) => {
    setEditingContractId(contract.id);
    setManualContractForm({
      name: contract.name || '',
      provider: contract.provider,
      contractNumber: contract.contractNumber,
      startDate: contract.startDate,
      endDate: contract.endDate,
      annualCost: contract.annualCost.toString(),
      coverageDetails: contract.coverageDetails,
      contactPhone: contract.contactPhone
    });
    setShowContractModal(true);
  };

  const handleSaveManualContract = () => {
    if (!manualContractForm.provider || !manualContractForm.startDate || !manualContractForm.endDate) {
      alert("Please fill in Provider, Start Date and End Date.");
      return;
    }

    if (editingContractId) {
      // Update existing contract
      const updatedContracts = device.contracts.map(c => 
        c.id === editingContractId 
        ? {
            ...c,
            name: manualContractForm.name,
            provider: manualContractForm.provider,
            contractNumber: manualContractForm.contractNumber || 'Manual',
            startDate: manualContractForm.startDate,
            endDate: manualContractForm.endDate,
            coverageDetails: manualContractForm.coverageDetails || 'Standard Coverage',
            contactPhone: manualContractForm.contactPhone || '',
            annualCost: Number(manualContractForm.annualCost) || 0
          }
        : c
      );
      onUpdate({ ...device, contracts: updatedContracts });
    } else {
      // Create new contract
      const newContract: Contract = {
        id: crypto.randomUUID(),
        name: manualContractForm.name,
        provider: manualContractForm.provider,
        contractNumber: manualContractForm.contractNumber || 'Manual',
        startDate: manualContractForm.startDate,
        endDate: manualContractForm.endDate,
        coverageDetails: manualContractForm.coverageDetails || 'Standard Coverage',
        contactPhone: manualContractForm.contactPhone || '',
        annualCost: Number(manualContractForm.annualCost) || 0
      };
      onUpdate({ ...device, contracts: [...device.contracts, newContract] });
    }

    closeContractModal();
  };

  const closeContractModal = () => {
    setShowContractModal(false);
    setEditingContractId(null);
    setManualContractForm(initialContractForm);
    setContractText('');
  };

  const handleDeleteContract = (contractId: string) => {
    onUpdate({
      ...device,
      contracts: device.contracts.filter(c => c.id !== contractId)
    });
  };

  // File Upload Helpers
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      // Limit file size to 1MB for database storage to avoid issues
      if (file.size > 1024 * 1024) {
        alert("File is too large for database storage. Please select a file under 1MB.");
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
      }

      setUploadingFile(true);

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;

        // Determine type based on extension
        let type: DeviceFile['type'] = 'other';
        const ext = file.name.split('.').pop()?.toLowerCase();
        if (['pdf', 'doc', 'docx'].includes(ext || '')) type = 'manual';
        else if (['jpg', 'jpeg', 'png', 'webp'].includes(ext || '')) type = 'image';
        else if (['csv', 'xls', 'xlsx'].includes(ext || '')) type = 'report';

        const newFile: DeviceFile = {
          id: crypto.randomUUID(),
          name: file.name,
          type: type,
          url: base64String, // Store as Base64 to sync across DB
          dateAdded: new Date().toISOString().split('T')[0]
        };

        onUpdate({
          ...device,
          files: [...device.files, newFile]
        });

        setUploadingFile(false);
        // Reset input
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  // Safe File Opening
  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') {
      alert('This is a mock file. Upload a real file to test viewing.');
      return;
    }

    // Convert base64 to blob to open in new tab (bypassing chrome security on data urls)
    try {
       const byteString = atob(file.url.split(',')[1]);
       const mimeString = file.url.split(',')[0].split(':')[1].split(';')[0];
       const ab = new ArrayBuffer(byteString.length);
       const ia = new Uint8Array(ab);
       for (let i = 0; i < byteString.length; i++) {
         ia[i] = byteString.charCodeAt(i);
       }
       const blob = new Blob([ab], { type: mimeString });
       const blobUrl = URL.createObjectURL(blob);
       window.open(blobUrl, '_blank');
    } catch(err) {
       console.error("Error opening file:", err);
       // Fallback to direct window open if blob fails
       const win = window.open();
       if (win) {
         win.document.write('<iframe src="' + file.url + '" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>');
       }
    }
  };

  // QR Code Image URL
  // Construct a URL that deep links to this specific device
  const appBaseUrl = window.location.origin + window.location.pathname;
  const qrData = `${appBaseUrl}?deviceId=${device.id}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qrData)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start">
        <div>
          <button onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1">
            ← Back to Inventory
          </button>
          <h1 className="text-2xl font-bold text-slate-900">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1"><Box className="w-4 h-4" /> {device.model}</span>
            <span className="px-2 py-1 bg-slate-100 rounded-full text-xs font-medium">SN: {device.serialNumber}</span>
            <span className={`px-2 py-1 rounded-full text-xs font-medium ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={onDelete}
             className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-100 transition text-sm font-medium"
           >
             <Trash2 className="w-4 h-4" />
             Delete Device
           </button>
           <button 
            onClick={() => setActiveTab('qr')}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700 transition text-sm font-medium"
           >
             <QrCode className="w-4 h-4" />
             View QR
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="Maintenance" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<FileText className="w-4 h-4" />} label="Contracts" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="QR Identity" />
      </div>

      {/* Content */}
      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-6">
              <Section title="General Information">
                <InfoRow label="Manufacturer" value={device.manufacturer} />
                <InfoRow label="Department" value={device.department} />
                <InfoRow label="Purchase Date" value={device.purchaseDate} />
                <InfoRow label="Location" value="Main Hospital, 3rd Floor" />
              </Section>

              <Section title="Notes">
                <p className="text-slate-600 text-sm leading-relaxed">
                  {device.notes || "No additional notes provided."}
                </p>
              </Section>
            </div>

            <div className="space-y-6">
               <Section title="Files & Manuals">
                 {device.files.length === 0 ? (
                   <div className="text-slate-400 text-sm italic py-4">No files attached.</div>
                 ) : (
                   <ul className="space-y-2">
                     {device.files.map(f => (
                       <li key={f.id} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-lg group hover:border-blue-300 transition-colors">
                         <div className="flex items-center gap-3">
                           <FileText className="w-5 h-5 text-blue-500" />
                           <div>
                             <a 
                               href={f.url} 
                               className="text-sm font-medium text-slate-800 hover:text-blue-600 hover:underline cursor-pointer block"
