      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };
    onSave(newDevice);
  };

  const handleProcessBulk = async () => {
    if (!bulkText.trim()) return;
    setIsProcessing(true);

    try {
      const apiKey = (window.process as any).env.API_KEY;
      if (!apiKey) throw new Error("API Key not found");

      const ai = new GoogleGenAI({ apiKey });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Parse the following messy medical device list into a structured JSON array of objects. 
        Each object must have: name, manufacturer, model, serialNumber, department, purchaseDate (YYYY-MM-DD), and status (one of: Active, In Maintenance, Broken, Retired).
        If data is missing, make a reasonable clinical engineering guess or use "Unknown".

        Data:
        "${bulkText}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                manufacturer: { type: Type.STRING },
                model: { type: Type.STRING },
                serialNumber: { type: Type.STRING },
                department: { type: Type.STRING },
                purchaseDate: { type: Type.STRING },
                status: { type: Type.STRING },
                notes: { type: Type.STRING }
