    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);

  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const getLocalData = (): MedicalDevice[] => {
    try {
      const savedData = localStorage.getItem('meditrack_devices');
      return savedData ? JSON.parse(savedData) : MOCK_DEVICES;
    } catch (e) {
      return MOCK_DEVICES;
    }
  };

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];

      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*');
          if (error) throw error;
          if (data) loadedDevices = data as MedicalDevice[];
        } catch (error) {
          console.error("Supabase load error:", error);
          loadedDevices = getLocalData();
        }
      } else {
        loadedDevices = getLocalData();
      }

      setDevices(loadedDevices);

      const params = new URLSearchParams(window.location.search);
      const deepLinkIds = params.get('deviceId');
      if (deepLinkIds) {
          const targetDevice = loadedDevices.find(d => d.id === deepLinkIds);
          if (targetDevice) {
              setSelectedDevice(targetDevice);
              setView('DEVICE_DETAIL');
          }
      }

      setIsLoading(false);
    };

    loadData();
  }, []);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    setDevices(newDevices);
    localStorage.setItem('meditrack_devices', JSON.stringify(newDevices));

    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').delete().eq('id', changedDevice.id);
        } else if (action === 'INSERT' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').insert([changedDevice]);
        } else if (action === 'UPDATE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        } else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) {
          await supabase.from('devices').insert(changedDevice);
        }
      } catch (err) {
        console.error("Failed to sync with cloud:", err);
      }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');

    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      setDevices(importedDevices);
      localStorage.setItem('meditrack_devices', JSON.stringify(importedDevices));
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button 
      onClick={() => { setView(targetView); setSidebarOpen(false); }}
      className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${
        view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'
      }`}
    >
      {icon}
      {label}
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />}

      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>

          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg">
              <QrCode className="w-5 h-5" /> Scan QR Code
            </button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }}
               className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
              <SettingsIcon className="w-5 h-5" /> Settings
            </button>
          </nav>

          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-xs text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900">
                  <Cloud className="w-3 h-3" /> <span>Cloud Connected</span>
                </div>
              ) : (
                <div className="flex items-center gap-2 text-xs text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900">
                  <CloudOff className="w-3 h-3" /> <span>Offline Mode</span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs">JD</div>
              <div>
                <p className="text-sm font-medium">Jane Doe</p>
                <p className="text-xs text-slate-500">Clinical Engineer</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sm font-medium text-blue-600">Syncing with cloud...</p>
            </div>
          </div>
        )}

        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-lg font-semibold text-slate-800">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Device Inventory'}
               {view === 'PLANNER' && 'Maintenance Planner'}
               {view === 'ADD_DEVICE' && 'Register Device'}
               {view === 'DEVICE_DETAIL' && 'Device Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && (
              <DeviceList 
                devices={devices} 
                onSelectDevice={handleSelectDevice} 
                onDelete={handleDeleteDevice}
                onAddDevice={() => setView('ADD_DEVICE')} 
              />
            )}
            {view === 'PLANNER' && (
              <MaintenancePlanner 
                devices={devices} 
                onApplyPlan={handleApplyGlobalPlan} 
              />
            )}
            {view === 'ADD_DEVICE' && (
              <AddDeviceForm 
                onSave={handleAddDevice}
                onBulkSave={handleBulkAddDevices}
                onCancel={() => setView('INVENTORY')}
              />
            )}
            {view === 'DEVICE_DETAIL' && selectedDevice && (
              <DeviceDetail 
                device={selectedDevice} 
                onBack={() => setView('INVENTORY')}
                onUpdate={handleUpdateDevice}
                onDelete={() => handleDeleteDevice(selectedDevice.id)}
              />
            )}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

export enum DeviceStatus {
  ACTIVE = 'Active',
  MAINTENANCE = 'In Maintenance',
  BROKEN = 'Broken',
  RETIRED = 'Retired',
}

export enum MaintenanceType {
  PREVENTIVE = 'Preventive',
  CORRECTIVE = 'Corrective',
  CALIBRATION = 'Calibration',
}

export interface MaintenanceRecord {
  id: string;
  date: string;
  type: MaintenanceType;
  technician: string;
  description: string;
  nextScheduledDate?: string;
  completed: boolean;
}

export interface Contract {
  id: string;
  name?: string;
  provider: string;
  contractNumber: string;
  startDate: string;
  endDate: string;
  coverageDetails: string;
  contactPhone: string;
  annualCost: number;
}

export interface DeviceFile {
  id: string;
  name: string;
  type: 'manual' | 'report' | 'image' | 'other';
  url: string; 
  dateAdded: string;
}

export interface DeviceComponent {
  id: string;
  name: string;
  serialNumber: string;
  status: DeviceStatus;
}

export interface MedicalDevice {
  id: string;
  name: string;
  manufacturer: string;
  model: string;
  serialNumber: string;
  department: string;
  purchaseDate: string;
  status: DeviceStatus;
  image?: string;
  notes?: string;
  maintenanceHistory: MaintenanceRecord[];
  contracts: Contract[];
  files: DeviceFile[];
  components?: DeviceComponent[];
}

export type ViewState = 'DASHBOARD' | 'INVENTORY' | 'DEVICE_DETAIL' | 'ADD_DEVICE' | 'SETTINGS' | 'PLANNER';

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [contractText, setContractText] = useState('');
  const [editingContractId, setEditingContractId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [uploadingFile, setUploadingFile] = useState(false);

  // Component Form State
  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  const initialContractForm = {
    name: '',
    provider: '',
    contractNumber: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    annualCost: '',
    coverageDetails: '',
    contactPhone: ''
  };

  const [manualContractForm, setManualContractForm] = useState(initialContractForm);

  // Component Helpers
  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: crypto.randomUUID(),
      ...newComponent
    };
    const updatedComponents = [...(device.components || []), component];
    onUpdate({ ...device, components: updatedComponents });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    const updatedComponents = (device.components || []).filter(c => c.id !== id);
    onUpdate({ ...device, components: updatedComponents });
  };

  // Image Upload Helper
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  // Maintenance Helpers
  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const suggestion = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion:\nType: ${suggestion.recommendedType}\nFreq: ${suggestion.frequency}\nTasks: ${suggestion.tasks.join(', ')}`);
    } catch (e) {
      alert("Failed to get suggestion.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSaveMaintenance = () => {
    if (!maintenanceForm.technician || !maintenanceForm.description) {
      alert("Please fill in Technician and Description fields");
      return;
    }

    const newRecord: MaintenanceRecord = {
      id: crypto.randomUUID(),
      date: maintenanceForm.date || new Date().toISOString().split('T')[0],
      type: maintenanceForm.type || MaintenanceType.PREVENTIVE,
      technician: maintenanceForm.technician,
      description: maintenanceForm.description,
      completed: maintenanceForm.completed || false,
      nextScheduledDate: maintenanceForm.nextScheduledDate || undefined
    };

    const updatedHistory = [newRecord, ...device.maintenanceHistory];

    let updatedStatus = device.status;
    if (!newRecord.completed && newRecord.date <= new Date().toISOString().split('T')[0]) {
        updatedStatus = DeviceStatus.MAINTENANCE;
    } else if (newRecord.completed && device.status === DeviceStatus.MAINTENANCE) {
        updatedStatus = DeviceStatus.ACTIVE;
    }

    onUpdate({
      ...device,
      status: updatedStatus,
      maintenanceHistory: updatedHistory
    });

    setShowMaintenanceModal(false);
    setMaintenanceForm({
      date: new Date().toISOString().split('T')[0],
      type: MaintenanceType.PREVENTIVE,
      technician: '',
      description: '',
      completed: false,
      nextScheduledDate: ''
    });
  };

  // Contract Helpers
  const handleAnalyzeContract = async () => {
    if (!contractText) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeContractText(contractText);
      const newContract: Contract = {
        id: crypto.randomUUID(),
        provider: result.provider || 'Unknown',
        contractNumber: result.contractNumber || 'N/A',
        startDate: result.startDate || new Date().toISOString().split('T')[0],
        endDate: result.endDate || new Date().toISOString().split('T')[0],
        coverageDetails: result.coverageDetails || '',
        contactPhone: result.contactPhone || '',
        annualCost: result.annualCost || 0
      };

      onUpdate({
        ...device,
        contracts: [...device.contracts, newContract]
      });
      setShowContractModal(false);
      setContractText('');
    } catch (e) {
      alert("Failed to analyze contract text.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleEditContract = (contract: Contract) => {
    setEditingContractId(contract.id);
    setManualContractForm({
      name: contract.name || '',
      provider: contract.provider,
      contractNumber: contract.contractNumber,
      startDate: contract.startDate,
      endDate: contract.endDate,
      annualCost: contract.annualCost.toString(),
      coverageDetails: contract.coverageDetails,
      contactPhone: contract.contactPhone
    });
    setShowContractModal(true);
  };

  const handleSaveManualContract = () => {
    if (!manualContractForm.provider || !manualContractForm.startDate || !manualContractForm.endDate) {
      alert("Please fill in Provider, Start Date and End Date.");
      return;
    }

    if (editingContractId) {
      const updatedContracts = device.contracts.map(c => 
        c.id === editingContractId 
        ? {
            ...c,
            name: manualContractForm.name,
            provider: manualContractForm.provider,
            contractNumber: manualContractForm.contractNumber || 'Manual',
            startDate: manualContractForm.startDate,
            endDate: manualContractForm.endDate,
            coverageDetails: manualContractForm.coverageDetails || 'Standard Coverage',
            contactPhone: manualContractForm.contactPhone || '',
            annualCost: Number(manualContractForm.annualCost) || 0
          }
        : c
      );
      onUpdate({ ...device, contracts: updatedContracts });
    } else {
      const newContract: Contract = {
        id: crypto.randomUUID(),
        name: manualContractForm.name,
        provider: manualContractForm.provider,
        contractNumber: manualContractForm.contractNumber || 'Manual',
        startDate: manualContractForm.startDate,
        endDate: manualContractForm.endDate,
        coverageDetails: manualContractForm.coverageDetails || 'Standard Coverage',
        contactPhone: manualContractForm.contactPhone || '',
        annualCost: Number(manualContractForm.annualCost) || 0
      };
      onUpdate({ ...device, contracts: [...device.contracts, newContract] });
    }

    closeContractModal();
  };

  const closeContractModal = () => {
    setShowContractModal(false);
    setEditingContractId(null);
    setManualContractForm(initialContractForm);
    setContractText('');
  };

  const handleDeleteContract = (contractId: string) => {
    onUpdate({
      ...device,
      contracts: device.contracts.filter(c => c.id !== contractId)
    });
  };

  // File Upload Helpers
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (file.size > 1024 * 1024) {
        alert("File is too large for database storage. Please select a file under 1MB.");
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
      }

      setUploadingFile(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        let type: DeviceFile['type'] = 'other';
        const ext = file.name.split('.').pop()?.toLowerCase();
        if (['pdf', 'doc', 'docx'].includes(ext || '')) type = 'manual';
        else if (['jpg', 'jpeg', 'png', 'webp'].includes(ext || '')) type = 'image';
        else if (['csv', 'xls', 'xlsx'].includes(ext || '')) type = 'report';

        const newFile: DeviceFile = {
          id: crypto.randomUUID(),
          name: file.name,
          type: type,
          url: base64String,
          dateAdded: new Date().toISOString().split('T')[0]
        };

        onUpdate({
          ...device,
          files: [...device.files, newFile]
        });
        setUploadingFile(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') {
      alert('This is a mock file. Upload a real file to test viewing.');
      return;
    }
    try {
       const byteString = atob(file.url.split(',')[1]);
       const mimeString = file.url.split(',')[0].split(':')[1].split(';')[0];
       const ab = new ArrayBuffer(byteString.length);
       const ia = new Uint8Array(ab);
       for (let i = 0; i < byteString.length; i++) {
         ia[i] = byteString.charCodeAt(i);
       }
       const blob = new Blob([ab], { type: mimeString });
       const blobUrl = URL.createObjectURL(blob);
       window.open(blobUrl, '_blank');
    } catch(err) {
       console.error("Error opening file:", err);
       const win = window.open();
       if (win) {
         win.document.write('<iframe src="' + file.url + '" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>');
       }
    }
  };

  const getBaseUrl = () => localStorage.getItem('meditrack_base_url') || (window.location.origin + window.location.pathname);
  const appBaseUrl = getBaseUrl();
  const qrData = `${appBaseUrl}?deviceId=${device.id}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qrData)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start">
        <div>
          <button onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1">
            ← Back to Inventory
          </button>
          <h1 className="text-2xl font-bold text-slate-900">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1"><Box className="w-4 h-4" /> {device.model}</span>
            <span className="px-2 py-1 bg-slate-100 rounded-full text-xs font-medium">SN: {device.serialNumber}</span>
            <span className={`px-2 py-1 rounded-full text-xs font-medium ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={onDelete}
             className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-600 border border-red-200 rounded-lg hover:bg-red-100 transition text-sm font-medium"
           >
             <Trash2 className="w-4 h-4" />
             Delete
           </button>
           <button 
            onClick={() => setActiveTab('qr')}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700 transition text-sm font-medium"
           >
             <QrCode className="w-4 h-4" />
             QR
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="Maintenance" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<FileText className="w-4 h-4" />} label="Contracts" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="QR Identity" />
      </div>

      {/* Content */}
      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left Column: Image & Info */}
            <div className="lg:col-span-2 space-y-6">

              {/* Image Section */}
              <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden group relative">
                <div className="aspect-video bg-slate-100 flex items-center justify-center relative">
                  {device.image ? (
                    <img src={device.image} alt={device.name} className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex flex-col items-center gap-3 text-slate-400">
                      <Camera className="w-12 h-12" />
                      <p className="text-sm font-medium">No Device Photo</p>
                    </div>
                  )}

                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button 
                      onClick={() => imageInputRef.current?.click()}
                      className="px-4 py-2 bg-white text-slate-900 rounded-lg text-sm font-bold shadow-lg flex items-center gap-2"
                    >
                      <Camera className="w-4 h-4" /> {device.image ? 'Change Photo' : 'Upload Photo'}
                    </button>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Section title="General Information" icon={<Info className="w-4 h-4" />}>
                  <InfoRow label="Manufacturer" value={device.manufacturer} />
                  <InfoRow label="Department" value={device.department} />
                  <InfoRow label="Purchase Date" value={device.purchaseDate} />
                  <InfoRow label="Serial Number" value={device.serialNumber} />
                </Section>

                <Section title="Notes" icon={<Edit2 className="w-4 h-4" />}>
                  <p className="text-slate-600 text-sm leading-relaxed min-h-[100px]">
                    {device.notes || "No clinical engineering notes provided for this unit."}
                  </p>
                </Section>
              </div>

              {/* Modular Components Section */}
              <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-4 pb-2 border-b border-slate-50">
                   <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide flex items-center gap-2">
                     <Package className="w-4 h-4 text-blue-600" /> Modular Components
                   </h3>
                   <button 
                    onClick={() => setShowComponentModal(true)}
                    className="text-blue-600 hover:text-blue-700 text-xs font-bold flex items-center gap-1 bg-blue-50 px-2 py-1 rounded"
                   >
                     <Plus className="w-3 h-3" /> Add Sub-Component
                   </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {device.components?.map(comp => (
                    <div key={comp.id} className="p-3 border border-slate-100 rounded-lg bg-slate-50 flex items-center justify-between group">
                      <div>
                        <p className="text-sm font-semibold text-slate-900">{comp.name}</p>
