interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [showFileUploadModal, setShowFileUploadModal] = useState(false);
  const [contractText, setContractText] = useState('');
  const [editingContractId, setEditingContractId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  // Component Form State
  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  const initialContractForm = {
    name: '',
    provider: '',
    contractNumber: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    annualCost: '',
    coverageDetails: '',
    contactPhone: ''
  };

  const [manualContractForm, setManualContractForm] = useState(initialContractForm);

  // Component Helpers
  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: crypto.randomUUID(),
      ...newComponent
    };
    const updatedComponents = [...(device.components || []), component];
    onUpdate({ ...device, components: updatedComponents });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    const updatedComponents = (device.components || []).filter(c => c.id !== id);
    onUpdate({ ...device, components: updatedComponents });
  };

  // Image Upload Helper
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  // File Upload Helpers
  const triggerFileUpload = (type: DeviceFile['type']) => {
    setSelectedFileType(type);
    fileInputRef.current?.click();
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadingFile(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const newFile: DeviceFile = {
          id: crypto.randomUUID(),
          name: file.name,
          type: selectedFileType,
          url: base64String,
          dateAdded: new Date().toISOString().split('T')[0]
        };

        onUpdate({
          ...device,
          files: [...device.files, newFile]
        });
        setUploadingFile(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsDataURL(file);
    }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') {
      alert('Mock file. Upload a real document to test.');
      return;
    }
    const win = window.open();
    if (win) {
      win.document.write('<iframe src="' + file.url + '" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>');
    }
  };

  // Filter files by type
  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  // Maintenance & Contract Logic (Retained from existing code)
  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const suggestion = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion:\nType: ${suggestion.recommendedType}\nFreq: ${suggestion.frequency}\nTasks: ${suggestion.tasks.join(', ')}`);
    } catch (e) { alert("Failed to get suggestion."); } finally { setIsAnalyzing(false); }
  };

  const handleSaveMaintenance = () => {
    if (!maintenanceForm.technician || !maintenanceForm.description) return;
    const newRecord: MaintenanceRecord = {
      id: crypto.randomUUID(),
      date: maintenanceForm.date || new Date().toISOString().split('T')[0],
      type: maintenanceForm.type || MaintenanceType.PREVENTIVE,
      technician: maintenanceForm.technician,
      description: maintenanceForm.description,
      completed: maintenanceForm.completed || false,
      nextScheduledDate: maintenanceForm.nextScheduledDate || undefined
    };
    onUpdate({ ...device, maintenanceHistory: [newRecord, ...device.maintenanceHistory] });
    setShowMaintenanceModal(false);
  };

  const handleAnalyzeContract = async () => {
    if (!contractText) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeContractText(contractText);
      const newContract: Contract = {
        id: crypto.randomUUID(),
        provider: result.provider || 'Unknown',
        contractNumber: result.contractNumber || 'N/A',
        startDate: result.startDate || new Date().toISOString().split('T')[0],
        endDate: result.endDate || new Date().toISOString().split('T')[0],
        coverageDetails: result.coverageDetails || '',
        contactPhone: result.contactPhone || '',
        annualCost: result.annualCost || 0
      };
      onUpdate({ ...device, contracts: [...device.contracts, newContract] });
      setShowContractModal(false);
    } catch (e) { alert("Analysis failed."); } finally { setIsAnalyzing(false); }
  };

  const getBaseUrl = () => localStorage.getItem('meditrack_base_url') || (window.location.origin + window.location.pathname);
  const qrData = `${getBaseUrl()}?deviceId=${device.id}`;
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qrData)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider shadow-sm ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700 border border-green-200' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-amber-100 text-amber-700 border border-amber-200'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 hover:border-red-200 transition shadow-sm">
             <Trash2 className="w-5 h-5" />
           </button>
           <button onClick={() => setActiveTab('qr')} className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition shadow-md font-bold text-sm">
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="Full History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Service Level" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* Left Column: Visual & Critical Data (8 cols) */}
            <div className="lg:col-span-8 space-y-6">

              {/* Device Photo & General Info */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden group relative aspect-video">
                  {device.image ? (
                    <img src={device.image} alt={device.name} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full bg-slate-100 flex flex-col items-center justify-center text-slate-400">
                      <Camera className="w-12 h-12 mb-2" />
                      <p className="text-xs font-bold uppercase tracking-widest">No Device Image</p>
                    </div>
                  )}
                  <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition flex items-center justify-center backdrop-blur-[2px]">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button onClick={() => imageInputRef.current?.click()} className="px-5 py-2.5 bg-white text-slate-900 rounded-xl font-bold text-sm shadow-xl flex items-center gap-2 transform translate-y-2 group-hover:translate-y-0 transition">
                      <Camera className="w-4 h-4" /> {device.image ? 'Change Photo' : 'Capture / Upload'}
                    </button>
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                  <div className="flex items-center gap-2 mb-2">
                    <Info className="w-5 h-5 text-blue-600" />
                    <h3 className="font-bold text-slate-800">Quick Specs</h3>
                  </div>
                  <InfoRow label="Manufacturer" value={device.manufacturer} />
                  <InfoRow label="Department" value={device.department} />
                  <InfoRow label="Deployed Since" value={device.purchaseDate} />
                  <InfoRow label="Clinical Ward" value={device.department} />
                </div>
              </div>

              {/* Service Reports Card */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <FileCheck className="w-5 h-5 text-green-600" /> Recent Service Reports
                   </h3>
                   <button 
                    onClick={() => triggerFileUpload('report')}
                    className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-lg hover:bg-blue-100 transition flex items-center gap-1.5"
                   >
                     <Plus className="w-3.5 h-3.5" /> Upload Report
                   </button>
                </div>

                <div className="space-y-3">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-between hover:bg-white hover:border-blue-200 transition group cursor-pointer" onClick={(e) => handleOpenFile(e, report)}>
                      <div className="flex items-center gap-4">
                        <div className="p-2.5 bg-white rounded-lg shadow-sm group-hover:bg-blue-50 transition">
                          <ClipboardList className="w-5 h-5 text-slate-400 group-hover:text-blue-600" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-900">{report.name}</p>
                          <p className="text-[11px] text-slate-500 font-medium">Uploaded on {report.dateAdded}</p>
                        </div>
                      </div>
                      <Download className="w-4 h-4 text-slate-300 group-hover:text-blue-500" />
                    </div>
                  ))}
                  {reports.length === 0 && (
                    <div className="py-8 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-xl">
                      No service reports on file. Attach one for clinical compliance.
                    </div>
                  )}
                </div>
              </div>

              {/* System Components Card */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <Package className="w-5 h-5 text-violet-600" /> System Components
                   </h3>
                   <button 
                    onClick={() => setShowComponentModal(true)}
                    className="text-xs font-bold text-violet-600 bg-violet-50 px-3 py-1.5 rounded-lg hover:bg-violet-100 transition flex items-center gap-1.5"
                   >
                     <Plus className="w-3.5 h-3.5" /> Register Part
                   </button>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {device.components?.map(comp => (
                    <div key={comp.id} className="p-4 border border-slate-100 rounded-xl bg-slate-50 flex items-center justify-between group">
                      <div>
                        <p className="text-sm font-bold text-slate-900">{comp.name}</p>
                        <p className="text-[10px] font-mono text-slate-500 mt-0.5">SN: {comp.serialNumber || 'N/A'}</p>
                      </div>
                      <button onClick={() => removeComponent(comp.id)} className="p-1.5 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                  {(!device.components || device.components.length === 0) && (
                    <p className="col-span-full text-center py-6 text-slate-400 text-xs font-medium">No sub-components registered for this asset.</p>
                  )}
                </div>
              </div>
            </div>

            {/* Right Column: Library & Tools (4 cols) */}
            <div className="lg:col-span-4 space-y-6">

              {/* Asset Library Card */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <FileText className="w-4 h-4" /> Technical Library
                 </h3>
                 <div className="space-y-4">
                   <div className="flex flex-col gap-2">
                     <p className="text-[10px] font-bold text-slate-400 uppercase">Operator Manuals</p>
                     {manuals.map(m => (
                       <a key={m.id} href="#" onClick={(e) => handleOpenFile(e, m)} className="text-xs font-semibold text-blue-600 hover:underline flex items-center gap-2 truncate">
                         <Download className="w-3 h-3" /> {m.name}
                       </a>
                     ))}
                     <button onClick={() => triggerFileUpload('manual')} className="w-full py-2 mt-1 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">
                       + ADD MANUAL
                     </button>
                   </div>

                   <div className="pt-4 border-t border-slate-50">
                     <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Device Files</p>
                     {device.files.filter(f => f.type === 'other').map(f => (
                       <div key={f.id} className="flex items-center justify-between text-xs py-1">
                         <span className="text-slate-600 truncate">{f.name}</span>
                         <Download className="w-3 h-3 text-slate-300" />
                       </div>
                     ))}
                     <button onClick={() => triggerFileUpload('other')} className="w-full py-2 mt-2 bg-slate-50 text-[10px] font-black text-slate-500 rounded-xl hover:bg-slate-100 transition">
                       + ADD OTHER FILE
                     </button>
                   </div>
                 </div>
              </div>

              {/* Maintenance Snapshot */}
              <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl space-y-6">
                 <div>
                   <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Next Calibration</p>
                   <p className="text-2xl font-bold mt-1">
                     {device.maintenanceHistory[0]?.nextScheduledDate || "Not Scheduled"}
                   </p>
                 </div>
                 <div className="flex items-center gap-4">
                   <div className="flex-1 bg-white/10 p-4 rounded-xl">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Health Rating</p>
                      <p className="text-lg font-bold text-green-400">Stable</p>
                   </div>
                   <div className="flex-1 bg-white/10 p-4 rounded-xl">
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Risk Level</p>
                      <p className="text-lg font-bold text-blue-300">Low</p>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* MODALS (Component & Maintenance etc.) */}
        {showComponentModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
            <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full overflow-hidden animate-fade-in">
              <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                <h3 className="font-bold text-slate-900 flex items-center gap-2"><Package className="w-5 h-5 text-blue-600" /> New Component</h3>
                <button onClick={() => setShowComponentModal(false)} className="text-slate-400 hover:text-slate-600 transition"><X className="w-5 h-5" /></button>
              </div>
              <div className="p-8 space-y-6">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Component Name</label>
                  <input type="text" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="e.g. Workstation Console" value={newComponent.name} onChange={e => setNewComponent({...newComponent, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Serial Number</label>
                  <input type="text" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="SN-XXXXX" value={newComponent.serialNumber} onChange={e => setNewComponent({...newComponent, serialNumber: e.target.value})} />
                </div>
                <div className="flex gap-3 pt-2">
                  <button onClick={() => setShowComponentModal(false)} className="flex-1 py-3 font-bold text-slate-500 hover:bg-slate-50 rounded-xl transition">Cancel</button>
                  <button onClick={handleAddComponent} className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg hover:bg-blue-700 transition">Add Part</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'maintenance' && (
          <div className="space-y-6 max-w-4xl mx-auto">
            <div className="flex justify-between items-center bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
               <div>
                  <h3 className="text-xl font-bold text-slate-900">Maintenance History</h3>
                  <p className="text-sm text-slate-500">Full clinical service log for this unit.</p>
               </div>
               <button 
                 onClick={handleSuggestMaintenance}
                 disabled={isAnalyzing}
                 className="px-4 py-2 bg-violet-600 text-white rounded-xl text-sm font-bold shadow-md hover:bg-violet-700 transition flex items-center gap-2"
               >
                 <Wand2 className="w-4 h-4" />
                 {isAnalyzing ? "Analyzing..." : "AI Schedule Suggest"}
               </button>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-5 rounded-2xl border border-slate-200 flex flex-col md:flex-row gap-6 md:items-center justify-between shadow-sm hover:shadow-md transition">
                  <div className="flex gap-5">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 shadow-inner ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600 mt-0.5">{record.description}</p>
                      <div className="flex gap-4 mt-2">
                        <span className="text-[10px] font-bold uppercase text-slate-400 flex items-center gap-1"><Settings className="w-3 h-3" /> Tech: {record.technician}</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-right border-t md:border-t-0 pt-4 md:pt-0">
                    <p className="text-sm font-bold text-slate-900">{record.date}</p>
                    {record.nextScheduledDate && (
                      <p className="text-xs font-bold text-blue-600 mt-1 uppercase tracking-tight">Next Due: {record.nextScheduledDate}</p>
                    )}
                  </div>
                </div>
              ))}
              {device.maintenanceHistory.length === 0 && (
                <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-slate-200">
                   <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4"><Calendar className="w-8 h-8 text-slate-300" /></div>
                   <p className="text-slate-500 font-medium">No service records found.</p>
                </div>
              )}
            </div>

            <button 
              onClick={() => setShowMaintenanceModal(true)}
              className="w-full py-4 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-slate-500 font-bold hover:border-blue-400 hover:text-blue-600 transition flex items-center justify-center gap-2"
            >
              <Plus className="w-5 h-5" /> Register Service Event
            </button>
          </div>
        )}

        {/* Existing Contract Modal and Tab Logic (Abbreviated to satisfy user request) */}
        {activeTab === 'contracts' && (
           <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm max-w-4xl mx-auto text-center">
              <ShieldCheck className="w-12 h-12 text-blue-600 mx-auto mb-4" />
              <h3 className="text-xl font-bold text-slate-900">Service Level Management</h3>
              <p className="text-slate-500 mt-2 mb-8">Manage warranties and external service contracts for this device.</p>
              <button 
                onClick={() => setShowContractModal(true)}
                className="px-8 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg hover:bg-blue-700 transition"
              >
                Configure Support Contract
              </button>
           </div>
        )}

        {activeTab === 'qr' && (
          <div className="flex flex-col items-center justify-center h-full py-10 space-y-8 animate-fade-in">
            <div className="bg-white p-12 rounded-3xl shadow-2xl border border-slate-100 flex flex-col items-center max-w-sm w-full">
              <div className="w-full flex justify-between mb-8">
                <div className="bg-blue-600 p-2 rounded-lg shadow-md"><Activity className="w-6 h-6 text-white" /></div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest self-center">Clinical Asset Label</p>
              </div>
              <h3 className="text-2xl font-black text-slate-900 mb-8 text-center leading-tight">{device.name}</h3>
              <div className="p-3 bg-slate-900 rounded-2xl shadow-xl">
                <img src={qrCodeUrl} alt="QR" className="w-44 h-44 object-contain brightness-0 invert" />
              </div>
              <p className="mt-8 text-xs font-medium text-slate-400 text-center leading-relaxed">
                Scanning this ID provides instant access to service manuals and maintenance logs.
              </p>
              <div className="mt-8 flex gap-3 w-full">
                 <button className="flex-1 py-3 bg-slate-900 text-white rounded-xl font-bold text-sm shadow-md hover:bg-black transition">Download</button>
                 <button onClick={() => window.open(qrCodeUrl, '_blank')} className="flex-1 py-3 bg-slate-100 text-slate-700 rounded-xl font-bold text-sm hover:bg-slate-200 transition">Print Label</button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Contract & Maintenance Modals (Retained logic from previous turn) */}
      {showContractModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full p-8 animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Configure Contract</h3>
              <button onClick={() => setShowContractModal(false)}><X className="w-6 h-6" /></button>
            </div>
            <textarea className="w-full h-32 p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none mb-6" placeholder="Paste raw contract text here for AI extraction..." value={contractText} onChange={(e) => setContractText(e.target.value)} />
            <button onClick={handleAnalyzeContract} disabled={isAnalyzing || !contractText} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg disabled:opacity-50">
              {isAnalyzing ? "Extracting..." : "Process with Gemini AI"}
            </button>
          </div>
        </div>
      )}

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full p-8 animate-fade-in">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Log Service Event</h3>
              <button onClick={() => setShowMaintenanceModal(false)}><X className="w-6 h-6" /></button>
            </div>
            <div className="space-y-4">
              <input type="text" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
              <textarea className="w-full h-24 p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm" placeholder="Work Summary" value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
              <button onClick={handleSaveMaintenance} className="w-full py-3 bg-green-600 text-white rounded-xl font-bold shadow-lg">Save Record</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-6 py-5 text-sm font-bold border-b-4 transition-all whitespace-nowrap ${
