import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus } from '../types';
import { Search, Filter, MoreVertical, Eye, Trash2 } from 'lucide-react';

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onAddDevice, onDelete }) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');

  // useMemo ensures we don't crash on null properties and optimizes performance during typing
  const filteredDevices = useMemo(() => {
    const searchTerm = search.toLowerCase().trim();

    return devices.filter(d => {
      // Added null-safety with (prop || '')
      const name = (d.name || '').toLowerCase();
      const serial = (d.serialNumber || '').toLowerCase();
      const model = (d.model || '').toLowerCase();
      const manufacturer = (d.manufacturer || '').toLowerCase();

      const matchesSearch = !searchTerm || 
                            name.includes(searchTerm) || 
                            serial.includes(searchTerm) ||
                            model.includes(searchTerm) ||
                            manufacturer.includes(searchTerm);

      const matchesStatus = filterStatus === 'ALL' || d.status === filterStatus;

      return matchesSearch && matchesStatus;
    });
  }, [devices, search, filterStatus]);

  return (
    <div className="space-y-4 animate-fade-in">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-200">
        <div className="relative w-full sm:w-96">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input 
            type="text"
            id="device-search"
            name="device-search"
            autoComplete="off"
            placeholder="Search devices by name, model, or serial..."
            className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm transition-all"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <select 
            className="px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
          >
            <option value="ALL">All Statuses</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
          </select>
          <button 
            onClick={onAddDevice}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-bold transition shadow-md whitespace-nowrap active:scale-95"
          >
            + New Device
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-6 py-4">Device Name</th>
                <th className="px-6 py-4">Model / Serial</th>
                <th className="px-6 py-4">Department</th>
                <th className="px-6 py-4">Next Maint.</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredDevices.map(device => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/30 transition-colors group cursor-pointer"
                  onClick={() => onSelectDevice(device)}
                >
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900 text-sm">{device.name}</div>
                    <div className="text-[11px] text-slate-500 font-medium uppercase tracking-tight">{device.manufacturer}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm text-slate-700 font-medium">{device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400">SN: {device.serialNumber}</div>
                  </td>
                  <td className="px-6 py-4 text-xs font-semibold text-slate-600">{device.department}</td>
                  <td className="px-6 py-4">
                    <div className="text-xs font-bold text-slate-700">
                      {device.maintenanceHistory?.[0]?.nextScheduledDate || "Not Scheduled"}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 relative z-20">
                      <button 
                        type="button"
                        className="p-2 text-slate-400 hover:text-blue-600 transition rounded-lg hover:bg-white" 
                        title="View Details"
                        onClick={(e) => {
                          e.stopPropagation();
                          onSelectDevice(device);
                        }}
                      >
                        <Eye className="w-4 h-4 pointer-events-none" />
                      </button>
                      <button 
                        type="button"
                        className="p-2 text-slate-400 hover:text-red-600 transition rounded-lg hover:bg-red-50" 
                        title="Delete Device"
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          if(confirm('Are you sure you want to delete this device?')) {
                            onDelete(device.id);
                          }
                        }}
                      >
                        <Trash2 className="w-4 h-4 pointer-events-none" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-6 py-16 text-center">
                    <div className="flex flex-col items-center justify-center gap-2">
                       <Search className="w-8 h-8 text-slate-200" />
                       <p className="text-slate-400 font-medium italic text-sm">No devices found matching your search.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return (
    <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider border ${styles}`}>
      {status}
    </span>
  );
};

