                      className="p-3 bg-white/90 backdrop-blur text-slate-900 rounded-xl shadow-xl hover:bg-white transition"
                      title="Update Photo"
                    >
                      <Camera className="w-4 h-4" />
                    </button>
                    {device.image && (
                      <button 
                        onClick={() => setShowFullImage(true)}
                        className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition"
                        title="View Fullscreen"
                      >
                        <Maximize2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4 flex flex-col justify-center">
