import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  onSave: (device: MedicalDevice) => void;
  onBulkSave: (devices: MedicalDevice[]) => void;
  onCancel: () => void;
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    notes: '',
    image: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleSingleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newDevice: MedicalDevice = {
      id: `DEV-${Math.floor(Math.random() * 90000) + 10000}`,
      ...formData,
      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };
    onSave(newDevice);
  };

  const processWithAI = async (inputData: string) => {
    setIsProcessing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Parse clinical device data into JSON array: "${inputData}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                manufacturer: { type: Type.STRING },
                model: { type: Type.STRING },
                serialNumber: { type: Type.STRING },
                department: { type: Type.STRING },
                purchaseDate: { type: Type.STRING },
                status: { type: Type.STRING }
              },
              required: ["name", "serialNumber"]
            }
          }
        }
      });
      const parsed: any[] = JSON.parse(response.text);
      setPreviewDevices(parsed.map(item => ({ ...item, id: `DEV-${Math.floor(Math.random() * 90000)}`, maintenanceHistory: [], contracts: [], files: [] })));
    } catch (error) {
      alert("AI Processing failed.");
    } finally { setIsProcessing(false); }
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        processWithAI(JSON.stringify(data));
      } catch (err) { alert("Error reading file."); }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20">
      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Hospital Inventory Management System</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Registration" />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="Smart AI Extract" />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Spreadsheet Import" />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             {/* Preview List (Existing logic) */}
             <div className="flex justify-between items-center bg-blue-50 p-6 rounded-3xl border border-blue-100">
               <h3 className="font-bold text-blue-900 flex items-center gap-3"><Check className="w-6 h-6 text-blue-600" /> Confirm Import ({previewDevices.length} assets)</h3>
               <button onClick={() => setPreviewDevices([])} className="text-sm font-black text-blue-600 uppercase hover:underline">Clear</button>
             </div>
             <div className="max-h-96 overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50">
               {previewDevices.map(d => (
                 <div key={d.id} className="p-5 flex items-center justify-between hover:bg-slate-50 transition">
                   <div className="flex items-center gap-4">
                     <div className="w-10 h-10 bg-white shadow-sm border border-slate-100 rounded-xl flex items-center justify-center"><Box className="w-5 h-5 text-slate-400" /></div>
                     <div><p className="font-bold text-slate-900 text-sm">{d.name}</p><p className="text-[10px] font-mono text-slate-500">{d.serialNumber}</p></div>
                   </div>
                 </div>
               ))}
             </div>
             <button onClick={() => onBulkSave(previewDevices)} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-xl">Complete Bulk Upload</button>
          </div>
        ) : (
          <>
            {activeTab === 'single' && (
              <form onSubmit={handleSingleSubmit} className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                  {/* Photo Upload Side */}
                  <div className="md:col-span-1 space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Asset Visual</label>
                     <div 
                      onClick={() => imageInputRef.current?.click()}
                      className="aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all overflow-hidden group"
                     >
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-contain" />
                       ) : (
                         <>
                           <Camera className="w-10 h-10 text-slate-300 group-hover:scale-110 transition-transform" />
                           <p className="mt-2 text-[10px] font-black text-slate-400 uppercase">Click to upload photo</p>
                         </>
                       )}
                       <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                     </div>
                     <p className="text-[10px] text-slate-400 text-center italic">Supported: JPG, PNG, WEBP (Max 1MB)</p>
                  </div>

                  {/* Fields Side */}
                  <div className="md:col-span-2 space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <FormField label="Asset Name" name="name" value={formData.name} onChange={handleChange} placeholder="e.g. Ventilator 500" required />
                      <FormField label="Manufacturer" name="manufacturer" value={formData.manufacturer} onChange={handleChange} placeholder="e.g. Medtronic" required />
                      <FormField label="Model / Type" name="model" value={formData.model} onChange={handleChange} placeholder="e.g. Puritan Bennett" required />
                      <FormField label="Serial Number" name="serialNumber" value={formData.serialNumber} onChange={handleChange} placeholder="Unique Ident." required />
                      <FormField label="Assigned Ward" name="department" value={formData.department} onChange={handleChange} placeholder="e.g. ICU-3" required />
                      <FormField label="Acquisition Date" name="purchaseDate" type="date" value={formData.purchaseDate} onChange={handleChange} required />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Initial Status</label>
                      <select name="status" value={formData.status} onChange={handleChange} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none">
                        {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
                  <button type="button" onClick={onCancel} className="px-8 py-3 bg-slate-100 text-slate-500 rounded-xl font-bold hover:bg-slate-200 transition">Cancel</button>
                  <button type="submit" className="px-12 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-xl hover:bg-blue-700 transition flex items-center gap-2">
                    <Save className="w-5 h-5" /> Save Asset
                  </button>
                </div>
              </form>
            )}

            {activeTab === 'bulk' && (
              <div className="space-y-6">
                <div className="bg-violet-50 p-6 rounded-3xl border border-violet-100 flex gap-4">
                  <Wand2 className="w-8 h-8 text-violet-600 shrink-0" />
                  <p className="text-sm text-violet-900 font-medium"><strong>Intelligence Engine:</strong> Paste raw data from inventory lists or clinical logs. Our system will intelligently extract structured metadata for you.</p>
                </div>
                <textarea className="w-full h-64 p-6 bg-slate-50 border border-slate-200 rounded-3xl focus:ring-2 focus:ring-violet-500 outline-none font-mono text-sm" placeholder="Paste equipment list data here..." value={bulkText} onChange={(e) => setBulkText(e.target.value)} />
                <button onClick={() => processWithAI(bulkText)} disabled={isProcessing || !bulkText} className="w-full py-4 bg-violet-600 text-white rounded-2xl font-bold shadow-xl hover:bg-violet-700 transition disabled:opacity-50">
                  {isProcessing ? "Analyzing Clinical Data..." : "Extract Assets with AI"}
                </button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-20 border-4 border-dashed border-slate-50 rounded-[40px] text-center">
                 <FileSpreadsheet className="w-16 h-16 text-blue-200 mb-6" />
                 <h3 className="text-xl font-bold text-slate-900 mb-2">Spreadsheet Ingestion</h3>
                 <p className="text-sm text-slate-400 max-w-sm mb-8">Upload CSV or XLSX files from your existing clinical engineering database.</p>
                 <input type="file" ref={excelInputRef} accept=".xlsx,.xls,.csv" onChange={handleExcelUpload} className="hidden" />
                 <button onClick={() => excelInputRef.current?.click()} className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-bold shadow-xl hover:bg-black transition flex items-center gap-2">
                   <Upload className="w-5 h-5" /> Choose File
                 </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, label }: { active: boolean, onClick: () => void, label: string }) => (
  <button onClick={onClick} className={`px-10 py-6 text-xs font-black uppercase tracking-[0.2em] transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-blue-50/30' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
    {label}
  </button>
);

const FormField = ({ label, name, value, onChange, placeholder, type = "text", required = false }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input required={required} name={name} type={type} value={value} onChange={onChange} placeholder={placeholder} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition" />
  </div>
);

