import React, { useState, useMemo, useEffect } from 'react';
import { MedicalDevice, DeviceStatus } from '../types';
import { Search, Eye, Trash2, Box } from 'lucide-react';

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onAddDevice, onDelete }) => {
  const [localSearch, setLocalSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');

  // useMemo with debounced-style reactivity for smooth typing
  const filteredDevices = useMemo(() => {
    const term = localSearch.toLowerCase().trim();
    return devices.filter(d => {
      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      return matchSearch && matchStatus;
    });
  }, [devices, localSearch, filterStatus]);

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Search Header */}
      <div className="flex flex-col lg:flex-row justify-between items-stretch lg:items-center gap-4 bg-white p-6 rounded-[2rem] shadow-xl border border-slate-100">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5" />
          <input 
            type="text"
            placeholder="Search clinical assets by name, serial, or department..."
            className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:outline-none text-sm font-medium transition-all"
            value={localSearch}
            onChange={(e) => setLocalSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-3">
          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl text-sm font-bold text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
          >
            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
          <button 
            onClick={onAddDevice}
            className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-2xl text-sm font-black uppercase tracking-widest transition shadow-xl active:scale-95"
          >
            + New Asset
          </button>
        </div>
      </div>

      {/* Grid Display for better visual overview */}
      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto overflow-y-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map(device => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/40 transition-all group cursor-pointer"
                  onClick={() => onSelectDevice(device)}
                >
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center">
                        {device.image ? (
                          <img src={device.image} className="w-full h-full object-cover" alt="Asset" />
                        ) : (
                          <Box className="w-5 h-5 text-slate-300" />
                        )}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="text-xs font-bold text-slate-700">{device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">#{device.serialNumber}</div>
                  </td>
                  <td className="px-8 py-6">
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6">
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 shadow-sm border border-slate-100 rounded-xl transition"
                        onClick={(e) => { e.stopPropagation(); onSelectDevice(device); }}
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-red-600 shadow-sm border border-slate-100 rounded-xl transition"
                        onClick={(e) => { 
                          e.stopPropagation(); 
                          if(confirm('Confirm permanent removal?')) onDelete(device.id); 
                        }}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-24 text-center">
                    <div className="flex flex-col items-center gap-4">
                       <Search className="w-12 h-12 text-slate-100" />
                       <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No matching clinical assets found</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return (
    <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>
      {status}
    </span>
  );
};

export default DeviceList;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [contractText, setContractText] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  // Component Form State
  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  // Helpers
  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: crypto.randomUUID(),
      ...newComponent
    };
    onUpdate({ ...device, components: [...(device.components || []), component] });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    onUpdate({ ...device, components: (device.components || []).filter(c => c.id !== id) });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadingFile(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFile: DeviceFile = {
          id: crypto.randomUUID(),
          name: file.name,
          type: selectedFileType,
          url: reader.result as string,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
        setUploadingFile(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDeleteFile = (e: React.MouseEvent, fileId: string) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to permanently delete this document?')) {
      const updatedFiles = device.files.filter(f => f.id !== fileId);
      onUpdate({ ...device, files: updatedFiles });
    }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') return alert('Mock file.');
    const win = window.open();
    if (win) win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`);
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion: ${res.recommendedType} every ${res.frequency}. Tasks: ${res.tasks.join(', ')}`);
    } finally { setIsAnalyzing(false); }
  };

  const handleAnalyzeContract = async () => {
    if (!contractText) return;
    setIsAnalyzing(true);
    try {
      const res = await analyzeContractText(contractText);
      const newC: Contract = {
        id: crypto.randomUUID(),
        provider: res.provider || 'Unknown',
        contractNumber: res.contractNumber || 'N/A',
        startDate: res.startDate || new Date().toISOString().split('T')[0],
        endDate: res.endDate || new Date().toISOString().split('T')[0],
        coverageDetails: res.coverageDetails || '',
        contactPhone: res.contactPhone || '',
        annualCost: res.annualCost || 0
      };
      onUpdate({ ...device, contracts: [...device.contracts, newC] });
      setShowContractModal(false);
    } finally { setIsAnalyzing(false); }
  };

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(device.id)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
