                         </div>
                       ))}
                       <button onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">
