              <div className="bg-slate-900 text-white p-7 rounded-3xl shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-[-20px] right-[-20px] w-32 h-32 bg-blue-600/20 blur-3xl group-hover:bg-blue-600/40 transition-all duration-700"></div>
                 <div className="relative z-10 space-y-8">
                   <div>
                     <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Next Calibration</p>
                     <p className="text-3xl font-bold mt-1 tracking-tight">
                       {device.maintenanceHistory[0]?.nextScheduledDate || "PENDING"}
                     </p>
