                   <div className="flex items-center gap-4">
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-4 rounded-2xl border border-white/10">
                        <p className="text-[9px] font-bold text-slate-400 uppercase">Operational Status</p>
                        <p className="text-lg font-bold text-green-400 mt-1">OPTIMAL</p>
                     </div>
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-4 rounded-2xl border border-white/10">
                        <p className="text-[9px] font-bold text-slate-400 uppercase">Compliance</p>
                        <p className="text-lg font-bold text-blue-400 mt-1">100%</p>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* FULL IMAGE MODAL */}
        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowFullImage(false)}>
            <button className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="High Res Visual" className="max-w-full max-h-full object-contain shadow-2xl" />
          </div>
        )}

        {/* COMPONENT MODAL */}
        {showComponentModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
            <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden animate-fade-in">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                <h3 className="font-black text-[11px] uppercase tracking-widest text-slate-900 flex items-center gap-2"><Package className="w-5 h-5 text-blue-600" /> New Component</h3>
                <button onClick={() => setShowComponentModal(false)} className="text-slate-400 hover:text-slate-600 transition"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-8 space-y-6">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Component Name</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="e.g. Laser Head" value={newComponent.name} onChange={e => setNewComponent({...newComponent, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Serial Number</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition" placeholder="SN-XXXXX" value={newComponent.serialNumber} onChange={e => setNewComponent({...newComponent, serialNumber: e.target.value})} />
                </div>
                <button onClick={handleAddComponent} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-xl hover:bg-blue-700 transition">Complete Registration</button>
              </div>
            </div>
          </div>
        )}

        {/* Maintenance View */}
        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
               <div>
                  <h3 className="text-2xl font-bold text-slate-900">Clinical History</h3>
                  <p className="text-sm text-slate-500 mt-1">Full engineering and maintenance log.</p>
               </div>
               <button onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3 bg-violet-600 text-white rounded-2xl font-bold shadow-lg hover:bg-violet-700 transition flex items-center gap-2">
                 <Wand2 className="w-5 h-5" /> {isAnalyzing ? "Analyzing..." : "AI Intelligence"}
               </button>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between hover:shadow-md transition">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600">{record.description}</p>
                      <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Engineer: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-slate-900">{record.date}</p>
                  </div>
                </div>
              ))}
            </div>

            <button onClick={() => setShowMaintenanceModal(true)} className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 hover:text-blue-500 transition-all flex items-center justify-center gap-2">
              <Plus className="w-5 h-5" /> REGISTER NEW SERVICE EVENT
            </button>
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4" placeholder="Summary of work..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <button 
              onClick={() => {
                const newR: MaintenanceRecord = { id: crypto.randomUUID(), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Admin', description: maintenanceForm.description || '', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setShowMaintenanceModal(false);
              }}
              className="w-full py-4 bg-green-600 text-white rounded-2xl font-bold"
            >
              Confirm Log
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${
      active ? 'border-blue-600 text-blue-600 scale-105' : 'border-transparent text-slate-400 hover:text-slate-600'
    }`}
  >
    {icon}
    {label}
  </button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

export default DeviceDetail;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [contractText, setContractText] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  // Component Form State
  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  // Helpers
  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: crypto.randomUUID(),
      ...newComponent
    };
    onUpdate({ ...device, components: [...(device.components || []), component] });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    onUpdate({ ...device, components: (device.components || []).filter(c => c.id !== id) });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setUploadingFile(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFile: DeviceFile = {
          id: crypto.randomUUID(),
          name: file.name,
          type: selectedFileType,
          url: reader.result as string,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
        setUploadingFile(false);
      };
      reader.readAsDataURL(file);
    }
  };

  // Improved robust deletion handler
  const handleDeleteFile = (e: React.MouseEvent, fileId: string) => {
    e.preventDefault();
    e.stopPropagation(); // Critical: Stop bubbling to handleOpenFile on parent

    if (window.confirm('Delete this clinical document permanently? This cannot be undone.')) {
      const updatedFiles = device.files.filter(f => f.id !== fileId);
      onUpdate({ ...device, files: updatedFiles });
    }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') return alert('Mock file.');
    const win = window.open();
    if (win) win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`);
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion: ${res.recommendedType} every ${res.frequency}. Tasks: ${res.tasks.join(', ')}`);
    } finally { setIsAnalyzing(false); }
  };

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(device.id)}`;

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider shadow-sm ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700 border border-green-200' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-amber-100 text-amber-700 border border-amber-200'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 hover:border-red-200 transition shadow-sm">
             <Trash2 className="w-5 h-5" />
           </button>
           <button type="button" onClick={() => setActiveTab('qr')} className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition shadow-md font-bold text-sm">
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="Full History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Service Level" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-slate-900 rounded-2xl border border-slate-200 shadow-xl overflow-hidden group relative min-h-[300px] flex items-center justify-center">
                  <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:16px_16px]"></div>
                  {device.image ? (
                    <img 
                      src={device.image} 
                      alt={device.name} 
                      className="w-full h-full object-contain relative z-10 transition-transform duration-300 group-hover:scale-[1.02]" 
                    />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 relative z-10">
                      <Camera className="w-16 h-16 mb-4 opacity-20" />
                      <p className="text-xs font-black uppercase tracking-[0.2em] opacity-40">No Asset Visual</p>
                    </div>
                  )}
                  <div className="absolute bottom-4 right-4 flex gap-2 z-20">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button type="button" onClick={() => imageInputRef.current?.click()} className="p-3 bg-white/90 backdrop-blur text-slate-900 rounded-xl shadow-xl hover:bg-white transition" title="Update Photo">
                      <Camera className="w-4 h-4" />
                    </button>
                    {device.image && (
                      <button type="button" onClick={() => setShowFullImage(true)} className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition" title="View Fullscreen">
                        <Maximize2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4 flex flex-col justify-center">
                  <div className="flex items-center gap-2 mb-4">
                    <Info className="w-5 h-5 text-blue-600" />
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Master Specification</h3>
                  </div>
                  <InfoRow label="Manufacturer" value={device.manufacturer} />
                  <InfoRow label="Serial Number" value={device.serialNumber} />
                  <InfoRow label="Clinical Dept" value={device.department} />
                  <InfoRow label="Purchase Date" value={device.purchaseDate} />
                  <div className="pt-4 mt-auto">
                    <div className="flex items-center gap-2 px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl">
                      <Activity className="w-4 h-4 text-green-500" />
                      <span className="text-[10px] font-bold text-slate-500 uppercase">Real-time health:</span>
                      <span className="text-xs font-black text-slate-900">NOMINAL</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Service Reports */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <FileCheck className="w-5 h-5 text-green-600" /> Maintenance & Service Reports
                   </h3>
                   <button type="button" onClick={() => { setSelectedFileType('report'); fileInputRef.current?.click(); }} className="text-xs font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl hover:bg-blue-100 transition flex items-center gap-2">
                     <Plus className="w-4 h-4" /> ATTACH REPORT
                   </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-300 hover:shadow-lg transition-all group cursor-pointer relative" onClick={(e) => handleOpenFile(e, report)}>
                      <div className="flex items-center gap-4">
                        <div className="p-3 bg-white rounded-xl shadow-sm group-hover:bg-blue-50 transition">
                          <ClipboardList className="w-5 h-5 text-slate-400 group-hover:text-blue-600" />
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-900 truncate max-w-[150px]">{report.name}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">Verified • {report.dateAdded}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-1">
                        <div className="p-2 text-slate-300 group-hover:text-blue-500 transition">
                           <Download className="w-4 h-4" />
                        </div>
                        <button 
                          type="button"
                          onClick={(e) => handleDeleteFile(e, report.id)}
                          className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 relative z-30"
                          title="Delete Report"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                  {reports.length === 0 && (
                    <div className="col-span-full py-12 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">
                      No service reports found.
                    </div>
                  )}
                </div>
              </div>

              {/* Components */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <Package className="w-5 h-5 text-violet-600" /> Modular Assemblies
                   </h3>
                   <button type="button" onClick={() => setShowComponentModal(true)} className="text-xs font-black text-violet-600 bg-violet-50 px-4 py-2 rounded-xl hover:bg-violet-100 transition flex items-center gap-2">
                     <Plus className="w-4 h-4" /> REGISTER PART
                   </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {device.components?.map(comp => (
                    <div key={comp.id} className="p-4 border border-slate-100 rounded-2xl bg-slate-50 flex items-center justify-between group">
                      <div>
                        <p className="text-sm font-bold text-slate-900">{comp.name}</p>
                        <p className="text-[10px] font-mono text-slate-500">SN: {comp.serialNumber || 'N/A'}</p>
                      </div>
                      <button type="button" onClick={() => removeComponent(comp.id)} className="p-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Library Tools */}
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <FileText className="w-4 h-4" /> Technical Library
                 </h3>
                 <div className="space-y-6">
                   <div>
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Operator Manuals</p>
                     <div className="space-y-2">
                       {manuals.map(m => (
                         <div key={m.id} className="flex items-center justify-between group cursor-pointer p-1 rounded-lg hover:bg-slate-50 transition-all">
                           <div className="flex items-center gap-2 truncate flex-1 text-xs font-bold text-blue-600" onClick={(e) => handleOpenFile(e, m)}>
                             <Download className="w-3.5 h-3.5 opacity-40" /> 
                             <span className="truncate">{m.name}</span>
                           </div>
                           <button 
                             type="button"
                             onClick={(e) => handleDeleteFile(e, m.id)}
                             className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all relative z-30"
                             title="Delete Manual"
                           >
                             <Trash2 className="w-3.5 h-3.5" />
                           </button>
                         </div>
                       ))}
                       <button type="button" onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">
                         + NEW DOCUMENT
                       </button>
                     </div>
                   </div>

                   <div className="pt-4 border-t border-slate-50">
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Support Data</p>
                     <div className="space-y-1">
                        {device.files.filter(f => f.type === 'other').map(f => (
                          <div key={f.id} className="flex items-center justify-between group p-1 rounded-lg hover:bg-slate-50 transition-all cursor-pointer">
                            <div className="flex items-center gap-2 truncate flex-1" onClick={(e) => handleOpenFile(e, f)}>
                              <span className="text-xs font-medium text-slate-600 truncate group-hover:text-blue-600">{f.name}</span>
                            </div>
                            <div className="flex items-center gap-1">
                              <Download className="w-3.5 h-3.5 text-slate-300" />
                              <button 
                                type="button"
                                onClick={(e) => handleDeleteFile(e, f.id)}
                                className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all relative z-30"
                                title="Delete Support File"
                              >
                                <Trash2 className="w-3.5 h-3.5" />
                              </button>
                            </div>
                          </div>
                        ))}
                     </div>
                     <button type="button" onClick={() => { setSelectedFileType('other'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 bg-slate-50 text-[10px] font-black text-slate-500 rounded-xl hover:bg-slate-100 transition">
                       + ADD SUPPORT FILE
                     </button>
                   </div>
                 </div>
              </div>

              <div className="bg-slate-900 text-white p-7 rounded-3xl shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-[-20px] right-[-20px] w-32 h-32 bg-blue-600/20 blur-3xl group-hover:bg-blue-600/40 transition-all duration-700"></div>
                 <div className="relative z-10 space-y-8">
                   <div>
                     <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Next Calibration</p>
                     <p className="text-3xl font-bold mt-1 tracking-tight">
                       {device.maintenanceHistory[0]?.nextScheduledDate || "PENDING"}
                     </p>
                   </div>
                   <div className="flex items-center gap-4">
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-4 rounded-2xl border border-white/10">
                        <p className="text-[9px] font-bold text-slate-400 uppercase">Operational Status</p>
                        <p className="text-lg font-bold text-green-400 mt-1">OPTIMAL</p>
                     </div>
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-4 rounded-2xl border border-white/10">
                        <p className="text-[9px] font-bold text-slate-400 uppercase">Compliance</p>
                        <p className="text-lg font-bold text-blue-400 mt-1">100%</p>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* Full Image Preview */}
        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="Asset Detail" className="max-w-full max-h-full object-contain shadow-2xl" />
          </div>
        )}

        {/* Modal for Components */}
        {showComponentModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
            <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden animate-fade-in">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                <h3 className="font-black text-[11px] uppercase tracking-widest text-slate-900 flex items-center gap-2"><Package className="w-5 h-5 text-blue-600" /> New Component</h3>
                <button type="button" onClick={() => setShowComponentModal(false)} className="text-slate-400 hover:text-slate-600 transition"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-8 space-y-6">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Component Name</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none transition" value={newComponent.name} onChange={e => setNewComponent({...newComponent, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Serial Number</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none transition" value={newComponent.serialNumber} onChange={e => setNewComponent({...newComponent, serialNumber: e.target.value})} />
                </div>
                <button type="button" onClick={handleAddComponent} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold">Register Part</button>
              </div>
            </div>
          </div>
        )}

        {/* Maintenance Schedule View */}
        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
               <div>
                  <h3 className="text-2xl font-bold text-slate-900">Clinical History</h3>
                  <p className="text-sm text-slate-500 mt-1">Maintenance and calibration logs.</p>
               </div>
               <button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3 bg-violet-600 text-white rounded-2xl font-bold flex items-center gap-2 transition disabled:opacity-50">
                 <Wand2 className="w-5 h-5" /> {isAnalyzing ? "Analyzing..." : "AI Intelligence"}
               </button>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between hover:shadow-md transition">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600">{record.description}</p>
                      <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Engineer: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right font-bold text-slate-900">{record.date}</div>
                </div>
              ))}
            </div>

            <button type="button" onClick={() => setShowMaintenanceModal(true)} className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 hover:text-blue-500 transition-all flex items-center justify-center gap-2">
              <Plus className="w-5 h-5" /> REGISTER NEW SERVICE EVENT
            </button>
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4" placeholder="Summary of work..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <button 
              type="button"
              onClick={() => {
                const newR: MaintenanceRecord = { id: crypto.randomUUID(), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Admin', description: maintenanceForm.description || '', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setShowMaintenanceModal(false);
              }}
              className="w-full py-4 bg-green-600 text-white rounded-2xl font-bold"
            >
              Confirm Log
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button
    type="button"
    onClick={onClick}
    className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${
      active ? 'border-blue-600 text-blue-600 scale-105' : 'border-transparent text-slate-400 hover:text-slate-600'
    }`}
  >
    {icon}
    {label}
  </button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

export default DeviceDetail;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 9),
      ...newComponent
    };
    onUpdate({ ...device, components: [...(device.components || []), component] });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    onUpdate({ ...device, components: (device.components || []).filter(c => c.id !== id) });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFile: DeviceFile = {
          id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 9),
          name: file.name,
          type: selectedFileType,
          url: reader.result as string,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
      };
      reader.readAsDataURL(file);
    }
  };

  // Robust Deletion: Force separation from parent click events
  const handleDeleteFile = (e: React.MouseEvent, fileId: string) => {
    e.preventDefault();
    e.stopPropagation();

    // We update the state immediately for a responsive feel
    const updatedFiles = device.files.filter(f => f.id !== fileId);
    onUpdate({ ...device, files: updatedFiles });
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') return alert('Sample file placeholder.');
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');
  const others = device.files.filter(f => f.type === 'other');

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion: ${res.recommendedType} every ${res.frequency}. Tasks: ${res.tasks.join(', ')}`);
    } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider shadow-sm ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700 border border-green-200' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-amber-100 text-amber-700 border border-amber-200'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm">
             <Trash2 className="w-5 h-5" />
           </button>
           <button type="button" onClick={() => setActiveTab('qr')} className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition shadow-md font-bold text-sm">
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Contracts" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Photo Display */}
                <div className="bg-slate-900 rounded-2xl border border-slate-200 shadow-xl overflow-hidden group relative min-h-[300px] flex items-center justify-center">
                  <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:16px_16px]"></div>
                  {device.image ? (
                    <img 
                      src={device.image} 
                      alt={device.name} 
                      className="w-full h-full object-contain relative z-10" 
                    />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 relative z-10">
                      <Camera className="w-16 h-16 mb-4 opacity-20" />
                      <p className="text-xs font-black uppercase tracking-[0.2em] opacity-40">No Asset Visual</p>
                    </div>
                  )}
                  <div className="absolute bottom-4 right-4 flex gap-2 z-20">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button type="button" onClick={() => imageInputRef.current?.click()} className="p-3 bg-white/90 backdrop-blur text-slate-900 rounded-xl shadow-xl hover:bg-white transition">
                      <Camera className="w-4 h-4" />
                    </button>
                    {device.image && (
                      <button type="button" onClick={() => setShowFullImage(true)} className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition">
                        <Maximize2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                  <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400 flex items-center gap-2">
                    <Info className="w-4 h-4" /> Master Specification
                  </h3>
                  <InfoRow label="Manufacturer" value={device.manufacturer} />
                  <InfoRow label="Serial Number" value={device.serialNumber} />
                  <InfoRow label="Department" value={device.department} />
                  <InfoRow label="Purchased" value={device.purchaseDate} />
                  <div className="mt-auto pt-4 flex items-center gap-3 px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl">
                    <Activity className="w-4 h-4 text-green-500" />
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Real-time health:</span>
                    <span className="text-xs font-black text-slate-900">NOMINAL</span>
                  </div>
                </div>
              </div>

              {/* Service Reports */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <FileCheck className="w-5 h-5 text-green-600" /> Service Reports
                   </h3>
                   <button type="button" onClick={() => { setSelectedFileType('report'); fileInputRef.current?.click(); }} className="text-[10px] font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl hover:bg-blue-100 transition flex items-center gap-2">
                     <Plus className="w-4 h-4" /> ADD REPORT
                   </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-300 hover:shadow-lg transition-all group relative">
                      <div className="flex items-center gap-4 flex-1 cursor-pointer" onClick={(e) => handleOpenFile(e, report)}>
                        <div className="p-3 bg-white rounded-xl shadow-sm group-hover:bg-blue-50 transition">
                          <ClipboardList className="w-5 h-5 text-slate-400 group-hover:text-blue-600" />
                        </div>
                        <div className="truncate">
                          <p className="text-sm font-bold text-slate-900 truncate">{report.name}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">{report.dateAdded}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-1 pl-2 border-l border-slate-200 ml-2 shrink-0">
                        <button 
                          type="button" 
                          onClick={(e) => handleDeleteFile(e, report.id)}
                          className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                          title="Delete File"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                  {reports.length === 0 && (
                    <div className="col-span-full py-12 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">
                      No service reports attached.
                    </div>
                  )}
                </div>
              </div>

              {/* Components */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <Package className="w-5 h-5 text-violet-600" /> Modular Components
                   </h3>
                   <button type="button" onClick={() => setShowComponentModal(true)} className="text-[10px] font-black text-violet-600 bg-violet-50 px-4 py-2 rounded-xl hover:bg-violet-100 transition flex items-center gap-2">
                     <Plus className="w-4 h-4" /> REGISTER PART
                   </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {device.components?.map(comp => (
                    <div key={comp.id} className="p-4 border border-slate-100 rounded-2xl bg-slate-50 flex items-center justify-between group">
                      <div>
                        <p className="text-sm font-bold text-slate-900">{comp.name}</p>
                        <p className="text-[10px] font-mono text-slate-400">SN: {comp.serialNumber || 'N/A'}</p>
                      </div>
                      <button type="button" onClick={() => removeComponent(comp.id)} className="p-2 text-slate-300 hover:text-red-500 transition opacity-0 group-hover:opacity-100">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Library Section */}
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <FileText className="w-4 h-4" /> Technical Library
                 </h3>
                 <div className="space-y-6">
                   <div>
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Operator Manuals</p>
                     <div className="space-y-2">
                       {manuals.map(m => (
                         <div key={m.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                           <div className="flex items-center gap-2 truncate flex-1 text-xs font-bold text-blue-600 cursor-pointer" onClick={(e) => handleOpenFile(e, m)}>
                             <Download className="w-3.5 h-3.5 opacity-40 shrink-0" /> 
                             <span className="truncate">{m.name}</span>
                           </div>
                           <button 
                             type="button"
                             onClick={(e) => handleDeleteFile(e, m.id)}
                             className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all ml-1"
                             title="Delete Manual"
                           >
                             <Trash2 className="w-3.5 h-3.5" />
                           </button>
                         </div>
                       ))}
                       <button type="button" onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">
                         + ADD MANUAL
                       </button>
                     </div>
                   </div>

                   <div className="pt-4 border-t border-slate-50">
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Additional Files</p>
                     <div className="space-y-2">
                        {others.map(f => (
                          <div key={f.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                            <div className="flex items-center gap-2 truncate flex-1 cursor-pointer" onClick={(e) => handleOpenFile(e, f)}>
                              <span className="text-xs font-medium text-slate-600 truncate group-hover:text-blue-600">{f.name}</span>
                            </div>
                            <button 
                              type="button"
                              onClick={(e) => handleDeleteFile(e, f.id)}
                              className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all ml-1"
                              title="Delete Support File"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        ))}
                     </div>
                     <button type="button" onClick={() => { setSelectedFileType('other'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 bg-slate-50 text-[10px] font-black text-slate-500 rounded-xl hover:bg-slate-100 transition">
                       + UPLOAD SUPPORT FILE
                     </button>
                   </div>
                 </div>
              </div>

              <div className="bg-slate-900 text-white p-7 rounded-3xl shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-[-20px] right-[-20px] w-32 h-32 bg-blue-600/20 blur-3xl group-hover:bg-blue-600/40 transition-all duration-700"></div>
                 <div className="relative z-10 space-y-6">
                   <div>
                     <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Next Calibration</p>
                     <p className="text-2xl font-bold mt-1 tracking-tight">
                       {device.maintenanceHistory[0]?.nextScheduledDate || "UNSCHEDULED"}
                     </p>
                   </div>
                   <div className="flex items-center gap-3">
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-3 rounded-2xl border border-white/10">
                        <p className="text-[8px] font-bold text-slate-400 uppercase">Operational</p>
                        <p className="text-base font-bold text-green-400 mt-0.5">OPTIMAL</p>
                     </div>
                     <div className="flex-1 bg-white/5 backdrop-blur-sm p-3 rounded-2xl border border-white/10">
                        <p className="text-[8px] font-bold text-slate-400 uppercase">Compliance</p>
                        <p className="text-base font-bold text-blue-400 mt-0.5">100%</p>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* Modal: Manual History View */}
        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
               <div>
                  <h3 className="text-2xl font-bold text-slate-900">Engineering Log</h3>
                  <p className="text-sm text-slate-500 mt-1">Full service and calibration history.</p>
               </div>
               <button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3 bg-violet-600 text-white rounded-2xl font-bold flex items-center gap-2 transition disabled:opacity-50">
                 <Wand2 className="w-5 h-5" /> {isAnalyzing ? "Analyzing..." : "AI Suggestion"}
               </button>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600 line-clamp-2">{record.description}</p>
                      <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Verified by: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right font-bold text-slate-900 whitespace-nowrap">{record.date}</div>
                </div>
              ))}
            </div>

            <button type="button" onClick={() => setShowMaintenanceModal(true)} className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 transition-all flex items-center justify-center gap-2">
              <Plus className="w-5 h-5" /> RECORD SERVICE EVENT
            </button>
          </div>
        )}

        {/* Full Image Preview */}
        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8 animate-fade-in" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="High Resolution Detail" className="max-w-full max-h-full object-contain shadow-2xl" />
          </div>
        )}

        {/* Modal: Add Component */}
        {showComponentModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
            <div className="bg-white rounded-3xl shadow-2xl max-w-md w-full overflow-hidden animate-fade-in">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                <h3 className="font-black text-[11px] uppercase tracking-widest text-slate-900 flex items-center gap-2"><Package className="w-5 h-5 text-blue-600" /> Register Part</h3>
                <button type="button" onClick={() => setShowComponentModal(false)} className="text-slate-400"><X className="w-6 h-6" /></button>
              </div>
              <div className="p-8 space-y-6">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Name</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none" value={newComponent.name} onChange={e => setNewComponent({...newComponent, name: e.target.value})} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">SN</label>
                  <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none" value={newComponent.serialNumber} onChange={e => setNewComponent({...newComponent, serialNumber: e.target.value})} />
                </div>
                <button type="button" onClick={handleAddComponent} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold">Register Module</button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Modal: Service Event */}
      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none min-h-[100px]" placeholder="Work summary..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <div className="flex gap-4">
              <button type="button" onClick={() => setShowMaintenanceModal(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold">Cancel</button>
              <button 
                type="button"
                onClick={() => {
                  const newR: MaintenanceRecord = { id: Math.random().toString(36).substring(7), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Engineering Dept', description: maintenanceForm.description || 'No details provided', completed: true };
                  onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                  setShowMaintenanceModal(false);
                }}
                className="flex-2 px-8 py-4 bg-green-600 text-white rounded-2xl font-bold"
              >
                Log Event
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button
    type="button"
    onClick={onClick}
    className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${
      active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'
    }`}
  >
    {icon}
    {label}
  </button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

export default DeviceDetail;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2
} from 'lucide-react';
import { analyzeContractText, suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB Limit

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showContractModal, setShowContractModal] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);
  const [showComponentModal, setShowComponentModal] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  const [newComponent, setNewComponent] = useState({
    name: '',
    serialNumber: '',
    status: DeviceStatus.ACTIVE
  });

  const [maintenanceForm, setMaintenanceForm] = useState<Partial<MaintenanceRecord>>({
    date: new Date().toISOString().split('T')[0],
    type: MaintenanceType.PREVENTIVE,
    technician: '',
    description: '',
    completed: false,
    nextScheduledDate: ''
  });

  const handleAddComponent = () => {
    if (!newComponent.name) return;
    const component: DeviceComponent = {
      id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 9),
      ...newComponent
    };
    onUpdate({ ...device, components: [...(device.components || []), component] });
    setNewComponent({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE });
    setShowComponentModal(false);
  };

  const removeComponent = (id: string) => {
    onUpdate({ ...device, components: (device.components || []).filter(c => c.id !== id) });
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      if (file.size > MAX_FILE_SIZE) {
        alert("Photo is too large. Please select an image under 2MB.");
        e.target.value = '';
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ ...device, image: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];

      if (file.size > MAX_FILE_SIZE) {
        alert(`The file "${file.name}" exceeds the 2MB limit. Please compress or select a smaller file.`);
        e.target.value = '';
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        const newFile: DeviceFile = {
          id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 9),
          name: file.name,
          type: selectedFileType,
          url: reader.result as string,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDeleteFile = (e: React.MouseEvent, fileId: string) => {
    e.preventDefault();
    e.stopPropagation();
    const updatedFiles = device.files.filter(f => f.id !== fileId);
    onUpdate({ ...device, files: updatedFiles });
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') return alert('Sample file placeholder.');
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');
  const others = device.files.filter(f => f.type === 'other');

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion: ${res.recommendedType} every ${res.frequency}. Tasks: ${res.tasks.join(', ')}`);
    } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full">
      {/* Header */}
      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider shadow-sm ${
              device.status === DeviceStatus.ACTIVE ? 'bg-green-100 text-green-700 border border-green-200' : 
              device.status === DeviceStatus.BROKEN ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-amber-100 text-amber-700 border border-amber-200'
            }`}>
              {device.status}
            </span>
          </div>
        </div>
        <div className="flex gap-2">
           <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm">
             <Trash2 className="w-5 h-5" />
           </button>
           <button type="button" onClick={() => setActiveTab('qr')} className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-lg hover:bg-slate-800 transition shadow-md font-bold text-sm">
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Contracts" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Photo Display */}
                <div className="bg-slate-900 rounded-2xl border border-slate-200 shadow-xl overflow-hidden group relative min-h-[300px] flex items-center justify-center">
                  <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:16px_16px]"></div>
                  {device.image ? (
                    <img 
                      src={device.image} 
                      alt={device.name} 
                      className="w-full h-full object-contain relative z-10" 
                    />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 relative z-10">
                      <Camera className="w-16 h-16 mb-4 opacity-20" />
                      <p className="text-xs font-black uppercase tracking-[0.2em] opacity-40">No Asset Visual</p>
                    </div>
                  )}
                  <div className="absolute bottom-4 right-4 flex gap-2 z-20">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button type="button" onClick={() => imageInputRef.current?.click()} className="p-3 bg-white/90 backdrop-blur text-slate-900 rounded-xl shadow-xl hover:bg-white transition flex flex-col items-center gap-1">
                      <Camera className="w-4 h-4" />
                      <span className="text-[8px] font-black opacity-40 uppercase">Max 2MB</span>
                    </button>
                    {device.image && (
                      <button type="button" onClick={() => setShowFullImage(true)} className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition">
                        <Maximize2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                  <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400 flex items-center gap-2">
                    <span className="p-1.5 bg-blue-50 text-blue-600 rounded-lg"><Info className="w-4 h-4" /></span> Master Specification
                  </h3>
                  <InfoRow label="Manufacturer" value={device.manufacturer} />
                  <InfoRow label="Serial Number" value={device.serialNumber} />
                  <InfoRow label="Department" value={device.department} />
                  <InfoRow label="Purchased" value={device.purchaseDate} />
                  <div className="mt-auto pt-4 flex items-center gap-3 px-4 py-3 bg-slate-50 border border-slate-100 rounded-xl">
                    <Activity className="w-4 h-4 text-green-500" />
                    <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Real-time health:</span>
                    <span className="text-xs font-black text-slate-900">NOMINAL</span>
                  </div>
                </div>
              </div>

              {/* Service Reports */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <FileCheck className="w-5 h-5 text-green-600" /> Service Reports
                   </h3>
                   <div className="flex flex-col items-end gap-1">
                    <button type="button" onClick={() => { setSelectedFileType('report'); fileInputRef.current?.click(); }} className="text-[10px] font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl hover:bg-blue-100 transition flex items-center gap-2">
                      <Plus className="w-4 h-4" /> ADD REPORT
                    </button>
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Max 2MB per file</span>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-300 hover:shadow-lg transition-all group relative">
                      <div className="flex items-center gap-4 flex-1 cursor-pointer" onClick={(e) => handleOpenFile(e, report)}>
                        <div className="p-3 bg-white rounded-xl shadow-sm group-hover:bg-blue-50 transition">
                          <ClipboardList className="w-5 h-5 text-slate-400 group-hover:text-blue-600" />
                        </div>
                        <div className="truncate">
                          <p className="text-sm font-bold text-slate-900 truncate">{report.name}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">{report.dateAdded}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-1 pl-2 border-l border-slate-200 ml-2 shrink-0">
                        <button 
                          type="button" 
                          onClick={(e) => handleDeleteFile(e, report.id)}
                          className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                          title="Delete File"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                  {reports.length === 0 && (
                    <div className="col-span-full py-12 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">
                      No service reports attached.
                    </div>
                  )}
                </div>
              </div>

              {/* Components */}
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                     <Package className="w-5 h-5 text-violet-600" /> Modular Components
                   </h3>
                   <button type="button" onClick={() => setShowComponentModal(true)} className="text-[10px] font-black text-violet-600 bg-violet-50 px-4 py-2 rounded-xl hover:bg-violet-100 transition flex items-center gap-2">
                     <Plus className="w-4 h-4" /> REGISTER PART
                   </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {device.components?.map(comp => (
                    <div key={comp.id} className="p-4 border border-slate-100 rounded-2xl bg-slate-50 flex items-center justify-between group">
                      <div>
                        <p className="text-sm font-bold text-slate-900">{comp.name}</p>
                        <p className="text-[10px] font-mono text-slate-400">SN: {comp.serialNumber || 'N/A'}</p>
                      </div>
                      <button type="button" onClick={() => removeComponent(comp.id)} className="p-2 text-slate-300 hover:text-red-500 transition opacity-0 group-hover:opacity-100">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Library Section */}
            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                      <FileText className="w-4 h-4" /> Technical Library
                    </h3>
                    <span className="text-[8px] font-black text-slate-300 uppercase tracking-[0.2em]">Limit: 2MB</span>
                 </div>
                 <div className="space-y-6">
                   <div>
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Operator Manuals</p>
                     <div className="space-y-2">
                       {manuals.map(m => (
                         <div key={m.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                           <div className="flex items-center gap-2 truncate flex-1 text-xs font-bold text-blue-600 cursor-pointer" onClick={(e) => handleOpenFile(e, m)}>
                             <Download className="w-3.5 h-3.5 opacity-40 shrink-0" /> 
                             <span className="truncate">{m.name}</span>
                           </div>
                           <button 
                             type="button"
                             onClick={(e) => handleDeleteFile(e, m.id)}
                             className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all ml-1"
                             title="Delete Manual"
                           >
                             <Trash2 className="w-3.5 h-3.5" />
                           </button>
                         </div>
                       ))}
                       <button type="button" onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">
                         + ADD MANUAL
                       </button>
                     </div>
                   </div>

                   <div className="pt-4 border-t border-slate-50">
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Additional Files</p>
                     <div className="space-y-2">
                        {others.map(f => (
                          <div key={f.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                            <div className="flex items-center gap-2 truncate flex-1 cursor-pointer" onClick={(e) => handleOpenFile(e, f)}>
                              <span className="text-xs font-medium text-slate-600 truncate group-hover:text-blue-600">{f.name}</span>
                            </div>
                            <button 
                              type="button"
                              onClick={(e) => handleDeleteFile(e, f.id)}
                              className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all ml-1"
                              title="Delete Support File"
