                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-300 hover:shadow-lg transition-all group relative">
