                             <Download className="w-3.5 h-3.5 opacity-40 shrink-0" /> 
                             <span className="truncate">{m.name}</span>
                           </div>
                           <button type="button" onClick={(e) => handleDeleteFile(e, m.id)} className="p-1.5 text-slate-300 hover:text-red-500 transition ml-1"><Trash2 className="w-3.5 h-3.5" /></button>
                         </div>
                       ))}
                       <button type="button" onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">+ ADD MANUAL</button>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
               <div>
                  <h3 className="text-2xl font-bold text-slate-900">Engineering Log</h3>
                  <p className="text-sm text-slate-500 mt-1">Full service and calibration history.</p>
               </div>
               <button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3 bg-violet-600 text-white rounded-2xl font-bold flex items-center gap-2 transition disabled:opacity-50">
                 <Wand2 className="w-5 h-5" /> {isAnalyzing ? "Analyzing..." : "AI Suggestion"}
               </button>
            </div>
            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600 line-clamp-2">{record.description}</p>
                      <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Verified by: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right font-bold text-slate-900 whitespace-nowrap">{record.date}</div>
                </div>
              ))}
            </div>
            <button type="button" onClick={() => setShowMaintenanceModal(true)} className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 transition flex items-center justify-center gap-2">+ RECORD SERVICE EVENT</button>
          </div>
        )}

        {activeTab === 'qr' && (
          <div className="max-w-xl mx-auto space-y-8 py-10 animate-fade-in">
             <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 flex flex-col items-center text-center">
                <div className="mb-8">
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Digital Asset Passport</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-2">Unique Identification QR</p>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-inner border-4 border-slate-50 mb-8">
                  <img src={qrCodeUrl} alt="QR Code" className="w-64 h-64" />
                </div>

                <div className="space-y-4 w-full">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-left">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Encrypted Link</p>
                    <p className="text-xs font-mono text-slate-600 break-all">{qrLink}</p>
                  </div>

                  <div className="flex gap-4">
                    <button 
                        onClick={printQrCode}
                        className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-black transition shadow-xl"
                    >
                      <Printer className="w-5 h-5" /> PRINT LABEL
                    </button>
                    <a 
                      href={qrCodeUrl} 
                      download={`${device.name}-qr.png`}
                      className="flex-1 py-4 bg-white border border-slate-200 text-slate-900 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition shadow-sm"
                    >
                      <Download className="w-5 h-5" /> DOWNLOAD
                    </a>
                  </div>
                </div>

                <p className="mt-8 text-xs text-slate-400 leading-relaxed max-w-xs">
                  Physical assets tagged with this QR can be scanned by any authorized mobile device to immediately pull up service records.
                </p>
             </div>
          </div>
        )}

        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="High Resolution Detail" className="max-w-full max-h-full object-contain shadow-2xl" />
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none min-h-[100px]" placeholder="Work summary..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <div className="flex gap-4">
              <button type="button" onClick={() => setShowMaintenanceModal(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold">Cancel</button>
              <button type="button" onClick={() => {
                const newR: MaintenanceRecord = { id: Math.random().toString(36).substring(7), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Engineering Dept', description: maintenanceForm.description || 'No details provided', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setShowMaintenanceModal(false);
              }} className="flex-2 px-8 py-4 bg-green-600 text-white rounded-2xl font-bold">Log Event</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
  if (status === DeviceStatus.ACTIVE) color = "bg-green-100 text-green-700 border-green-200";
  if (status === DeviceStatus.BROKEN) color = "bg-red-100 text-red-700 border-red-200";
  if (status === DeviceStatus.MAINTENANCE) color = "bg-amber-100 text-amber-700 border-amber-200";
  return <span className={`px-2.5 py-1 border rounded-full text-xs font-semibold shadow-sm uppercase ${color}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button type="button" onClick={onClick} className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>{icon}{label}</button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

export default DeviceDetail;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { Html5QrcodeScanner } from 'html5-qrcode';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const getLocalData = (): MedicalDevice[] => {
    try {
      const savedData = localStorage.getItem('meditrack_devices');
      return savedData ? JSON.parse(savedData) : MOCK_DEVICES;
    } catch (e) {
      return MOCK_DEVICES;
    }
  };

  // 1. Initial Data Loading
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*');
          if (error) throw error;
          if (data) loadedDevices = data as MedicalDevice[];
        } catch (error) {
          loadedDevices = getLocalData();
        }
      } else {
        loadedDevices = getLocalData();
      }
      setDevices(loadedDevices);
      setIsLoading(false);
    };
    loadData();
  }, []);

  // 2. Reactive Deep Linking (Handles scan from phone's native camera or URL update)
  useEffect(() => {
    if (devices.length === 0) return;

    const checkDeepLink = () => {
      const params = new URLSearchParams(window.location.search);
      const deviceId = params.get('deviceId');
      if (deviceId) {
        const target = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
        if (target) {
          setSelectedDevice(target);
          setView('DEVICE_DETAIL');
          // Clear query param without refreshing to keep URL clean after handling
          window.history.replaceState({}, '', window.location.pathname);
        }
      }
    };

    checkDeepLink();
    window.addEventListener('popstate', checkDeepLink);
    return () => window.removeEventListener('popstate', checkDeepLink);
  }, [devices]);

  // 3. In-App Scanner Implementation
  useEffect(() => {
    if (isScannerOpen) {
      // Use shorter timeout to wait for modal animation
      const timer = setTimeout(() => {
        try {
          const scanner = new Html5QrcodeScanner(
            "reader",
            { 
              fps: 15, 
              qrbox: { width: 250, height: 250 },
              aspectRatio: 1.0,
              showTorchButtonIfSupported: true
            },
            /* verbose= */ false
          );

          scanner.render((decodedText) => {
            let deviceId = decodedText;
            // Handle full URL strings in the scan
            if (decodedText.includes('deviceId=')) {
              try {
                const url = new URL(decodedText);
                deviceId = url.searchParams.get('deviceId') || decodedText;
              } catch (e) {}
            }

            const found = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
            if (found) {
              scanner.clear();
              setIsScannerOpen(false);
              handleSelectDevice(found);
            } else {
              alert(`Device not found: ${deviceId}. Ensure your phone is synced with the same data source.`);
            }
          }, (error) => {});

          scannerRef.current = scanner;
        } catch (e) {
          console.error("Scanner init failed", e);
        }
      }, 300);
      return () => clearTimeout(timer);
    } else {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(e => console.error(e));
        scannerRef.current = null;
      }
    }
  }, [isScannerOpen, devices]);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      localStorage.setItem('meditrack_devices', JSON.stringify(newDevices));
      setDevices(newDevices);
    } catch (e: any) {
      if (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED') {
        alert("CRITICAL: Browser storage is full! Please delete some old devices or remove large file attachments to save new changes.");
      } else {
        console.error("Storage error:", e);
      }
      return;
    }

    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').delete().eq('id', changedDevice.id);
        } else if (action === 'INSERT' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').insert([changedDevice]);
        } else if (action === 'UPDATE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        } else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) {
          await supabase.from('devices').insert(changedDevice);
        }
      } catch (err) {
        console.error("Cloud sync failed:", err);
      }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      persistDeviceChange(importedDevices);
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button 
      onClick={() => { setView(targetView); setSidebarOpen(false); }}
      className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${
        view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'
      }`}
    >
      {icon}
      {label}
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />}
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button 
              onClick={() => { setIsScannerOpen(true); setSidebarOpen(false); }}
              className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"
            >
              <QrCode className="w-5 h-5" /> Scan QR Code
            </button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }}
               className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
              <SettingsIcon className="w-5 h-5" /> Settings
            </button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-xs text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900">
                  <Cloud className="w-3 h-3" /> <span>Cloud Connected</span>
                </div>
              ) : (
                <div className="flex items-center gap-2 text-xs text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900">
                  <CloudOff className="w-3 h-3" /> <span>Offline Mode</span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs">JD</div>
              <div><p className="text-sm font-medium">Jane Doe</p><p className="text-xs text-slate-500">Clinical Engineer</p></div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sm font-medium text-blue-600">Syncing database...</p>
            </div>
          </div>
        )}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-lg font-semibold text-slate-800">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Device Inventory'}
               {view === 'PLANNER' && 'Maintenance Planner'}
               {view === 'ADD_DEVICE' && 'Register Device'}
               {view === 'DEVICE_DETAIL' && 'Device Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && (
              <DeviceList 
                devices={devices} 
                onSelectDevice={handleSelectDevice} 
                onDelete={handleDeleteDevice}
                onAddDevice={() => setView('ADD_DEVICE')} 
              />
            )}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && (
              <DeviceDetail 
                device={selectedDevice} 
                onBack={() => setView('INVENTORY')}
                onUpdate={handleUpdateDevice}
                onDelete={() => handleDeleteDevice(selectedDevice.id)}
              />
            )}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>

      {/* Enhanced QR Scanner Modal */}
      {isScannerOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900 flex flex-col items-center justify-center p-0 sm:p-4">
          <div className="w-full h-full sm:h-auto sm:max-w-lg bg-white sm:rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-100 rounded-lg"><Camera className="w-5 h-5 text-blue-600" /></div>
                <h3 className="font-black text-slate-900 uppercase tracking-tight">Clinical Scan</h3>
              </div>
              <button onClick={() => setIsScannerOpen(false)} className="p-2 bg-white text-slate-400 hover:text-slate-900 rounded-xl border border-slate-200 shadow-sm transition"><X className="w-6 h-6" /></button>
            </div>

            <div className="flex-1 flex flex-col p-6 overflow-hidden bg-slate-50">
              <div className="relative w-full aspect-square bg-black rounded-3xl overflow-hidden shadow-inner ring-8 ring-white/50">
                <div id="reader" className="w-full h-full"></div>
                {/* Visual Scanning Frame Overlay */}
                <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                   <div className="w-64 h-64 border-2 border-blue-500/50 rounded-2xl relative">
                      <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-blue-500 rounded-tl-xl"></div>
                      <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-blue-500 rounded-tr-xl"></div>
                      <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-blue-500 rounded-bl-xl"></div>
                      <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-blue-500 rounded-br-xl"></div>
                      <div className="absolute inset-0 bg-blue-500/5 animate-pulse"></div>
                   </div>
                </div>
              </div>

              <div className="mt-8 space-y-4">
                <div className="p-4 bg-white rounded-2xl border border-slate-200 flex items-start gap-3">
                   <Info className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
                   <div>
