import React, { useRef, useState, useEffect } from 'react';
import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, Cloud, CheckCircle, Save, Link, LogOut, QrCode, Globe, Smartphone, Wifi, ShieldAlert } from 'lucide-react';
import { isSupabaseConfigured, getSupabaseConfig, saveSupabaseConfig, clearSupabaseConfig } from '../services/supabase';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [config, setConfig] = useState(getSupabaseConfig());
  const [inputUrl, setInputUrl] = useState(config.url || '');
  const [inputKey, setInputKey] = useState(config.key || '');
  const [showKey, setShowKey] = useState(false);

  // QR Settings
  const [baseUrl, setBaseUrl] = useState('');

  useEffect(() => {
    const currentConfig = getSupabaseConfig();
    setConfig(currentConfig);
    setInputUrl(currentConfig.url || '');
    if (!currentConfig.isEnv) {
      setInputKey(currentConfig.key || '');
    }

    const storedBaseUrl = localStorage.getItem('meditrack_base_url');
    // Default to current window origin if nothing stored
    setBaseUrl(storedBaseUrl || window.location.origin);
  }, []);

  const handleSaveCloudConfig = () => {
    if (!inputUrl || !inputKey) {
      alert("Please provide both the Supabase URL and Anon Key.");
      return;
    }
    saveSupabaseConfig(inputUrl, inputKey);
  };

  const handleDisconnectCloud = () => {
    if (window.confirm("Are you sure? You will switch back to offline mode and data won't sync with your phone.")) {
      clearSupabaseConfig();
    }
  };

  const handleSaveBaseUrl = () => {
      let finalUrl = baseUrl.trim();

      // Auto-correct: Add http:// if it's an IP and protocol is missing
      if (finalUrl && !finalUrl.startsWith('http')) {
          finalUrl = 'http://' + finalUrl;
      }

      // Auto-correct: If it's just an IP/host and we are in dev mode, try to append the current port
      if (window.location.port && !finalUrl.includes(':', 7)) {
          finalUrl = finalUrl + ':' + window.location.port;
      }

      localStorage.setItem('meditrack_base_url', finalUrl);
      setBaseUrl(finalUrl);
      alert("QR Base URL Updated: " + finalUrl);
  };

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(devices, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `meditrack_backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (Array.isArray(jsonData)) {
          const isValid = jsonData.every(d => d.id && d.name && d.status);
          if (isValid) {
            if (window.confirm(`Found ${jsonData.length} devices. This will overwrite local data. Continue?`)) {
              onImport(jsonData);
              alert('Import successful!');
            }
          } else {
            alert('Invalid backup file.');
          }
        }
      } catch (error) {
        alert('Error reading file.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in pb-20">

      {/* 1. Cloud Sync Section */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-4 mb-8">
          <div className={`p-4 rounded-2xl ${isSupabaseConfigured ? 'bg-green-100' : 'bg-amber-100'}`}>
            <Cloud className={`w-8 h-8 ${isSupabaseConfigured ? 'text-green-600' : 'text-amber-600'}`} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Cloud Data Sync</h2>
            <p className="text-sm text-slate-500 font-medium">Required for phone scanning and multi-device access.</p>
          </div>
        </div>

        {!isSupabaseConfigured && (
          <div className="mb-8 p-6 bg-amber-50 rounded-2xl border border-amber-100 flex gap-4">
            <AlertTriangle className="w-6 h-6 text-amber-600 shrink-0" />
            <div className="text-sm text-amber-900 font-medium">
              <p className="font-bold">Sync is currently disabled.</p>
              <p className="opacity-80">You can add devices here, but your phone won't see them unless you connect to a Supabase project.</p>
            </div>
          </div>
        )}

        <div className="space-y-5">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Supabase Project URL</label>
              <input 
                type="text" 
                value={inputUrl}
                onChange={(e) => setInputUrl(e.target.value)}
                placeholder="https://xyz.supabase.co"
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Anon Key</label>
              <div className="relative">
                <input 
                  type={showKey ? "text" : "password"}
                  value={inputKey}
                  onChange={(e) => setInputKey(e.target.value)}
                  placeholder="Paste your key here..."
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-mono pr-20"
                />
                <button 
                  onClick={() => setShowKey(!showKey)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-400 hover:text-slate-600"
                >
                  {showKey ? "HIDE" : "SHOW"}
                </button>
              </div>
            </div>

            <div className="pt-4 flex gap-3">
              <button 
                onClick={handleSaveCloudConfig}
                className="flex-1 py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-xl hover:bg-blue-700 transition flex items-center justify-center gap-2"
              >
                <Save className="w-5 h-5" /> {isSupabaseConfigured ? "Update Credentials" : "Connect & Sync"}
              </button>
              {isSupabaseConfigured && (
                <button 
                  onClick={handleDisconnectCloud}
                  className="px-6 py-4 bg-red-50 text-red-600 rounded-2xl font-bold hover:bg-red-100 transition"
                >
                  <LogOut className="w-5 h-5" />
                </button>
              )}
            </div>
        </div>
      </div>

      {/* 2. QR Mobile Access Configuration */}
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-4 rounded-2xl bg-violet-100">
            <Smartphone className="w-8 h-8 text-violet-600" />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Mobile Scanning Access</h2>
            <p className="text-sm text-slate-500 font-medium">Configure how your phone connects to this computer.</p>
          </div>
        </div>

        <div className="space-y-6">
          <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Computer's Network IP (e.g. 192.168.1.5)</label>
             <div className="flex gap-2">
               <input 
                  type="text" 
                  value={baseUrl}
                  onChange={(e) => setBaseUrl(e.target.value)}
                  placeholder="192.168.x.x"
                  className="flex-1 px-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-violet-500 outline-none text-sm font-mono"
                />
                <button 
                  onClick={handleSaveBaseUrl}
                  className="px-6 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-black transition"
                >
                  Apply
                </button>
             </div>

             <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
                <TroubleStep icon={<Wifi className="w-4 h-4" />} title="Same Wi-Fi" text="Phone and PC must be on the same network." />
                <TroubleStep icon={<ShieldAlert className="w-4 h-4" />} title="Firewall" text="Ensure port 5173 is allowed on your PC." />
                <TroubleStep icon={<Globe className="w-4 h-4" />} title="IP Address" text="Use your internal IP, not 'localhost'." />
             </div>
          </div>
        </div>
      </div>

      {/* 3. Manual Backup */}
      <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl text-white">
        <div className="flex items-center gap-4 mb-8">
          <Database className="w-8 h-8 text-blue-400" />
          <h2 className="text-2xl font-black uppercase tracking-tight">Manual Data Vault</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={handleExport}
            className="p-6 bg-white/5 border border-white/10 rounded-3xl hover:bg-white/10 transition text-left group"
          >
            <Download className="w-6 h-6 text-blue-400 mb-4 group-hover:scale-110 transition" />
            <h3 className="font-bold text-lg">Export Backup</h3>
            <p className="text-xs text-slate-400 mt-1">Download your clinical database as a JSON file.</p>
          </button>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-6 bg-white/5 border border-white/10 rounded-3xl hover:bg-white/10 transition text-left group"
          >
            <Upload className="w-6 h-6 text-green-400 mb-4 group-hover:scale-110 transition" />
            <h3 className="font-bold text-lg">Restore Data</h3>
            <p className="text-xs text-slate-400 mt-1">Import devices from a previously saved backup.</p>
            <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </button>
        </div>
      </div>
    </div>
  );
};

const TroubleStep = ({ icon, title, text }: { icon: React.ReactNode, title: string, text: string }) => (
  <div className="p-4 bg-white rounded-2xl border border-slate-100">
    <div className="flex items-center gap-2 text-blue-600 mb-1">
      {icon}
      <span className="text-[10px] font-black uppercase tracking-wider">{title}</span>
    </div>
    <p className="text-[10px] text-slate-500 font-medium leading-relaxed">{text}</p>
  </div>
);

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { Html5QrcodeScanner } from 'html5-qrcode';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [deepLinkPending, setDeepLinkPending] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const getLocalData = (): MedicalDevice[] => {
    try {
      const savedData = localStorage.getItem('meditrack_devices');
      return savedData ? JSON.parse(savedData) : MOCK_DEVICES;
    } catch (e) {
      return MOCK_DEVICES;
    }
  };

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*');
          if (error) throw error;
          if (data) loadedDevices = data as MedicalDevice[];
        } catch (error) {
          loadedDevices = getLocalData();
        }
      } else {
        loadedDevices = getLocalData();
      }
      setDevices(loadedDevices);

      const params = new URLSearchParams(window.location.search);
      const devId = params.get('deviceId');
      if (devId) setDeepLinkPending(devId);

      setIsLoading(false);
    };
    loadData();
  }, []);

  useEffect(() => {
    if (deepLinkPending && devices.length > 0) {
      const target = devices.find(d => d.id === deepLinkPending || d.serialNumber === deepLinkPending);
      if (target) {
        setSelectedDevice(target);
        setView('DEVICE_DETAIL');
        setDeepLinkPending(null);
        window.history.replaceState({}, '', window.location.pathname);
      }
    }
  }, [deepLinkPending, devices]);

  useEffect(() => {
    if (isScannerOpen) {
      const timer = setTimeout(() => {
        try {
          const scanner = new Html5QrcodeScanner("reader", { fps: 15, qrbox: 250 }, false);
          scanner.render((decodedText) => {
            let deviceId = decodedText;
            if (decodedText.includes('deviceId=')) {
              try { deviceId = new URL(decodedText).searchParams.get('deviceId') || decodedText; } catch (e) {}
            }
            const found = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
            if (found) {
              scanner.clear();
              setIsScannerOpen(false);
              handleSelectDevice(found);
            } else {
              alert(`Asset ${deviceId} not found in this device's current database.`);
            }
          }, () => {});
          scannerRef.current = scanner;
        } catch (e) { console.error(e); }
      }, 300);
      return () => clearTimeout(timer);
    } else {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
        scannerRef.current = null;
      }
    }
  }, [isScannerOpen, devices]);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      localStorage.setItem('meditrack_devices', JSON.stringify(newDevices));
      setDevices(newDevices);
    } catch (e: any) {
      console.error(e);
      return;
    }

    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) await supabase.from('devices').delete().eq('id', changedDevice.id);
        else if (action === 'INSERT' && !Array.isArray(changedDevice)) await supabase.from('devices').insert([changedDevice]);
        else if (action === 'UPDATE' && !Array.isArray(changedDevice)) await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) await supabase.from('devices').insert(changedDevice);
      } catch (err) { console.error(err); }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      persistDeviceChange(importedDevices);
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />}
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button onClick={() => { setIsScannerOpen(true); setSidebarOpen(false); }} className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"><QrCode className="w-5 h-5" /> Scan QR Code</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-xs text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900"><Cloud className="w-3 h-3" /> <span>Cloud Connected</span></div>
              ) : (
                <div className="flex items-center gap-2 text-xs text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900"><CloudOff className="w-3 h-3" /> <span>Offline Mode</span></div>
              )}
            </div>
            <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs">JD</div>
              <div><p className="text-sm font-medium">Jane Doe</p><p className="text-xs text-slate-500">Clinical Engineer</p></div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sm font-medium text-blue-600">Syncing data...</p>
            </div>
          </div>
        )}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-lg font-semibold text-slate-800">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Device Inventory'}
               {view === 'PLANNER' && 'Maintenance Planner'}
               {view === 'ADD_DEVICE' && 'Register Device'}
               {view === 'DEVICE_DETAIL' && 'Device Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto h-full">
            {/* MOBILE SYNC WARNING: If deep link is pending but no data found */}
            {deepLinkPending && devices.length === 0 && !isLoading && (
              <div className="h-full flex flex-col items-center justify-center text-center p-6 animate-fade-in">
                 <div className="p-6 bg-blue-50 rounded-full mb-8"><ShieldAlert className="w-16 h-16 text-blue-600" /></div>
                 <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tight mb-4 leading-none">Cloud Sync Required</h2>
                 <p className="text-slate-500 max-w-sm mb-10 font-medium">You scanned a device, but this phone's database is empty. You need to connect to the same <strong>Supabase</strong> project used on your computer.</p>
                 <button onClick={() => setView('SETTINGS')} className="w-full max-w-xs py-4 bg-blue-600 text-white rounded-2xl font-bold shadow-2xl flex items-center justify-center gap-2 hover:scale-105 transition">Go to Sync Settings <ArrowRight className="w-5 h-5" /></button>
              </div>
            )}

            {!deepLinkPending && view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={handleSelectDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>

      {isScannerOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900 flex flex-col items-center justify-center p-0 sm:p-4">
          <div className="w-full h-full sm:h-auto sm:max-w-lg bg-white sm:rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-3"><div className="p-2 bg-blue-100 rounded-lg"><Camera className="w-5 h-5 text-blue-600" /></div><h3 className="font-black text-slate-900 uppercase tracking-tight">Clinical Scan</h3></div>
              <button onClick={() => setIsScannerOpen(false)} className="p-2 bg-white text-slate-400 rounded-xl border border-slate-200 shadow-sm transition"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex-1 flex flex-col p-6 overflow-hidden bg-slate-50">
              <div className="relative w-full aspect-square bg-black rounded-3xl overflow-hidden shadow-inner ring-8 ring-white/50"><div id="reader" className="w-full h-full"></div></div>
              <div className="mt-8 space-y-4">
                <div className="p-4 bg-white rounded-2xl border border-slate-200 flex items-start gap-3"><Info className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" /><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Scanning Info</p><p className="text-xs text-slate-600 font-medium">Assets must be synced to the Cloud for mobile identification to work.</p></div></div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, Cloud, CheckCircle, Save, Link, LogOut, QrCode, Globe, Smartphone, Wifi, ShieldAlert, Terminal, ExternalLink } from 'lucide-react';
import { isSupabaseConfigured, getSupabaseConfig, saveSupabaseConfig, clearSupabaseConfig } from '../services/supabase';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [config, setConfig] = useState(getSupabaseConfig());
  const [inputUrl, setInputUrl] = useState(config.url || '');
  const [inputKey, setInputKey] = useState(config.key || '');
  const [showKey, setShowKey] = useState(false);

  // QR Settings
  const [baseUrl, setBaseUrl] = useState('');

  useEffect(() => {
    const currentConfig = getSupabaseConfig();
    setConfig(currentConfig);
    setInputUrl(currentConfig.url || '');
    if (!currentConfig.isEnv) {
      setInputKey(currentConfig.key || '');
    }

    const storedBaseUrl = localStorage.getItem('meditrack_base_url');
    setBaseUrl(storedBaseUrl || window.location.origin);
  }, []);

  const handleSaveCloudConfig = () => {
    if (!inputUrl || !inputKey) {
      alert("Please provide both the Supabase URL and Anon Key.");
      return;
    }
    saveSupabaseConfig(inputUrl, inputKey);
  };

  const handleDisconnectCloud = () => {
    if (window.confirm("Are you sure? Multi-device sync will stop.")) {
      clearSupabaseConfig();
    }
  };

  const handleSaveBaseUrl = () => {
      let finalUrl = baseUrl.trim();

      // Auto-correct: Ensure http:// protocol
      if (finalUrl && !finalUrl.startsWith('http')) {
          finalUrl = 'http://' + finalUrl;
      }

      // Auto-correct: Ensure port is present (defaulting to 5173 if not specified and not on standard port)
      if (finalUrl && !finalUrl.includes(':', 7) && window.location.port) {
          finalUrl = finalUrl + ':' + (window.location.port || '5173');
      }

      localStorage.setItem('meditrack_base_url', finalUrl);
      setBaseUrl(finalUrl);
      alert("QR Base URL Updated: " + finalUrl);
  };

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(devices, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `meditrack_backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (Array.isArray(jsonData)) {
          const isValid = jsonData.every(d => d.id && d.name && d.status);
          if (isValid) {
            if (window.confirm(`Restore ${jsonData.length} devices?`)) {
              onImport(jsonData);
              alert('Import successful!');
            }
          }
        }
      } catch (error) {
        alert('Error reading file.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in pb-20 px-4">

      {/* 1. Cloud Sync Section */}
      <div className="bg-white p-6 sm:p-10 rounded-[2.5rem] shadow-xl border border-slate-100">
        <div className="flex items-center gap-5 mb-10">
          <div className={`p-5 rounded-3xl ${isSupabaseConfigured ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
            <Cloud className="w-10 h-10" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tight leading-none">Global Sync</h2>
            <p className="text-sm text-slate-400 font-bold uppercase tracking-widest mt-1">Supabase Infrastructure</p>
          </div>
        </div>

        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Project Endpoint</label>
                <input 
                  type="text" 
                  value={inputUrl}
                  onChange={(e) => setInputUrl(e.target.value)}
                  placeholder="https://abc.supabase.co"
                  className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 outline-none text-sm font-mono transition-all"
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Service Anon Key</label>
                <div className="relative">
                  <input 
                    type={showKey ? "text" : "password"}
                    value={inputKey}
                    onChange={(e) => setInputKey(e.target.value)}
                    placeholder="eyJhbG..."
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 outline-none text-sm font-mono transition-all pr-24"
                  />
                  <button onClick={() => setShowKey(!showKey)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-400 hover:text-slate-900">{showKey ? "HIDE" : "SHOW"}</button>
                </div>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 pt-4">
              <button 
                onClick={handleSaveCloudConfig}
                className="flex-1 py-5 bg-blue-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95"
              >
                Sync with Database
              </button>
              {isSupabaseConfigured && (
                <button onClick={handleDisconnectCloud} className="px-8 py-5 bg-red-50 text-red-600 rounded-[1.5rem] font-black transition hover:bg-red-100">
                  <LogOut className="w-6 h-6" />
                </button>
              )}
            </div>
        </div>
      </div>

      {/* 2. Network Bridge Assistant (THE FIX FOR "CANNOT OPEN SITE") */}
      <div className="bg-white p-6 sm:p-10 rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden relative">
        <div className="absolute top-0 right-0 p-8 opacity-5">
           <Wifi className="w-40 h-40" />
        </div>

        <div className="flex items-center gap-5 mb-10">
          <div className="p-5 rounded-3xl bg-violet-100 text-violet-600">
            <Smartphone className="w-10 h-10" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tight leading-none">Network Bridge</h2>
            <p className="text-sm text-slate-400 font-bold uppercase tracking-widest mt-1">Mobile Access Assistant</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-5 gap-10">
          <div className="lg:col-span-3 space-y-8">
            <div className="p-6 bg-slate-900 rounded-[2rem] text-white">
               <h3 className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-violet-400 mb-4">
                 <Terminal className="w-4 h-4" /> Server Exposure Rule
               </h3>
               <p className="text-xs text-slate-300 mb-4 leading-relaxed font-medium">
                 Standard servers block network access for safety. To let your phone connect, you <strong>MUST</strong> run your computer's terminal command with the host flag:
               </p>
               <code className="block p-4 bg-black rounded-xl font-mono text-green-400 text-sm mb-4 border border-white/5">
                 npm run dev -- --host
               </code>
               <div className="flex items-start gap-3 p-4 bg-white/5 rounded-xl border border-white/10">
                  <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
                  <p className="text-[10px] text-slate-400 font-medium">Without "--host", your computer only listens to itself (localhost) and ignores your phone scan.</p>
               </div>
            </div>

            <div className="space-y-4">
               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Computer's Wi-Fi IP (Target URL)</label>
               <div className="flex gap-2">
                 <input 
                    type="text" 
                    value={baseUrl}
                    onChange={(e) => setBaseUrl(e.target.value)}
                    placeholder="192.168.1.XX"
                    className="flex-1 px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-mono text-sm"
                  />
                  <button onClick={handleSaveBaseUrl} className="px-8 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition">Set</button>
               </div>
               {baseUrl && !baseUrl.includes('localhost') && (
                 <a 
                  href={baseUrl} 
                  target="_blank" 
                  rel="noreferrer"
                  className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase tracking-widest px-2 group"
                 >
                   <ExternalLink className="w-3 h-3" /> Verify Link Works on PC <ArrowRight className="w-3 h-3 group-hover:translate-x-1 transition-transform" />
                 </a>
               )}
            </div>
          </div>

          <div className="lg:col-span-2 space-y-4">
             <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Diagnostic Checklist</h4>
             <TroubleStep icon={<Wifi className="w-5 h-5" />} title="Same Frequency" text="Phone must be on exact same Wi-Fi SSID." />
             <TroubleStep icon={<ShieldAlert className="w-5 h-5" />} title="Windows Firewall" text="Allow Port 5173 through Private Firewall settings." />
             <TroubleStep icon={<Link className="w-5 h-5" />} title="No Localhost" text="QR codes pointing to 'localhost' will fail on mobile." />
          </div>
        </div>
      </div>

      {/* 3. Manual Backup */}
      <div className="bg-slate-950 p-10 rounded-[3rem] shadow-2xl text-white">
        <div className="flex items-center gap-5 mb-10">
          <div className="p-4 bg-blue-500 rounded-2xl shadow-lg shadow-blue-500/20">
            <Database className="w-8 h-8 text-white" />
          </div>
          <div>
             <h2 className="text-2xl font-black uppercase tracking-tight">System Backup</h2>
             <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Manual Data Portability</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <button onClick={handleExport} className="p-8 bg-white/5 border border-white/10 rounded-[2rem] hover:bg-white/10 transition text-left group">
            <Download className="w-8 h-8 text-blue-400 mb-6 group-hover:scale-110 transition" />
            <h3 className="font-bold text-xl">Cloud Backup</h3>
            <p className="text-xs text-slate-500 mt-2 font-medium leading-relaxed">Download your clinical inventory as a JSON blueprint for manual transfer.</p>
          </button>

          <button onClick={() => fileInputRef.current?.click()} className="p-8 bg-white/5 border border-white/10 rounded-[2rem] hover:bg-white/10 transition text-left group">
            <Upload className="w-8 h-8 text-green-400 mb-6 group-hover:scale-110 transition" />
            <h3 className="font-bold text-xl">Restore Point</h3>
            <p className="text-xs text-slate-500 mt-2 font-medium leading-relaxed">Overwrite current data with a saved clinical equipment manifest.</p>
            <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </button>
        </div>
      </div>
    </div>
  );
};

const TroubleStep = ({ icon, title, text }: { icon: React.ReactNode, title: string, text: string }) => (
  <div className="p-5 bg-slate-50 border border-slate-100 rounded-2xl flex gap-4">
    <div className="text-blue-600 shrink-0">{icon}</div>
    <div>
      <h5 className="text-[10px] font-black text-slate-900 uppercase tracking-widest mb-1">{title}</h5>
      <p className="text-[10px] text-slate-500 font-medium leading-tight">{text}</p>
    </div>
  </div>
);

const ArrowRight = ({ className }: { className?: string }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
);

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight, WifiOff, RefreshCw } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { Html5QrcodeScanner } from 'html5-qrcode';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [deepLinkPending, setDeepLinkPending] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const getLocalData = (): MedicalDevice[] => {
    try {
      const savedData = localStorage.getItem('meditrack_devices');
      return savedData ? JSON.parse(savedData) : MOCK_DEVICES;
    } catch (e) {
      return MOCK_DEVICES;
    }
  };

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*');
          if (error) throw error;
          if (data) loadedDevices = data as MedicalDevice[];
        } catch (error) {
          loadedDevices = getLocalData();
        }
      } else {
        loadedDevices = getLocalData();
      }
      setDevices(loadedDevices);

      const params = new URLSearchParams(window.location.search);
      const devId = params.get('deviceId');
      if (devId) setDeepLinkPending(devId);

      setIsLoading(false);
    };
    loadData();
  }, []);

  useEffect(() => {
    if (deepLinkPending && devices.length > 0) {
      const target = devices.find(d => d.id === deepLinkPending || d.serialNumber === deepLinkPending);
      if (target) {
        setSelectedDevice(target);
        setView('DEVICE_DETAIL');
        setDeepLinkPending(null);
        window.history.replaceState({}, '', window.location.pathname);
      }
    }
  }, [deepLinkPending, devices]);

  useEffect(() => {
    if (isScannerOpen) {
      const timer = setTimeout(() => {
        try {
          const scanner = new Html5QrcodeScanner("reader", { fps: 15, qrbox: 250 }, false);
          scanner.render((decodedText) => {
            let deviceId = decodedText;
            if (decodedText.includes('deviceId=')) {
              try { deviceId = new URL(decodedText).searchParams.get('deviceId') || decodedText; } catch (e) {}
            }
            const found = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
            if (found) {
              scanner.clear();
              setIsScannerOpen(false);
              handleSelectDevice(found);
            } else {
              alert(`Diagnostic: Asset "${deviceId}" not found in current phone database. Check Cloud Sync settings.`);
            }
          }, () => {});
          scannerRef.current = scanner;
        } catch (e) { console.error(e); }
      }, 300);
      return () => clearTimeout(timer);
    } else {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
        scannerRef.current = null;
      }
    }
  }, [isScannerOpen, devices]);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      localStorage.setItem('meditrack_devices', JSON.stringify(newDevices));
      setDevices(newDevices);
    } catch (e: any) {
      console.error(e);
      return;
    }

    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) await supabase.from('devices').delete().eq('id', changedDevice.id);
        else if (action === 'INSERT' && !Array.isArray(changedDevice)) await supabase.from('devices').insert([changedDevice]);
        else if (action === 'UPDATE' && !Array.isArray(changedDevice)) await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) await supabase.from('devices').insert(changedDevice);
      } catch (err) { console.error(err); }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      persistDeviceChange(importedDevices);
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />}
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button onClick={() => { setIsScannerOpen(true); setSidebarOpen(false); }} className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"><QrCode className="w-5 h-5" /> Scan QR Code</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSupabaseConfigured ? (
