                      <p className="text-xs font-bold text-slate-700">Are both devices on the same Wi-Fi SSID?</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center font-bold text-blue-600">2</div>
                      <p className="text-xs font-bold text-slate-700">Did you enable <strong>Cloud Sync</strong> in Settings?</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center font-bold text-blue-600">3</div>
                      <p className="text-xs font-bold text-slate-700">Check computer firewall for port 5173.</p>
                    </div>
                 </div>

                 <div className="flex flex-col w-full gap-4">
                   <button onClick={() => setView('SETTINGS')} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-2">Configure Bridge <ArrowRight className="w-5 h-5" /></button>
                   <button onClick={() => window.location.reload()} className="w-full py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center gap-2"><RefreshCw className="w-5 h-5" /> Retry Scan</button>
                 </div>
              </div>
            )}

            {!deepLinkPending && view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={handleSelectDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>

      {isScannerOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900 flex flex-col items-center justify-center p-0 sm:p-4">
          <div className="w-full h-full sm:h-auto sm:max-w-lg bg-white sm:rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-3"><div className="p-2 bg-blue-100 rounded-lg"><Camera className="w-5 h-5 text-blue-600" /></div><h3 className="font-black text-slate-900 uppercase tracking-tight">Clinical Scan</h3></div>
              <button onClick={() => setIsScannerOpen(false)} className="p-2 bg-white text-slate-400 rounded-xl border border-slate-200 shadow-sm transition"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex-1 flex flex-col p-6 overflow-hidden bg-slate-50">
              <div className="relative w-full aspect-square bg-black rounded-3xl overflow-hidden shadow-inner ring-8 ring-white/50"><div id="reader" className="w-full h-full"></div></div>
              <div className="mt-8 space-y-4">
                <div className="p-4 bg-white rounded-2xl border border-slate-200 flex items-start gap-3"><Info className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" /><div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Scanning Info</p><p className="text-xs text-slate-600 font-medium">Assets must be synced to the Cloud for mobile identification to work.</p></div></div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera, Loader2, Layers, Hash } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  onSave: (device: MedicalDevice) => void;
  onBulkSave: (devices: MedicalDevice[]) => void;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 500 * 1024; // Target ~500KB

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    notes: '',
    image: ''
  });

  // Batch specific state
  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("File error"));
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("Image error"));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;

          if (width > height) {
            if (width > MAX_DIM) {
              height *= MAX_DIM / width;
              width = MAX_DIM;
            }
          } else {
            if (height > MAX_DIM) {
              width *= MAX_DIM / height;
              height = MAX_DIM;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);

          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed. Please check file format.");
      } finally {
        setIsCompressing(false);
        if (imageInputRef.current) imageInputRef.current.value = '';
      }
    }
  };

  const handleSingleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newDevice: MedicalDevice = {
      id: `DEV-${Math.floor(Math.random() * 90000) + 10000}`,
      ...formData,
      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };
    onSave(newDevice);
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    for (let i = 0; i < batchData.quantity; i++) {
      const currentSerialNum = batchData.startNum + i;
      batch.push({
        id: `DEV-B-${Date.now()}-${i}`,
        ...formData,
        serialNumber: `${batchData.serialPrefix}${currentSerialNum}`,
        status: formData.status as DeviceStatus,
        maintenanceHistory: [],
        contracts: [],
        files: []
      });
    }
    setPreviewDevices(batch);
  };

  const processWithAI = async (inputData: string) => {
    setIsProcessing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Parse clinical device data into JSON array: "${inputData}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                manufacturer: { type: Type.STRING },
                model: { type: Type.STRING },
                serialNumber: { type: Type.STRING },
                department: { type: Type.STRING },
                purchaseDate: { type: Type.STRING },
                status: { type: Type.STRING }
              },
              required: ["name", "serialNumber"]
            }
          }
        }
      });
      const parsed: any[] = JSON.parse(response.text);
      setPreviewDevices(parsed.map(item => ({ ...item, id: `DEV-${Math.floor(Math.random() * 90000)}`, maintenanceHistory: [], contracts: [], files: [] })));
    } catch (error) {
      alert("AI Processing failed.");
    } finally { setIsProcessing(false); }
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        processWithAI(JSON.stringify(data));
      } catch (err) { alert("Error reading file."); }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20 relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/60 backdrop-blur-sm z-[100] flex flex-col items-center justify-center animate-fade-in">
          <div className="bg-slate-900 text-white p-10 rounded-[2.5rem] shadow-2xl flex flex-col items-center gap-6">
            <Loader2 className="w-12 h-12 text-blue-400 animate-spin" />
            <div className="text-center">
              <p className="text-sm font-black uppercase tracking-widest text-white">Optimizing Asset</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-2">Preparing visual record...</p>
            </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Multi-Device Registration Interface</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Entry" icon={<Box className="w-4 h-4" />} />
        <TabButton active={activeTab === 'batch'} onClick={() => setActiveTab('batch')} label="Batch Generator" icon={<Layers className="w-4 h-4" />} />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="Smart AI Extract" icon={<Wand2 className="w-4 h-4" />} />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Spreadsheet Import" icon={<FileSpreadsheet className="w-4 h-4" />} />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center bg-blue-50 p-6 rounded-3xl border border-blue-100">
               <h3 className="font-bold text-blue-900 flex items-center gap-3"><Check className="w-6 h-6 text-blue-600" /> Confirm Import ({previewDevices.length} assets)</h3>
               <button onClick={() => setPreviewDevices([])} className="text-sm font-black text-blue-600 uppercase hover:underline">Clear & Re-edit</button>
             </div>
             <div className="max-h-96 overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50">
               {previewDevices.map((d, i) => (
                 <div key={i} className="p-5 flex items-center justify-between hover:bg-slate-50 transition">
                   <div className="flex items-center gap-4">
                     <div className="w-10 h-10 bg-white shadow-sm border border-slate-100 rounded-xl flex items-center justify-center"><Box className="w-5 h-5 text-slate-400" /></div>
                     <div>
                       <p className="font-bold text-slate-900 text-sm">{d.name}</p>
                       <p className="text-[10px] font-mono text-slate-500 uppercase">Serial: {d.serialNumber}</p>
                     </div>
                   </div>
                   <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-100 px-3 py-1 rounded-full">{d.department}</div>
                 </div>
               ))}
             </div>
             <button onClick={() => onBulkSave(previewDevices)} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95">Complete Bulk Upload</button>
          </div>
        ) : (
          <>
            {(activeTab === 'single' || activeTab === 'batch') && (
              <form onSubmit={activeTab === 'single' ? handleSingleSubmit : handleGenerateBatch} className="space-y-10">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Base Asset Visual</label>
                     <div 
                      onClick={() => imageInputRef.current?.click()}
                      className="aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all overflow-hidden group relative"
                     >
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-contain" />
                       ) : (
                         <>
                           <Camera className="w-10 h-10 text-slate-300 group-hover:scale-110 transition-transform" />
                           <p className="mt-2 text-[10px] font-black text-slate-400 uppercase">Upload Reference Photo</p>
                         </>
                       )}
                       <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                     </div>
                  </div>

                  <div className="lg:col-span-8 space-y-8">
                    {activeTab === 'batch' && (
                       <div className="bg-blue-900 p-8 rounded-[2rem] text-white shadow-xl mb-10">
                         <h3 className="flex items-center gap-3 text-sm font-black uppercase tracking-widest mb-6">
                           <Hash className="w-5 h-5 text-blue-400" /> Auto-Increment Config
                         </h3>
                         <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                            <div>
                               <label className="text-[9px] font-black text-blue-300 uppercase tracking-widest mb-2 block">Quantity to Generate</label>
                               <input name="quantity" type="number" min="1" max="100" value={batchData.quantity} onChange={handleBatchChange} className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/20 outline-none" />
                            </div>
                            <div>
                               <label className="text-[9px] font-black text-blue-300 uppercase tracking-widest mb-2 block">Serial Prefix</label>
                               <input name="serialPrefix" type="text" value={batchData.serialPrefix} onChange={handleBatchChange} className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/20 outline-none" placeholder="SN-" />
                            </div>
                            <div>
                               <label className="text-[9px] font-black text-blue-300 uppercase tracking-widest mb-2 block">Starting Number</label>
                               <input name="startNum" type="number" value={batchData.startNum} onChange={handleBatchChange} className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/20 outline-none" />
                            </div>
                         </div>
                       </div>
                    )}

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <FormField label="Asset Template Name" name="name" value={formData.name} onChange={handleChange} placeholder="e.g. Alaris Pump" required />
                      <FormField label="Manufacturer" name="manufacturer" value={formData.manufacturer} onChange={handleChange} placeholder="e.g. BD" required />
                      <FormField label="Model" name="model" value={formData.model} onChange={handleChange} placeholder="e.g. 8100" required />

                      {activeTab === 'single' && (
                        <FormField label="Unique Serial Number" name="serialNumber" value={formData.serialNumber} onChange={handleChange} placeholder="SN-XXXX" required />
                      )}

                      <FormField label="Assigned Department" name="department" value={formData.department} onChange={handleChange} placeholder="e.g. Oncology" required />
                      <FormField label="Acquisition Date" name="purchaseDate" type="date" value={formData.purchaseDate} onChange={handleChange} required />
                    </div>

                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Initial Status (Applies to all)</label>
                      <select name="status" value={formData.status} onChange={handleChange} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none">
                        {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
                  <button type="button" onClick={onCancel} className="px-8 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
                  <button type="submit" className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center gap-2">
                    {activeTab === 'single' ? <><Save className="w-4 h-4" /> Save Asset</> : <><Layers className="w-4 h-4" /> Generate Batch Preview</>}
                  </button>
                </div>
              </form>
            )}

            {activeTab === 'bulk' && (
              <div className="space-y-6">
                <div className="bg-violet-50 p-6 rounded-3xl border border-violet-100 flex gap-4">
                  <Wand2 className="w-8 h-8 text-violet-600 shrink-0" />
                  <p className="text-sm text-violet-900 font-medium leading-relaxed">Intelligence Engine: Paste clinical equipment manifests, packing slips, or informal lists. We'll extract structured device profiles automatically.</p>
                </div>
                <textarea className="w-full h-64 p-8 bg-slate-50 border border-slate-200 rounded-3xl focus:ring-4 focus:ring-violet-500/10 outline-none font-mono text-sm leading-relaxed" placeholder="Paste equipment list from clipboard..." value={bulkText} onChange={(e) => setBulkText(e.target.value)} />
                <button onClick={() => processWithAI(bulkText)} disabled={isProcessing || !bulkText} className="w-full py-5 bg-violet-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl hover:bg-violet-700 transition disabled:opacity-50">
                  {isProcessing ? "Processing Intelligence..." : "Extract Assets with AI"}
                </button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-20 border-4 border-dashed border-slate-50 rounded-[40px] text-center bg-slate-50/30">
                 <div className="p-8 bg-white rounded-full shadow-2xl mb-8">
                   <FileSpreadsheet className="w-16 h-16 text-blue-500" />
                 </div>
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-2">Spreadsheet Integration</h3>
                 <p className="text-sm text-slate-400 max-w-sm mb-10 font-medium">Upload your existing clinical inventory Excel or CSV for massive bulk ingestion.</p>
                 <input type="file" ref={excelInputRef} accept=".xlsx,.xls,.csv" onChange={handleExcelUpload} className="hidden" />
                 <button onClick={() => excelInputRef.current?.click()} className="px-12 py-5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-black transition flex items-center gap-3">
                   <Upload className="w-5 h-5" /> Select Local File
                 </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, label, icon }: { active: boolean, onClick: () => void, label: string, icon: React.ReactNode }) => (
