            {activeTab === 'bulk' && (
              <div className="space-y-6">
                <div className="bg-violet-50 p-6 rounded-3xl border border-violet-100 flex gap-4">
                  <Wand2 className="w-8 h-8 text-violet-600 shrink-0" />
