                </button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-20 border-4 border-dashed border-slate-50 rounded-[40px] text-center bg-slate-50/30">
                 <div className="p-8 bg-white rounded-full shadow-2xl mb-8">
                   <FileSpreadsheet className="w-16 h-16 text-blue-500" />
