                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                  {reports.length === 0 && (
                    <div className="col-span-full py-12 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">No service reports attached.</div>
                  )}
                </div>
              </div>
            </div>

            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                   <FileText className="w-4 h-4" /> Technical Library
                 </h3>
                 <div className="space-y-6">
                   <div>
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Operator Manuals</p>
                     <div className="space-y-2">
                       {manuals.map(m => (
                         <div key={m.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                           <div className="flex items-center gap-2 truncate flex-1 text-xs font-bold text-blue-600 cursor-pointer" onClick={(e) => handleOpenFile(e, m)}>
                             <Download className="w-3.5 h-3.5 opacity-40 shrink-0" /> 
                             <span className="truncate">{m.name}</span>
                           </div>
                           <button type="button" onClick={(e) => handleDeleteFile(e, m.id)} className="p-1.5 text-slate-300 hover:text-red-500 transition ml-1"><Trash2 className="w-3.5 h-3.5" /></button>
                         </div>
                       ))}
                       <button type="button" onClick={() => { setSelectedFileType('manual'); fileInputRef.current?.click(); }} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">+ ADD MANUAL</button>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex items-center justify-between">
               <div>
                  <h3 className="text-2xl font-bold text-slate-900">Engineering Log</h3>
                  <p className="text-sm text-slate-500 mt-1">Full service and calibration history.</p>
               </div>
               <button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3 bg-violet-600 text-white rounded-2xl font-bold flex items-center gap-2 transition disabled:opacity-50">
                 <Wand2 className="w-5 h-5" /> {isAnalyzing ? "Analyzing..." : "AI Suggestion"}
               </button>
            </div>
            <div className="space-y-4">
              {device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-200 flex items-center justify-between">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                      {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Activity className="w-7 h-7" />}
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-900 text-lg">{record.type}</h4>
                      <p className="text-sm text-slate-600 line-clamp-2">{record.description}</p>
                      <p className="text-[10px] font-black text-slate-400 uppercase mt-2">Verified by: {record.technician}</p>
                    </div>
                  </div>
                  <div className="text-right font-bold text-slate-900 whitespace-nowrap">{record.date}</div>
                </div>
              ))}
            </div>
            <button type="button" onClick={() => setShowMaintenanceModal(true)} className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 transition flex items-center justify-center gap-2">+ RECORD SERVICE EVENT</button>
          </div>
        )}

        {activeTab === 'qr' && (
          <div className="max-w-xl mx-auto space-y-8 py-10 animate-fade-in">
             <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 flex flex-col items-center text-center">
                <div className="mb-8">
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Digital Asset Passport</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-2">Unique Identification QR</p>
                </div>

                <div className="bg-white p-6 rounded-3xl shadow-inner border-4 border-slate-50 mb-8">
                  <img src={qrCodeUrl} alt="QR Code" className="w-64 h-64" />
                </div>

                <div className="space-y-4 w-full">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-left">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Encrypted Link</p>
                    <p className="text-xs font-mono text-slate-600 break-all">{qrLink}</p>
                  </div>

                  <div className="flex gap-4">
                    <button 
                        onClick={printQrCode}
                        className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-black transition shadow-xl"
                    >
                      <Printer className="w-5 h-5" /> PRINT LABEL
                    </button>
                    <a 
                      href={qrCodeUrl} 
                      download={`${device.name}-qr.png`}
                      className="flex-1 py-4 bg-white border border-slate-200 text-slate-900 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition shadow-sm"
                    >
                      <Download className="w-5 h-5" /> DOWNLOAD
                    </a>
                  </div>
                </div>

                <p className="mt-8 text-xs text-slate-400 leading-relaxed max-w-xs">
                  Physical assets tagged with this QR can be scanned by any authorized mobile device to immediately pull up service records.
                </p>
             </div>
          </div>
        )}

        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="High Resolution Detail" className="max-w-full max-h-full object-contain shadow-2xl" />
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none min-h-[100px]" placeholder="Work summary..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <div className="flex gap-4">
              <button type="button" onClick={() => setShowMaintenanceModal(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold">Cancel</button>
              <button type="button" onClick={() => {
                const newR: MaintenanceRecord = { id: Math.random().toString(36).substring(7), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Engineering Dept', description: maintenanceForm.description || 'No details provided', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setShowMaintenanceModal(false);
              }} className="flex-2 px-8 py-4 bg-green-600 text-white rounded-2xl font-bold">Log Event</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
  if (status === DeviceStatus.ACTIVE) color = "bg-green-100 text-green-700 border-green-200";
  if (status === DeviceStatus.BROKEN) color = "bg-red-100 text-red-700 border-red-200";
  if (status === DeviceStatus.MAINTENANCE) color = "bg-amber-100 text-amber-700 border-amber-200";
  return <span className={`px-2.5 py-1 border rounded-full text-xs font-semibold shadow-sm uppercase ${color}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button type="button" onClick={onClick} className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>{icon}{label}</button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

const EditField = ({ label, name, value, onChange }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input 
      name={name}
      value={value}
      onChange={onChange}
      className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none"
    />
  </div>
);

export default DeviceDetail;

import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent, HOSPITAL_DEPARTMENTS } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2, Loader2, Printer, Check, ChevronDown
} from 'lucide-react';
import { suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB Limit
const COMPRESSION_TARGET = 500 * 1024; // Target ~500KB for better storage efficiency

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  // Edit State
  const [editForm, setEditForm] = useState({
    name: device.name,
    manufacturer: device.manufacturer,
    model: device.model,
    department: device.department,
    customDepartment: '',
    status: device.status
  });

  // Fix: Added missing state for maintenance form logging
  const [maintenanceForm, setMaintenanceForm] = useState({
    technician: '',
    description: ''
  });

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditForm(prev => ({ ...prev, [name]: value }));
  };

  const saveGeneralEdits = () => {
    const finalDept = editForm.department === 'OTHER' ? editForm.customDepartment : editForm.department;
    onUpdate({
      ...device,
      name: editForm.name,
      manufacturer: editForm.manufacturer,
      model: editForm.model,
      department: finalDept,
      status: editForm.status as DeviceStatus
    });
    setIsEditing(false);
  };

  // Calculate QR Code Link
  const qrLink = useMemo(() => {
    const baseUrl = localStorage.getItem('meditrack_base_url') || (window.location.origin + window.location.pathname);
    const url = new URL(baseUrl);
    url.searchParams.set('deviceId', device.id);
    return url.toString();
  }, [device.id]);

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrLink)}`;

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("File reading failed"));
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("Image decoding failed"));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;

          if (width > height) {
            if (width > MAX_DIM) {
              height *= MAX_DIM / width;
              width = MAX_DIM;
            }
          } else {
            if (height > MAX_DIM) {
              width *= MAX_DIM / height;
              height = MAX_DIM;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context failed"));

          ctx.drawImage(img, 0, 0, width, height);

          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const optimized = await compressImage(file);
        onUpdate({ ...device, image: optimized });
      } catch (err) {
        alert("Visual update failed. Please check image format.");
      } finally {
        setIsCompressing(false);
        if (imageInputRef.current) imageInputRef.current.value = '';
      }
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const isImage = file.type.startsWith('image/');
      let fileUrl = '';

      setIsCompressing(true);
      try {
        if (isImage) {
          fileUrl = await compressImage(file);
        } else {
          if (file.size > MAX_FILE_SIZE) {
             alert(`PDF/Docs over 2MB cannot be auto-compressed. Please upload a smaller file.`);
             setIsCompressing(false);
             return;
          }
          fileUrl = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onerror = reject;
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });
        }

        const newFile: DeviceFile = {
          id: Math.random().toString(36).substring(7),
          name: file.name,
          type: selectedFileType,
          url: fileUrl,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
      } catch (err) {
        alert("Upload failed. Storage might be full or file is corrupted.");
      } finally {
        setIsCompressing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    }
  };

  const handleDeleteFile = (e: React.MouseEvent, fileId: string) => {
    e.preventDefault();
    e.stopPropagation();
    const updatedFiles = device.files.filter(f => f.id !== fileId);
    onUpdate({ ...device, files: updatedFiles });
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url === '#') return alert('Sample file placeholder.');
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      alert(`AI Suggestion: ${res.recommendedType} every ${res.frequency}. Tasks: ${res.tasks.join(', ')}`);
    } finally { setIsAnalyzing(false); }
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  const printQrCode = () => {
      const printWindow = window.open('', '_blank');
      if (printWindow) {
          printWindow.document.write(`
            <html>
                <head>
                    <title>MediTrack Asset Label - ${device.name}</title>
                    <style>
                        body { font-family: sans-serif; text-align: center; padding: 40px; }
                        .label { border: 2px solid #000; padding: 20px; display: inline-block; border-radius: 10px; }
                        h1 { margin: 0; font-size: 24px; }
                        h2 { margin: 10px 0; font-size: 16px; color: #555; }
                        img { margin: 20px 0; }
                        p { font-size: 12px; font-weight: bold; }
                    </style>
                </head>
                <body onload="window.print(); window.close();">
                    <div class="label">
                        <h1>MediTrack</h1>
                        <h2>${device.name}</h2>
                        <img src="${qrCodeUrl}" width="200" height="200" />
                        <p>ID: ${device.id}</p>
                        <p>SN: ${device.serialNumber}</p>
                    </div>
                </body>
            </html>
          `);
          printWindow.document.close();
      }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[100] flex flex-col items-center justify-center animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-100 flex flex-col items-center gap-4">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
            <div className="text-center">
              <p className="font-black text-slate-900 uppercase tracking-widest text-xs">Processing Asset</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Optimizing storage...</p>
            </div>
          </div>
        </div>
      )}

      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <div className="flex items-center gap-3">
             {isEditing ? (
               <input 
                name="name"
                value={editForm.name} 
                onChange={handleEditChange}
                className="text-3xl font-bold text-slate-900 tracking-tight bg-white border-2 border-blue-500 rounded-xl px-4 py-1 outline-none shadow-lg shadow-blue-500/10"
               />
             ) : (
               <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
             )}
          </div>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex gap-2">
           {isEditing ? (
             <>
                <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
                <button onClick={saveGeneralEdits} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 transition shadow-lg flex items-center gap-2"><Check className="w-4 h-4" /> Save Info</button>
             </>
           ) : (
             <>
                <button onClick={() => setIsEditing(true)} className="p-2.5 bg-white text-blue-600 border border-slate-200 rounded-lg hover:bg-blue-50 transition shadow-sm">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm">
                  <Trash2 className="w-5 h-5" />
                </button>
             </>
           )}
           <button 
            type="button" 
            onClick={() => setActiveTab('qr')} 
            className={`flex items-center gap-2 px-4 py-2 rounded-lg transition shadow-md font-bold text-sm ${activeTab === 'qr' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}
           >
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Contracts" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-slate-900 rounded-2xl border border-slate-200 shadow-xl overflow-hidden group relative min-h-[300px] flex items-center justify-center">
                  <div className="absolute inset-0 opacity-10 bg-[radial-gradient(#ffffff_1px,transparent_1px)] [background-size:16px_16px]"></div>
                  {device.image ? (
                    <img src={device.image} alt={device.name} className="w-full h-full object-contain relative z-10" />
                  ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 relative z-10">
                      <Camera className="w-16 h-16 mb-4 opacity-20" />
                      <p className="text-xs font-black uppercase tracking-[0.2em] opacity-40">No Asset Visual</p>
                    </div>
                  )}
                  <div className="absolute bottom-4 right-4 flex gap-2 z-20">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button type="button" onClick={() => imageInputRef.current?.click()} className="p-3 bg-white/90 backdrop-blur text-slate-900 rounded-xl shadow-xl hover:bg-white transition flex flex-col items-center gap-1 min-w-[64px]">
