    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input 
      name={name}
      value={value}
      onChange={onChange}
      className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none"
    />
  </div>
);

export default DeviceDetail;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onAddDevice, onDelete }) => {
  const [localSearch, setLocalSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');

  const filteredDevices = useMemo(() => {
    const term = localSearch.toLowerCase().trim();
    return devices.filter(d => {
      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;

      return matchSearch && matchStatus && matchDept;
    });
  }, [devices, localSearch, filterStatus, filterDept]);

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => set.add(d.department));
    return Array.from(set).sort();
  }, [devices]);

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");

    // Flatten data for spreadsheet
    const dataToExport = filteredDevices.map(d => ({
      'Asset Name': d.name,
      'Manufacturer': d.manufacturer,
      'Model': d.model,
      'Serial Number': d.serialNumber,
      'Department': d.department,
      'Status': d.status,
      'Purchase Date': d.purchaseDate,
      'Last Maintenance': d.maintenanceHistory[0]?.date || 'N/A',
      'Asset ID': d.id
    }));

    try {
      const worksheet = XLSX.utils.json_to_sheet(dataToExport);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Inventory");

      // Generate filename based on filters
      const date = new Date().toISOString().split('T')[0];
      const filename = `MediTrack_Inventory_${filterDept !== 'ALL' ? filterDept + '_' : ''}${date}.xlsx`;

      XLSX.writeFile(workbook, filename);
    } catch (err) {
      console.error("Export failed:", err);
      alert("Spreadsheet generation failed. Please check browser permissions.");
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Search Header */}
      <div className="flex flex-col xl:flex-row justify-between items-stretch xl:items-center gap-4 bg-white p-6 rounded-[2rem] shadow-xl border border-slate-100">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5" />
          <input 
            type="text"
            placeholder="Search assets by name, serial, or model..."
            className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:outline-none text-sm font-medium transition-all"
            value={localSearch}
            onChange={(e) => setLocalSearch(e.target.value)}
          />
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider"
            value={filterDept}
            onChange={(e) => setFilterDept(e.target.value)}
          >
            <option value="ALL">ALL DEPTS</option>
            {uniqueDeptsInData.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
          </select>

          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
          >
            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>

          <button 
            onClick={handleExportExcel}
            className="bg-white border border-slate-200 text-slate-600 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-sm hover:bg-slate-50 active:scale-95 flex items-center justify-center gap-2"
          >
            <FileSpreadsheet className="w-4 h-4" /> Export
          </button>

          <button 
            onClick={onAddDevice}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-xl active:scale-95 whitespace-nowrap"
          >
            + New Asset
          </button>
        </div>
      </div>

      {/* Grid Display */}
      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto overflow-y-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map(device => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/40 transition-all group cursor-pointer"
                  onClick={() => onSelectDevice(device)}
                >
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center">
                        {device.image ? (
                          <img src={device.image} className="w-full h-full object-cover" alt="Asset" />
                        ) : (
                          <Box className="w-5 h-5 text-slate-300" />
                        )}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="text-xs font-bold text-slate-700">{device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">#{device.serialNumber}</div>
                  </td>
                  <td className="px-8 py-6">
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6">
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 shadow-sm border border-slate-100 rounded-xl transition"
                        onClick={(e) => { e.stopPropagation(); onSelectDevice(device); }}
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-red-600 shadow-sm border border-slate-100 rounded-xl transition"
                        onClick={(e) => { 
                          e.stopPropagation(); 
                          if(confirm('Confirm permanent removal?')) onDelete(device.id); 
                        }}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-24 text-center">
                    <div className="flex flex-col items-center gap-4">
                       <Search className="w-12 h-12 text-slate-100" />
                       <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No matching clinical assets found</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return (
    <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>
      {status}
    </span>
  );
};

