    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [deepLinkPending, setDeepLinkPending] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  const getLocalData = (): MedicalDevice[] => {
    try {
      const savedData = localStorage.getItem('meditrack_devices');
      return savedData ? JSON.parse(savedData) : MOCK_DEVICES;
    } catch (e) {
      return MOCK_DEVICES;
    }
  };

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*');
          if (error) throw error;
          if (data) loadedDevices = data as MedicalDevice[];
        } catch (error) {
          loadedDevices = getLocalData();
        }
      } else {
        loadedDevices = getLocalData();
      }
      setDevices(loadedDevices);

      const params = new URLSearchParams(window.location.search);
      const devId = params.get('deviceId');
      if (devId) setDeepLinkPending(devId);

      setIsLoading(false);
    };
    loadData();
  }, []);

  useEffect(() => {
    if (deepLinkPending && devices.length > 0) {
      const target = devices.find(d => d.id === deepLinkPending || d.serialNumber === deepLinkPending);
      if (target) {
        setSelectedDevice(target);
        setView('DEVICE_DETAIL');
        setDeepLinkPending(null);
        window.history.replaceState({}, '', window.location.pathname);
      }
    }
  }, [deepLinkPending, devices]);

  useEffect(() => {
    if (isScannerOpen) {
      const timer = setTimeout(() => {
        try {
          const scanner = new Html5QrcodeScanner("reader", { fps: 15, qrbox: 250 }, false);
          scanner.render((decodedText) => {
            let deviceId = decodedText;
            if (decodedText.includes('deviceId=')) {
              try { deviceId = new URL(decodedText).searchParams.get('deviceId') || decodedText; } catch (e) {}
            }
            const found = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
            if (found) {
              scanner.clear();
              setIsScannerOpen(false);
              handleSelectDevice(found);
            } else {
              alert(`Diagnostic: Asset "${deviceId}" not found in current phone database. Check Cloud Sync settings.`);
            }
          }, () => {});
          scannerRef.current = scanner;
        } catch (e) { console.error(e); }
      }, 300);
      return () => clearTimeout(timer);
    } else {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
        scannerRef.current = null;
      }
    }
  }, [isScannerOpen, devices]);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      localStorage.setItem('meditrack_devices', JSON.stringify(newDevices));
      setDevices(newDevices);
    } catch (e: any) {
      console.error(e);
      return;
    }

    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) await supabase.from('devices').delete().eq('id', changedDevice.id);
        else if (action === 'INSERT' && !Array.isArray(changedDevice)) await supabase.from('devices').insert([changedDevice]);
        else if (action === 'UPDATE' && !Array.isArray(changedDevice)) await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) await supabase.from('devices').insert(changedDevice);
      } catch (err) { console.error(err); }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      persistDeviceChange(importedDevices);
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleSaveContract = (contract: Contract, selectedDeviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (selectedDeviceIds.includes(device.id)) {
        // Prevent duplicate contracts by matching contractNumber
        const existing = device.contracts.find(c => c.contractNumber === contract.contractNumber);
        if (!existing) {
          return { ...device, contracts: [contract, ...device.contracts] };
        }
      }
      return device;
    });
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('CONTRACTS');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-20 lg:hidden" onClick={() => setSidebarOpen(false)} />}
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <NavItem icon={<ShieldCheck className="w-5 h-5" />} label="Contract Registry" targetView="CONTRACTS" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button onClick={() => { setIsScannerOpen(true); setSidebarOpen(false); }} className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"><QrCode className="w-5 h-5" /> Scan QR Code</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-xs text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900"><Cloud className="w-3 h-3" /> <span>Cloud Connected</span></div>
              ) : (
                <div className="flex items-center gap-2 text-xs text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900"><CloudOff className="w-3 h-3" /> <span>Offline Mode</span></div>
              )}
            </div>
            <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs">JD</div>
              <div><p className="text-sm font-medium">Jane Doe</p><p className="text-xs text-slate-500">Clinical Engineer</p></div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/80 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
              <p className="text-sm font-medium text-blue-600">Syncing database...</p>
            </div>
          </div>
        )}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-lg font-semibold text-slate-800">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Device Inventory'}
               {view === 'PLANNER' && 'Maintenance Planner'}
               {view === 'CONTRACTS' && 'Contract Registry'}
               {view === 'ADD_DEVICE' && 'Register Device'}
               {view === 'DEVICE_DETAIL' && 'Device Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto h-full">
            {/* ENHANCED CONNECTIVITY DIAGNOSTIC SCREEN */}
            {deepLinkPending && devices.length === 0 && !isLoading && (
              <div className="h-full flex flex-col items-center justify-center text-center p-6 animate-fade-in max-w-xl mx-auto">
                 <div className="p-8 bg-amber-50 rounded-[3rem] mb-8 border-4 border-white shadow-xl">
                   <WifiOff className="w-20 h-20 text-amber-500 animate-pulse" />
                 </div>
                 <h2 className="text-4xl font-black text-slate-900 uppercase tracking-tighter mb-4 leading-none">Access Blocked</h2>
                 <p className="text-slate-500 mb-8 font-medium leading-relaxed">
                   Your phone successfully scanned the QR code, but it <strong>cannot communicate</strong> with your clinical database.
                 </p>

                 <div className="w-full bg-white p-6 rounded-3xl border border-slate-200 text-left mb-10 space-y-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center font-bold text-blue-600">1</div>
                      <p className="text-xs font-bold text-slate-700">Are both devices on the same Wi-Fi SSID?</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center font-bold text-blue-600">2</div>
                      <p className="text-xs font-bold text-slate-700">Did you enable <strong>Cloud Sync</strong> in Settings?</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-blue-100 flex items-center justify-center font-bold text-blue-600">3</div>
                      <p className="text-xs font-bold text-slate-700">Check computer firewall for port 5173.</p>
                    </div>
                 </div>

                 <div className="flex flex-col w-full gap-4">
                   <button onClick={() => setView('SETTINGS')} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-2">Configure Bridge <ArrowRight className="w-5 h-5" /></button>
                   <button onClick={() => window.location.reload()} className="w-full py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center gap-2"><RefreshCw className="w-5 h-5" /> Retry Scan</button>
                 </div>
              </div>
            )}

            {!deepLinkPending && view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={handleSelectDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'CONTRACTS' && <ContractManager devices={devices} onSaveContract={handleSaveContract} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>

      {isScannerOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900 flex flex-col items-center justify-center p-0 sm:p-4">
          <div className="w-full h-full sm:h-auto sm:max-w-lg bg-white sm:rounded-[2.5rem] overflow-hidden shadow-2xl animate-fade-in flex flex-col">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <div className="flex items-center gap-3"><div className="p-2 bg-blue-100 rounded-lg"><Camera className="w-5 h-5 text-blue-600" /></div><h3 className="font-black text-slate-900 uppercase tracking-tight">Clinical Scan</h3></div>
              <button onClick={() => setIsScannerOpen(false)} className="p-2 bg-white text-slate-400 rounded-xl border border-slate-200 shadow-sm transition"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex-1 flex flex-col p-6 overflow-hidden bg-slate-50">
              <div className="relative w-full aspect-square bg-black rounded-3xl overflow-hidden shadow-inner ring-8 ring-white/50"><div id="reader" className="w-full h-full"></div></div>
