import { MedicalDevice } from '../types';

const DB_NAME = 'MediTrackDB';
const STORE_NAME = 'devices';
const DB_VERSION = 1;

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event: any) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event: any) => resolve(event.target.result);
    request.onerror = (event: any) => reject(event.target.error);
  });
};

export const saveDevicesToDB = async (devices: MedicalDevice[]): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    // Clear existing to ensure sync with the provided array
    const clearRequest = store.clear();

    clearRequest.onsuccess = () => {
      devices.forEach(device => {
        store.add(device);
      });
    };

    transaction.oncomplete = () => resolve();
    transaction.onerror = (event: any) => reject(event.target.error);
  });
};

export const getAllDevicesFromDB = async (): Promise<MedicalDevice[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = (event: any) => reject(event.target.error);
  });
};

/**
 * Migration helper to move data from legacy localStorage to IndexedDB
 */
export const migrateFromLocalStorage = async (): Promise<MedicalDevice[] | null> => {
  const legacyData = localStorage.getItem('meditrack_devices');
  if (legacyData) {
    try {
      const devices = JSON.parse(legacyData);
      await saveDevicesToDB(devices);
      // We don't remove it yet to be safe, but we mark it as migrated
      localStorage.setItem('meditrack_migrated', 'true');
      return devices;
    } catch (e) {
      console.error("Migration failed", e);
    }
  }
  return null;
};

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight, WifiOff, RefreshCw, ShieldCheck } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType, Contract } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { Html5QrcodeScanner } from 'html5-qrcode';
import { getAllDevicesFromDB, saveDevicesToDB, migrateFromLocalStorage } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [deepLinkPending, setDeepLinkPending] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      let loadedDevices: MedicalDevice[] = [];

      try {
        // 1. Check for migration from localStorage
        const isMigrated = localStorage.getItem('meditrack_migrated') === 'true';
        if (!isMigrated) {
          const migrated = await migrateFromLocalStorage();
          if (migrated) {
            loadedDevices = migrated;
          }
        }

        // 2. Load from IndexedDB if migration was skipped or already done
        if (loadedDevices.length === 0) {
          loadedDevices = await getAllDevicesFromDB();
        }

        // 3. Fallback to Supabase or Mock if local is empty
        if (loadedDevices.length === 0) {
          if (isSupabaseConfigured && supabase) {
            const { data, error } = await supabase.from('devices').select('*');
            if (!error && data) loadedDevices = data as MedicalDevice[];
          }
        }

        // 4. Final fallback to Mock
        if (loadedDevices.length === 0) {
          loadedDevices = MOCK_DEVICES;
        }

      } catch (error) {
        console.error("Critical storage error:", error);
        loadedDevices = MOCK_DEVICES;
      }

      setDevices(loadedDevices);

      const params = new URLSearchParams(window.location.search);
      const devId = params.get('deviceId');
      if (devId) setDeepLinkPending(devId);

      setIsLoading(false);
    };
    loadData();
  }, []);

  useEffect(() => {
    if (deepLinkPending && devices.length > 0) {
      const target = devices.find(d => d.id === deepLinkPending || d.serialNumber === deepLinkPending);
      if (target) {
        setSelectedDevice(target);
        setView('DEVICE_DETAIL');
        setDeepLinkPending(null);
        window.history.replaceState({}, '', window.location.pathname);
      }
    }
  }, [deepLinkPending, devices]);

  useEffect(() => {
    if (isScannerOpen) {
      const timer = setTimeout(() => {
        try {
          const scanner = new Html5QrcodeScanner("reader", { fps: 15, qrbox: 250 }, false);
          scanner.render((decodedText) => {
            let deviceId = decodedText;
            if (decodedText.includes('deviceId=')) {
              try { deviceId = new URL(decodedText).searchParams.get('deviceId') || decodedText; } catch (e) {}
            }
            const found = devices.find(d => d.id === deviceId || d.serialNumber === deviceId);
            if (found) {
              scanner.clear();
              setIsScannerOpen(false);
              handleSelectDevice(found);
            } else {
              alert(`Diagnostic: Asset "${deviceId}" not found in current phone database.`);
            }
          }, () => {});
          scannerRef.current = scanner;
        } catch (e) { console.error(e); }
      }, 300);
      return () => clearTimeout(timer);
    } else {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
        scannerRef.current = null;
      }
    }
  }, [isScannerOpen, devices]);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      // Save to High-Capacity IndexedDB
      await saveDevicesToDB(newDevices);
      setDevices(newDevices);
    } catch (e: any) {
      console.error("Failed to save to browser database:", e);
      alert("Browser storage limit reached. Please use Cloud Sync to save more assets.");
      return;
    }

    // Sync with Cloud if available
    if (isSupabaseConfigured && supabase && changedDevice && action) {
      try {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) await supabase.from('devices').delete().eq('id', changedDevice.id);
        else if (action === 'INSERT' && !Array.isArray(changedDevice)) await supabase.from('devices').insert([changedDevice]);
        else if (action === 'UPDATE' && !Array.isArray(changedDevice)) await supabase.from('devices').update(changedDevice).eq('id', changedDevice.id);
        else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) await supabase.from('devices').insert(changedDevice);
      } catch (err) { console.error("Cloud sync failed:", err); }
    }
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    setSelectedDevice(updated);
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const newDevices = [newDevice, ...devices];
    persistDeviceChange(newDevices, newDevice, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const newDevices = [...newDevicesList, ...devices];
    persistDeviceChange(newDevices, newDevicesList, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
      persistDeviceChange(importedDevices);
      setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleSaveContract = (contract: Contract, selectedDeviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (selectedDeviceIds.includes(device.id)) {
        const existing = device.contracts.find(c => c.contractNumber === contract.contractNumber);
        if (!existing) {
          return { ...device, contracts: [contract, ...device.contracts] };
        }
      }
      return device;
    });
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('CONTRACTS');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

