import React, { useRef, useState, useEffect } from 'react';
import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, Cloud, CheckCircle, Save, Link, LogOut, QrCode, Globe, Smartphone, Wifi, ShieldAlert, Terminal, ExternalLink, HardDrive, ShieldCheck } from 'lucide-react';
import { isSupabaseConfigured, getSupabaseConfig, saveSupabaseConfig, clearSupabaseConfig } from '../services/supabase';
import { getStorageStats } from '../services/storageService';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [config, setConfig] = useState(getSupabaseConfig());
  const [inputUrl, setInputUrl] = useState(config.url || '');
  const [inputKey, setInputKey] = useState(config.key || '');
  const [showKey, setShowKey] = useState(false);

  // Storage Diagnostic State
  const [dbCount, setDbCount] = useState<number | null>(null);
  const [lsCount, setLsCount] = useState<number | null>(null);
  const [baseUrl, setBaseUrl] = useState('');

  useEffect(() => {
    const checkStorage = async () => {
      const stats = await getStorageStats();
      setDbCount(stats.count);

      const legacy = localStorage.getItem('meditrack_devices');
      if (legacy) {
        try { setLsCount(JSON.parse(legacy).length); } catch (e) { setLsCount(0); }
      } else {
        setLsCount(0);
      }
    };
    checkStorage();

    const currentConfig = getSupabaseConfig();
    setConfig(currentConfig);
    setInputUrl(currentConfig.url || '');
    if (!currentConfig.isEnv) {
      setInputKey(currentConfig.key || '');
    }

    const storedBaseUrl = localStorage.getItem('meditrack_base_url');
    setBaseUrl(storedBaseUrl || window.location.origin);
  }, []);

  const handleSaveCloudConfig = () => {
    if (!inputUrl || !inputKey) {
      alert("Please provide both the Supabase URL and Anon Key.");
      return;
    }
    saveSupabaseConfig(inputUrl, inputKey);
  };

  const handleDisconnectCloud = () => {
    if (window.confirm("Are you sure? Multi-device sync will stop.")) {
      clearSupabaseConfig();
    }
  };

  const handleSaveBaseUrl = () => {
      let finalUrl = baseUrl.trim();
      if (finalUrl && !finalUrl.startsWith('http')) finalUrl = 'http://' + finalUrl;
      localStorage.setItem('meditrack_base_url', finalUrl);
      setBaseUrl(finalUrl);
      alert("QR Base URL Updated: " + finalUrl);
  };

  const handleExport = () => {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(devices, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `meditrack_backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (Array.isArray(jsonData)) {
          if (window.confirm(`Restore ${jsonData.length} devices? This will overwrite your current local database.`)) {
            onImport(jsonData);
          }
        }
      } catch (error) {
        alert('Error reading file.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in pb-20 px-4">

      {/* 0. Storage Diagnostic Panel */}
      <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl border border-white/5 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
          <HardDrive className="w-40 h-40 text-blue-400" />
        </div>
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
          <div className="flex-1">
             <h2 className="text-2xl font-black text-white uppercase tracking-tight">Database Integrity</h2>
             <p className="text-xs text-slate-400 font-bold uppercase mt-1 tracking-widest">Storage Status Diagnostics</p>

             <div className="grid grid-cols-2 gap-4 mt-8">
                <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                   <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">IndexedDB Assets</p>
                   <p className="text-3xl font-black text-white">{dbCount ?? '...'}</p>
                   <p className="text-[9px] text-slate-500 font-bold mt-1 uppercase">High Capacity Storage</p>
                </div>
                <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                   <p className="text-[10px] font-black text-amber-400 uppercase tracking-widest mb-1">Memory (Active)</p>
                   <p className="text-3xl font-black text-white">{devices.length}</p>
                   <p className="text-[9px] text-slate-500 font-bold mt-1 uppercase">Currently Loaded</p>
                </div>
             </div>
          </div>

          <div className="w-full md:w-64 space-y-3">
             <div className="p-4 bg-blue-500/10 rounded-2xl border border-blue-500/20 flex items-center gap-3">
                <CheckCircle className="w-5 h-5 text-blue-400" />
                <span className="text-[10px] font-black text-blue-100 uppercase">System Nominal</span>
             </div>
             <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic">
                If "IndexedDB Assets" is lower than your expected count, your browser may be restricting storage space. Clear cache or check device disk space.
             </p>
          </div>
        </div>
      </div>

      {/* 1. Cloud Sync Section */}
      <div className="bg-white p-6 sm:p-10 rounded-[2.5rem] shadow-xl border border-slate-100">
        <div className="flex items-center gap-5 mb-10">
          <div className={`p-5 rounded-3xl ${isSupabaseConfigured ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
            <Cloud className="w-10 h-10" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tight leading-none">Cloud Infrastructure</h2>
            <p className="text-sm text-slate-400 font-bold uppercase tracking-widest mt-1">Multi-Device Sync</p>
          </div>
        </div>

        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Project Endpoint</label>
                <input 
                  type="text" 
                  value={inputUrl}
                  onChange={(e) => setInputUrl(e.target.value)}
                  placeholder="https://abc.supabase.co"
                  className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 outline-none text-sm font-mono transition-all"
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Service Anon Key</label>
                <div className="relative">
                  <input 
                    type={showKey ? "text" : "password"}
                    value={inputKey}
                    onChange={(e) => setInputKey(e.target.value)}
                    placeholder="eyJhbG..."
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-blue-500/10 outline-none text-sm font-mono transition-all pr-24"
                  />
                  <button onClick={() => setShowKey(!showKey)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-400 hover:text-slate-900">{showKey ? "HIDE" : "SHOW"}</button>
                </div>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 pt-4">
              <button 
                onClick={handleSaveCloudConfig}
                className="flex-1 py-5 bg-blue-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95"
              >
                Sync with Database
              </button>
              {isSupabaseConfigured && (
                <button onClick={handleDisconnectCloud} className="px-8 py-5 bg-red-50 text-red-600 rounded-[1.5rem] font-black transition hover:bg-red-100">
                  <LogOut className="w-6 h-6" />
                </button>
              )}
            </div>
        </div>
      </div>

      {/* 3. Manual Backup */}
      <div className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100">
        <div className="flex items-center gap-5 mb-10">
          <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
            <Database className="w-8 h-8" />
          </div>
          <div>
             <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Manual Portability</h2>
             <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Full System Blueprint</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <button onClick={handleExport} className="p-8 bg-slate-50 border border-slate-200 rounded-[2rem] hover:bg-white hover:border-blue-400 transition text-left group">
            <Download className="w-8 h-8 text-blue-500 mb-6 group-hover:scale-110 transition" />
            <h3 className="font-bold text-xl text-slate-900">Export Blueprint</h3>
            <p className="text-xs text-slate-500 mt-2 font-medium leading-relaxed">Download your 1,000+ clinical inventory as a JSON file for manual backup.</p>
          </button>

          <button onClick={() => fileInputRef.current?.click()} className="p-8 bg-slate-50 border border-slate-200 rounded-[2rem] hover:bg-white hover:border-green-400 transition text-left group">
            <Upload className="w-8 h-8 text-green-500 mb-6 group-hover:scale-110 transition" />
            <h3 className="font-bold text-xl text-slate-900">Restore Point</h3>
            <p className="text-xs text-slate-500 mt-2 font-medium leading-relaxed">Overwrite current data with a saved clinical equipment manifest.</p>
            <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useRef } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera, Loader2, Layers, Hash, ChevronDown, Activity, Terminal } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  onSave: (device: MedicalDevice) => void;
  onBulkSave: (devices: MedicalDevice[]) => void;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 500 * 1024; // Target ~500KB
const AI_BATCH_SIZE = 50; // Process 50 rows at a time for stability

interface ProgressState {
  current: number;
  total: number;
  stage: 'READING' | 'MAPPING' | 'PROCESSING' | 'FINALIZING';
  message: string;
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [progress, setProgress] = useState<ProgressState | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    customDepartment: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    notes: '',
    image: ''
  });

  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed.");
      } finally {
        setIsCompressing(false);
      }
    }
  };

  const handleSingleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newDevice: MedicalDevice = {
      id: `DEV-${Math.floor(Math.random() * 90000)}`,
      ...formData,
      department: formData.department === 'OTHER' ? formData.customDepartment : formData.department,
      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };
    onSave(newDevice);
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    const dept = formData.department === 'OTHER' ? formData.customDepartment : formData.department;
    for (let i = 0; i < batchData.quantity; i++) {
      batch.push({
        id: `DEV-B-${Date.now()}-${i}`,
        ...formData,
        department: dept,
        serialNumber: `${batchData.serialPrefix}${batchData.startNum + i}`,
        status: formData.status as DeviceStatus,
        maintenanceHistory: [],
        contracts: [],
        files: []
      });
    }
    setPreviewDevices(batch);
  };

  const processDataChunks = async (allRows: any[]) => {
    setIsProcessing(true);
    setPreviewDevices([]);
    const totalRows = allRows.length;
    const allParsed: MedicalDevice[] = [];
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    setProgress({
      current: 0,
      total: totalRows,
      stage: 'PROCESSING',
      message: `Preparing to process ${totalRows} fleet items...`
    });

    for (let i = 0; i < totalRows; i += AI_BATCH_SIZE) {
      const chunk = allRows.slice(i, i + AI_BATCH_SIZE);
      setProgress(prev => ({
        ...prev!,
        current: i,
        message: `Analyzing batch ${Math.floor(i / AI_BATCH_SIZE) + 1} of ${Math.ceil(totalRows / AI_BATCH_SIZE)}...`
      }));

      try {
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview",
          contents: `Map this raw data to a clinical asset manifest: ${JSON.stringify(chunk)}`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  manufacturer: { type: Type.STRING },
                  model: { type: Type.STRING },
                  serialNumber: { type: Type.STRING },
                  department: { type: Type.STRING },
                  purchaseDate: { type: Type.STRING },
                  status: { type: Type.STRING }
                },
                required: ["name", "serialNumber"]
              }
            }
          }
        });

        const parsed: any[] = JSON.parse(response.text || "[]");
        const transformed = parsed.map(item => ({
          ...item,
          id: `DEV-${Math.floor(Math.random() * 1000000)}`,
          maintenanceHistory: [],
          contracts: [],
          files: [],
          status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
        }));
        allParsed.push(...transformed);
      } catch (error) {
        console.error("Batch error:", error);
      }
    }

    setProgress({
      current: totalRows,
      total: totalRows,
      stage: 'FINALIZING',
      message: 'Generating asset preview...'
    });

    setPreviewDevices(allParsed);
    setIsProcessing(false);
    setTimeout(() => setProgress(null), 1000);
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setProgress({ current: 0, total: 100, stage: 'READING', message: 'Decoding spreadsheet binary...' });

    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        await processDataChunks(data);
      } catch (err) { 
        alert("Spreadsheet decoding failed.");
        setIsProcessing(false);
        setProgress(null);
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleBulkTextProcess = () => {
    if (!bulkText.trim()) return;
    // Simple line split as basic chunking for raw text
    const lines = bulkText.split('\n').filter(l => l.trim());
    processDataChunks(lines);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20 relative">

      {/* Universal Processing Progress Overlay */}
      {isProcessing && progress && (
        <div className="absolute inset-0 bg-slate-900/95 backdrop-blur-xl z-[200] flex flex-col items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-md space-y-8">
            <div className="flex flex-col items-center text-center">
              <div className="p-5 bg-blue-600 rounded-3xl shadow-2xl shadow-blue-500/20 mb-6 animate-pulse">
                <Activity className="w-10 h-10 text-white" />
              </div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tight">Clinical Data Sync</h3>
              <p className="text-xs text-blue-400 font-bold uppercase mt-2 tracking-widest">{progress.stage} IN PROGRESS</p>
            </div>

            <div className="space-y-4">
              <div className="h-4 w-full bg-white/5 rounded-full overflow-hidden border border-white/10 p-0.5">
                <div 
                  className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 rounded-full transition-all duration-500 ease-out shadow-[0_0_15px_rgba(37,99,235,0.5)]"
                  style={{ width: `${(progress.current / progress.total) * 100}%` }}
                ></div>
              </div>
              <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-500">
                <span>{Math.round((progress.current / progress.total) * 100)}% Complete</span>
                <span>{progress.current} / {progress.total} Assets</span>
              </div>
            </div>

            <div className="bg-black/40 border border-white/5 rounded-2xl p-6 font-mono text-[10px] text-blue-300 space-y-2">
              <div className="flex items-center gap-2">
                <Terminal className="w-3 h-3 text-slate-500" />
                <span className="text-slate-500">medi-track-cli > status:</span>
                <span>{progress.message}</span>
              </div>
              <div className="flex items-center gap-2 opacity-50">
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-ping"></div>
                <span>Streaming validated entities to IndexedDB...</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {isCompressing && (
        <div className="absolute inset-0 bg-white/80 backdrop-blur-md z-[150] flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-12 h-12 text-blue-600 animate-spin mb-4" />
          <p className="text-sm font-black text-slate-900 uppercase tracking-widest">Optimizing Reference Image</p>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Mass Fleet Registration Engine</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Record" icon={<Box className="w-4 h-4" />} />
        <TabButton active={activeTab === 'batch'} onClick={() => setActiveTab('batch')} label="Batch Generator" icon={<Layers className="w-4 h-4" />} />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="Smart AI Extract" icon={<Wand2 className="w-4 h-4" />} />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Fleet Spreadsheet" icon={<FileSpreadsheet className="w-4 h-4" />} />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center bg-blue-50 p-8 rounded-[2.5rem] border border-blue-100">
               <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-blue-200">
                    {previewDevices.length}
                  </div>
                  <div>
                    <h3 className="font-black text-blue-900 uppercase tracking-tight text-lg">Validate Fleet Injection</h3>
                    <p className="text-xs text-blue-400 font-bold uppercase tracking-widest">Assets successfully parsed from manifest</p>
                  </div>
               </div>
               <button onClick={() => setPreviewDevices([])} className="px-6 py-3 bg-white text-blue-600 border border-blue-100 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-100 transition">Cancel Import</button>
             </div>

             <div className="max-h-[400px] overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50 shadow-inner bg-slate-50/50 p-4">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {previewDevices.map((d, i) => (
                   <div key={i} className="p-5 bg-white border border-slate-100 rounded-2xl flex items-center justify-between hover:border-blue-300 transition-all shadow-sm">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center"><Box className="w-5 h-5 text-slate-300" /></div>
                       <div>
                         <p className="font-bold text-slate-900 text-xs truncate max-w-[150px]">{d.name}</p>
                         <p className="text-[9px] font-mono text-slate-400 uppercase">SN: {d.serialNumber}</p>
                       </div>
                     </div>
                     <div className="text-[9px] font-black text-slate-400 uppercase tracking-tighter bg-slate-50 px-2.5 py-1 rounded-md">{d.department}</div>
                   </div>
                 ))}
               </div>
             </div>
             <button onClick={() => onBulkSave(previewDevices)} className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-700 transition active:scale-95 text-sm">
               Deploy {previewDevices.length} Assets to Fleet Database
             </button>
          </div>
        ) : (
          <>
            {(activeTab === 'single' || activeTab === 'batch') && (
