                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Master Reference Visual</label>
                     <div 
                      onClick={() => imageInputRef.current?.click()}
                      className="aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all overflow-hidden group relative"
                     >
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-contain" />
                       ) : (
                         <>
                           <Camera className="w-12 h-12 text-slate-300 group-hover:scale-110 transition-transform mb-2" />
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Attach Visual ID</p>
                         </>
                       )}
                       <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                     </div>
                  </div>

                  <div className="lg:col-span-8 space-y-8">
                    {activeTab === 'batch' && (
                       <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                         <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none"><Hash className="w-32 h-32 text-blue-400" /></div>
                         <h3 className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest mb-6 text-blue-400">
