                      <FormField label="Acquisition Date" name="purchaseDate" type="date" value={formData.purchaseDate} onChange={handleChange} required />
                    </div>
                  </div>
                </div>

                <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
                  <button type="button" onClick={onCancel} className="px-8 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
