                          const val = e.target.value;
                          if (val) handleUpdateDraft(device.id, { nextScheduledDate: `${val}-01` });
                        }}
                        className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-xs font-bold text-slate-700 outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 transition-all cursor-pointer"
                      />
