import React, { useState, useMemo, useEffect } from 'react';
import { MedicalDevice, MaintenanceRecord, MaintenanceType } from '../types';
import { 
  Calendar, Check, Clock, Save, CalendarDays, 
  ChevronDown, Search, Filter, ClipboardList, 
  AlertCircle, ArrowRight, Activity, FileSpreadsheet, Download, Box
} from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface MaintenancePlannerProps {
  devices: MedicalDevice[];
  onApplyPlan: (updatedDevices: MedicalDevice[]) => void;
}

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const FREQUENCY_OPTIONS = [
  'Monthly',
  'Quarterly',
  'Bi-Annually',
  'Annually',
  'Biennially',
  'On-Demand'
];

interface ScheduleDraft {
  deviceId: string;
  nextScheduledDate: string;
  frequency: string;
  tasks: string;
  isModified: boolean;
}

const MaintenancePlanner: React.FC<MaintenancePlannerProps> = ({ devices, onApplyPlan }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [drafts, setDrafts] = useState<Record<string, ScheduleDraft>>({});

  const currentYear = new Date().getFullYear();
  const yearOptions = Array.from({ length: 11 }, (_, i) => currentYear + i);

  // Initialize drafts with existing data or defaults
  useEffect(() => {
    const initialDrafts: Record<string, ScheduleDraft> = {};
    devices.forEach(device => {
      // Find the most recent scheduled date if it exists
      const latestRecord = device.maintenanceHistory[0];
      initialDrafts[device.id] = {
        deviceId: device.id,
        nextScheduledDate: latestRecord?.nextScheduledDate || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        frequency: 'Annually', // Default
        tasks: 'Standard preventive maintenance inspection.',
        isModified: false
      };
    });
    setDrafts(initialDrafts);
  }, [devices]);

  const handleUpdateDraft = (deviceId: string, updates: Partial<ScheduleDraft>) => {
    setDrafts(prev => ({
      ...prev,
      [deviceId]: { ...prev[deviceId], ...updates, isModified: true }
    }));
  };

  const filteredDevices = useMemo(() => {
    const term = (searchQuery || '').toLowerCase().trim();
    if (!term) return devices;

    return devices.filter(d => 
      (d.name || '').toLowerCase().includes(term) || 
      (d.model || '').toLowerCase().includes(term) || 
      (d.serialNumber || '').toLowerCase().includes(term) ||
      (d.department || '').toLowerCase().includes(term)
    );
  }, [devices, searchQuery]);

  const modifiedCount = useMemo(() => 
    (Object.values(drafts) as ScheduleDraft[]).filter(d => d.isModified).length
  , [drafts]);

  const handleExportSchedule = () => {
    if (devices.length === 0) return alert("No devices available to export.");

    const exportData = devices.map(device => {
      const draft = drafts[device.id] || { nextScheduledDate: 'N/A', frequency: 'N/A', tasks: 'N/A' };
      return {
        'Asset ID': device.id,
        'Asset Name': device.name,
        'Serial Number': device.serialNumber,
        'Department': device.department,
        'Model': device.model,
        'Next Planned Service': draft.nextScheduledDate,
        'Service Frequency': draft.frequency,
        'Technical Tasks': draft.tasks,
        'Current Status': device.status
      };
    });

    try {
      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Service Schedule");

      const date = new Date().toISOString().split('T')[0];
      XLSX.writeFile(workbook, `MediTrack_Service_Plan_${date}.xlsx`);
    } catch (err) {
      console.error("Export error:", err);
      alert("Failed to generate service manifest.");
    }
  };

  const commitAllSchedules = () => {
    if (modifiedCount === 0) {
      alert("No changes detected to apply.");
      return;
    }

    const updatedDevices = devices.map(device => {
      const draft = drafts[device.id] as ScheduleDraft | undefined;
      if (draft && draft.isModified) {
        const newRecord: MaintenanceRecord = {
          id: `SCHED-${Math.floor(Math.random() * 90000)}`,
          date: new Date().toISOString().split('T')[0],
          type: MaintenanceType.PREVENTIVE,
          technician: 'Fleet Planner',
          description: `[${draft.frequency}] ${draft.tasks}`,
          nextScheduledDate: draft.nextScheduledDate,
          completed: false
        };
        return {
          ...device,
          maintenanceHistory: [newRecord, ...device.maintenanceHistory]
        };
      }
      return device;
    });

    onApplyPlan(updatedDevices);
    alert(`Successfully applied schedules for ${modifiedCount} assets.`);
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      {/* Header & Global Controls */}
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-xl flex flex-col xl:flex-row items-center justify-between gap-8">
        <div className="flex-1">
          <h2 className="text-3xl font-black text-slate-900 flex items-center gap-4 uppercase tracking-tight">
            <div className="p-4 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-200">
              <CalendarDays className="w-8 h-8" />
            </div>
            Fleet Maintenance Planner
          </h2>
          <p className="text-slate-500 mt-2 font-medium max-w-xl text-sm">
            Manually schedule upcoming service windows and clinical task protocols for your equipment.
          </p>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch gap-4 w-full xl:w-auto">
          <div className="relative flex-1 sm:min-w-[300px]">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5" />
            <input 
              type="text"
              placeholder="Search by name, model, serial, or dept..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-4 focus:ring-blue-500/10 outline-none text-sm font-bold shadow-inner"
            />
          </div>
          <div className="flex gap-2">
            <button 
              onClick={handleExportSchedule}
              className="px-6 py-4 bg-white border border-slate-200 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-50 transition shadow-sm flex items-center gap-2"
            >
              <FileSpreadsheet className="w-5 h-5" /> Export Schedule
            </button>
            <button 
              onClick={commitAllSchedules}
              disabled={modifiedCount === 0}
              className={`px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-2xl active:scale-95 ${
                modifiedCount > 0 
                  ? 'bg-blue-600 text-white hover:bg-blue-700' 
                  : 'bg-slate-100 text-slate-400 cursor-not-allowed'
              }`}
            >
              <Save className="w-5 h-5" /> Apply All ({modifiedCount})
            </button>
          </div>
        </div>
      </div>

      {/* Planning Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 2xl:grid-cols-3 gap-6">
        {filteredDevices.map(device => {
          const draft = drafts[device.id] || ({ 
            nextScheduledDate: '', 
            frequency: 'Annually', 
            tasks: '', 
            isModified: false 
          } as ScheduleDraft);

          // Parse current date to get month and year indices
          const currentDate = new Date(draft.nextScheduledDate || Date.now());
          const selectedMonth = currentDate.getMonth(); // 0-11
          const selectedYear = currentDate.getFullYear();

          const handleDatePartChange = (part: 'month' | 'year', value: number) => {
            const newDate = new Date(draft.nextScheduledDate || Date.now());
            if (part === 'month') newDate.setMonth(value);
            if (part === 'year') newDate.setFullYear(value);
            // Normalize to 1st of month
            newDate.setDate(1);
            handleUpdateDraft(device.id, { nextScheduledDate: newDate.toISOString().split('T')[0] });
          };

          return (
            <div 
              key={device.id} 
              className={`bg-white p-6 rounded-[2.5rem] border-2 transition-all relative overflow-hidden group flex flex-col ${
                draft.isModified 
                  ? 'border-blue-400 shadow-2xl shadow-blue-500/10 bg-blue-50/10' 
                  : 'border-slate-100 shadow-sm hover:border-slate-200'
              }`}
            >
              <div className="flex justify-between items-start mb-6">
                <div className="flex-1">
                  <h4 className="font-black text-slate-900 text-lg leading-tight break-words">{device.name}</h4>
                  <div className="flex flex-col gap-1 mt-2">
                    <div className="flex items-center gap-2 text-[10px] font-bold text-blue-600 bg-blue-50 w-fit px-2 py-0.5 rounded-md uppercase tracking-widest">
                      <Box className="w-3 h-3" /> Model: {device.model || 'N/A'}
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{device.department || 'Unknown'}</span>
                      <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                      <span className="text-[9px] font-mono text-slate-400 font-bold">SN: {device.serialNumber || 'N/A'}</span>
                    </div>
                  </div>
                </div>
                {draft.isModified && (
                  <div className="bg-blue-600 text-white p-1.5 rounded-lg animate-pulse shrink-0 ml-2">
                    <Check className="w-4 h-4" />
                  </div>
                )}
              </div>

              <div className="space-y-6 flex-1">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">Service Target</label>
                  <div className="grid grid-cols-2 gap-2">
                    <div className="relative">
                      <select 
                        value={selectedMonth}
                        onChange={(e) => handleDatePartChange('month', parseInt(e.target.value))}
                        className="w-full bg-slate-50 border border-slate-200 px-3 py-3 rounded-xl text-xs font-bold text-slate-700 outline-none appearance-none cursor-pointer focus:border-blue-500 transition-all"
                      >
                        {MONTHS.map((m, idx) => <option key={m} value={idx}>{m}</option>)}
                      </select>
                      <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                    </div>
                    <div className="relative">
                      <select 
                        value={selectedYear}
                        onChange={(e) => handleDatePartChange('year', parseInt(e.target.value))}
                        className="w-full bg-slate-50 border border-slate-200 px-3 py-3 rounded-xl text-xs font-bold text-slate-700 outline-none appearance-none cursor-pointer focus:border-blue-500 transition-all"
                      >
                        {yearOptions.map(y => <option key={y} value={y}>{y}</option>)}
                      </select>
                      <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">Frequency</label>
                  <div className="relative">
                    <select 
                      value={draft.frequency}
                      onChange={(e) => handleUpdateDraft(device.id, { frequency: e.target.value })}
                      className="w-full bg-slate-50 border border-slate-200 px-4 py-3 rounded-xl text-xs font-bold text-slate-700 outline-none appearance-none cursor-pointer focus:border-blue-500 transition-all"
                    >
                      {FREQUENCY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">Service Protocol / Tasks</label>
                  <textarea 
                    value={draft.tasks}
                    onChange={(e) => handleUpdateDraft(device.id, { tasks: e.target.value })}
                    placeholder="Describe calibration, cleaning, or parts replacement..."
                    className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl text-xs font-medium text-slate-600 min-h-[80px] outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/5 transition-all resize-none placeholder:text-slate-300"
                  />
                </div>
              </div>

              <div className="mt-6 pt-4 border-t border-slate-50 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Activity className="w-4 h-4 text-blue-400" />
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Asset Health: Nominal</span>
                </div>
                {!draft.isModified && (
                  <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest italic">Unchanged</span>
                )}
              </div>
            </div>
          );
        })}

        {filteredDevices.length === 0 && (
          <div className="col-span-full py-32 flex flex-col items-center justify-center text-center">
            <div className="p-8 bg-slate-50 rounded-full mb-6">
              <ClipboardList className="w-16 h-16 text-slate-200" />
            </div>
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">No Assets Found</h3>
            <p className="text-sm text-slate-400 mt-2 font-medium max-w-xs">Adjust your search or add new devices to the inventory to begin planning.</p>
          </div>
        )}
      </div>

      {/* Footer Status Bar */}
      {modifiedCount > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-3xl shadow-2xl border border-white/10 flex items-center gap-8 z-50 animate-fade-in">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center font-black">
              {modifiedCount}
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 leading-none mb-1">Pending Sync</p>
              <p className="text-sm font-bold leading-none">Changes Ready to Apply</p>
            </div>
          </div>
          <div className="w-px h-8 bg-white/10"></div>
          <button 
            onClick={commitAllSchedules}
            className="px-6 py-2 bg-white text-slate-900 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-50 transition active:scale-95 flex items-center gap-2"
          >
            Deploy Now <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      )}
    </div>
  );
};

export default MaintenancePlanner;

import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent, HOSPITAL_DEPARTMENTS } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2, Loader2, Printer, Check, ChevronDown, Clock, Sparkles
} from 'lucide-react';
import { suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const FREQUENCY_OPTIONS = [
  'Monthly',
  'Quarterly',
  'Bi-Annually',
  'Annually',
  'Biennially'
];

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB Limit
const COMPRESSION_TARGET = 500 * 1024; // Target ~500KB

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);

  // Suggested Plan State for this specific device
  const [suggestedPlan, setSuggestedPlan] = useState<{
    nextScheduledDate: string;
    frequency: string;
    tasks: string;
    isModified?: boolean;
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  const currentYear = new Date().getFullYear();
  const yearOptions = Array.from({ length: 11 }, (_, i) => currentYear + i);

  const [editForm, setEditForm] = useState({
    name: device.name,
    manufacturer: device.manufacturer,
    model: device.model,
    department: device.department,
    customDepartment: '',
    status: device.status
  });

  const [maintenanceForm, setMaintenanceForm] = useState({
    technician: '',
    description: ''
  });

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditForm(prev => ({ ...prev, [name]: value }));
  };

  const saveGeneralEdits = () => {
    const finalDept = editForm.department === 'OTHER' ? editForm.customDepartment : editForm.department;
    onUpdate({
      ...device,
      name: editForm.name,
      manufacturer: editForm.manufacturer,
      model: editForm.model,
      department: finalDept,
      status: editForm.status as DeviceStatus
    });
    setIsEditing(false);
  };

  const qrLink = useMemo(() => {
    const baseUrl = localStorage.getItem('meditrack_base_url') || (window.location.origin + window.location.pathname);
    const url = new URL(baseUrl);
    url.searchParams.set('deviceId', device.id);
    return url.toString();
  }, [device.id]);

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrLink)}`;

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("File reading failed"));
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("Image decoding failed"));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context failed"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const optimized = await compressImage(file);
        onUpdate({ ...device, image: optimized });
      } catch (err) {
        alert("Visual update failed.");
      } finally {
        setIsCompressing(false);
        if (imageInputRef.current) imageInputRef.current.value = '';
      }
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let fileUrl = '';
        if (file.type.startsWith('image/')) {
          fileUrl = await compressImage(file);
        } else {
          if (file.size > MAX_FILE_SIZE) {
             alert(`PDF/Docs over 2MB cannot be auto-compressed.`);
             setIsCompressing(false);
             return;
          }
          fileUrl = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onerror = reject;
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });
        }
        const newFile: DeviceFile = {
          id: Math.random().toString(36).substring(7),
          name: file.name,
          type: selectedFileType,
          url: fileUrl,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
      } catch (err) {
        alert("Upload failed.");
      } finally {
        setIsCompressing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    }
  };

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      setSuggestedPlan({
        nextScheduledDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        frequency: res.frequency,
        tasks: res.tasks.join(', '),
        isModified: false
      });
    } catch (err) {
      alert("AI Intelligence unavailable.");
    } finally { setIsAnalyzing(false); }
  };

  const handleUpdateSuggestedDate = (part: 'month' | 'year', value: number) => {
    if (!suggestedPlan) return;
    const newDate = new Date(suggestedPlan.nextScheduledDate || Date.now());
    if (part === 'month') newDate.setMonth(value);
    if (part === 'year') newDate.setFullYear(value);
    newDate.setDate(1); // Keep as first of month
    setSuggestedPlan({ ...suggestedPlan, nextScheduledDate: newDate.toISOString().split('T')[0], isModified: true });
  };

  const commitSuggestedSchedule = () => {
    if (!suggestedPlan) return;
    const newRecord: MaintenanceRecord = {
      id: `SCHED-${Math.floor(Math.random() * 10000)}`,
      date: new Date().toISOString().split('T')[0],
      type: MaintenanceType.PREVENTIVE,
      technician: 'AI Smart Scheduler',
      description: `[SCHEDULED: ${suggestedPlan.frequency}] ${suggestedPlan.tasks}`,
      nextScheduledDate: suggestedPlan.nextScheduledDate,
      completed: false
    };
    onUpdate({
      ...device,
      maintenanceHistory: [newRecord, ...device.maintenanceHistory]
    });
    setSuggestedPlan(null);
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    const win = window.open();
    if (win) { win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`); }
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[100] flex flex-col items-center justify-center animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-100 flex flex-col items-center gap-4">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
            <div className="text-center">
              <p className="font-black text-slate-900 uppercase tracking-widest text-xs">Processing Asset</p>
            </div>
          </div>
        </div>
      )}

      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <div className="flex items-center gap-3">
             {isEditing ? (
               <input 
                name="name"
                value={editForm.name} 
                onChange={handleEditChange}
                className="text-3xl font-bold text-slate-900 tracking-tight bg-white border-2 border-blue-500 rounded-xl px-4 py-1 outline-none shadow-lg shadow-blue-500/10"
               />
             ) : (
               <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
             )}
          </div>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex gap-2">
           {isEditing ? (
             <>
                <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
                <button onClick={saveGeneralEdits} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 transition shadow-lg flex items-center gap-2"><Check className="w-4 h-4" /> Save Info</button>
             </>
           ) : (
             <>
                <button onClick={() => setIsEditing(true)} className="p-2.5 bg-white text-blue-600 border border-slate-200 rounded-lg hover:bg-blue-50 transition shadow-sm">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm">
                  <Trash2 className="w-5 h-5" />
                </button>
             </>
           )}
           <button 
            type="button" 
            onClick={() => setActiveTab('qr')} 
            className={`flex items-center gap-2 px-4 py-2 rounded-lg transition shadow-md font-bold text-sm ${activeTab === 'qr' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}
           >
             <QrCode className="w-4 h-4" /> QR ID
