      const serviceWindow = isNaN(serviceDate.getTime()) 
        ? 'UNSCHEDULED' 
        : `${MONTHS[serviceDate.getMonth()].toUpperCase()} ${serviceDate.getFullYear()}`;

      return [
        device.name,
        device.manufacturer,
        device.model,
        device.serialNumber,
        device.department,
        serviceWindow,
        draft.frequency.toUpperCase(),
        draft.tasks,
        device.status.toUpperCase()
      ];
    });

    // 2. Construct Aesthetic AOA (Array of Arrays)
    const aoa = [
      ['MEDITRACK | CLINICAL ENGINEERING FLEET MANIFEST'],
      [`OFFICIAL SERVICE PLAN GENERATED ON ${dateStr} AT ${timeStr}`],
