          nextScheduledDate: draft.nextScheduledDate,
          completed: false
        };
        return {
          ...device,
          maintenanceHistory: [newRecord, ...device.maintenanceHistory]
        };
      }
      return device;
    });

    onApplyPlan(updatedDevices);
