import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent, HOSPITAL_DEPARTMENTS } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2, Loader2, Printer, Check, ChevronDown, Clock, Sparkles
} from 'lucide-react';
import { suggestMaintenanceSchedule } from '../services/geminiService';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const FREQUENCY_OPTIONS = [
  'Monthly',
  'Quarterly',
  'Bi-Annually',
  'Annually',
  'Biennially'
];

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB Limit
const COMPRESSION_TARGET = 500 * 1024; // Target ~500KB

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);

  // Suggested Plan State for this specific device
  const [suggestedPlan, setSuggestedPlan] = useState<{
    nextScheduledDate: string;
    frequency: string;
    tasks: string;
    isModified?: boolean;
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [selectedFileType, setSelectedFileType] = useState<DeviceFile['type']>('report');

  const currentYear = new Date().getFullYear();
  const yearOptions = Array.from({ length: 11 }, (_, i) => currentYear + i);

  // Determine if current department is in the standard list
  const isDeptStandard = useMemo(() => 
    (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department)
  , [device.department]);

  const [editForm, setEditForm] = useState({
    name: device.name,
    manufacturer: device.manufacturer,
    model: device.model,
    department: isDeptStandard ? device.department : 'OTHER',
    customDepartment: isDeptStandard ? '' : device.department,
    status: device.status
  });

  const [maintenanceForm, setMaintenanceForm] = useState({
    technician: '',
    description: ''
  });

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditForm(prev => ({ ...prev, [name]: value }));
  };

  const saveGeneralEdits = () => {
    const finalDept = editForm.department === 'OTHER' ? (editForm.customDepartment || 'Unassigned') : editForm.department;
    onUpdate({
      ...device,
      name: editForm.name,
      manufacturer: editForm.manufacturer,
      model: editForm.model,
      department: finalDept,
      status: editForm.status as DeviceStatus
    });
    setIsEditing(false);
  };

  const qrLink = useMemo(() => {
    const baseUrl = localStorage.getItem('meditrack_base_url') || (window.location.origin + window.location.pathname);
    const url = new URL(baseUrl);
    url.searchParams.set('deviceId', device.id);
    return url.toString();
  }, [device.id]);

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrLink)}`;

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onerror = () => reject(new Error("File reading failed"));
      reader.onload = (event) => {
        const img = new Image();
        img.onerror = () => reject(new Error("Image decoding failed"));
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context failed"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const optimized = await compressImage(file);
        onUpdate({ ...device, image: optimized });
      } catch (err) {
        alert("Visual update failed.");
      } finally {
        setIsCompressing(false);
        if (imageInputRef.current) imageInputRef.current.value = '';
      }
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let fileUrl = '';
        if (file.type.startsWith('image/')) {
          fileUrl = await compressImage(file);
        } else {
          if (file.size > MAX_FILE_SIZE) {
             alert(`PDF/Docs over 2MB cannot be auto-compressed.`);
             setIsCompressing(false);
             return;
          }
          fileUrl = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onerror = reject;
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(file);
          });
        }
        const newFile: DeviceFile = {
          id: Math.random().toString(36).substring(7),
          name: file.name,
          type: selectedFileType,
          url: fileUrl,
          dateAdded: new Date().toISOString().split('T')[0]
        };
        onUpdate({ ...device, files: [...device.files, newFile] });
      } catch (err) {
        alert("Upload failed.");
      } finally {
        setIsCompressing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    }
  };

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      setSuggestedPlan({
        nextScheduledDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        frequency: res.frequency,
        tasks: res.tasks.join(', '),
        isModified: false
      });
    } catch (err) {
      alert("AI Intelligence unavailable.");
    } finally { setIsAnalyzing(false); }
  };

  const handleUpdateSuggestedDate = (part: 'month' | 'year', value: number) => {
    if (!suggestedPlan) return;
    const newDate = new Date(suggestedPlan.nextScheduledDate || Date.now());
    if (part === 'month') newDate.setMonth(value);
    if (part === 'year') newDate.setFullYear(value);
    newDate.setDate(1); // Keep as first of month
    setSuggestedPlan({ ...suggestedPlan, nextScheduledDate: newDate.toISOString().split('T')[0], isModified: true });
  };

  const commitSuggestedSchedule = () => {
    if (!suggestedPlan) return;
    const newRecord: MaintenanceRecord = {
      id: `SCHED-${Math.floor(Math.random() * 10000)}`,
      date: new Date().toISOString().split('T')[0],
      type: MaintenanceType.PREVENTIVE,
      technician: 'AI Smart Scheduler',
      description: `[SCHEDULED: ${suggestedPlan.frequency}] ${suggestedPlan.tasks}`,
      nextScheduledDate: suggestedPlan.nextScheduledDate,
      completed: false
    };
    onUpdate({
      ...device,
      maintenanceHistory: [newRecord, ...device.maintenanceHistory]
    });
    setSuggestedPlan(null);
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    const win = window.open();
    if (win) { win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`); }
  };

  const reports = device.files.filter(f => f.type === 'report');
  const manuals = device.files.filter(f => f.type === 'manual');

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/60 backdrop-blur-[2px] z-[100] flex flex-col items-center justify-center animate-fade-in">
          <div className="bg-white p-8 rounded-3xl shadow-2xl border border-slate-100 flex flex-col items-center gap-4">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
            <div className="text-center">
              <p className="font-black text-slate-900 uppercase tracking-widest text-xs">Processing Asset</p>
            </div>
          </div>
        </div>
      )}

      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">
            ← Back to Inventory
          </button>
          <div className="flex items-center gap-3">
             {isEditing ? (
               <input 
                name="name"
                value={editForm.name} 
                onChange={handleEditChange}
                className="text-3xl font-bold text-slate-900 tracking-tight bg-white border-2 border-blue-500 rounded-xl px-4 py-1 outline-none shadow-lg shadow-blue-500/10"
               />
             ) : (
               <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>
             )}
          </div>
          <div className="flex items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex gap-2">
           {isEditing ? (
             <>
                <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
                <button onClick={saveGeneralEdits} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 transition shadow-lg flex items-center gap-2"><Check className="w-4 h-4" /> Save Info</button>
             </>
           ) : (
             <>
                <button onClick={() => setIsEditing(true)} className="p-2.5 bg-white text-blue-600 border border-slate-200 rounded-lg hover:bg-blue-50 transition shadow-sm">
                  <Edit2 className="w-5 h-5" />
                </button>
                <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm">
                  <Trash2 className="w-5 h-5" />
                </button>
             </>
           )}
           <button 
