            onClick={() => setActiveTab('qr')} 
            className={`flex items-center gap-2 px-4 py-2 rounded-lg transition shadow-md font-bold text-sm ${activeTab === 'qr' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}
           >
             <QrCode className="w-4 h-4" /> QR ID
           </button>
        </div>
      </div>

      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
