        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Contracts" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
