              <div className="bg-blue-50 p-8 rounded-[2.5rem] border-2 border-blue-400 shadow-2xl animate-fade-in space-y-6">
                <div className="flex justify-between items-center">
                  <h4 className="text-sm font-black text-blue-900 uppercase tracking-widest flex items-center gap-2">
                    <Clock className="w-5 h-5" /> Pending Maintenance Strategy
                  </h4>
                  <button onClick={() => setSuggestedPlan(null)} className="text-blue-400 hover:text-blue-600 transition p-1"><X className="w-5 h-5" /></button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-white p-8 rounded-3xl border border-blue-100">
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Service Target</label>
                      <div className="grid grid-cols-2 gap-2">
                        <div className="relative">
                          <select 
                            value={new Date(suggestedPlan.nextScheduledDate || Date.now()).getMonth()}
                            onChange={(e) => handleUpdateSuggestedDate('month', parseInt(e.target.value))}
                            className="w-full bg-blue-50/50 border-2 border-blue-200 px-4 py-3 rounded-2xl text-xs font-bold text-blue-900 outline-none appearance-none cursor-pointer focus:border-blue-500 transition-all"
                          >
                            {MONTHS.map((m, idx) => <option key={m} value={idx}>{m}</option>)}
                          </select>
                          <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-blue-400 pointer-events-none" />
                        </div>
                        <div className="relative">
                          <select 
                            value={new Date(suggestedPlan.nextScheduledDate || Date.now()).getFullYear()}
                            onChange={(e) => handleUpdateSuggestedDate('year', parseInt(e.target.value))}
                            className="w-full bg-blue-50/50 border-2 border-blue-200 px-4 py-3 rounded-2xl text-xs font-bold text-blue-900 outline-none appearance-none cursor-pointer focus:border-blue-500 transition-all"
                          >
                            {yearOptions.map(y => <option key={y} value={y}>{y}</option>)}
                          </select>
                          <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-blue-400 pointer-events-none" />
                        </div>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Cycle Frequency</label>
                      <div className="relative">
                        <select 
                          value={suggestedPlan.frequency}
                          onChange={(e) => setSuggestedPlan({ ...suggestedPlan, frequency: e.target.value, isModified: true })}
                          className="w-full bg-blue-50/50 border-2 border-blue-200 px-5 py-4 rounded-2xl text-sm font-bold text-blue-900 outline-none appearance-none cursor-pointer focus:border-blue-500"
                        >
                          {FREQUENCY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                          {!FREQUENCY_OPTIONS.includes(suggestedPlan.frequency) && <option value={suggestedPlan.frequency}>{suggestedPlan.frequency}</option>}
                        </select>
                        <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-blue-400 pointer-events-none" />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Clinical Task Manifest</label>
                     <p className="text-sm text-slate-600 font-medium leading-relaxed italic bg-slate-50 p-6 rounded-2xl border border-slate-100 min-h-[120px]">
                       "{suggestedPlan.tasks}"
                     </p>
                  </div>
                </div>

                <button 
                  onClick={commitSuggestedSchedule}
                  className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95 flex items-center justify-center gap-3"
                >
                  <Check className="w-5 h-5" /> Commit to Service Calendar
                </button>
              </div>
            )}

            {/* Existing Logs */}
            <div className="space-y-4">
              {device.maintenanceHistory.length > 0 ? (
                device.maintenanceHistory.map(record => (
                  <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-blue-200 transition-all">
                    <div className="flex gap-6">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>
                        {record.completed ? <ShieldCheck className="w-7 h-7" /> : <Clock className="w-7 h-7" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-3">
                          <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">{record.type}</h4>
                          {!record.completed && <span className="text-[9px] font-black text-amber-600 bg-amber-50 px-2 py-1 rounded-md uppercase">UPCOMING</span>}
