                        <p className="text-sm text-slate-600 line-clamp-2 mt-1 font-medium">{record.description}</p>
                        <div className="flex items-center gap-4 mt-3">
                           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tech: {record.technician}</span>
                           {record.nextScheduledDate && <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded">Due: {record.nextScheduledDate}</span>}
                        </div>
                      </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                      <div className="font-black text-slate-900 text-sm whitespace-nowrap">{record.date}</div>
                      <button 
                        onClick={() => onUpdate({ ...device, maintenanceHistory: device.maintenanceHistory.filter(r => r.id !== record.id) })}
                        className="mt-4 p-2 text-slate-300 hover:text-red-500 transition opacity-0 group-hover:opacity-100"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-20 flex flex-col items-center justify-center text-center opacity-40">
                   <Calendar className="w-16 h-16 text-slate-200 mb-4" />
                   <p className="text-sm font-black uppercase tracking-widest text-slate-400">No logs on record</p>
                </div>
              )}
            </div>
          </div>
        )}

        {activeTab === 'contracts' && (
          <div className="max-w-4xl mx-auto space-y-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
               <h3 className="text-2xl font-bold text-slate-900 mb-6">Service Level Agreements</h3>
               {device.contracts.map(contract => (
                 <div key={contract.id} className="p-6 bg-slate-50 border border-slate-200 rounded-3xl mb-4">
                    <div className="flex justify-between items-start mb-4">
                      <div>
                        <p className="text-lg font-bold text-slate-900">{contract.provider}</p>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">ID: {contract.contractNumber}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-lg font-black text-green-600">${contract.annualCost.toLocaleString()}/yr</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4 text-sm mb-6">
                      <div className="bg-white p-4 rounded-2xl border border-slate-100">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Effective Period</p>
                        <p className="font-bold">{contract.startDate} → {contract.endDate}</p>
                      </div>
                      <div className="bg-white p-4 rounded-2xl border border-slate-100">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Support Contact</p>
                        <p className="font-bold">{contract.contactPhone}</p>
                      </div>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border border-slate-100">
                       <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Coverage Scope</p>
                       <p className="text-slate-600 font-medium">{contract.coverageDetails}</p>
                    </div>
                 </div>
               ))}
               <button className="w-full py-6 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400 font-bold hover:border-blue-300 transition">+ REGISTER NEW CONTRACT</button>
            </div>
          </div>
        )}

        {activeTab === 'qr' && (
          <div className="max-w-xl mx-auto space-y-8 py-10 animate-fade-in">
             <div className="bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 flex flex-col items-center text-center">
                <div className="mb-8">
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Digital Asset Passport</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-2">Unique Identification QR</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-inner border-4 border-slate-50 mb-8">
                  <img src={qrCodeUrl} alt="QR Code" className="w-64 h-64" />
                </div>
                <div className="space-y-4 w-full">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 text-left">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Encrypted Link</p>
                    <p className="text-xs font-mono text-slate-600 break-all">{qrLink}</p>
                  </div>
                  <div className="flex gap-4">
                    <button onClick={() => {
                      const printWindow = window.open('', '_blank');
                      if (printWindow) {
                          printWindow.document.write(`<html><body onload="window.print(); window.close();" style="text-align:center; padding:40px;"><div style="border:2px solid #000; display:inline-block; padding:20px; border-radius:10px;"><h1>MediTrack</h1><h2>${device.name}</h2><img src="${qrCodeUrl}" width="200" height="200" /><p>ID: ${device.id}</p></div></body></html>`);
                          printWindow.document.close();
                      }
                    }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-black transition shadow-xl"><Printer className="w-5 h-5" /> PRINT LABEL</button>
                    <a href={qrCodeUrl} download={`${device.name}-qr.png`} className="flex-1 py-4 bg-white border border-slate-200 text-slate-900 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition shadow-sm"><Download className="w-5 h-5" /> DOWNLOAD</a>
                  </div>
                </div>
             </div>
          </div>
        )}

        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="Detail" className="max-w-full max-h-full object-contain" />
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none min-h-[100px]" placeholder="Work summary..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <div className="flex gap-4">
              <button type="button" onClick={() => setShowMaintenanceModal(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold">Cancel</button>
              <button type="button" onClick={() => {
                const newR: MaintenanceRecord = { id: Math.random().toString(36).substring(7), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Engineering Dept', description: maintenanceForm.description || 'No details', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setMaintenanceForm({ technician: '', description: '' });
                setShowMaintenanceModal(false);
              }} className="flex-2 px-8 py-4 bg-green-600 text-white rounded-2xl font-bold">Log Event</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
  if (status === DeviceStatus.ACTIVE) color = "bg-green-100 text-green-700 border-green-200";
  if (status === DeviceStatus.BROKEN) color = "bg-red-100 text-red-700 border-red-200";
  if (status === DeviceStatus.MAINTENANCE) color = "bg-amber-100 text-amber-700 border-amber-200";
  return <span className={`px-2.5 py-1 border rounded-full text-xs font-semibold shadow-sm uppercase ${color}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
