                      <Camera className="w-4 h-4" />
                      <span className="text-[8px] font-black opacity-40 uppercase">Update Photo</span>
                    </button>
                    {device.image && (
                      <button type="button" onClick={() => setShowFullImage(true)} className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition">
