                 <button type="button" onClick={() => setShowMaintenanceModal(true)} className="px-6 py-3.5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 transition hover:bg-black shadow-xl">
