        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5" />
          <input 
            type="text"
            placeholder="Search assets by name, serial, or model..."
            className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:outline-none text-sm font-medium transition-all"
            value={localSearch}
            onChange={(e) => setLocalSearch(e.target.value)}
          />
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider"
            value={filterDept}
            onChange={(e) => setFilterDept(e.target.value)}
          >
            <option value="ALL">ALL DEPTS</option>
            {uniqueDeptsInData.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
          </select>

          <select 
            className="px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
          >
            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>

          <button 
            onClick={handleExportExcel}
            className="bg-white border border-slate-200 text-slate-600 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-sm hover:bg-slate-50 active:scale-95 flex items-center justify-center gap-2"
          >
            <FileSpreadsheet className="w-4 h-4" /> Export
          </button>

          <button 
            onClick={onAddDevice}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-xl active:scale-95 whitespace-nowrap"
          >
            + New Asset
          </button>
        </div>
      </div>

      {/* Grid Display */}
      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto overflow-y-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map(device => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/40 transition-all group cursor-pointer"
                  onClick={() => onSelectDevice(device)}
                >
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center">
                        {device.image ? (
                          <img src={device.image} className="w-full h-full object-cover" alt="Asset" />
                        ) : (
                          <Box className="w-5 h-5 text-slate-300" />
                        )}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="text-xs font-bold text-slate-700">{device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">#{device.serialNumber}</div>
                  </td>
                  <td className="px-8 py-6">
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6">
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    {/* FIXED: Removed opacity-0 to ensure buttons are always visible for functional access */}
                    <div className="flex justify-end gap-2 transition-opacity">
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-95"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                        title="Quick Edit Information"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-95"
                        onClick={(e) => handleViewClick(e, device)}
                        title="View Full Details"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-red-600 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-95"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                        title="Remove Asset"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-24 text-center">
