                    }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-black transition shadow-xl"><Printer className="w-5 h-5" /> PRINT LABEL</button>
                    <a href={qrCodeUrl} download={`${device.name}-qr.png`} className="flex-1 py-4 bg-white border border-slate-200 text-slate-900 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition shadow-sm"><Download className="w-5 h-5" /> DOWNLOAD</a>
                  </div>
                </div>
             </div>
          </div>
        )}

        {showFullImage && device.image && (
          <div className="fixed inset-0 bg-black/95 z-[100] flex items-center justify-center p-8" onClick={() => setShowFullImage(false)}>
            <button type="button" className="absolute top-8 right-8 text-white hover:scale-110 transition"><X className="w-10 h-10" /></button>
            <img src={device.image} alt="Detail" className="max-w-full max-h-full object-contain" />
          </div>
        )}
      </div>

      {showMaintenanceModal && (
        <div className="fixed inset-0 bg-black/50 z-[9999] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-8 max-w-lg w-full animate-fade-in relative border-4 border-white">
            <h3 className="text-xl font-bold mb-6">Log Service Record</h3>
            <input className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none" placeholder="Technician Name" value={maintenanceForm.technician} onChange={e => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
            <textarea className="w-full p-4 bg-slate-50 border rounded-2xl mb-4 outline-none min-h-[100px]" placeholder="Work summary..." value={maintenanceForm.description} onChange={e => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
            <div className="flex gap-4">
              <button type="button" onClick={() => setShowMaintenanceModal(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold">Cancel</button>
              <button type="button" onClick={() => {
                const newR: MaintenanceRecord = { id: Math.random().toString(36).substring(7), date: new Date().toISOString().split('T')[0], type: MaintenanceType.PREVENTIVE, technician: maintenanceForm.technician || 'Engineering Dept', description: maintenanceForm.description || 'No details', completed: true };
                onUpdate({ ...device, maintenanceHistory: [newR, ...device.maintenanceHistory] });
                setMaintenanceForm({ technician: '', description: '' });
                setShowMaintenanceModal(false);
              }} className="flex-2 px-8 py-4 bg-green-600 text-white rounded-2xl font-bold">Log Event</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
