import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onAddDevice, onDelete }) => {
  const [localSearch, setLocalSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    status: DeviceStatus.ACTIVE
  });

  const filteredDevices = useMemo(() => {
    const term = localSearch.toLowerCase().trim();
    return devices.filter(d => {
      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;

      return matchSearch && matchStatus && matchDept;
    });
  }, [devices, localSearch, filterStatus, filterDept]);

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => set.add(d.department));
    return Array.from(set).sort();
  }, [devices]);

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    const isDeptStandard = (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department as any);

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: isDeptStandard ? device.department : 'OTHER',
      customDepartment: isDeptStandard ? '' : device.department,
      purchaseDate: device.purchaseDate,
      status: device.status
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setQuickEditForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSaveQuickEdit = () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'OTHER' ? (quickEditForm.customDepartment || 'Unassigned') : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      status: quickEditForm.status
    };

    onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleViewClick = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();
    onSelectDevice(device);
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['ASSET NAME', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'LAST SERVICE', 'INTERNAL ID'];
    const tableRows = filteredDevices.map(d => [d.name, d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.maintenanceHistory[0]?.date || 'NO HISTORY', d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | STATUS FILTER: ${filterStatus.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  return (
    <div className="space-y-6 animate-fade-in relative">
      {/* Search & Filter Header - STICKY FOR ACCESSIBILITY IN FULLSCREEN */}
      <div className="sticky top-0 z-30 -mx-8 -mt-8 px-8 pt-8 pb-4 bg-slate-50/90 backdrop-blur-md transition-all">
        <div className="flex flex-col xl:flex-row justify-between items-stretch xl:items-center gap-4 bg-white p-6 rounded-[2rem] shadow-xl border border-slate-100">
          <div className="relative flex-1 group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
            <input 
              type="text"
              placeholder="Search assets..."
              className="w-full pl-12 pr-6 py-4 bg-slate-50 border-none rounded-2xl focus:ring-4 focus:ring-blue-500/10 focus:outline-none text-sm font-medium transition-all"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <div className="relative">
              <select 
                className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterDept}
                onChange={(e) => setFilterDept(e.target.value)}
              >
                <option value="ALL">ALL DEPTS</option>
                {uniqueDeptsInData.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
              >
                <option value="ALL">ALL STATUSES</option>
                {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <button onClick={handleExportExcel} className="bg-white border border-slate-200 text-slate-600 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-sm hover:bg-slate-50 active:scale-95 flex items-center justify-center gap-2">
              <FileSpreadsheet className="w-4 h-4" /> Export
            </button>
            <button onClick={onAddDevice} className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition shadow-xl active:scale-95 whitespace-nowrap">
              + New Asset
            </button>
          </div>
        </div>
      </div>

      {/* Grid Display */}
      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map(device => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/40 transition-all group"
                >
                  {/* Clickable Area for Navigation */}
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center">
                        {device.image ? <img src={device.image} className="w-full h-full object-cover" alt="Asset" /> : <Box className="w-5 h-5 text-slate-300" />}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="text-xs font-bold text-slate-700">{device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">#{device.serialNumber}</div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <StatusBadge status={device.status} />
                  </td>
                  {/* ISOLATED ACTIONS: These buttons won't trigger the row's click navigation */}
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                        title="Quick Edit Information"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                        onClick={(e) => handleViewClick(e, device)}
                        title="View Full Details"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                        title="Remove Asset"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-24 text-center">
                    <div className="flex flex-col items-center gap-4">
                       <Search className="w-12 h-12 text-slate-100" />
                       <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No matching clinical assets found</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Quick Edit Modal - REINFORCED STACKING AND INTERACTION */}
      {editingDevice && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90 transition-opacity" onClick={() => setEditingDevice(null)}></div>
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-fade-in border-4 border-white overflow-hidden relative z-10">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-100 text-blue-600 rounded-xl">
                    <Edit2 className="w-5 h-5" />
