      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;

      return matchSearch && matchStatus && matchDept;
    });
  }, [devices, localSearch, filterStatus, filterDept]);

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => set.add(d.department));
    return Array.from(set).sort();
  }, [devices]);

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    const isDeptStandard = (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department as any);

