  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['ASSET NAME', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'LAST SERVICE', 'INTERNAL ID'];
    const tableRows = filteredDevices.map(d => [d.name, d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.maintenanceHistory[0]?.date || 'NO HISTORY', d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | STATUS FILTER: ${filterStatus.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
