        <div className="flex flex-col xl:flex-row justify-between items-stretch xl:items-center gap-4 bg-white p-6 rounded-[2rem] shadow-xl border border-slate-100">
          <div 
            className="relative flex-1 group cursor-text" 
            onPointerDown={forceFocus}
            onClick={forceFocus}
          >
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 w-5 h-5 pointer-events-none group-focus-within:text-blue-500 transition-colors" />
            <input 
              ref={searchInputRef}
              type="text"
              placeholder="Search assets by name, model or serial..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-blue-500/20 focus:bg-white focus:ring-4 focus:ring-blue-500/10 focus:outline-none text-sm font-medium transition-all"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
            <div className="relative">
              <select 
                className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterDept}
                onChange={(e) => setFilterDept(e.target.value)}
              >
                <option value="ALL">ALL DEPTS</option>
                {uniqueDeptsInData.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black text-slate-600 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterStatus}
