               <button type="button" onClick={() => setEditingDevice(null)} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm border border-slate-200"><X className="w-6 h-6" /></button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto max-h-[70vh]">
              <QuickField label="Asset Name" name="name" value={quickEditForm.name} onChange={handleQuickEditChange} icon={<Box className="w-3 h-3"/>} />
              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Manufacturer" name="manufacturer" value={quickEditForm.manufacturer} onChange={handleQuickEditChange} />
                <QuickField label="Model" name="model" value={quickEditForm.model} onChange={handleQuickEditChange} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Serial Number" name="serialNumber" value={quickEditForm.serialNumber} onChange={handleQuickEditChange} />
                <QuickField label="Purchase Date" name="purchaseDate" type="date" value={quickEditForm.purchaseDate} onChange={handleQuickEditChange} icon={<Calendar className="w-3 h-3"/>} />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Department Registry</label>
                <div className="relative">
                   <select 
                     name="department" 
                     value={quickEditForm.department} 
                     onChange={handleQuickEditChange} 
                     className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                   >
                      {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      <option value="OTHER">OTHER / CUSTOM...</option>
                   </select>
                   <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
              {quickEditForm.department === 'OTHER' && (
                <div className="animate-fade-in">
                  <QuickField label="Custom Dept Name" name="customDepartment" value={quickEditForm.customDepartment} onChange={handleQuickEditChange} placeholder="Type new department..." />
                </div>
              )}
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Life Cycle Status</label>
                <div className="relative">
                  <select 
                    name="status" 
                    value={quickEditForm.status} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex gap-4">
              <button type="button" onClick={() => setEditingDevice(null)} className="flex-1 py-4 bg-white text-slate-500 border border-slate-200 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition">Cancel</button>
              <button 
                type="button"
                onClick={handleSaveQuickEdit}
                className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center justify-center gap-2 active:scale-95"
              >
                <Check className="w-5 h-5" /> Update Registry
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const QuickField = ({ label, name, value, onChange, type = "text", icon, placeholder }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 ml-1">
      {icon} {label}
    </label>
    <input 
      name={name} 
      type={type}
      value={value} 
      onChange={onChange} 
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
    />
  </div>
);

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight, WifiOff, RefreshCw, ShieldCheck, Database, Loader2 } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType, Contract } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { Html5QrcodeScanner } from 'html5-qrcode';
import { getAllDevicesFromDB, saveDevicesToDB, migrateFromLocalStorage } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [deepLinkPending, setDeepLinkPending] = useState<string | null>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      try {
        const isMigrated = localStorage.getItem('meditrack_migrated') === 'true';
        if (!isMigrated) {
          const migrated = await migrateFromLocalStorage();
          if (migrated && migrated.length > 0) {
            setDevices(migrated);
            setIsLoading(false);
            return;
          }
        }

        const localData = await getAllDevicesFromDB();

        if (localData.length === 0 && isSupabaseConfigured && supabase) {
          const { data, error } = await supabase.from('devices').select('*');
          if (!error && data && data.length > 0) {
            await saveDevicesToDB(data as MedicalDevice[]);
            setDevices(data as MedicalDevice[]);
            setIsLoading(false);
            return;
          }
        }

        setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
      } catch (error) {
        console.error("Critical storage error:", error);
        setDevices(MOCK_DEVICES);
      } finally {
        setIsLoading(false);
      }
    };
    loadData();
  }, []);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      await saveDevicesToDB(newDevices);
      setDevices(newDevices);

      if (isSupabaseConfigured && supabase && changedDevice && action) {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').delete().eq('id', (changedDevice as MedicalDevice).id);
        } else if (action === 'INSERT' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').insert([changedDevice]);
        } else if (action === 'UPDATE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').update(changedDevice).eq('id', (changedDevice as MedicalDevice).id);
        } else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) {
          const chunkSize = 100;
          for (let i = 0; i < changedDevice.length; i += chunkSize) {
            const chunk = changedDevice.slice(i, i + chunkSize);
            await supabase.from('devices').insert(chunk);
          }
        }
      }
    } catch (e: any) {
      console.error("Database Error:", e);
      alert(`Storage failure: ${e.message || "Disk full or quota exceeded"}.`);
    }
  };

  const generateUniqueId = () => {
    return `DEV-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  };

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    if (selectedDevice?.id === updated.id) {
      setSelectedDevice(updated);
    }
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const deviceWithId = { ...newDevice, id: generateUniqueId() };
    const newDevices = [deviceWithId, ...devices];
    persistDeviceChange(newDevices, deviceWithId, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const devicesWithIds = newDevicesList.map(d => ({ ...d, id: d.id || generateUniqueId() }));
    const newDevices = [...devicesWithIds, ...devices];
    persistDeviceChange(newDevices, devicesWithIds, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    if (!deviceToDelete) return;
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
    persistDeviceChange(importedDevices, importedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleSaveContract = (contract: Contract, selectedDeviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (selectedDeviceIds.includes(device.id)) {
        const existing = device.contracts.find(c => c.contractNumber === contract.contractNumber);
        if (!existing) {
          return { ...device, contracts: [contract, ...device.contracts] };
        }
      }
      return device;
    });
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('CONTRACTS');
  };

