                  value={inventorySearch}
                  onChange={(e) => setInventorySearch(e.target.value)}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-4 min-w-[150px] justify-end">
             {isSyncing && <Zap className="w-4 h-4 text-blue-500 animate-pulse" />}
             {view === 'INVENTORY' && (
               <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-lg active:scale-95 whitespace-nowrap">
                 + New Asset
               </button>
             )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto min-h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={handleSelectDevice} onUpdateDevice={handleUpdateDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} searchQuery={inventorySearch} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'CONTRACTS' && <ContractManager devices={devices} onSaveContract={handleSaveContract} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent, HOSPITAL_DEPARTMENTS } from '../types';
