    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [inventorySearch, setInventorySearch] = useState('');

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      // 1. Initial Local Load (Always fast)
      const localData = await getAllDevicesFromDB();
      if (!force) setDevices(localData.length > 0 ? localData : MOCK_DEVICES);

      // 2. Cloud Sync (Source of truth for multi-computer updates)
      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase
          .from('devices')
          .select('*')
          .order('id', { ascending: true });

        if (!error && cloudData) {
          const cloudDevices = cloudData as MedicalDevice[];
          await saveDevicesToDB(cloudDevices);
          setDevices(cloudDevices);
        }
      }
    } catch (error) {
      console.error("Sync error:", error);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      await saveDevicesToDB(newDevices);
      setDevices(newDevices);

      if (isSupabaseConfigured && supabase && changedDevice && action) {
        setIsSyncing(true);
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').delete().eq('id', (changedDevice as MedicalDevice).id);
        } else if (action === 'INSERT' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').insert([changedDevice]);
        } else if (action === 'UPDATE' && !Array.isArray(changedDevice)) {
          await supabase.from('devices').upsert(changedDevice);
        } else if (action === 'BULK_INSERT' && Array.isArray(changedDevice)) {
          await supabase.from('devices').upsert(changedDevice);
        }
        setIsSyncing(false);
      }
    } catch (e: any) {
      console.error("Database Error:", e);
      alert(`Cloud sync failure: ${e.message}. Data saved locally.`);
      setIsSyncing(false);
    }
  };

  const generateUniqueId = () => `DEV-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    persistDeviceChange(newDevices, updated, 'UPDATE');
    if (selectedDevice?.id === updated.id) {
      setSelectedDevice(updated);
    }
  };

  const handleAddDevice = (newDevice: MedicalDevice) => {
    const deviceWithId = { ...newDevice, id: generateUniqueId() };
    const newDevices = [deviceWithId, ...devices];
    persistDeviceChange(newDevices, deviceWithId, 'INSERT');
    setView('INVENTORY');
  };

  const handleBulkAddDevices = (newDevicesList: MedicalDevice[]) => {
    const devicesWithIds = newDevicesList.map(d => ({ ...d, id: d.id || generateUniqueId() }));
    const newDevices = [...devicesWithIds, ...devices];
    persistDeviceChange(newDevices, devicesWithIds, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleDeleteDevice = (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    if (!deviceToDelete) return;
    const newDevices = devices.filter(d => d.id !== id);
    persistDeviceChange(newDevices, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = (importedDevices: MedicalDevice[]) => {
    persistDeviceChange(importedDevices, importedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleApplyGlobalPlan = (updatedDevices: MedicalDevice[]) => {
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleSaveContract = (contract: Contract, selectedDeviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (selectedDeviceIds.includes(device.id)) {
        const existing = device.contracts.find(c => c.contractNumber === contract.contractNumber);
        if (!existing) {
          return { ...device, contracts: [contract, ...device.contracts] };
        }
      }
      return device;
    });
    persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('CONTRACTS');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <NavItem icon={<ShieldCheck className="w-5 h-5" />} label="Contract Registry" targetView="CONTRACTS" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button onClick={() => { setIsScannerOpen(true); setSidebarOpen(false); }} className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"><QrCode className="w-5 h-5" /> Scan QR Code</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSyncing ? (
                <div className="flex items-center gap-2 text-[10px] text-blue-400 bg-blue-900/30 px-3 py-2 rounded-md border border-blue-900 animate-pulse"><RefreshCw className="w-3 h-3 animate-spin" /> <span>Syncing Fleet...</span></div>
              ) : isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-[10px] text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900"><Cloud className="w-3 h-3" /> <span>Cloud Verified</span></div>
              ) : (
                <div className="flex items-center gap-2 text-[10px] text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900"><Database className="w-3 h-3" /> <span>Offline Cache</span></div>
              )}
            </div>
            <div className="flex items-center gap-3 px-2">
              <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center font-bold text-xs shadow-lg">JD</div>
              <div><p className="text-sm font-bold text-white">Jane Doe</p><p className="text-[10px] text-slate-500 uppercase font-black">Clinical Admin</p></div>
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/95 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-4 p-8 bg-white rounded-3xl shadow-2xl border border-slate-100">
              <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
              <div className="text-center">
                <p className="text-lg font-black text-slate-900 uppercase tracking-tight">Accessing Fleet Records</p>
                <p className="text-xs text-slate-400 font-bold uppercase mt-1">Indexing clinical assets...</p>
              </div>
            </div>
          </div>
        )}
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 shrink-0 z-50 shadow-sm">
          <div className="flex items-center gap-3 min-w-[200px]">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight hidden sm:block">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Inventory'}
               {view === 'PLANNER' && 'Planner'}
               {view === 'CONTRACTS' && 'Contracts'}
               {view === 'ADD_DEVICE' && 'Register'}
               {view === 'DEVICE_DETAIL' && 'Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>

          {view === 'INVENTORY' && (
            <div className="flex-1 max-w-xl mx-4">
              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 pointer-events-none group-focus-within:text-blue-600 transition-colors" />
                <input 
                  type="text"
                  autoFocus
                  placeholder="Search assets by name, model or serial..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-blue-500/20 focus:bg-white focus:ring-4 focus:ring-blue-500/5 focus:outline-none text-sm font-bold transition-all shadow-inner"
                  value={inventorySearch}
                  onChange={(e) => setInventorySearch(e.target.value)}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-4 min-w-[150px] justify-end">
             {isSupabaseConfigured && (
               <button 
                onClick={() => loadAndSync(true)}
                title="Force Sync with Cloud"
                className={`p-2.5 rounded-xl border border-slate-100 hover:bg-blue-50 transition-all ${isSyncing ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}
               >
                 <RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
               </button>
             )}
             {view === 'INVENTORY' && (
               <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-lg active:scale-95 whitespace-nowrap">
                 + New Asset
               </button>
             )}
          </div>
