];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [inventorySearch, setInventorySearch] = useState('');

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      // 1. Initial Local Load (Immediate UI feedback)
      const localData = await getAllDevicesFromDB();

      // Only use MOCK_DEVICES if there's absolutely no data and no cloud config
      if (localData.length > 0) {
        setDevices(localData);
      } else if (!isSupabaseConfigured) {
        setDevices(MOCK_DEVICES);
      }

      // 2. Cloud Sync (Smart Merge)
      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase
          .from('devices')
          .select('*')
          .order('id', { ascending: true });

        if (!error && cloudData && cloudData.length > 0) {
          const cloudDevices = cloudData as MedicalDevice[];
          // Only overwrite local if cloud actually has items
          await saveDevicesToDB(cloudDevices);
          setDevices(cloudDevices);
        } else if (error) {
          console.error("Supabase fetch error:", error);
        }
      }
    } catch (error) {
      console.error("Critical initialization error:", error);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      // ALWAYS SAVE LOCALLY FIRST - This prevents data loss on refresh
      await saveDevicesToDB(newDevices);
      setDevices(newDevices);

      if (isSupabaseConfigured && supabase && changedDevice && action) {
        setIsSyncing(true);
        let error;

        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          ({ error } = await supabase.from('devices').delete().eq('id', (changedDevice as MedicalDevice).id));
        } else {
          // INSERT, UPDATE, BULK_INSERT all use upsert for maximum reliability
          ({ error } = await supabase.from('devices').upsert(changedDevice));
        }

        if (error) throw error;
        setIsSyncing(false);
      }
    } catch (e: any) {
      console.error("Persistence Error:", e);
      // We don't alert for every sync error to avoid annoying the user, 
      // as the data is already safe in IndexedDB (local storage).
      setIsSyncing(false);
    }
