import { MedicalDevice } from '../types';

const DB_NAME = 'MediTrackDB';
const STORE_NAME = 'devices';
const DB_VERSION = 2; 

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event: any) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };

    request.onsuccess = (event: any) => resolve(event.target.result);
    request.onerror = (event: any) => reject(event.target.error);
  });
};

/**
 * Persists the entire device fleet to IndexedDB using an atomic transaction.
 * Optimized for both individual registration and bulk imports.
 */
export const saveDevicesToDB = async (devices: MedicalDevice[]): Promise<void> => {
  const db = await initDB();

  return new Promise((resolve, reject) => {
    // Start a readwrite transaction
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    // Step 1: Clear existing cache to maintain a clean manifest
    const clearRequest = store.clear();

    clearRequest.onsuccess = () => {
      try {
        // Step 2: Batch write current fleet
        for (const device of devices) {
          store.put(device);
        }
      } catch (e) {
        transaction.abort();
        reject(new Error("Database write failure: " + e));
      }
    };

    transaction.oncomplete = () => {
      console.log(`[IndexedDB] Asset manifest successfully synced (${devices.length} records)`);
      resolve();
    };

    transaction.onerror = (event: any) => {
      console.error("[IndexedDB] Critical Error:", event.target.error);
      reject(event.target.error);
    };

    transaction.onabort = () => {
      reject(new Error("Storage operation aborted - disk space or quota issue."));
    };
  });
};

export const getAllDevicesFromDB = async (): Promise<MedicalDevice[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result || []);
    request.onerror = (event: any) => reject(event.target.error);
  });
};

export const getStorageStats = async () => {
  const db = await initDB();
  return new Promise<{ count: number }>((resolve) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const countRequest = store.count();
    countRequest.onsuccess = () => resolve({ count: countRequest.result });
  });
};

export const migrateFromLocalStorage = async (): Promise<MedicalDevice[] | null> => {
  const legacyData = localStorage.getItem('meditrack_devices');
  if (legacyData) {
    try {
      const devices = JSON.parse(legacyData);
      if (Array.isArray(devices) && devices.length > 0) {
        await saveDevicesToDB(devices);
        localStorage.setItem('meditrack_migrated', 'true');
        return devices;
      }
    } catch (e) {
      console.error("Migration failed", e);
    }
  }
  return null;
};

