import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  devices: MedicalDevice[];
  onSave: (device: MedicalDevice) => Promise<void>;
  onBulkSave: (devices: MedicalDevice[]) => Promise<void>;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 500 * 1024; 
const AI_BATCH_SIZE = 50; 

interface ProgressState {
  current: number;
  total: number;
  stage: 'READING' | 'MAPPING' | 'PROCESSING' | 'FINALIZING';
  message: string;
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ devices, onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [progress, setProgress] = useState<ProgressState | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    customDepartment: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    notes: '',
    image: ''
  });

  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.7;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET * 1.3 && quality > 0.15) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed.");
      } finally {
        setIsCompressing(false);
      }
    }
  };

  /**
   * Unified Pipeline: Manual records now enter the "Staging" area
   * to ensure they use the same hardened bulk-deployment logic as spreadsheets.
   */
  const handleSingleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;
    const newDevice: MedicalDevice = {
      id: `DEV-MAN-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      ...formData,
      department: finalDept,
      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };
    // Send to preview instead of direct save
    setPreviewDevices([newDevice]);
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;
    for (let i = 0; i < batchData.quantity; i++) {
      batch.push({
        id: `DEV-BATCH-${Date.now()}-${i}`,
        ...formData,
        department: finalDept,
        serialNumber: `${batchData.serialPrefix}${batchData.startNum + i}`,
        status: formData.status as DeviceStatus,
        maintenanceHistory: [],
        contracts: [],
        files: []
      });
    }
    setPreviewDevices(batch);
  };

  const handleDeployAssets = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      // Calls handleBulkAddDevices in App.tsx which awaits Supabase confirmation
      await onBulkSave(previewDevices);
    } catch (err) {
      alert("Registration failed. Please verify your Supabase connectivity.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const processDataChunks = async (allRows: any[]) => {
    setIsProcessing(true);
    setPreviewDevices([]);
    const totalRows = allRows.length;
    const allParsed: MedicalDevice[] = [];
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    setProgress({
      current: 0,
      total: totalRows,
      stage: 'PROCESSING',
      message: `Analyzing manifest with ${totalRows} entries...`
    });

    for (let i = 0; i < totalRows; i += AI_BATCH_SIZE) {
      const chunk = allRows.slice(i, i + AI_BATCH_SIZE);
      setProgress(prev => ({
        ...prev!,
        current: i,
        message: `Synthesizing batch ${Math.floor(i / AI_BATCH_SIZE) + 1}...`
      }));

      try {
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview",
          contents: `Analyze and map this clinical data to a structured device schema: ${JSON.stringify(chunk)}`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  manufacturer: { type: Type.STRING },
                  model: { type: Type.STRING },
                  serialNumber: { type: Type.STRING },
                  department: { type: Type.STRING },
                  purchaseDate: { type: Type.STRING },
                  status: { type: Type.STRING }
                },
                required: ["name", "serialNumber"]
              }
            }
          }
        });

        const parsed: any[] = JSON.parse(response.text || "[]");
        const transformed = parsed.map(item => ({
          ...item,
          id: `DEV-AUTO-${Math.floor(Math.random() * 1000000)}`,
          maintenanceHistory: [],
          contracts: [],
          files: [],
          status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
        }));
        allParsed.push(...transformed);
      } catch (error) {
        console.error("Batch processing error:", error);
      }
    }

    setProgress({
      current: totalRows,
      total: totalRows,
      stage: 'FINALIZING',
      message: 'Compiling asset manifest...'
    });

    setPreviewDevices(allParsed);
    setIsProcessing(false);
    setTimeout(() => setProgress(null), 1000);
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setProgress({ current: 0, total: 100, stage: 'READING', message: 'Decoding spreadsheet...' });

    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        await processDataChunks(data);
      } catch (err) { 
        alert("Spreadsheet ingestion failed.");
        setIsProcessing(false);
        setProgress(null);
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleBulkTextProcess = () => {
    if (!bulkText.trim()) return;
    const lines = bulkText.split('\n').filter(l => l.trim());
    processDataChunks(lines);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20 relative">

      {(isProcessing || isSubmitting) && (
        <div className="absolute inset-0 bg-slate-900/95 z-[200] flex flex-col items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-md space-y-8">
            <div className="flex flex-col items-center text-center">
              <div className="p-5 bg-blue-600 rounded-3xl shadow-2xl shadow-blue-500/20 mb-6 animate-pulse">
                {isSubmitting ? <Save className="w-10 h-10 text-white" /> : <Activity className="w-10 h-10 text-white" />}
              </div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tight">{isSubmitting ? 'Pushing to Cloud' : 'Clinical Sync'}</h3>
              <p className="text-xs text-blue-400 font-bold uppercase mt-2 tracking-widest">{isSubmitting ? 'UPDATING SUPABASE MANIFEST' : (progress?.stage || 'PROCESSING')} IN PROGRESS</p>
            </div>

            {progress && (
              <div className="space-y-4">
                <div className="h-4 w-full bg-white/5 rounded-full overflow-hidden border border-white/10 p-0.5">
                  <div 
                    className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 rounded-full transition-all duration-500 ease-out shadow-[0_0_15px_rgba(37,99,235,0.5)]"
                    style={{ width: `${(progress.current / progress.total) * 100}%` }}
                  ></div>
                </div>
              </div>
            )}

            <div className="bg-black/40 border border-white/5 rounded-2xl p-6 font-mono text-[10px] text-blue-300 space-y-2 text-center">
              <div className="flex items-center justify-center gap-2">
                <Terminal className="w-3 h-3 text-slate-500" />
                <span>{isSubmitting ? 'Verifying transaction with clinical database...' : progress?.message}</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {isCompressing && (
        <div className="absolute inset-0 bg-white/95 z-[150] flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-12 h-12 text-blue-600 animate-spin mb-4" />
          <p className="text-sm font-black text-slate-900 uppercase tracking-widest">Optimizing Visual Record</p>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Register individual or mass fleet items</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Record" icon={<Box className="w-4 h-4" />} />
        <TabButton active={activeTab === 'batch'} onClick={() => setActiveTab('batch')} label="Batch Generator" icon={<Layers className="w-4 h-4" />} />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="AI Smart Extract" icon={<Wand2 className="w-4 h-4" />} />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Fleet Spreadsheet" icon={<FileSpreadsheet className="w-4 h-4" />} />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center bg-blue-50 p-8 rounded-[2.5rem] border border-blue-100">
               <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-blue-200">
                    {previewDevices.length}
                  </div>
                  <div>
                    <h3 className="font-black text-blue-900 uppercase tracking-tight text-lg">Verify Deployment</h3>
                    <p className="text-xs text-blue-400 font-bold uppercase tracking-widest">Confirm records before final database synchronization.</p>
                  </div>
               </div>
               <button onClick={() => setPreviewDevices([])} className="px-6 py-3 bg-white text-blue-600 border border-blue-100 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-100 transition">Cancel</button>
             </div>

             <div className="max-h-[400px] overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50 shadow-inner bg-slate-50/50 p-4">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {previewDevices.map((d, i) => (
                   <div key={i} className="p-5 bg-white border border-slate-100 rounded-2xl flex items-center justify-between hover:border-blue-300 transition-all shadow-sm">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center"><Box className="w-5 h-5 text-slate-300" /></div>
                       <div>
                         <p className="font-bold text-slate-900 text-xs truncate max-w-[150px]">{d.name}</p>
                         <p className="text-[9px] font-mono text-slate-400 uppercase">SN: {d.serialNumber}</p>
                       </div>
                     </div>
                     <div className="text-[9px] font-black text-slate-400 uppercase tracking-tighter bg-slate-50 px-2.5 py-1 rounded-md">{d.department}</div>
                   </div>
                 ))}
               </div>
             </div>
             <button onClick={handleDeployAssets} className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-700 transition active:scale-95 text-sm flex items-center justify-center gap-3">
               Register Asset and Sync with Supabase <ArrowRight className="w-5 h-5" />
             </button>
          </div>
        ) : (
          <>
            {(activeTab === 'single' || activeTab === 'batch') && (
              <form onSubmit={activeTab === 'single' ? handleSingleSubmit : handleGenerateBatch} className="space-y-10">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Master Reference Visual</label>
                     <div 
                      onClick={() => imageInputRef.current?.click()}
                      className="aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all overflow-hidden group relative"
                     >
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-contain" />
                       ) : (
                         <>
                           <Camera className="w-12 h-12 text-slate-300 group-hover:scale-110 transition-transform mb-2" />
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Attach Visual ID</p>
                         </>
                       )}
                       <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                     </div>
                  </div>

                  <div className="lg:col-span-8 space-y-8">
                    {activeTab === 'batch' && (
                       <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                         <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none"><Hash className="w-32 h-32 text-blue-400" /></div>
                         <h3 className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest mb-6 text-blue-400">
                           <Layers className="w-4 h-4" /> Batch Generator Configuration
                         </h3>
                         <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 relative z-10">
                            <div>
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Quantity</label>
                               <input name="quantity" type="number" min="1" max="500" value={batchData.quantity} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" />
                            </div>
                            <div>
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Serial Prefix</label>
                               <input name="serialPrefix" type="text" value={batchData.serialPrefix} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" />
                            </div>
                            <div>
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Start #</label>
                               <input name="startNum" type="number" value={batchData.startNum} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" />
                            </div>
                         </div>
                       </div>
                    )}

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <FormField label="Asset Name" name="name" value={formData.name} onChange={handleChange} placeholder="e.g. Vital Signs Monitor" required />
                      <FormField label="Manufacturer" name="manufacturer" value={formData.manufacturer} onChange={handleChange} placeholder="e.g. Philips" required />
                      <FormField label="Model" name="model" value={formData.model} onChange={handleChange} placeholder="IntelliVue Series" required />

                      {activeTab === 'single' && (
                        <FormField label="Unique Serial Number" name="serialNumber" value={formData.serialNumber} onChange={handleChange} placeholder="SN-882910" required />
                      )}

                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Department Registry</label>
                        <div className="relative">
                          <select 
                            name="department" 
                            value={formData.department} 
                            onChange={handleChange} 
                            className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none appearance-none cursor-pointer"
                          >
                            <optgroup label="Hospitals Units">
                              {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                            </optgroup>
                            <optgroup label="Custom Registry">
                              {uniqueDeptsInData.filter(d => !HOSPITAL_DEPARTMENTS.includes(d as any)).map(dept => (
                                <option key={dept} value={dept}>{dept}</option>
                              ))}
                            </optgroup>
                            <option value="NEW_DEPT">+ ADD NEW DEPARTMENT...</option>
                          </select>
                          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                        </div>
                      </div>

                      {formData.department === 'NEW_DEPT' && (
                        <div className="animate-fade-in bg-blue-50/50 p-4 rounded-2xl border border-blue-100 col-span-1 sm:col-span-2">
                          <div className="flex items-center gap-2 mb-2">
                            <PlusCircle className="w-3 h-3 text-blue-600" />
                            <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Specify Clinical Unit</span>
                          </div>
                          <input 
                            name="customDepartment" 
                            type="text"
                            value={formData.customDepartment} 
                            onChange={handleChange} 
                            placeholder="Enter department name..."
                            className="w-full bg-white border border-blue-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
                            required
                          />
                        </div>
                      )}

                      <FormField label="Acquisition Date" name="purchaseDate" type="date" value={formData.purchaseDate} onChange={handleChange} required />
                    </div>
                  </div>
                </div>

                <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
                  <button type="button" onClick={onCancel} className="px-8 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Discard</button>
                  <button type="submit" className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center gap-2 active:scale-95">
                    {activeTab === 'single' ? <><Layers className="w-4 h-4" /> Prepare Record</> : <><Layers className="w-4 h-4" /> Generate Preview</>}
                  </button>
                </div>
              </form>
            )}

            {activeTab === 'bulk' && (
              <div className="space-y-6">
                <div className="bg-indigo-50 p-8 rounded-[2.5rem] border border-indigo-100 flex gap-6 items-center">
                  <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg"><Wand2 className="w-8 h-8" /></div>
                  <div>
                    <h3 className="text-lg font-black text-indigo-900 uppercase tracking-tight">AI Smart Extraction</h3>
                    <p className="text-sm text-indigo-600/70 font-medium">Paste asset lists for automated database mapping.</p>
                  </div>
                </div>
                <textarea 
                  className="w-full h-80 p-8 bg-slate-50 border border-slate-200 rounded-[2.5rem] focus:ring-8 focus:ring-indigo-500/5 outline-none font-mono text-xs leading-relaxed transition-all shadow-inner" 
                  placeholder="Paste raw data here..." 
                  value={bulkText} 
                  onChange={(e) => setBulkText(e.target.value)} 
                />
                <button onClick={handleBulkTextProcess} disabled={isProcessing || !bulkText} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-indigo-700 transition disabled:opacity-50 text-sm">
                  Analyze & Staging Record
                </button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-24 border-4 border-dashed border-slate-100 rounded-[3rem] text-center bg-slate-50/50 group hover:border-blue-200 transition-all">
                 <div className="p-10 bg-white rounded-full shadow-2xl mb-8 group-hover:scale-110 transition-transform">
                   <FileSpreadsheet className="w-16 h-16 text-blue-500" />
                 </div>
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-2">Spreadsheet Ingestion</h3>
                 <p className="text-xs text-slate-400 max-w-sm mb-12 font-bold uppercase tracking-widest leading-relaxed">Mass import via master XLSX or CSV file.</p>
                 <input type="file" ref={excelInputRef} accept=".xlsx,.xls,.csv" onChange={handleExcelUpload} className="hidden" />
                 <button onClick={() => excelInputRef.current?.click()} className="px-14 py-6 bg-slate-900 text-white rounded-3xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl hover:bg-black transition flex items-center gap-4">
                   <Upload className="w-5 h-5" /> Select Local File
                 </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, label, icon }: { active: boolean, onClick: () => void, label: string, icon: React.ReactNode }) => (
  <button onClick={onClick} className={`px-10 py-6 text-[10px] font-black uppercase tracking-[0.2em] transition-all border-b-4 flex items-center gap-3 whitespace-nowrap ${active ? 'border-blue-600 text-blue-600 bg-blue-50/30' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
    {icon}
    {label}
  </button>
);

const FormField = ({ label, name, value, onChange, placeholder, type = "text", required = false }: any) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input required={required} name={name} type={type} value={value} onChange={onChange} placeholder={placeholder} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" />
  </div>
);

export default AddDeviceForm;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight, WifiOff, RefreshCw, ShieldCheck, Database, Loader2, Search, Zap } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import { MedicalDevice, DeviceStatus, ViewState, MaintenanceType, Contract } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [inventorySearch, setInventorySearch] = useState('');

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      const localData = await getAllDevicesFromDB();
      if (localData.length > 0) {
        setDevices(localData);
      }

      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase
          .from('devices')
          .select('*')
          .order('id', { ascending: true });

        if (!error && cloudData) {
          const cloudDevices = cloudData as MedicalDevice[];
          const cloudIds = new Set(cloudDevices.map(c => c.id));
          const localPending = localData.filter(l => !cloudIds.has(l.id));
          const finalFleet = [...localPending, ...cloudDevices];

          if (finalFleet.length > 0) {
            await saveDevicesToDB(finalFleet);
            setDevices(finalFleet);
          }
        } else if (error) {
          console.warn("Cloud connection limited:", error.message);
        }
      } else if (localData.length === 0) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
      }
    } catch (error) {
      console.error("Clinical fleet index failure:", error);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  /**
   * Hardened Persistence Flow:
   * 1. Updates state and Local Database (IndexedDB) immediately.
   * 2. Awaits Supabase completion if cloud is enabled.
   */
  const persistDeviceChange = async (newDevices: MedicalDevice[], changedDevice?: MedicalDevice | MedicalDevice[], action?: 'INSERT' | 'UPDATE' | 'DELETE' | 'BULK_INSERT') => {
    try {
      // Step 1: Immutable local save
      await saveDevicesToDB(newDevices);
      setDevices([...newDevices]); 

      // Step 2: Supabase synchronization
      if (isSupabaseConfigured && supabase && changedDevice && action) {
        setIsSyncing(true);
        let error;

        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          ({ error } = await supabase.from('devices').delete().eq('id', (changedDevice as MedicalDevice).id));
        } else {
          const payload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
          // Use onConflict: 'id' for robust cross-computer syncing
          ({ error } = await supabase.from('devices').upsert(payload, { onConflict: 'id' }));
        }

        if (error) {
          console.error("Supabase sync deferred. Local record is safe.", error.message);
        } else {
          console.log(`[Supabase] Sync successful for action: ${action}`);
        }
        setIsSyncing(false);
      }
    } catch (e: any) {
      console.error("Critical database operation failed:", e);
      setIsSyncing(false);
      throw e; 
    }
  };

  const generateUniqueId = () => `DEV-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`;

  const handleSelectDevice = (device: MedicalDevice) => {
    setSelectedDevice(device);
    setView('DEVICE_DETAIL');
  };

  const handleUpdateDevice = async (updated: MedicalDevice) => {
    const newDevices = devices.map(d => d.id === updated.id ? updated : d);
    await persistDeviceChange(newDevices, updated, 'UPDATE');
    if (selectedDevice?.id === updated.id) {
      setSelectedDevice(updated);
    }
  };

  const handleAddDevice = async (newDevice: MedicalDevice) => {
    try {
      const deviceWithId: MedicalDevice = { 
        ...newDevice, 
        id: newDevice.id || generateUniqueId(),
        maintenanceHistory: newDevice.maintenanceHistory || [],
        contracts: newDevice.contracts || [],
        files: newDevice.files || []
      };

      const updatedFleet = [deviceWithId, ...devices];
      await persistDeviceChange(updatedFleet, deviceWithId, 'INSERT');
      setView('INVENTORY');
    } catch (error) {
      alert("Registration sync failed.");
    }
  };

  /**
   * Unified deployment point for all intake types (Manual, Excel, AI).
   * Ensures the view only changes AFTER Supabase confirms receipt.
   */
  const handleBulkAddDevices = async (newDevicesList: MedicalDevice[]) => {
    try {
      const devicesWithIds = newDevicesList.map(d => ({ 
        ...d, 
        id: d.id || generateUniqueId(),
        maintenanceHistory: d.maintenanceHistory || [],
        contracts: d.contracts || [],
        files: d.files || []
      }));

      const updatedFleet = [...devicesWithIds, ...devices];

      // The await here is crucial - it blocks navigation until Supabase is done
      await persistDeviceChange(updatedFleet, devicesWithIds, 'BULK_INSERT');

      // Navigate only after database confirmation
      setView('INVENTORY');
    } catch (error) {
      console.error("Bulk sync operation failed:", error);
      throw error;
    }
  };

  const handleDeleteDevice = async (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    if (!deviceToDelete) return;
    const updatedFleet = devices.filter(d => d.id !== id);
    await persistDeviceChange(updatedFleet, deviceToDelete, 'DELETE');
    if (selectedDevice?.id === id) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }
  };

  const handleImportData = async (importedDevices: MedicalDevice[]) => {
    await persistDeviceChange(importedDevices, importedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleApplyGlobalPlan = async (updatedDevices: MedicalDevice[]) => {
    await persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('INVENTORY');
  };

  const handleSaveContract = async (contract: Contract, selectedDeviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (selectedDeviceIds.includes(device.id)) {
        const existing = device.contracts.find(c => c.contractNumber === contract.contractNumber);
        if (!existing) {
          return { ...device, contracts: [contract, ...device.contracts] };
        }
      }
      return device;
    });
    await persistDeviceChange(updatedDevices, updatedDevices, 'BULK_INSERT');
    setView('CONTRACTS');
  };

  const NavItem = ({ icon, label, targetView }: { icon: React.ReactNode, label: string, targetView: ViewState }) => (
    <button onClick={() => { setView(targetView); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === targetView && view !== 'DEVICE_DETAIL' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>{icon}{label}</button>
  );

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" targetView="DASHBOARD" />
            <NavItem icon={<List className="w-5 h-5" />} label="Inventory" targetView="INVENTORY" />
            <NavItem icon={<CalendarRange className="w-5 h-5" />} label="Maintenance Planner" targetView="PLANNER" />
            <NavItem icon={<ShieldCheck className="w-5 h-5" />} label="Contract Registry" targetView="CONTRACTS" />
            <div className="pt-8 pb-2 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Tools</div>
            <button className="flex items-center gap-3 w-full px-4 py-3 text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg"><QrCode className="w-5 h-5" /> Scan QR Code</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSyncing ? (
                <div className="flex items-center gap-2 text-[10px] text-blue-400 bg-blue-900/30 px-3 py-2 rounded-md border border-blue-900 animate-pulse"><RefreshCw className="w-3 h-3 animate-spin" /> <span>Syncing Fleet...</span></div>
              ) : isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-[10px] text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900"><Cloud className="w-3 h-3" /> <span>Cloud Verified</span></div>
              ) : (
                <div className="flex items-center gap-2 text-[10px] text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900"><Database className="w-3 h-3" /> <span>Local Mode</span></div>
              )}
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/95 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-4 p-8 bg-white rounded-3xl shadow-2xl border border-slate-100">
              <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
              <div className="text-center">
                <p className="text-lg font-black text-slate-900 uppercase tracking-tight">Accessing Fleet Records</p>
                <p className="text-xs text-slate-400 font-bold uppercase mt-1">Indexing clinical assets...</p>
              </div>
            </div>
          </div>
        )}
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-4 lg:px-8 shrink-0 z-50 shadow-sm">
          <div className="flex items-center gap-3 min-w-[200px]">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight hidden sm:block">
               {view === 'DASHBOARD' && 'Overview'}
               {view === 'INVENTORY' && 'Inventory'}
               {view === 'PLANNER' && 'Planner'}
               {view === 'CONTRACTS' && 'Contracts'}
               {view === 'ADD_DEVICE' && 'Register'}
               {view === 'DEVICE_DETAIL' && 'Details'}
               {view === 'SETTINGS' && 'Settings'}
             </h2>
          </div>

          {view === 'INVENTORY' && (
            <div className="flex-1 max-w-xl mx-4">
              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 pointer-events-none group-focus-within:text-blue-600 transition-colors" />
                <input 
                  type="text"
                  placeholder="Search assets by name, model or serial..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-blue-500/20 focus:bg-white focus:ring-4 focus:ring-blue-500/5 focus:outline-none text-sm font-bold transition-all shadow-inner"
                  value={inventorySearch}
                  onChange={(e) => setInventorySearch(e.target.value)}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-4 min-w-[150px] justify-end">
             {isSupabaseConfigured && (
               <button 
                onClick={() => loadAndSync(true)}
                title="Force Sync with Cloud"
                className={`p-2.5 rounded-xl border border-slate-100 hover:bg-blue-50 transition-all ${isSyncing ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}
               >
                 <RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
               </button>
             )}
             {view === 'INVENTORY' && (
               <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-lg active:scale-95 whitespace-nowrap">
                 + New Asset
               </button>
             )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto min-h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={handleSelectDevice} onUpdateDevice={handleUpdateDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} searchQuery={inventorySearch} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleApplyGlobalPlan} />}
            {view === 'CONTRACTS' && <ContractManager devices={devices} onSaveContract={handleSaveContract} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={handleImportData} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera, Loader2, Layers, Hash, ChevronDown, Activity, Terminal, PlusCircle, ArrowRight } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  devices: MedicalDevice[];
  onSave: (device: MedicalDevice) => Promise<void>;
  onBulkSave: (devices: MedicalDevice[]) => Promise<void>;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 400 * 1024; // Aggressive compression for cloud compatibility
const AI_BATCH_SIZE = 50; 

interface ProgressState {
  current: number;
  total: number;
  stage: 'READING' | 'MAPPING' | 'PROCESSING' | 'FINALIZING';
  message: string;
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ devices, onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [progress, setProgress] = useState<ProgressState | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    customDepartment: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    notes: '',
    image: ''
  });

  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; // Slightly smaller to ensure Supabase row size compliance
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.6;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          // Loop to ensure we stay under the target size for cloud stability
          while (dataUrl.length > COMPRESSION_TARGET && quality > 0.1) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed.");
      } finally {
        setIsCompressing(false);
      }
    }
  };

  /**
   * FIX: Standardized Manual Registration
   * Now uses a shorter ID format identical to the spreadsheet import 
   * to avoid database character limit failures.
   */
  const handleSingleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;

    // Shorter ID format (12-15 chars) ensures compatibility with SQL VARCHAR columns
    const shortId = `DEV-${Math.floor(Math.random() * 1000000).toString().padStart(6, '0')}`;

    const newDevice: MedicalDevice = {
      id: shortId,
      ...formData,
      department: finalDept,
      status: formData.status as DeviceStatus,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };

    // Push to the same "Staging" workflow as the spreadsheet
    setPreviewDevices([newDevice]);
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;
    for (let i = 0; i < batchData.quantity; i++) {
      batch.push({
        id: `DEV-B-${Math.floor(Math.random() * 100000)}`,
        ...formData,
        department: finalDept,
        serialNumber: `${batchData.serialPrefix}${batchData.startNum + i}`,
        status: formData.status as DeviceStatus,
        maintenanceHistory: [],
        contracts: [],
        files: []
      });
    }
    setPreviewDevices(batch);
  };

  const handleDeployAssets = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      // Calls handleBulkAddDevices in App.tsx which strictly awaits Supabase sync
      await onBulkSave(previewDevices);
    } catch (err) {
      alert("Deployment failed. Please check your Supabase settings or network.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const processDataChunks = async (allRows: any[]) => {
    setIsProcessing(true);
    setPreviewDevices([]);
    const totalRows = allRows.length;
    const allParsed: MedicalDevice[] = [];
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    setProgress({
      current: 0,
      total: totalRows,
      stage: 'PROCESSING',
      message: `Analyzing manifest with ${totalRows} entries...`
    });

    for (let i = 0; i < totalRows; i += AI_BATCH_SIZE) {
      const chunk = allRows.slice(i, i + AI_BATCH_SIZE);
      setProgress(prev => ({
        ...prev!,
        current: i,
        message: `Synthesizing batch ${Math.floor(i / AI_BATCH_SIZE) + 1}...`
      }));

      try {
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview",
          contents: `Analyze and map this clinical data to a structured device schema: ${JSON.stringify(chunk)}`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  manufacturer: { type: Type.STRING },
                  model: { type: Type.STRING },
                  serialNumber: { type: Type.STRING },
                  department: { type: Type.STRING },
                  purchaseDate: { type: Type.STRING },
                  status: { type: Type.STRING }
                },
                required: ["name", "serialNumber"]
              }
            }
          }
        });

        const parsed: any[] = JSON.parse(response.text || "[]");
        const transformed = parsed.map(item => ({
          ...item,
          id: `DEV-A-${Math.floor(Math.random() * 100000)}`,
          maintenanceHistory: [],
          contracts: [],
          files: [],
          status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
        }));
        allParsed.push(...transformed);
      } catch (error) {
        console.error("Batch processing error:", error);
      }
    }

    setProgress({
      current: totalRows,
      total: totalRows,
      stage: 'FINALIZING',
      message: 'Compiling asset manifest...'
    });

    setPreviewDevices(allParsed);
    setIsProcessing(false);
    setTimeout(() => setProgress(null), 1000);
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setProgress({ current: 0, total: 100, stage: 'READING', message: 'Decoding spreadsheet...' });

    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        await processDataChunks(data);
      } catch (err) { 
        alert("Spreadsheet ingestion failed.");
        setIsProcessing(false);
        setProgress(null);
      }
    };
    reader.readAsBinaryString(file);
  };

