        maintenanceHistory: d.maintenanceHistory || [],
        contracts: d.contracts || [],
        files: d.files || []
      }));

      const updatedFleet = [...devicesWithIds, ...devices];

      // We explicitly await the cloud persistence here.
      // This prevents the user from navigating back to the list until the data is actually in Supabase.
      await persistDeviceChange(updatedFleet, devicesWithIds, 'BULK_INSERT');

      // Navigate only after the cloud confirms success
      setView('INVENTORY');
    } catch (error) {
      console.error("Bulk sync operation failed:", error);
      alert("Critical: Asset deployment failed. Please check network connectivity.");
      throw error;
    }
  };

