            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
          <div className="p-4 border-t border-slate-800">
            <div className="mb-4 px-2">
              {isSyncing ? (
                <div className="flex items-center gap-2 text-[10px] text-blue-400 bg-blue-900/30 px-3 py-2 rounded-md border border-blue-900 animate-pulse"><RefreshCw className="w-3 h-3 animate-spin" /> <span>Cloud Handshake...</span></div>
              ) : isSupabaseConfigured ? (
                <div className="flex items-center gap-2 text-[10px] text-green-400 bg-green-900/30 px-3 py-2 rounded-md border border-green-900"><Cloud className="w-3 h-3" /> <span>Cloud Synchronized</span></div>
              ) : (
                <div className="flex items-center gap-2 text-[10px] text-amber-400 bg-amber-900/30 px-3 py-2 rounded-md border border-amber-900"><Database className="w-3 h-3" /> <span>Offline Mode</span></div>
              )}
