                  className="w-full h-80 p-8 bg-slate-50 border border-slate-200 rounded-[2.5rem] focus:ring-8 focus:ring-indigo-500/5 outline-none font-mono text-xs leading-relaxed transition-all shadow-inner" 
                  placeholder="Paste raw data here..." 
                  value={bulkText} 
                  onChange={(e) => setBulkText(e.target.value)} 
                />
                <button onClick={handleBulkTextProcess} disabled={isProcessing || !bulkText} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-indigo-700 transition disabled:opacity-50 text-sm">
                  Analyze & Staging Record
                </button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-24 border-4 border-dashed border-slate-100 rounded-[3rem] text-center bg-slate-50/50 group hover:border-blue-200 transition-all">
                 <div className="p-10 bg-white rounded-full shadow-2xl mb-8 group-hover:scale-110 transition-transform">
                   <FileSpreadsheet className="w-16 h-16 text-blue-500" />
