                       {manuals.map(m => (
                         <div key={m.id} className="flex items-center justify-between group p-2 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100">
                           <div className="flex items-center gap-2 truncate flex-1 text-xs font-bold text-blue-600 cursor-pointer" onClick={(e) => handleOpenFile(e, m)}><Download className="w-3.5 h-3.5 opacity-40 shrink-0" /><span className="truncate">{m.name}</span></div>
                           <button type="button" onClick={(e) => { e.preventDefault(); e.stopPropagation(); onUpdate({ ...device, files: (device.files || []).filter(f => f.id !== m.id) }); }} className="p-1.5 text-slate-300 hover:text-red-500 transition ml-1"><Trash2 className="w-3.5 h-3.5" /></button>
                         </div>
                       ))}
                       <button type="button" onClick={() => triggerFileUpload('manual')} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">+ ADD MANUAL</button>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {/* ... (Other Tabs like maintenance and contracts remain mostly same) ... */}
        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
               <div className="flex-1"><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight flex items-center gap-3"><Sparkles className="w-6 h-6 text-violet-600" /> Engineering Planner</h3><p className="text-sm text-slate-500 mt-1 font-medium">Optimize maintenance lifecyle for this asset.</p></div>
               <div className="flex gap-3"><button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3.5 bg-violet-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 transition disabled:opacity-50 hover:bg-violet-700 shadow-xl">{isAnalyzing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Wand2 className="w-5 h-5" />}{isAnalyzing ? "Calculating..." : "Smart Suggest"}</button><button type="button" onClick={() => setShowMaintenanceModal(true)} className="px-6 py-3.5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 transition hover:bg-black shadow-xl"><Plus className="w-5 h-5" /> Log Event</button></div>
            </div>
            {/* ... (List existing maintenance history) ... */}
            <div className="space-y-4">
              {device.maintenanceHistory.length > 0 ? device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-blue-200 transition-all">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>{record.completed ? <ShieldCheck className="w-7 h-7" /> : <Clock className="w-7 h-7" />}</div>
                    <div><h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">{record.type}</h4><p className="text-sm text-slate-600 line-clamp-2 mt-1 font-medium">{record.description}</p></div>
                  </div>
                </div>
              )) : <div className="py-20 flex flex-col items-center justify-center text-center opacity-40"><Calendar className="w-16 h-16 text-slate-200 mb-4" /><p className="text-sm font-black uppercase tracking-widest text-slate-400">No logs on record</p></div>}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
  if (status === DeviceStatus.ACTIVE) color = "bg-green-100 text-green-700 border-green-200";
  if (status === DeviceStatus.BROKEN) color = "bg-red-100 text-red-700 border-red-200";
  if (status === DeviceStatus.MAINTENANCE) color = "bg-amber-100 text-amber-700 border-amber-200";
  return <span className={`px-2.5 py-1 border rounded-full text-xs font-semibold shadow-sm uppercase ${color}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button type="button" onClick={onClick} className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>{icon}{label}</button>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between py-3 border-b border-slate-50 last:border-0">
    <span className="text-slate-400 text-[10px] font-black uppercase tracking-wider">{label}</span>
    <span className="text-slate-900 font-bold text-xs">{value}</span>
  </div>
);

const EditField = ({ label, name, value, onChange, type = "text" }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input name={name} type={type} value={value} onChange={onChange} className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" />
  </div>
);

export default DeviceDetail;

import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera, Loader2, Layers, Hash, ChevronDown, Activity, Terminal, PlusCircle, ArrowRight, AlertTriangle, Fingerprint, ShieldAlert, History } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  devices: MedicalDevice[];
  onSave: (device: MedicalDevice) => Promise<void>;
  onBulkSave: (devices: MedicalDevice[]) => Promise<void>;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 400 * 1024; 
const AI_BATCH_SIZE = 50; 

interface ProgressState {
  current: number;
  total: number;
  stage: 'READING' | 'MAPPING' | 'PROCESSING' | 'FINALIZING' | 'DEDUPLICATING';
  message: string;
}

interface DuplicateReport {
  existingIds: string[]; // Serial numbers already in the system
  internalDupes: string[]; // Serial numbers repeated in the file
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ devices, onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [progress, setProgress] = useState<ProgressState | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const [duplicateReport, setDuplicateReport] = useState<DuplicateReport | null>(null);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    customDepartment: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    isCNCAN: false,
    notes: '',
    image: ''
  });

  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setFormData(prev => ({ ...prev, [name]: val }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; 
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.6;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET && quality > 0.1) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed.");
      } finally {
        setIsCompressing(false);
      }
    }
  };

  const analyzeDuplicates = (incoming: MedicalDevice[]) => {
    const existingSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
    const incomingSerials = new Map<string, number>();

    const existingIds: string[] = [];
    const internalDupes: string[] = [];

    incoming.forEach(d => {
      const sn = d.serialNumber.toLowerCase();
      if (existingSerials.has(sn)) {
        existingIds.push(d.serialNumber);
      }
      incomingSerials.set(sn, (incomingSerials.get(sn) || 0) + 1);
    });

    incomingSerials.forEach((count, sn) => {
      if (count > 1) internalDupes.push(sn.toUpperCase());
    });

    if (existingIds.length > 0 || internalDupes.length > 0) {
      setDuplicateReport({ existingIds, internalDupes });
    } else {
      setDuplicateReport(null);
    }
  };

  const handlePurgeDuplicates = () => {
    if (!duplicateReport) return;

    const seenSerials = new Set<string>();
    const existingSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));

    const purged = previewDevices.filter(d => {
      const sn = d.serialNumber.toLowerCase();
      if (existingSerials.has(sn)) return false;
      if (seenSerials.has(sn)) return false;
      seenSerials.add(sn);
      return true;
    });

    setPreviewDevices(purged);
    setDuplicateReport(null);
  };

  const handleSingleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;

    const newDevice: MedicalDevice = {
      id: '', 
      name: formData.name,
      manufacturer: formData.manufacturer,
      model: formData.model,
      serialNumber: formData.serialNumber,
      department: finalDept,
      purchaseDate: formData.purchaseDate,
      status: formData.status as DeviceStatus,
      isCNCAN: formData.isCNCAN,
      notes: formData.notes,
      image: formData.image,
      maintenanceHistory: [],
      contracts: [],
      files: []
    };

    try {
      await onSave(newDevice);
    } catch (err) {
      console.warn("Manual registration attempt failed.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;
    for (let i = 0; i < batchData.quantity; i++) {
      batch.push({
        id: `DEV-B-${Date.now()}-${i}`,
        name: formData.name,
        manufacturer: formData.manufacturer,
        model: formData.model,
        serialNumber: `${batchData.serialPrefix}${batchData.startNum + i}`,
        department: finalDept,
        purchaseDate: formData.purchaseDate,
        status: formData.status as DeviceStatus,
        isCNCAN: formData.isCNCAN,
        notes: formData.notes,
        image: formData.image,
        maintenanceHistory: [],
        contracts: [],
        files: []
      });
    }
    analyzeDuplicates(batch);
    setPreviewDevices(batch);
  };

  const handleDeployAssets = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onBulkSave(previewDevices);
    } catch (err) {} finally {
      setIsSubmitting(false);
    }
  };

  const processDataChunks = async (allRows: any[]) => {
    setIsProcessing(true);
    setPreviewDevices([]);
    const totalRows = allRows.length;
    const allParsed: MedicalDevice[] = [];
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    setProgress({
      current: 0,
      total: totalRows,
      stage: 'PROCESSING',
      message: `Analyzing manifest with ${totalRows} entries...`
    });

    for (let i = 0; i < totalRows; i += AI_BATCH_SIZE) {
      const chunk = allRows.slice(i, i + AI_BATCH_SIZE);
      setProgress(prev => ({ ...prev!, current: i, message: `Synthesizing batch ${Math.floor(i / AI_BATCH_SIZE) + 1}...` }));

      try {
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview",
          contents: `Analyze and map this clinical data to a structured device schema: ${JSON.stringify(chunk)}`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  manufacturer: { type: Type.STRING },
                  model: { type: Type.STRING },
                  serialNumber: { type: Type.STRING },
                  department: { type: Type.STRING },
                  purchaseDate: { type: Type.STRING },
                  status: { type: Type.STRING },
                  isCNCAN: { type: Type.BOOLEAN }
                },
                required: ["name", "serialNumber"]
              }
            }
          }
        });

        const parsed: any[] = JSON.parse(response.text || "[]");
        const transformed = parsed.map(item => ({
          ...item,
          id: `DEV-A-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          isCNCAN: !!item.isCNCAN,
          maintenanceHistory: [],
          contracts: [],
          files: [],
          status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
        }));
        allParsed.push(...transformed);
      } catch (error) { console.error("Batch processing error:", error); }
    }

    analyzeDuplicates(allParsed);
    setPreviewDevices(allParsed);
    setIsProcessing(false);
    setTimeout(() => setProgress(null), 1000);
  };

  // Fix: Implemented handleBulkTextProcess to extract devices from raw text using Gemini AI
  const handleBulkTextProcess = async () => {
    if (!bulkText) return;
    setIsProcessing(true);
    setPreviewDevices([]);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    setProgress({
      current: 0,
      total: 1,
      stage: 'PROCESSING',
      message: 'Analyzing raw data with AI...'
    });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analyze the following text and extract all clinical assets. Return a JSON array of objects with these fields: name, manufacturer, model, serialNumber, department, purchaseDate (YYYY-MM-DD), status (Active, In Maintenance, Broken, Retired), isCNCAN (boolean).

        Text to analyze:
        ${bulkText}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                manufacturer: { type: Type.STRING },
                model: { type: Type.STRING },
                serialNumber: { type: Type.STRING },
                department: { type: Type.STRING },
                purchaseDate: { type: Type.STRING },
                status: { type: Type.STRING },
                isCNCAN: { type: Type.BOOLEAN }
              },
              required: ["name", "serialNumber"]
            }
          }
        }
      });

      const parsed: any[] = JSON.parse(response.text || "[]");
      const transformed = parsed.map(item => ({
        ...item,
        id: `DEV-AI-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
        isCNCAN: !!item.isCNCAN,
        maintenanceHistory: [],
        contracts: [],
        files: [],
        status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
      }));

      analyzeDuplicates(transformed);
      setPreviewDevices(transformed);
    } catch (error) {
      console.error("Smart extract error:", error);
      alert("AI extraction failed. Please check the text format.");
    } finally {
      setIsProcessing(false);
      setProgress(null);
    }
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        await processDataChunks(data);
      } catch (err) { setIsProcessing(false); }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20 relative">
      {/* ... (Existing Overlays for Sync and Duplicates) ... */}

      {(isProcessing || isSubmitting) && (
        <div className="absolute inset-0 bg-slate-900/95 z-[200] flex flex-col items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-md space-y-8">
            <div className="flex flex-col items-center text-center">
              <div className="p-5 bg-blue-600 rounded-3xl shadow-2xl shadow-blue-500/20 mb-6 animate-pulse">
                {isSubmitting ? <Save className="w-10 h-10 text-white" /> : <Activity className="w-10 h-10 text-white" />}
              </div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tight">{isSubmitting ? 'Syncing Global Cloud' : 'Clinical Sync'}</h3>
            </div>
            {progress && (
              <div className="space-y-4">
                <div className="h-4 w-full bg-white/5 rounded-full overflow-hidden border border-white/10 p-0.5">
                  <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 rounded-full transition-all duration-500 ease-out" style={{ width: `${(progress.current / progress.total) * 100}%` }}></div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {duplicateReport && (
        <div className="absolute inset-0 bg-slate-900/95 z-[210] flex flex-col items-center justify-center p-8 animate-fade-in overflow-y-auto">
          <div className="w-full max-w-2xl bg-white rounded-[2.5rem] p-10 shadow-2xl">
            <div className="flex items-center gap-6 mb-8">
              <div className="p-4 bg-amber-100 text-amber-600 rounded-2xl">
                <ShieldAlert className="w-10 h-10" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Redundancy Detected</h3>
              </div>
            </div>
            <div className="flex flex-col sm:flex-row gap-4">
              <button onClick={handlePurgeDuplicates} className="flex-1 py-5 bg-amber-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-3">
                <Trash2 className="w-4 h-4" /> Purge Redundancies
              </button>
              <button onClick={() => setDuplicateReport(null)} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase tracking-widest">
                Keep & Override
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Register individual or mass fleet items</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Record" icon={<Box className="w-4 h-4" />} />
        <TabButton active={activeTab === 'batch'} onClick={() => setActiveTab('batch')} label="Batch Generator" icon={<Layers className="w-4 h-4" />} />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="AI Smart Extract" icon={<Wand2 className="w-4 h-4" />} />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Fleet Spreadsheet" icon={<FileSpreadsheet className="w-4 h-4" />} />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center bg-blue-50 p-8 rounded-[2.5rem] border border-blue-100">
               <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-blue-200">
                    {previewDevices.length}
                  </div>
                  <div>
                    <h3 className="font-black text-blue-900 uppercase tracking-tight text-lg">Verify Global Deployment</h3>
                  </div>
               </div>
               <button onClick={() => { setPreviewDevices([]); setDuplicateReport(null); }} className="px-6 py-3 bg-white text-blue-600 border border-blue-100 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-100 transition">Cancel</button>
             </div>

             <div className="max-h-[400px] overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50 shadow-inner bg-slate-50/50 p-4">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {previewDevices.map((d, i) => (
                   <div key={i} className="p-5 bg-white border border-slate-100 rounded-2xl flex items-center justify-between hover:border-blue-300 transition-all shadow-sm">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center relative">
                         <Box className="w-5 h-5 text-slate-300" />
                         {d.isCNCAN && <div className="absolute -top-1 -right-1 p-0.5 bg-amber-500 rounded-full"><ShieldAlert className="w-2 h-2 text-white" /></div>}
                       </div>
                       <div>
                         <p className="font-bold text-slate-900 text-xs truncate max-w-[150px]">{d.name}</p>
                         <p className="text-[9px] font-mono text-slate-400 uppercase">SN: {d.serialNumber}</p>
                       </div>
                     </div>
                     <div className="text-[9px] font-black text-slate-400 uppercase tracking-tighter bg-slate-50 px-2.5 py-1 rounded-md">{d.department}</div>
                   </div>
                 ))}
