    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ]
  }
];

const CLOUD_TIMEOUT_MS = 12000;

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [inventorySearch, setInventorySearch] = useState('');

  // Mismatch Error State
  const [schemaError, setSchemaError] = useState<{ message: string; sql: string } | null>(null);

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase
          .from('devices')
          .select('*')
          .order('id', { ascending: true });

        if (!error && cloudData) {
          const cloudDevices = cloudData as MedicalDevice[];
          await saveDevicesToDB(cloudDevices);
          setDevices(cloudDevices);
        } else if (error) {
          console.warn("Cloud access limited, falling back to local storage.", error.message);
          const localData = await getAllDevicesFromDB();
          setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
        }
      } else {
        const localData = await getAllDevicesFromDB();
        setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
      }
    } catch (error) {
      console.error("Clinical fleet index failure:", error);
      const localData = await getAllDevicesFromDB();
      setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const persistDeviceChange = async (changedDevice: MedicalDevice | MedicalDevice[], action: 'UPSERT' | 'DELETE', ignoreCNCAN: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isSupabaseConfigured && supabase) {
        const rawPayload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
        const dedupeMap = new Map<string, MedicalDevice>();
        rawPayload.forEach(d => dedupeMap.set(d.id, d));
        const payload = Array.from(dedupeMap.values());

        const transactionPromise = (async () => {
          if (action === 'DELETE' && !Array.isArray(changedDevice)) {
            const { error } = await supabase.from('devices').delete().eq('id', changedDevice.id);
            if (error) throw error;
          } else {
            const sanitizedPayload = payload.map(d => {
              const base: any = {
                id: d.id,
                name: d.name,
                category: d.category,
                manufacturer: d.manufacturer,
                model: d.model,
                serialNumber: d.serialNumber,
                department: d.department,
                purchaseDate: d.purchaseDate,
                status: d.status,
                maintenanceHistory: d.maintenanceHistory || [],
                contracts: d.contracts || [],
                files: d.files || []
              };

              if (!ignoreCNCAN) {
                base.isCNCAN = !!d.isCNCAN;
              }

              return base;
            });

            const { data, error } = await supabase
              .from('devices')
              .upsert(sanitizedPayload, { onConflict: 'id' })
              .select('id');

            if (error) {
              if (error.message.includes('isCNCAN') || error.hint?.includes('isCNCAN')) {
                setSchemaError({
                  message: "Your cloud registry is missing the 'isCNCAN' column. The sync failed because the database doesn't know where to store this new data.",
                  sql: `ALTER TABLE devices ADD COLUMN "isCNCAN" BOOLEAN DEFAULT FALSE;`
                });
                throw new Error("SCHEMA_MISMATCH");
              }
              throw error;
            }
            if (!data || data.length === 0) throw new Error("Registry write timeout.");
          }
          return true;
        })();

        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error("Global registry timeout.")), CLOUD_TIMEOUT_MS)
        );

        await Promise.race([transactionPromise, timeoutPromise]);
      } else {
        const currentLocal = await getAllDevicesFromDB();
        const payload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
        let updatedLocal: MedicalDevice[];
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          updatedLocal = currentLocal.filter(d => d.id !== changedDevice.id);
        } else {
          const map = new Map(currentLocal.map(d => [d.id, d]));
          payload.forEach(p => map.set(p.id, p));
          updatedLocal = Array.from(map.values());
        }
        await saveDevicesToDB(updatedLocal);
      }
      await loadAndSync(false);
    } catch (e: any) {
      if (e.message !== "SCHEMA_MISMATCH") {
        console.error("Clinical Registry Error:", e.message);
        throw e;
      }
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddDevice = async (newDevice: MedicalDevice) => {
    const deviceWithId: MedicalDevice = { ...newDevice, id: `DEV-REG-${Date.now()}` };
    try { await persistDeviceChange(deviceWithId, 'UPSERT'); setView('INVENTORY'); } catch (err) {}
  };

  const handleUpdateDevice = async (updated: MedicalDevice) => {
    try { 
      await persistDeviceChange(updated, 'UPSERT'); 
      if (selectedDevice?.id === updated.id) setSelectedDevice(updated);
    } catch (err) {}
  };

  const handleBulkAddDevices = async (newDevicesList: MedicalDevice[]) => {
    const devicesWithIds = newDevicesList.map(d => ({ ...d, id: d.id || `DEV-B-${Date.now()}-${Math.random()}` }));
    try { await persistDeviceChange(devicesWithIds, 'UPSERT'); setView('INVENTORY'); } catch (err) {}
  };

  const handleDeleteDevice = async (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    if (deviceToDelete) {
      try { await persistDeviceChange(deviceToDelete, 'DELETE'); if (selectedDevice?.id === id) setView('INVENTORY'); } catch (err) {}
    }
  };

  const handleSaveContract = async (contract: Contract, deviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (deviceIds.includes(device.id)) {
        return {
          ...device,
          contracts: [...(device.contracts || []), contract]
        };
      }
      return device;
    });

    try {
      await persistDeviceChange(updatedDevices, 'UPSERT');
    } catch (err) {
      console.error("Failed to save contract association:", err);
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* SCHEMA ERROR MODAL */}
      {schemaError && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl p-10 relative border-4 border-amber-400">
            <div className="flex items-center gap-6 mb-8">
              <div className="p-4 bg-amber-100 text-amber-600 rounded-3xl">
                <ShieldAlert className="w-12 h-12" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Database Out of Sync</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Schema Mismatch Detected</p>
              </div>
            </div>

            <p className="text-sm text-slate-600 mb-8 leading-relaxed font-medium">
              {schemaError.message}
            </p>

            <div className="bg-slate-900 rounded-2xl p-6 mb-8 relative group">
              <code className="text-xs font-mono text-blue-300 break-all">{schemaError.sql}</code>
              <button 
                onClick={() => { navigator.clipboard.writeText(schemaError.sql); }}
                className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all"
              >
                <Copy className="w-4 h-4" />
              </button>
            </div>

            <div className="flex flex-col gap-3">
              <button 
                onClick={() => { setView('SETTINGS'); setSchemaError(null); }}
                className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-black transition flex items-center justify-center gap-3"
              >
                Go to Database Migration <ArrowRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => setSchemaError(null)}
                className="w-full py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition"
              >
                Close & Stay Offline
              </button>
            </div>
          </div>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <button onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'DASHBOARD' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><LayoutDashboard className="w-5 h-5" /> Dashboard</button>
            <button onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'INVENTORY' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><List className="w-5 h-5" /> Inventory</button>
            <button onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'PLANNER' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><CalendarRange className="w-5 h-5" /> Planner</button>
            <button onClick={() => { setView('CONTRACTS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'CONTRACTS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><ShieldCheck className="w-5 h-5" /> Contracts</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/95 z-50 flex items-center justify-center">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
          </div>
        )}
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-50 shadow-sm">
          <div className="flex items-center gap-3 min-w-[200px]">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight hidden sm:block">
               {view.replace('_', ' ')}
             </h2>
          </div>

          {/* RESTORED SEARCH BAR */}
          {view === 'INVENTORY' && (
            <div className="flex-1 max-w-xl mx-4">
              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 pointer-events-none group-focus-within:text-blue-600 transition-colors" />
                <input 
                  type="text"
                  placeholder="Search assets by name, model or serial..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-blue-500/20 focus:bg-white focus:ring-4 focus:ring-blue-500/5 focus:outline-none text-sm font-bold transition-all shadow-inner"
                  value={inventorySearch}
                  onChange={(e) => setInventorySearch(e.target.value)}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-4 min-w-[150px] justify-end">
             {isSupabaseConfigured && (
               <button onClick={() => loadAndSync(true)} className={`p-2.5 rounded-xl border border-slate-100 hover:bg-blue-50 transition-all ${isSyncing ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}>
                 <RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
               </button>
             )}
             {view === 'INVENTORY' && (
               <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-lg active:scale-95 whitespace-nowrap">
                 + New Asset
               </button>
             )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto min-h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={(d) => { setSelectedDevice(d); setView('DEVICE_DETAIL'); }} onUpdateDevice={handleUpdateDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} searchQuery={inventorySearch} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
            {view === 'CONTRACTS' && <ContractManager devices={devices} onSaveContract={handleSaveContract} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
          </div>
        </div>
      </main>
    </div>
  );
};

