  const [inventorySearch, setInventorySearch] = useState('');

  // Mismatch Error State
  const [schemaError, setSchemaError] = useState<{ message: string; sql: string } | null>(null);

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase
          .from('devices')
          .select('*')
          .order('id', { ascending: true });

        if (!error && cloudData) {
          const cloudDevices = cloudData as MedicalDevice[];
          await saveDevicesToDB(cloudDevices);
          setDevices(cloudDevices);
        } else if (error) {
          console.warn("Cloud access limited, falling back to local storage.", error.message);
          const localData = await getAllDevicesFromDB();
          setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
        }
      } else {
        const localData = await getAllDevicesFromDB();
        setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
      }
    } catch (error) {
      console.error("Clinical fleet index failure:", error);
      const localData = await getAllDevicesFromDB();
      setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const persistDeviceChange = async (changedDevice: MedicalDevice | MedicalDevice[], action: 'UPSERT' | 'DELETE', ignoreCNCAN: boolean = false) => {
    setIsSyncing(true);
    try {
      if (isSupabaseConfigured && supabase) {
        const rawPayload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
        const dedupeMap = new Map<string, MedicalDevice>();
        rawPayload.forEach(d => dedupeMap.set(d.id, d));
        const payload = Array.from(dedupeMap.values());

        const transactionPromise = (async () => {
          if (action === 'DELETE' && !Array.isArray(changedDevice)) {
            const { error } = await supabase.from('devices').delete().eq('id', changedDevice.id);
            if (error) throw error;
          } else {
            const sanitizedPayload = payload.map(d => {
              const base: any = {
                id: d.id,
                name: d.name,
                category: d.category || 'Altele',
                manufacturer: d.manufacturer,
                model: d.model,
                serialNumber: d.serialNumber,
                department: d.department,
                purchaseDate: d.purchaseDate,
                status: d.status,
                maintenanceHistory: d.maintenanceHistory || [],
                contracts: d.contracts || [],
                files: d.files || []
              };

              if (!ignoreCNCAN) {
                base.isCNCAN = !!d.isCNCAN;
              }

              return base;
            });

            const { data, error } = await supabase
              .from('devices')
              .upsert(sanitizedPayload, { onConflict: 'id' })
              .select('id');

            if (error) {
              if (error.message.includes('category') || error.hint?.includes('category')) {
                setSchemaError({
                  message: "Your cloud registry is missing the 'category' column. This field is required to organize assets by type (e.g., Aparat ventilatie).",
                  sql: `ALTER TABLE devices ADD COLUMN "category" TEXT DEFAULT 'Altele';`
                });
                throw new Error("SCHEMA_MISMATCH");
              }
              if (error.message.includes('isCNCAN') || error.hint?.includes('isCNCAN')) {
                setSchemaError({
                  message: "Your cloud registry is missing the 'isCNCAN' column. The sync failed because the database doesn't know where to store this new data.",
                  sql: `ALTER TABLE devices ADD COLUMN "isCNCAN" BOOLEAN DEFAULT FALSE;`
                });
                throw new Error("SCHEMA_MISMATCH");
              }
              throw error;
            }
            if (!data || data.length === 0) throw new Error("Registry write timeout.");
          }
          return true;
        })();

        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error("Global registry timeout.")), CLOUD_TIMEOUT_MS)
        );

        await Promise.race([transactionPromise, timeoutPromise]);
      } else {
        const currentLocal = await getAllDevicesFromDB();
        const payload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
        let updatedLocal: MedicalDevice[];
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          updatedLocal = currentLocal.filter(d => d.id !== changedDevice.id);
        } else {
          const map = new Map(currentLocal.map(d => [d.id, d]));
          payload.forEach(p => map.set(p.id, p));
          updatedLocal = Array.from(map.values());
        }
        await saveDevicesToDB(updatedLocal);
      }
      await loadAndSync(false);
    } catch (e: any) {
      if (e.message !== "SCHEMA_MISMATCH") {
        console.error("Clinical Registry Error:", e.message);
        throw e;
      }
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddDevice = async (newDevice: MedicalDevice) => {
    const deviceWithId: MedicalDevice = { ...newDevice, id: `DEV-REG-${Date.now()}` };
    try { await persistDeviceChange(deviceWithId, 'UPSERT'); setView('INVENTORY'); } catch (err) {}
  };

  const handleUpdateDevice = async (updated: MedicalDevice) => {
    try { 
      await persistDeviceChange(updated, 'UPSERT'); 
      if (selectedDevice?.id === updated.id) setSelectedDevice(updated);
    } catch (err) {}
  };

  const handleBulkAddDevices = async (newDevicesList: MedicalDevice[]) => {
    const devicesWithIds = newDevicesList.map(d => ({ ...d, id: d.id || `DEV-B-${Date.now()}-${Math.random()}` }));
    try { await persistDeviceChange(devicesWithIds, 'UPSERT'); setView('INVENTORY'); } catch (err) {}
  };

  const handleDeleteDevice = async (id: string) => {
    const deviceToDelete = devices.find(d => d.id === id);
    if (deviceToDelete) {
      try { await persistDeviceChange(deviceToDelete, 'DELETE'); if (selectedDevice?.id === id) setView('INVENTORY'); } catch (err) {}
    }
  };

  const handleSaveContract = async (contract: Contract, deviceIds: string[]) => {
    const updatedDevices = devices.map(device => {
      if (deviceIds.includes(device.id)) {
        return {
          ...device,
          contracts: [...(device.contracts || []), contract]
        };
      }
      return device;
    });

    try {
      await persistDeviceChange(updatedDevices, 'UPSERT');
    } catch (err) {
      console.error("Failed to save contract association:", err);
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* SCHEMA ERROR MODAL */}
      {schemaError && (
        <div className="fixed inset-0 z-[500] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl p-10 relative border-4 border-amber-400">
            <div className="flex items-center gap-6 mb-8">
              <div className="p-4 bg-amber-100 text-amber-600 rounded-3xl">
                <ShieldAlert className="w-12 h-12" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Database Out of Sync</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Schema Mismatch Detected</p>
              </div>
            </div>

            <p className="text-sm text-slate-600 mb-8 leading-relaxed font-medium">
              {schemaError.message}
            </p>

            <div className="bg-slate-900 rounded-2xl p-6 mb-8 relative group">
              <code className="text-xs font-mono text-blue-300 break-all">{schemaError.sql}</code>
              <button 
                onClick={() => { navigator.clipboard.writeText(schemaError.sql); }}
                className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all"
              >
                <Copy className="w-4 h-4" />
              </button>
            </div>

            <div className="flex flex-col gap-3">
              <button 
                onClick={() => { setView('SETTINGS'); setSchemaError(null); }}
                className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-black transition flex items-center justify-center gap-3"
              >
                Go to Database Migration <ArrowRight className="w-5 h-5" />
              </button>
              <button 
                onClick={() => setSchemaError(null)}
                className="w-full py-5 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition"
              >
                Close & Stay Offline
              </button>
            </div>
          </div>
        </div>
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <button onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'DASHBOARD' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><LayoutDashboard className="w-5 h-5" /> Dashboard</button>
            <button onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'INVENTORY' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><List className="w-5 h-5" /> Inventory</button>
            <button onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'PLANNER' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><CalendarRange className="w-5 h-5" /> Planner</button>
            <button onClick={() => { setView('CONTRACTS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'CONTRACTS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><ShieldCheck className="w-5 h-5" /> Contracts</button>
            <button onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'SETTINGS' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}><SettingsIcon className="w-5 h-5" /> Settings</button>
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {isLoading && (
          <div className="absolute inset-0 bg-white/95 z-50 flex items-center justify-center">
            <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
          </div>
        )}
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-50 shadow-sm">
          <div className="flex items-center gap-3 min-w-[200px]">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight hidden sm:block">
               {view.replace('_', ' ')}
             </h2>
          </div>

          {/* RESTORED SEARCH BAR */}
          {view === 'INVENTORY' && (
            <div className="flex-1 max-w-xl mx-4">
              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 pointer-events-none group-focus-within:text-blue-600 transition-colors" />
                <input 
                  type="text"
                  placeholder="Search assets by name, model or serial..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border-2 border-transparent rounded-2xl focus:border-blue-500/20 focus:bg-white focus:ring-4 focus:ring-blue-500/5 focus:outline-none text-sm font-bold transition-all shadow-inner"
                  value={inventorySearch}
                  onChange={(e) => setInventorySearch(e.target.value)}
                />
              </div>
            </div>
          )}

          <div className="flex items-center gap-4 min-w-[150px] justify-end">
             {isSupabaseConfigured && (
               <button onClick={() => loadAndSync(true)} className={`p-2.5 rounded-xl border border-slate-100 hover:bg-blue-50 transition-all ${isSyncing ? 'text-blue-600 bg-blue-50' : 'text-slate-400'}`}>
                 <RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} />
               </button>
             )}
             {view === 'INVENTORY' && (
               <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-lg active:scale-95 whitespace-nowrap">
                 + New Asset
               </button>
             )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto min-h-full">
            {view === 'DASHBOARD' && <Dashboard devices={devices} />}
            {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={(d) => { setSelectedDevice(d); setView('DEVICE_DETAIL'); }} onUpdateDevice={handleUpdateDevice} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} searchQuery={inventorySearch} />}
            {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
            {view === 'CONTRACTS' && <ContractManager devices={devices} onSaveContract={handleSaveContract} />}
            {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={handleAddDevice} onBulkSave={handleBulkAddDevices} onCancel={() => setView('INVENTORY')} />}
            {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} onBack={() => setView('INVENTORY')} onUpdate={handleUpdateDevice} onDelete={() => handleDeleteDevice(selectedDevice.id)} />}
            {view === 'SETTINGS' && <Settings devices={devices} onImport={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { MedicalDevice } from '../types';
import { Download, Upload, AlertTriangle, Database, Cloud, CheckCircle, Save, LogOut, ShieldCheck, RefreshCw, Loader2, AlertCircle, Terminal, Copy, Check, Info, HardDrive } from 'lucide-react';
import { isSupabaseConfigured, getSupabaseConfig, saveSupabaseConfig, clearSupabaseConfig, supabase } from '../services/supabase';
import { getStorageStats } from '../services/storageService';

interface SettingsProps {
  devices: MedicalDevice[];
  onImport: (devices: MedicalDevice[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ devices, onImport }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [config, setConfig] = useState(getSupabaseConfig());
  const [inputUrl, setInputUrl] = useState(config.url || '');
  const [inputKey, setInputKey] = useState(config.key || '');
  const [showKey, setShowKey] = useState(false);
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null);
  const [copied, setCopied] = useState(false);

  const [dbCount, setDbCount] = useState<number | null>(null);
  const [lsCount, setLsCount] = useState<number | null>(null);

  // Updated SQL fix to include category column
  const SQL_FIX = `ALTER TABLE devices ADD COLUMN IF NOT EXISTS "isCNCAN" BOOLEAN DEFAULT FALSE;
ALTER TABLE devices ADD COLUMN IF NOT EXISTS "category" TEXT DEFAULT 'Altele';`;

  useEffect(() => {
    const checkStorage = async () => {
      const stats = await getStorageStats();
      setDbCount(stats.count);
      const legacy = localStorage.getItem('meditrack_devices');
      setLsCount(legacy ? JSON.parse(legacy).length : 0);
    };
    checkStorage();
  }, []);

  const handleCopySql = () => {
    navigator.clipboard.writeText(SQL_FIX);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleRunIntegrityTest = async () => {
    if (!supabase) return;
    setIsTesting(true);
    setTestResult(null);
    try {
      const testId = `TEST-${Date.now()}`;
      const { error: upsertError } = await supabase.from('devices').upsert({
        id: testId, name: 'Integrity Test', manufacturer: 'SYS', model: 'DIAG', serialNumber: testId, department: 'SYS', purchaseDate: '2024-01-01', status: 'Active', category: 'Altele'
      });
      if (upsertError) throw upsertError;
      const { data, error: fetchError } = await supabase.from('devices').select('id').eq('id', testId).single();
      if (fetchError || !data) throw new Error("Sync loop failed.");
      await supabase.from('devices').delete().eq('id', testId);
      setTestResult({ success: true, message: "Cloud connection fully verified." });
    } catch (e: any) {
      setTestResult({ success: false, message: `Failure: ${e.message}` });
    } finally {
      setIsTesting(false);
    }
  };

  const handleDisconnectCloud = () => {
    if (window.confirm("Confirm disconnection from the clinical cloud registry? The application will reload in local-only mode.")) {
      clearSupabaseConfig();
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-fade-in pb-20 px-4">

      {/* SCHEMA MIGRATION HUB */}
      <div className="bg-amber-50 p-8 rounded-[2.5rem] border border-amber-200 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
          <Terminal className="w-40 h-40 text-amber-600" />
        </div>
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-3 bg-amber-600 text-white rounded-2xl shadow-lg shadow-amber-200">
              <Database className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-xl font-black text-amber-900 uppercase tracking-tight">Database Schema Setup</h2>
              <p className="text-[10px] text-amber-600 font-bold uppercase tracking-widest">Required for Categorization & CNCAN</p>
            </div>
          </div>

          <div className="bg-slate-900 rounded-2xl p-6 mb-6 shadow-inner relative group">
            <pre className="text-xs font-mono text-blue-300 break-all whitespace-pre-wrap leading-relaxed">
              {SQL_FIX}
            </pre>
            <button 
              onClick={handleCopySql}
              className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-all flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest"
            >
              {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copied' : 'Copy SQL'}
            </button>
          </div>

          <div className="flex items-start gap-4 p-4 bg-white/50 rounded-2xl border border-amber-200">
            <Info className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
            <p className="text-[11px] text-amber-800 font-medium leading-relaxed">
              If your database was created before the "Tip Aparat" (Category) update, you must run the SQL above in your <span className="font-bold">Supabase SQL Editor</span>. This adds the required organization fields to your cloud table.
            </p>
          </div>
        </div>
      </div>

      <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-2xl border border-white/5 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
          <HardDrive className="w-40 h-40 text-blue-400" />
        </div>
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
          <div className="flex-1">
             <h2 className="text-2xl font-black text-white uppercase tracking-tight">Cloud Integrity Diagnostics</h2>
             <div className="grid grid-cols-2 gap-4 mt-8">
                <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                   <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Local Index</p>
                   <p className="text-3xl font-black text-white">{dbCount ?? '...'}</p>
                </div>
                <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                   <p className="text-[10px] font-black text-amber-400 uppercase tracking-widest mb-1">Global Mirror</p>
                   <p className="text-3xl font-black text-white">{devices.length}</p>
                </div>
             </div>
          </div>
          <div className="w-full md:w-64 space-y-3">
             <button onClick={handleRunIntegrityTest} disabled={isTesting || !isSupabaseConfigured} className="w-full p-4 bg-blue-500/10 rounded-2xl border border-blue-500/20 flex items-center justify-center gap-3 hover:bg-blue-500/20 transition-all group disabled:opacity-30">
                {isTesting ? <RefreshCw className="w-5 h-5 text-blue-400 animate-spin" /> : <ShieldCheck className="w-5 h-5 text-blue-400 group-hover:scale-110 transition" />}
                <span className="text-[10px] font-black text-blue-100 uppercase">Verify Sync</span>
             </button>
          </div>
        </div>
        {testResult && (
          <div className={`mt-6 p-4 rounded-2xl border flex items-start gap-4 animate-fade-in ${testResult.success ? 'bg-green-500/10 border-green-500/20 text-green-400' : 'bg-red-500/10 border-red-500/20 text-red-400'}`}>
            {testResult.success ? <CheckCircle className="w-5 h-5 shrink-0" /> : <AlertCircle className="w-5 h-5 shrink-0" />}
            <p className="text-xs font-bold leading-relaxed">{testResult.message}</p>
          </div>
        )}
      </div>

      <div className="bg-white p-6 sm:p-10 rounded-[2.5rem] shadow-xl border border-slate-100">
        <div className="flex items-center gap-5 mb-10">
          <div className={`p-5 rounded-3xl ${isSupabaseConfigured ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
            <Cloud className="w-10 h-10" />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tight leading-none">Cloud Infrastructure</h2>
            <p className="text-sm text-slate-400 font-bold uppercase tracking-widest mt-1">Multi-Device Connectivity</p>
          </div>
        </div>

        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Project Endpoint</label>
                <input type="text" value={inputUrl} onChange={(e) => setInputUrl(e.target.value)} placeholder="https://abc.supabase.co" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-sm font-mono" />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Service Anon Key</label>
                <div className="relative">
                  <input type={showKey ? "text" : "password"} value={inputKey} onChange={(e) => setInputKey(e.target.value)} placeholder="eyJhbG..." className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none text-sm font-mono pr-24" />
                  <button onClick={() => setShowKey(!showKey)} className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-400">{showKey ? "HIDE" : "SHOW"}</button>
                </div>
              </div>
            </div>
            <div className="flex flex-col sm:flex-row gap-4 pt-4">
              <button onClick={() => saveSupabaseConfig(inputUrl, inputKey)} className="flex-1 py-5 bg-blue-600 text-white rounded-[1.5rem] font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95">Authenticate Registry</button>
              {isSupabaseConfigured && <button onClick={handleDisconnectCloud} className="px-8 py-5 bg-red-50 text-red-600 rounded-[1.5rem] font-black transition hover:bg-red-100"><LogOut className="w-6 h-6" /></button>}
            </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { MedicalDevice, DeviceStatus, MaintenanceType, Contract, DeviceFile, MaintenanceRecord, DeviceComponent, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { 
  Calendar, FileText, Activity, Box, QrCode, Plus, Trash2, 
  Download, ExternalLink, Wand2, ShieldCheck, X, Edit2, 
  Camera, Package, Settings, Info, FileCheck, ClipboardList, Maximize2, Loader2, Printer, Check, ChevronDown, Clock, Sparkles, CloudUpload, ShieldAlert
} from 'lucide-react';
import { suggestMaintenanceSchedule } from '../services/geminiService';
import { uploadDeviceFile, isSupabaseConfigured } from '../services/supabase';

interface DeviceDetailProps {
  device: MedicalDevice;
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: () => void;
  onBack: () => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, onUpdate, onDelete, onBack }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'contracts' | 'qr'>('overview');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showFullImage, setShowFullImage] = useState(false);
  const [showMaintenanceModal, setShowMaintenanceModal] = useState(false);

  const [maintenanceForm, setMaintenanceForm] = useState({ technician: '', description: '' });
  const [suggestedPlan, setSuggestedPlan] = useState<{ nextScheduledDate: string; frequency: string; tasks: string; isModified?: boolean; } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const uploadTypeRef = useRef<DeviceFile['type']>('report');

  const isDeptStandard = useMemo(() => (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department as any), [device.department]);

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category || DEVICE_CATEGORIES[0],
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: isDeptStandard ? device.department : 'OTHER',
    customDepartment: isDeptStandard ? '' : device.department,
    purchaseDate: device.purchaseDate,
    status: device.status,
    isCNCAN: !!device.isCNCAN
  });

  useEffect(() => {
    const standard = (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department as any);
    setEditForm({
      name: device.name,
      category: device.category || DEVICE_CATEGORIES[0],
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: standard ? device.department : 'OTHER',
      customDepartment: standard ? '' : device.department,
      purchaseDate: device.purchaseDate,
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  }, [device]);

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const saveGeneralEdits = () => {
    const finalDept = editForm.department === 'OTHER' ? (editForm.customDepartment || 'Unassigned') : editForm.department;
    onUpdate({
      ...device,
      name: editForm.name,
      category: editForm.category,
      manufacturer: editForm.manufacturer,
      model: editForm.model,
      serialNumber: editForm.serialNumber,
      department: finalDept,
      purchaseDate: editForm.purchaseDate,
      status: editForm.status as DeviceStatus,
      isCNCAN: editForm.isCNCAN
    });
    setIsEditing(false);
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas failed"));
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.7));
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let finalUrl = isSupabaseConfigured ? await uploadDeviceFile(file, `asset_${device.id}.jpg`) : await compressImage(file);
        onUpdate({ ...device, image: finalUrl! });
      } catch (err) { alert("Visual update failed."); } finally { setIsCompressing(false); }
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let fileUrl = isSupabaseConfigured ? await uploadDeviceFile(file, file.name) : await compressImage(file);
        const newFile: DeviceFile = { id: `FL-${Date.now()}`, name: file.name, type: uploadTypeRef.current, url: fileUrl!, dateAdded: new Date().toISOString().split('T')[0] };
        onUpdate({ ...device, files: [...(device.files || []), newFile] });
      } catch (err) { alert("Clinical document processing failed."); } finally { setIsCompressing(false); }
    }
  };

  const triggerFileUpload = (type: DeviceFile['type']) => {
    uploadTypeRef.current = type;
    fileInputRef.current?.click();
  };

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      setSuggestedPlan({ nextScheduledDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], frequency: res.frequency, tasks: res.tasks.join(', ') });
    } catch (err) { alert("AI Intelligence unavailable."); } finally { setIsAnalyzing(false); }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url.startsWith('http')) window.open(file.url, '_blank');
    else { const win = window.open(); win?.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`); }
  };

  const reports = (device.files || []).filter(f => f.type === 'report');
  const manuals = (device.files || []).filter(f => f.type === 'manual');

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/95 z-[100] flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
        </div>
      )}

      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">← Back to Inventory</button>
          <div className="flex items-center gap-3">
             {isEditing ? <input name="name" value={editForm.name} onChange={handleEditChange} className="text-3xl font-bold text-slate-900 bg-white border-2 border-blue-500 rounded-xl px-4 py-1 outline-none" /> : <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>}
          </div>
          <div className="flex flex-wrap items-center gap-4 mt-2 text-sm text-slate-500">
            <span className="flex items-center gap-1.5"><Box className="w-4 h-4 text-blue-500" /> {device.category} / {device.model}</span>
            <span className="px-2.5 py-1 bg-white border border-slate-200 rounded-full text-xs font-semibold shadow-sm">SN: {device.serialNumber}</span>
            <StatusBadge status={device.status} />
            {device.isCNCAN && <span className="px-2.5 py-1 bg-amber-100 text-amber-700 border border-amber-200 rounded-full text-xs font-black uppercase tracking-widest flex items-center gap-1.5 shadow-sm"><ShieldAlert className="w-3.5 h-3.5" /> CNCAN Regulated</span>}
          </div>
        </div>
        <div className="flex gap-2">
           {isEditing ? (
             <>
                <button onClick={() => setIsEditing(false)} className="px-6 py-2.5 bg-slate-100 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Cancel</button>
                <button onClick={saveGeneralEdits} className="px-6 py-2.5 bg-blue-600 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 transition shadow-lg flex items-center gap-2"><Check className="w-4 h-4" /> Save Info</button>
             </>
           ) : (
             <>
                <button onClick={() => setIsEditing(true)} className="p-2.5 bg-white text-blue-600 border border-slate-200 rounded-lg hover:bg-blue-50 transition shadow-sm"><Edit2 className="w-5 h-5" /></button>
                <button type="button" onClick={onDelete} className="p-2.5 bg-white text-red-600 border border-slate-200 rounded-lg hover:bg-red-50 transition shadow-sm"><Trash2 className="w-5 h-5" /></button>
             </>
           )}
           <button type="button" onClick={() => setActiveTab('qr')} className={`flex items-center gap-2 px-4 py-2 rounded-lg transition shadow-md font-bold text-sm ${activeTab === 'qr' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white hover:bg-slate-800'}`}><QrCode className="w-4 h-4" /> QR ID</button>
        </div>
      </div>

      <div className="flex border-b border-slate-200 px-6 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview'} icon={<Activity className="w-4 h-4" />} label="Command Center" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Calendar className="w-4 h-4" />} label="History" />
        <TabButton active={activeTab === 'contracts'} onClick={() => setActiveTab('contracts')} icon={<ShieldCheck className="w-4 h-4" />} label="Contracts" />
      </div>

      <div className="p-6 overflow-y-auto flex-1 bg-slate-50/50">
        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />

        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-slate-900 rounded-2xl border border-slate-200 shadow-xl overflow-hidden relative min-h-[300px] flex items-center justify-center">
                  {device.image ? <img src={device.image} alt={device.name} className="w-full h-full object-contain relative z-10" /> : <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 relative z-10"><Camera className="w-16 h-16 mb-4 opacity-20" /><p className="text-xs font-black uppercase tracking-[0.2em] opacity-40">No Asset Visual</p></div>}
                  <div className="absolute bottom-4 right-4 flex gap-2 z-20">
                    <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
                    <button type="button" onClick={() => imageInputRef.current?.click()} className="p-3 bg-white text-slate-900 rounded-xl shadow-xl hover:bg-slate-50 transition flex flex-col items-center gap-1 min-w-[64px]"><Camera className="w-4 h-4" /><span className="text-[8px] font-black opacity-40 uppercase">Update Photo</span></button>
                    {device.image && <button type="button" onClick={() => setShowFullImage(true)} className="p-3 bg-blue-600 text-white rounded-xl shadow-xl hover:bg-blue-700 transition"><Maximize2 className="w-4 h-4" /></button>}
                  </div>
                </div>

                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
                  <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400 flex items-center gap-2">
                    <span className="p-1.5 bg-blue-50 text-blue-600 rounded-lg"><Info className="w-4 h-4" /></span> Master Specification
                  </h3>
                  {isEditing ? (
                    <div className="space-y-4 overflow-y-auto max-h-[400px] pr-2 custom-scrollbar">
                      <div className="flex items-center gap-3 p-3 bg-amber-50 rounded-xl border border-amber-200 mb-2">
                        <input type="checkbox" id="edit-cncan" name="isCNCAN" checked={editForm.isCNCAN} onChange={handleEditChange} className="w-4 h-4 text-amber-600 focus:ring-amber-500 rounded" />
                        <label htmlFor="edit-cncan" className="text-[10px] font-black text-amber-900 uppercase">CNCAN Regulated</label>
                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Tip Aparat (Category)</label>
                        <select name="category" value={editForm.category} onChange={handleEditChange} className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none">
                          {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                        </select>
                      </div>
                      <EditField label="Manufacturer" name="manufacturer" value={editForm.manufacturer} onChange={handleEditChange} />
                      <EditField label="Model" name="model" value={editForm.model} onChange={handleEditChange} />
                      <EditField label="Serial Number" name="serialNumber" value={editForm.serialNumber} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Department</label>
                        <select name="department" value={editForm.department} onChange={handleEditChange} className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none appearance-none">
                          {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                          <option value="OTHER">OTHER / CUSTOM...</option>
                        </select>
                      </div>
                      <EditField label="Purchase Date" name="purchaseDate" type="date" value={editForm.purchaseDate} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Life Cycle Status</label>
                        <select name="status" value={editForm.status} onChange={handleEditChange} className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none">
                          {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                    </div>
                  ) : (
                    <>
                      <InfoRow label="Compliance" value={device.isCNCAN ? "CNCAN Regulated" : "Standard Asset"} />
                      <InfoRow label="Tip Aparat" value={device.category} />
                      <InfoRow label="Manufacturer" value={device.manufacturer} />
                      <InfoRow label="Serial Number" value={device.serialNumber} />
                      <InfoRow label="Department" value={device.department} />
                      <InfoRow label="Purchased" value={device.purchaseDate} />
                    </>
                  )}
                </div>
              </div>

              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex justify-between items-center mb-6">
                   <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2"><FileCheck className="w-5 h-5 text-green-600" /> Service Reports</h3>
                   <button type="button" onClick={() => triggerFileUpload('report')} className="text-[10px] font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl hover:bg-blue-100 transition flex items-center gap-2"><Plus className="w-4 h-4" /> ADD REPORT</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {reports.map(report => (
                    <div key={report.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-300 hover:shadow-lg transition-all group relative">
                      <div className="flex items-center gap-4 flex-1 min-w-0 cursor-pointer" onClick={(e) => handleOpenFile(e, report)}>
                        <div className="p-3 bg-white rounded-xl shadow-sm group-hover:bg-blue-50 transition shrink-0"><ClipboardList className="w-5 h-5 text-slate-400 group-hover:text-blue-600" /></div>
                        <div className="min-w-0 flex-1">
                          <p className="text-sm font-bold text-slate-900 break-all line-clamp-2 leading-tight mb-0.5">{report.name}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter">{report.dateAdded}</p>
                        </div>
                      </div>
                      <button type="button" onClick={(e) => { e.preventDefault(); e.stopPropagation(); onUpdate({ ...device, files: (device.files || []).filter(f => f.id !== report.id) }); }} className="p-2 text-slate-300 hover:text-red-500 rounded-lg transition ml-2 shrink-0"><Trash2 className="w-4 h-4" /></button>
                    </div>
                  ))}
                  {reports.length === 0 && <div className="col-span-full py-12 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">No service reports attached.</div>}
                </div>
              </div>
            </div>

            <div className="lg:col-span-4 space-y-6">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                 <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><FileText className="w-4 h-4" /> Technical Library</h3>
                 <div className="space-y-6">
                   <div>
                     <p className="text-[10px] font-bold text-slate-800 uppercase mb-3 border-b pb-1 border-slate-50">Operator Manuals</p>
                     <div className="space-y-2">
                       {manuals.map(m => (
                         <div key={m.id} className="flex items-start justify-between group p-3 rounded-xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100 min-w-0">
                           <div className="flex items-start gap-3 flex-1 min-w-0 text-xs font-bold text-blue-600 cursor-pointer" onClick={(e) => handleOpenFile(e, m)}>
                             <Download className="w-4 h-4 opacity-40 shrink-0 mt-0.5" />
                             <span className="break-all leading-snug flex-1">{m.name}</span>
                           </div>
                           <button type="button" onClick={(e) => { e.preventDefault(); e.stopPropagation(); onUpdate({ ...device, files: (device.files || []).filter(f => f.id !== m.id) }); }} className="p-1.5 text-slate-300 hover:text-red-500 transition ml-2 shrink-0"><Trash2 className="w-3.5 h-3.5" /></button>
                         </div>
                       ))}
                       <button type="button" onClick={() => triggerFileUpload('manual')} className="w-full py-3 mt-2 border-2 border-dashed border-slate-100 rounded-xl text-[10px] font-black text-slate-400 hover:border-blue-200 hover:text-blue-500 transition">+ ADD MANUAL</button>
                     </div>
                   </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'maintenance' && (
          <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
               <div className="flex-1"><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight flex items-center gap-3"><Sparkles className="w-6 h-6 text-violet-600" /> Engineering Planner</h3><p className="text-sm text-slate-500 mt-1 font-medium">Optimize maintenance lifecyle for this asset.</p></div>
               <div className="flex gap-3"><button type="button" onClick={handleSuggestMaintenance} disabled={isAnalyzing} className="px-6 py-3.5 bg-violet-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 transition disabled:opacity-50 hover:bg-violet-700 shadow-xl">{isAnalyzing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Wand2 className="w-5 h-5" />}{isAnalyzing ? "Calculating..." : "Smart Suggest"}</button><button type="button" onClick={() => setShowMaintenanceModal(true)} className="px-6 py-3.5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 transition hover:bg-black shadow-xl"><Plus className="w-5 h-5" /> Log Event</button></div>
            </div>

            <div className="space-y-4">
              {device.maintenanceHistory.length > 0 ? device.maintenanceHistory.map(record => (
                <div key={record.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-blue-200 transition-all">
                  <div className="flex gap-6">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${record.completed ? 'bg-green-50 text-green-600' : 'bg-amber-50 text-amber-600'}`}>{record.completed ? <ShieldCheck className="w-7 h-7" /> : <Clock className="w-7 h-7" />}</div>
                    <div><h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">{record.type}</h4><p className="text-sm text-slate-600 line-clamp-2 mt-1 font-medium">{record.description}</p></div>
                  </div>
                </div>
              )) : <div className="py-20 flex flex-col items-center justify-center text-center opacity-40"><Calendar className="w-16 h-16 text-slate-200 mb-4" /><p className="text-sm font-black uppercase tracking-widest text-slate-400">No logs on record</p></div>}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let color = "bg-slate-100 text-slate-700 border-slate-200";
  if (status === DeviceStatus.ACTIVE) color = "bg-green-100 text-green-700 border-green-200";
  if (status === DeviceStatus.BROKEN) color = "bg-red-100 text-red-700 border-red-200";
  if (status === DeviceStatus.MAINTENANCE) color = "bg-amber-100 text-amber-700 border-amber-200";
  return <span className={`px-2.5 py-1 border rounded-full text-xs font-semibold shadow-sm uppercase ${color}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button type="button" onClick={onClick} className={`flex items-center gap-3 px-8 py-5 text-sm font-black uppercase tracking-[0.1em] border-b-4 transition-all ${active ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>
    {icon}
    {label}
  </button>
);

const EditField = ({ label, name, value, onChange, type = "text" }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</label>
    <input 
      name={name} 
      type={type}
      value={value} 
      onChange={onChange} 
      className="w-full bg-blue-50 border-2 border-blue-500 rounded-xl px-3 py-2 text-xs font-bold outline-none transition-all" 
    />
  </div>
);

const InfoRow = ({ label, value }: { label: string, value: string }) => (
  <div className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    <span className="text-xs font-bold text-slate-700">{value}</span>
  </div>
);

export default DeviceDetail;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onAddDevice, onDelete, searchQuery = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const allAvailableDepartments = useMemo(() => {
    const combined = new Set([...HOSPITAL_DEPARTMENTS, ...uniqueDeptsInData]);
    return Array.from(combined).sort();
  }, [uniqueDeptsInData]);

  const filteredDevices = useMemo(() => {
    const term = searchQuery.toLowerCase().trim();
    return devices.filter(d => {
      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.category || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, searchQuery, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['#', 'ASSET NAME', 'TIP APARAT', 'CNCAN', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'INTERNAL ID'];
    const tableRows = filteredDevices.map((d, idx) => [idx + 1, d.name, d.category, d.isCNCAN ? 'YES' : 'NO', d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | CATEGORY: ${filterCategory.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-slate-100 flex flex-col lg:flex-row items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-4 flex-1 w-full">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl hidden md:block">
            <Filter className="w-5 h-5" />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 flex-1 lg:flex-none w-full lg:w-auto">
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterCNCAN}
                onChange={(e) => setFilterCNCAN(e.target.value as any)}
              >
                <option value="ALL">CNCAN: ALL</option>
                <option value="YES">CNCAN ONLY</option>
                <option value="NO">NON-CNCAN</option>
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterDept}
                onChange={(e) => setFilterDept(e.target.value)}
              >
                <option value="ALL">ALL DEPTS</option>
                {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
              >
                <option value="ALL">ALL CATEGORIES</option>
                {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
              >
                <option value="ALL">ALL STATUSES</option>
                {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
          </div>
        </div>

        <button 
          onClick={handleExportExcel} 
          className="w-full lg:w-auto px-6 py-3.5 bg-white border-2 border-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-sm hover:border-blue-200 active:scale-95 flex items-center justify-center gap-2"
        >
          <FileSpreadsheet className="w-4 h-4" /> Export Report
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center w-12">#</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map((device, index) => (
                <tr 
                  key={device.id} 
                  className="hover:bg-blue-50/40 transition-all group"
                >
                  <td className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase text-center align-middle">
                    {index + 1}
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center relative">
                        {device.image ? <img src={device.image} className="w-full h-full object-cover" alt="Asset" /> : <Box className="w-5 h-5 text-slate-300" />}
                        {device.isCNCAN && (
                          <div className="absolute top-0 right-0 p-0.5 bg-amber-500 rounded-bl-lg shadow-sm" title="CNCAN Regulated">
                            <ShieldAlert className="w-2.5 h-2.5 text-white" />
                          </div>
                        )}
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                          {device.isCNCAN && (
                            <span className="px-1.5 py-0.5 bg-amber-100 text-amber-700 text-[8px] font-black rounded border border-amber-200 uppercase tracking-tighter">CNCAN</span>
                          )}
                        </div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="text-xs font-bold text-slate-700">{device.category} / {device.model || 'N/A'}</div>
                    <div className="text-[10px] font-mono text-slate-400 mt-0.5">#{device.serialNumber}</div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-8 py-24 text-center">
                    <div className="flex flex-col items-center gap-4">
                       <Search className="w-12 h-12 text-slate-100" />
                       <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No matching clinical assets found</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {editingDevice && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90" onClick={() => setEditingDevice(null)}></div>
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-fade-in border-4 border-white overflow-hidden relative z-10">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-100 text-blue-600 rounded-xl"><Edit2 className="w-5 h-5" /></div>
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Quick Edit</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Asset Record Registry</p>
                 </div>
               </div>
               <button type="button" onClick={() => setEditingDevice(null)} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition border border-slate-200"><X className="w-6 h-6" /></button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto max-h-[70vh]">
              <QuickField label="Asset Name" name="name" value={quickEditForm.name} onChange={handleQuickEditChange} />

              <div className="flex items-center gap-4 p-4 bg-amber-50 rounded-2xl border border-amber-200">
                <input 
                  type="checkbox" 
                  id="qe-cncan" 
                  name="isCNCAN" 
                  checked={quickEditForm.isCNCAN} 
                  onChange={handleQuickEditChange}
                  className="w-5 h-5 rounded border-amber-300 text-amber-600 focus:ring-amber-500 cursor-pointer"
                />
                <label htmlFor="qe-cncan" className="flex-1 cursor-pointer">
                  <p className="text-xs font-black text-amber-900 uppercase tracking-tight">CNCAN Regulated</p>
                  <p className="text-[9px] text-amber-600 font-bold uppercase tracking-widest">Radiation safety protocol asset</p>
                </label>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Tip Aparat (Category)</label>
                <div className="relative">
                  <select 
                    name="category" 
                    value={quickEditForm.category} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Manufacturer" name="manufacturer" value={quickEditForm.manufacturer} onChange={handleQuickEditChange} />
                <QuickField label="Model" name="model" value={quickEditForm.model} onChange={handleQuickEditChange} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Serial Number" name="serialNumber" value={quickEditForm.serialNumber} onChange={handleQuickEditChange} />
                <QuickField label="Purchase Date" name="purchaseDate" type="date" value={quickEditForm.purchaseDate} onChange={handleQuickEditChange} />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Department Registry</label>
                <div className="relative">
                   <select 
                     name="department" 
                     value={quickEditForm.department} 
                     onChange={handleQuickEditChange} 
                     className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                   >
                      <optgroup label="Standard Departments">
                        {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      </optgroup>
                      <optgroup label="Your Custom Registry">
                        {uniqueDeptsInData.filter(d => !HOSPITAL_DEPARTMENTS.includes(d as any)).map(dept => (
                          <option key={dept} value={dept}>{dept}</option>
                        ))}
                      </optgroup>
                      <option value="NEW_DEPT">+ ADD NEW DEPARTMENT...</option>
                   </select>
                   <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              {quickEditForm.department === 'NEW_DEPT' && (
                <div className="animate-fade-in bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
                  <div className="flex items-center gap-2 mb-2">
                    <PlusCircle className="w-3 h-3 text-blue-600" />
                    <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest">New Clinical Unit Name</span>
                  </div>
                  <input 
                    name="customDepartment" 
                    type="text"
                    value={quickEditForm.customDepartment} 
                    onChange={handleQuickEditChange} 
                    placeholder="Enter new department name..."
                    className="w-full bg-white border border-blue-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
                  />
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Life Cycle Status</label>
                <div className="relative">
                  <select 
                    name="status" 
                    value={quickEditForm.status} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex gap-4">
              <button type="button" onClick={() => setEditingDevice(null)} className="flex-1 py-4 bg-white text-slate-500 border border-slate-200 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition">Cancel</button>
              <button 
                type="button"
                onClick={handleSaveQuickEdit}
                className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center justify-center gap-2 active:scale-95"
              >
                <Check className="w-5 h-5" /> Update Registry
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const QuickField = ({ label, name, value, onChange, type = "text", placeholder }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      name={name} 
      type={type}
      value={value} 
      onChange={onChange} 
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
    />
  </div>
);

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onAddDevice, onDelete, searchQuery = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const allAvailableDepartments = useMemo(() => {
    const combined = new Set([...HOSPITAL_DEPARTMENTS, ...uniqueDeptsInData]);
    return Array.from(combined).sort();
  }, [uniqueDeptsInData]);

  const filteredDevices = useMemo(() => {
    const term = searchQuery.toLowerCase().trim();
    return devices.filter(d => {
      const matchSearch = !term || 
        (d.name || '').toLowerCase().includes(term) || 
        (d.serialNumber || '').toLowerCase().includes(term) ||
        (d.model || '').toLowerCase().includes(term) ||
        (d.category || '').toLowerCase().includes(term) ||
        (d.department || '').toLowerCase().includes(term);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, searchQuery, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['#', 'ASSET NAME', 'TIP APARAT', 'CNCAN', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'INTERNAL ID'];
    const tableRows = filteredDevices.map((d, idx) => [idx + 1, d.name, d.category, d.isCNCAN ? 'YES' : 'NO', d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | CATEGORY: ${filterCategory.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-slate-100 flex flex-col lg:flex-row items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-4 flex-1 w-full">
          <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl hidden md:block">
            <Filter className="w-5 h-5" />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 flex-1 lg:flex-none w-full lg:w-auto">
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterCNCAN}
                onChange={(e) => setFilterCNCAN(e.target.value as any)}
              >
                <option value="ALL">CNCAN: ALL</option>
                <option value="YES">CNCAN ONLY</option>
                <option value="NO">NON-CNCAN</option>
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterDept}
                onChange={(e) => setFilterDept(e.target.value)}
              >
                <option value="ALL">ALL DEPTS</option>
                {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
              >
                <option value="ALL">ALL CATEGORIES</option>
                {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
            <div className="relative">
              <select 
                className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
              >
                <option value="ALL">ALL STATUSES</option>
                {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
            </div>
          </div>
        </div>

        <button 
          onClick={handleExportExcel} 
          className="w-full lg:w-auto px-6 py-3.5 bg-white border-2 border-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase tracking-widest transition shadow-sm hover:border-blue-200 active:scale-95 flex items-center justify-center gap-2"
        >
          <FileSpreadsheet className="w-4 h-4" /> Export Report
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center w-12">#</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
