      value={value} 
      onChange={onChange} 
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
    />
  </div>
);

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

