    warrantyExpiration: device.warrantyExpiration || '',
    status: device.status,
    isCNCAN: !!device.isCNCAN
  });

  useEffect(() => {
    const standard = (HOSPITAL_DEPARTMENTS as readonly string[]).includes(device.department as any);
    setEditForm({
      name: device.name,
      category: device.category || DEVICE_CATEGORIES[0],
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: standard ? device.department : 'OTHER',
      customDepartment: standard ? '' : device.department,
      purchaseDate: device.purchaseDate,
      warrantyExpiration: device.warrantyExpiration || '',
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  }, [device]);

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const saveGeneralEdits = () => {
    const finalDept = editForm.department === 'OTHER' ? (editForm.customDepartment || 'Unassigned') : editForm.department;
    onUpdate({
      ...device,
      name: editForm.name,
      category: editForm.category,
      manufacturer: editForm.manufacturer,
      model: editForm.model,
      serialNumber: editForm.serialNumber,
      department: finalDept,
      purchaseDate: editForm.purchaseDate,
      warrantyExpiration: editForm.warrantyExpiration,
      status: editForm.status as DeviceStatus,
      isCNCAN: editForm.isCNCAN
    });
    setIsEditing(false);
  };

  const handleLogMaintenance = () => {
    const newRecord: MaintenanceRecord = {
      id: `MNT-${Date.now()}`,
      date: maintenanceForm.date,
      type: maintenanceForm.type,
      technician: maintenanceForm.technician,
      description: maintenanceForm.description,
      nextScheduledDate: maintenanceForm.nextDate || undefined,
      completed: true
    };
    onUpdate({
      ...device,
      maintenanceHistory: [newRecord, ...device.maintenanceHistory]
    });
    setShowMaintenanceModal(false);
    setMaintenanceForm({ technician: '', description: '', type: MaintenanceType.PREVENTIVE, date: new Date().toISOString().split('T')[0], nextDate: '' });
  };

  const handleAddComponent = () => {
    const newComp: DeviceComponent = {
      id: `COMP-${Date.now()}`,
      ...componentForm
    };
    onUpdate({
      ...device,
      components: [...(device.components || []), newComp]
    });
    setShowComponentModal(false);
    setComponentForm({ name: '', serialNumber: '', status: DeviceStatus.ACTIVE, installDate: new Date().toISOString().split('T')[0] });
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1200;
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas failed"));
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.7));
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let finalUrl = isSupabaseConfigured ? await uploadDeviceFile(file, `asset_${device.id}.jpg`) : await compressImage(file);
        onUpdate({ ...device, image: finalUrl! });
      } catch (err) { alert("Visual update failed."); } finally { setIsCompressing(false); }
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        let fileUrl = isSupabaseConfigured ? await uploadDeviceFile(file, file.name) : await compressImage(file);
        const newFile: DeviceFile = { id: `FL-${Date.now()}`, name: file.name, type: uploadTypeRef.current, url: fileUrl!, dateAdded: new Date().toISOString().split('T')[0] };
        onUpdate({ ...device, files: [...(device.files || []), newFile] });
      } catch (err) { alert("Clinical document processing failed."); } finally { setIsCompressing(false); }
    }
  };

  const triggerFileUpload = (type: DeviceFile['type']) => {
    uploadTypeRef.current = type;
    fileInputRef.current?.click();
  };

  const handleSuggestMaintenance = async () => {
    setIsAnalyzing(true);
    try {
      const res = await suggestMaintenanceSchedule(device.name, device.model);
      setSuggestedPlan({ nextScheduledDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], frequency: res.frequency, tasks: res.tasks.join(', ') });
    } catch (err) { alert("AI Intelligence unavailable."); } finally { setIsAnalyzing(false); }
  };

  const handleOpenFile = (e: React.MouseEvent, file: DeviceFile) => {
    e.preventDefault();
    if (file.url.startsWith('http')) window.open(file.url, '_blank');
    else { const win = window.open(); win?.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; width:100%; height:100%;" allowfullscreen></iframe>`); }
  };

  const reports = (device.files || []).filter(f => f.type === 'report');
  const manuals = (device.files || []).filter(f => f.type === 'manual');

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col h-full relative">
      {isCompressing && (
        <div className="absolute inset-0 bg-white/95 z-[100] flex flex-col items-center justify-center animate-fade-in">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
        </div>
      )}

      {/* Maintenance Modal */}
      {showMaintenanceModal && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-xl shadow-2xl animate-fade-in">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black uppercase tracking-tight">Log Service Event</h3>
                <button onClick={() => setShowMaintenanceModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition"><X className="w-6 h-6" /></button>
             </div>
             <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                   <EditField label="Service Date" type="date" value={maintenanceForm.date} onChange={(e:any) => setMaintenanceForm({...maintenanceForm, date: e.target.value})} />
                   <div className="space-y-1">
                      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Type</label>
                      <select className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" value={maintenanceForm.type} onChange={(e:any) => setMaintenanceForm({...maintenanceForm, type: e.target.value})}>
                         {Object.values(MaintenanceType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                   </div>
                </div>
                <EditField label="Technician Name" value={maintenanceForm.technician} onChange={(e:any) => setMaintenanceForm({...maintenanceForm, technician: e.target.value})} />
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Service Description</label>
                   <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold min-h-[100px]" value={maintenanceForm.description} onChange={(e:any) => setMaintenanceForm({...maintenanceForm, description: e.target.value})} />
                </div>
                <EditField label="Next Scheduled Service" type="date" value={maintenanceForm.nextDate} onChange={(e:any) => setMaintenanceForm({...maintenanceForm, nextDate: e.target.value})} />
                <button onClick={handleLogMaintenance} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-blue-700 shadow-xl transition active:scale-95">Commit Log</button>
             </div>
          </div>
        </div>
      )}

      {/* Component Modal */}
      {showComponentModal && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-md shadow-2xl animate-fade-in">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black uppercase tracking-tight">Register Component</h3>
                <button onClick={() => setShowComponentModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition"><X className="w-6 h-6" /></button>
             </div>
             <div className="space-y-4">
                <EditField label="Component Name" value={componentForm.name} onChange={(e:any) => setComponentForm({...componentForm, name: e.target.value})} />
                <EditField label="Serial Number" value={componentForm.serialNumber} onChange={(e:any) => setComponentForm({...componentForm, serialNumber: e.target.value})} />
                <EditField label="Install Date" type="date" value={componentForm.installDate} onChange={(e:any) => setComponentForm({...componentForm, installDate: e.target.value})} />
                <button onClick={handleAddComponent} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-black shadow-xl transition active:scale-95">Add Component</button>
             </div>
          </div>
        </div>
      )}

      <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/30">
        <div>
          <button type="button" onClick={onBack} className="text-slate-500 hover:text-slate-700 text-sm mb-2 flex items-center gap-1 transition">← Back to Inventory</button>
          <div className="flex items-center gap-3">
             {isEditing ? <input name="name" value={editForm.name} onChange={handleEditChange} className="text-3xl font-bold text-slate-900 bg-white border-2 border-blue-500 rounded-xl px-4 py-1 outline-none" /> : <h1 className="text-3xl font-bold text-slate-900 tracking-tight">{device.name}</h1>}
