              )) : <div className="py-20 flex flex-col items-center justify-center text-center opacity-40"><Calendar className="w-16 h-16 text-slate-200 mb-4" /><p className="text-sm font-black uppercase tracking-widest text-slate-400">No logs on record</p></div>}
            </div>
          </div>
        )}

        {activeTab === 'components' && (
          <div className="max-w-4xl mx-auto space-y-8 animate-fade-in">
             <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between">
                <div><h3 className="text-2xl font-black uppercase tracking-tight">Sub-Systems & Parts</h3><p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Manage modular clinical components</p></div>
                <button onClick={() => setShowComponentModal(true)} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest flex items-center gap-2 hover:bg-black transition"><Plus className="w-4 h-4" /> Register Part</button>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {(device.components || []).map(comp => (
                  <div key={comp.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-blue-300 transition-all">
                     <div className="flex gap-4">
                        <div className="p-3 bg-slate-50 text-slate-400 rounded-xl group-hover:bg-blue-50 group-hover:text-blue-600 transition"><Cpu className="w-6 h-6" /></div>
                        <div>
                           <h4 className="font-black text-slate-900 text-sm uppercase">{comp.name}</h4>
                           <p className="text-[10px] font-mono text-slate-400 mt-0.5">SN: {comp.serialNumber}</p>
                           <p className="text-[9px] text-slate-400 mt-1">Installed: {comp.installDate || 'N/A'}</p>
                        </div>
                     </div>
                     <StatusBadge status={comp.status} />
                  </div>
                ))}
                {(device.components || []).length === 0 && <div className="col-span-full py-20 text-center text-slate-400 italic text-sm border-2 border-dashed border-slate-100 rounded-3xl">No modular components registered.</div>}
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

