import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { MedicalDevice, DeviceStatus, MedicalTask, TaskStatus, TaskPriority } from '../types';
import { Activity, AlertTriangle, CheckCircle, Wrench, CheckSquare, Clock } from 'lucide-react';

interface DashboardProps {
  devices: MedicalDevice[];
  tasks: MedicalTask[];
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ devices, tasks }) => {

  const statusData = useMemo(() => {
    const counts = {
      [DeviceStatus.ACTIVE]: 0,
      [DeviceStatus.MAINTENANCE]: 0,
      [DeviceStatus.BROKEN]: 0,
      [DeviceStatus.RETIRED]: 0,
    };
    devices.forEach(d => counts[d.status]++);
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [devices]);

  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.COMPLETED).length;
  const criticalTasks = tasks.filter(t => t.priority === TaskPriority.CRITICAL && t.status !== TaskStatus.COMPLETED).length;

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
        <StatCard title="Total Assets" value={devices.length} icon={<Activity className="w-6 h-6 text-blue-600" />} color="bg-blue-50" />
        <StatCard title="Issues / Broken" value={devices.filter(d => d.status === DeviceStatus.BROKEN).length} icon={<AlertTriangle className="w-6 h-6 text-red-600" />} color="bg-red-50" />
        <StatCard title="Open Tickets" value={pendingTasks} icon={<CheckSquare className="w-6 h-6 text-indigo-600" />} color="bg-indigo-50" />
        <StatCard title="Critical Task Force" value={criticalTasks} icon={<AlertTriangle className="w-6 h-6 text-orange-600" />} color="bg-orange-50" />
        <StatCard title="Planned Service" value={devices.filter(d => d.status === DeviceStatus.MAINTENANCE).length} icon={<Wrench className="w-6 h-6 text-amber-600" />} color="bg-amber-50" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-black uppercase tracking-tight mb-4 text-slate-800">Global Fleet Integrity</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={statusData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                  {statusData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-black uppercase tracking-tight text-slate-800">Urgent Field Operations</h3>
            <span className="text-[10px] font-black bg-orange-100 text-orange-600 px-2 py-1 rounded">High Priority Only</span>
          </div>
          <div className="space-y-4 max-h-[220px] overflow-y-auto pr-2 custom-scrollbar">
            {tasks.filter(t => t.priority === TaskPriority.CRITICAL || t.priority === TaskPriority.HIGH).filter(t => t.status !== TaskStatus.COMPLETED).map(task => (
              <div key={task.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div>
                  <p className="text-sm font-black text-slate-900 leading-tight">{task.title}</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{task.department}</p>
                </div>
                <div className={`px-2 py-1 rounded text-[8px] font-black uppercase tracking-widest ${task.priority === TaskPriority.CRITICAL ? 'bg-red-100 text-red-600' : 'bg-orange-100 text-orange-600'}`}>
                  {task.priority}
                </div>
              </div>
            ))}
            {tasks.length === 0 && <p className="text-center py-10 text-slate-300 font-bold uppercase tracking-widest text-xs">No active critical tasks</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, icon, color }: { title: string, value: number, icon: React.ReactNode, color: string }) => (
  <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
    <div>
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{title}</p>
      <p className="text-2xl font-black text-slate-900 mt-1">{value}</p>
    </div>
    <div className={`p-3 rounded-2xl ${color}`}>
      {icon}
    </div>
  </div>
);

