                 <InfoRow label="Purchased" value={device.purchaseDate} />
                 <InfoRow label="Unit" value={device.department} />
              </div>
           </div>
        )}

        {activeTab === 'tasks' && (
           <div className="space-y-4 max-w-4xl mx-auto">
              {tasks.length > 0 ? tasks.map(task => (
                <div key={task.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex items-center justify-between group">
                   <div className="flex gap-6">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${task.status === TaskStatus.COMPLETED ? 'bg-green-50 text-green-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        {task.status === TaskStatus.COMPLETED ? <CheckCircle2 className="w-7 h-7" /> : <Clock className="w-7 h-7" />}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight leading-none">{task.title}</h4>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Priority: {task.priority} • Status: {task.status}</p>
                        <p className="text-sm text-slate-600 mt-2 font-medium">{task.description}</p>
                      </div>
                   </div>
                </div>
              )) : (
                <div className="py-20 text-center opacity-40">
                   <CheckSquare className="w-16 h-16 text-slate-200 mx-auto mb-4" />
                   <p className="text-sm font-black uppercase tracking-widest text-slate-400">No active tickets for this asset</p>
                </div>
              )}
           </div>
        )}
      </div>
    </div>
  );
};

