export default AddDeviceForm;

import React, { useState, useMemo } from 'react';
import { MedicalTask, TaskPriority, TaskStatus, MedicalDevice, HOSPITAL_DEPARTMENTS } from '../types';
import { CheckSquare, Plus, Search, Filter, AlertCircle, Clock, CheckCircle2, MoreHorizontal, Trash2, Edit, X, ArrowRight, User, Info, Building, MessageSquare, StickyNote } from 'lucide-react';

interface TaskTrackerProps {
  tasks: MedicalTask[];
  devices: MedicalDevice[];
  onAddTask: (task: MedicalTask) => void;
  onUpdateTask: (task: MedicalTask) => void;
  onDeleteTask: (id: string) => void;
}

const TaskTracker: React.FC<TaskTrackerProps> = ({ tasks, devices, onAddTask, onUpdateTask, onDeleteTask }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingTask, setEditingTask] = useState<MedicalTask | null>(null);
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    deviceId: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    priority: TaskPriority.MEDIUM,
    dueDate: '',
    notes: ''
  });

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchStatus = filterStatus === 'ALL' || t.status === filterStatus;
      const matchSearch = t.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          t.department.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          (t.deviceName && t.deviceName.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchStatus && matchSearch;
    });
  }, [tasks, filterStatus, searchQuery]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const device = devices.find(d => d.id === formData.deviceId);

    if (editingTask) {
      const updatedTask: MedicalTask = {
        ...editingTask,
        title: formData.title,
        description: formData.description,
        deviceId: formData.deviceId || undefined,
        deviceName: device?.name,
        department: formData.department,
        priority: formData.priority,
        dueDate: formData.dueDate,
        notes: formData.notes
      };
      onUpdateTask(updatedTask);
      setEditingTask(null);
    } else {
      const newTask: MedicalTask = {
        id: `TASK-${Date.now()}`,
        title: formData.title,
        description: formData.description,
        deviceId: formData.deviceId || undefined,
        deviceName: device?.name,
        department: formData.department,
        priority: formData.priority,
        status: TaskStatus.PENDING,
        createdAt: new Date().toISOString().split('T')[0],
        dueDate: formData.dueDate,
        notes: formData.notes
      };
      onAddTask(newTask);
      setIsAdding(false);
    }

    resetForm();
  };

  const handleEdit = (task: MedicalTask) => {
    setEditingTask(task);
    setFormData({
      title: task.title,
      description: task.description,
      deviceId: task.deviceId || '',
      department: task.department,
      priority: task.priority,
      dueDate: task.dueDate || '',
      notes: task.notes || ''
    });
  };

  const resetForm = () => {
    setFormData({ 
      title: '', 
      description: '', 
      deviceId: '', 
      department: HOSPITAL_DEPARTMENTS[0], 
      priority: TaskPriority.MEDIUM, 
      dueDate: '', 
      notes: '' 
    });
  };

  const toggleStatus = (task: MedicalTask) => {
    const nextStatus = task.status === TaskStatus.PENDING ? TaskStatus.IN_PROGRESS :
                      task.status === TaskStatus.IN_PROGRESS ? TaskStatus.COMPLETED : 
                      TaskStatus.PENDING;
    onUpdateTask({ ...task, status: nextStatus });
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-slate-100 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-4 flex-1">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-4 h-4" />
            <input 
              type="text"
              placeholder="Search tasks, departments..."
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border-none rounded-xl text-xs font-bold shadow-inner focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <select 
            className="bg-slate-50 border-none px-4 py-3 rounded-xl text-xs font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:bg-slate-100 transition-colors"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
          >
            <option value="ALL">All Status</option>
            {Object.values(TaskStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl hover:bg-blue-700 transition flex items-center gap-2 active:scale-95"
        >
          <Plus className="w-4 h-4" /> New Ticket
        </button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredTasks.map(task => (
          <div key={task.id} className="bg-white rounded-[1.5rem] border border-slate-100 shadow-sm hover:shadow-md transition-all overflow-hidden flex items-stretch group">
            <div className={`w-2 ${getPriorityColor(task.priority)} transition-all group-hover:w-3`} />
            <div className="p-6 flex-1 flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex-1 min-w-0">
                <div className="flex flex-wrap items-center gap-3 mb-2">
                  <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${getPriorityText(task.priority)}`}>{task.priority}</span>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1">
                    <Building className="w-3 h-3" /> {task.department}
                  </span>
                  {task.deviceName && (
                    <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded-md uppercase tracking-tighter flex items-center gap-1 border border-blue-100">
                      <Info className="w-3 h-3" /> Device: {task.deviceName}
                    </span>
                  )}
                  {task.notes && (
                    <span className="text-[8px] font-black text-amber-600 bg-amber-50 px-1.5 py-0.5 rounded uppercase tracking-tighter flex items-center gap-1 border border-amber-100" title="Technical Notes Available">
                      <StickyNote className="w-2.5 h-2.5" /> Notes
                    </span>
                  )}
                </div>
                <h4 className="text-lg font-black text-slate-900 leading-tight truncate">{task.title}</h4>
                <p className="text-sm text-slate-500 mt-1 line-clamp-2 max-w-3xl font-medium">{task.description}</p>
                {task.notes && (
                  <div className="mt-3 p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1">
                      <MessageSquare className="w-3 h-3" /> Technical Follow-up
                    </p>
                    <p className="text-xs text-slate-600 italic leading-relaxed">{task.notes}</p>
                  </div>
                )}
              </div>

              <div className="flex items-center gap-4 shrink-0">
                <div className="text-right hidden xl:block">
                  <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Logged On</p>
                  <p className="text-xs font-bold text-slate-600">{task.createdAt}</p>
                </div>

                <div className="flex items-center gap-2">
                  <button 
                    onClick={() => toggleStatus(task)}
                    className={`px-4 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest border transition-all flex items-center gap-2 shadow-sm active:scale-95 ${getStatusStyles(task.status)}`}
                  >
                    {getStatusIcon(task.status)}
                    {task.status}
                  </button>

                  <div className="flex gap-1 border-l border-slate-100 pl-4 ml-2">
                    <button 
                      onClick={() => handleEdit(task)} 
                      className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      title="Add Data / Edit Task"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => onDeleteTask(task.id)} 
                      className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                      title="Delete Ticket"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
        {filteredTasks.length === 0 && (
          <div className="py-24 text-center bg-white rounded-[3rem] border-4 border-dashed border-slate-50">
            <div className="p-6 bg-slate-50 w-fit rounded-full mx-auto mb-6">
              <CheckSquare className="w-16 h-16 text-slate-200" />
            </div>
            <p className="text-slate-400 font-black uppercase tracking-[0.2em] text-sm">Task queue is currently clear</p>
            <p className="text-xs text-slate-300 mt-2 font-bold uppercase">All clinical requests handled</p>
          </div>
        )}
      </div>

      {(isAdding || editingTask) && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-2xl animate-fade-in overflow-hidden border-4 border-white">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
               <div>
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                    {editingTask ? 'Augment Task Data' : 'Open Service Ticket'}
                  </h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
                    {editingTask ? `Refining ID: ${editingTask.id}` : 'Clinical Engineering Registry'}
                  </p>
               </div>
               <button onClick={() => { setIsAdding(false); setEditingTask(null); }} className="p-3 text-slate-400 hover:bg-white hover:text-slate-900 rounded-2xl transition border border-slate-200 shadow-sm"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[75vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Task Title / Fault Type</label>
                <input required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" value={formData.title} onChange={(e) => setFormData({...formData, title: e.target.value})} placeholder="e.g., Ultrasound probe failure" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Requesting Unit</label>
                  <div className="relative">
                    <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.department} onChange={(e) => setFormData({...formData, department: e.target.value})}>
                      {HOSPITAL_DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                    <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Priority</label>
                  <div className="relative">
                    <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.priority} onChange={(e) => setFormData({...formData, priority: e.target.value as any})}>
                      {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Linked Clinical Asset (Optional)</label>
                <div className="relative">
                  <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.deviceId} onChange={(e) => setFormData({...formData, deviceId: e.target.value})}>
                    <option value="">No device linked</option>
                    {devices.map(d => <option key={d.id} value={d.id}>{d.name} ({d.serialNumber})</option>)}
                  </select>
                  <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Initial Problem Description</label>
                <textarea className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[100px] focus:ring-4 focus:ring-blue-500/10 outline-none transition-all resize-none" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} placeholder="Describe the issue reported by the unit..." />
              </div>

              {/* ADDITIONAL DATA FIELD */}
              <div className="space-y-2 p-6 bg-blue-50/50 rounded-3xl border border-blue-100">
                <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <StickyNote className="w-4 h-4" /> Technical Notes & Follow-up Data
                </label>
                <textarea 
                  className="w-full bg-white border border-blue-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[120px] focus:ring-4 focus:ring-blue-500/10 outline-none transition-all resize-none placeholder:text-blue-300" 
                  value={formData.notes} 
                  onChange={(e) => setFormData({...formData, notes: e.target.value})} 
                  placeholder="Append diagnostic results, parts needed, or technical progress..."
                />
                <p className="text-[9px] text-blue-400 font-bold uppercase tracking-widest text-right mt-1 italic">This data is visible only to the engineering team</p>
              </div>

              <div className="pt-4 flex gap-4">
                <button type="button" onClick={() => { setIsAdding(false); setEditingTask(null); }} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition">Discard</button>
                <button type="submit" className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95 flex items-center justify-center gap-2">
                  <CheckCircle2 className="w-5 h-5" /> {editingTask ? 'Commit Data Updates' : 'Authorize Ticket'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const getPriorityColor = (p: TaskPriority) => {
  switch(p) {
    case TaskPriority.CRITICAL: return 'bg-red-600';
    case TaskPriority.HIGH: return 'bg-orange-500';
    case TaskPriority.MEDIUM: return 'bg-blue-500';
    case TaskPriority.LOW: return 'bg-slate-400';
  }
};

const getPriorityText = (p: TaskPriority) => {
  switch(p) {
    case TaskPriority.CRITICAL: return 'bg-red-50 text-red-600 border border-red-100';
    case TaskPriority.HIGH: return 'bg-orange-50 text-orange-600 border border-orange-100';
    case TaskPriority.MEDIUM: return 'bg-blue-50 text-blue-600 border border-blue-100';
    case TaskPriority.LOW: return 'bg-slate-50 text-slate-600 border border-slate-100';
  }
};

const getStatusStyles = (s: TaskStatus) => {
  switch(s) {
    case TaskStatus.PENDING: return 'border-slate-200 text-slate-400 bg-white hover:border-slate-300';
    case TaskStatus.IN_PROGRESS: return 'border-blue-200 text-blue-600 bg-blue-50/50 hover:bg-blue-50';
    case TaskStatus.COMPLETED: return 'border-green-200 text-green-600 bg-green-50/50 hover:bg-green-50';
  }
};

const getStatusIcon = (s: TaskStatus) => {
  switch(s) {
    case TaskStatus.PENDING: return <Clock className="w-3.5 h-3.5" />;
    case TaskStatus.IN_PROGRESS: return <AlertCircle className="w-3.5 h-3.5 animate-pulse" />;
    case TaskStatus.COMPLETED: return <CheckCircle2 className="w-3.5 h-3.5" />;
  }
};

export default TaskTracker;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint, AlertCircle, ShieldOff, RotateCcw } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onAddDevice, onDelete, searchQuery: externalSearch = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');
  const [localSearch, setLocalSearch] = useState('');

  // Combine external search from App.tsx header and local search in this component
  const effectiveSearch = (localSearch || externalSearch).toLowerCase().trim();

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    warrantyExpiration: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const allAvailableDepartments = useMemo(() => {
    const combined = new Set([...HOSPITAL_DEPARTMENTS, ...uniqueDeptsInData]);
    return Array.from(combined).sort();
  }, [uniqueDeptsInData]);

  const filteredDevices = useMemo(() => {
    return devices.filter(d => {
      const matchSearch = !effectiveSearch || 
        (d.name || '').toLowerCase().includes(effectiveSearch) || 
        (d.serialNumber || '').toLowerCase().includes(effectiveSearch) ||
        (d.model || '').toLowerCase().includes(effectiveSearch) ||
        (d.category || '').toLowerCase().includes(effectiveSearch) ||
        (d.manufacturer || '').toLowerCase().includes(effectiveSearch) ||
        (d.department || '').toLowerCase().includes(effectiveSearch);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, effectiveSearch, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const resetFilters = () => {
    setLocalSearch('');
    setFilterStatus('ALL');
    setFilterDept('ALL');
    setFilterCategory('ALL');
    setFilterCNCAN('ALL');
  };

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      warrantyExpiration: device.warrantyExpiration || '',
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      warrantyExpiration: quickEditForm.warrantyExpiration,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['#', 'ASSET NAME', 'TIP APARAT', 'CNCAN', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'WARRANTY EXP', 'INTERNAL ID'];
    const tableRows = filteredDevices.map((d, idx) => [idx + 1, d.name, d.category, d.isCNCAN ? 'YES' : 'NO', d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.warrantyExpiration || 'N/A', d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | CATEGORY: ${filterCategory.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  const isWarrantyExpired = (date?: string) => {
    if (!date) return false;
    return new Date(date) < new Date();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col gap-6">
        {/* Main Search Row */}
        <div className="flex flex-col lg:flex-row items-center gap-4 w-full">
          <div className="relative flex-1 w-full group">
            <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${effectiveSearch ? 'text-blue-600' : 'text-slate-300'}`} />
            <input 
              type="text"
              placeholder="Search by asset name, serial number, model, manufacturer..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 focus:bg-white rounded-2xl text-sm font-bold focus:outline-none transition-all shadow-inner"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
            {effectiveSearch && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                 <span className="px-2.5 py-1 bg-blue-100 text-blue-600 rounded-lg text-[10px] font-black uppercase tracking-widest">
                   {filteredDevices.length} Results
                 </span>
                 <button onClick={() => setLocalSearch('')} className="p-1.5 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                    <X className="w-4 h-4" />
                 </button>
              </div>
            )}
          </div>
          <div className="flex gap-2 w-full lg:w-auto">
            <button 
              onClick={handleExportExcel} 
              className="flex-1 lg:flex-none px-6 py-4 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl text-[10px] font-black uppercase tracking-widest transition shadow-sm hover:border-blue-200 active:scale-95 flex items-center justify-center gap-2"
            >
              <FileSpreadsheet className="w-5 h-5" /> Export Manifest
            </button>
            <button 
              onClick={resetFilters}
              className="px-4 py-4 bg-slate-50 text-slate-400 rounded-2xl hover:text-blue-600 hover:bg-blue-50 transition-all shadow-inner"
              title="Reset All Filters"
            >
              <RotateCcw className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Filters Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 w-full">
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCNCAN}
              onChange={(e) => setFilterCNCAN(e.target.value as any)}
            >
              <option value="ALL">CNCAN: ALL</option>
              <option value="YES">CNCAN ONLY</option>
              <option value="NO">NON-CNCAN</option>
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterDept}
              onChange={(e) => setFilterDept(e.target.value)}
            >
              <option value="ALL">ALL DEPTS</option>
              {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
            >
              <option value="ALL">ALL CATEGORIES</option>
              {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
            >
              <option value="ALL">ALL STATUSES</option>
              {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center w-12">#</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map((device, index) => {
                const expired = isWarrantyExpired(device.warrantyExpiration);
                return (
                  <tr 
                    key={device.id} 
                    className="hover:bg-blue-50/40 transition-all group"
                  >
                    <td className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase text-center align-middle">
                      {index + 1}
                    </td>
                    <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center relative">
                          {device.image ? <img src={device.image} className="w-full h-full object-cover" alt="Asset" /> : <Box className="w-5 h-5 text-slate-300" />}
                          {device.isCNCAN && (
                            <div className="absolute top-0 right-0 p-0.5 bg-amber-500 rounded-bl-lg shadow-sm" title="CNCAN Regulated">
                              <ShieldAlert className="w-2.5 h-2.5 text-white" />
                            </div>
                          )}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                            {device.isCNCAN && (
                              <span className="px-1.5 py-0.5 bg-amber-100 text-amber-700 text-[8px] font-black rounded border border-amber-200 uppercase tracking-tighter">CNCAN</span>
                            )}
                            {expired && (
                              <span className="p-1 bg-red-100 text-red-600 rounded-full" title="Warranty Expired">
                                <ShieldOff className="w-3 h-3" />
                              </span>
                            )}
                          </div>
                          <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                      <div className="text-xs font-bold text-slate-700 mb-2">{device.category} / {device.model || 'N/A'}</div>
                      <div className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-slate-900 text-blue-400 rounded-md font-mono text-[11px] font-black tracking-tight shadow-sm border border-slate-700 group-hover:bg-blue-600 group-hover:text-white group-hover:border-blue-500 transition-colors">
                        <Fingerprint className="w-3.5 h-3.5 opacity-50" />
                        {device.serialNumber}
                      </div>
                    </td>
                    <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                      <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                    </td>
                    <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                      <StatusBadge status={device.status} />
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          type="button"
                          className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                          onClick={(e) => handleOpenQuickEdit(e, device)}
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          type="button"
                          className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all hover:scale-105 active:scale-90"
                          onClick={(e) => handleDeleteClick(e, device.id)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-8 py-24 text-center">
                    <div className="flex flex-col items-center gap-6">
                       <div className="p-8 bg-slate-50 rounded-full">
                          <Search className="w-16 h-16 text-slate-200" />
                       </div>
                       <div className="space-y-2">
                          <p className="text-slate-900 font-black text-xl uppercase tracking-tight">No Clinical Assets Found</p>
                          <p className="text-slate-400 font-medium text-sm max-w-xs mx-auto">We couldn't find any devices matching "{effectiveSearch}". Try adjusting your filters or checking the spelling.</p>
                       </div>
                       <button onClick={resetFilters} className="px-6 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-black transition-all">Clear All Filters</button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {editingDevice && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90" onClick={() => setEditingDevice(null)}></div>
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-fade-in border-4 border-white overflow-hidden relative z-10">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-100 text-blue-600 rounded-xl"><Edit2 className="w-5 h-5" /></div>
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Quick Edit</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Asset Record Registry</p>
                 </div>
               </div>
               <button type="button" onClick={() => setEditingDevice(null)} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition border border-slate-200"><X className="w-6 h-6" /></button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto max-h-[70vh]">
              <QuickField label="Asset Name" name="name" value={quickEditForm.name} onChange={handleQuickEditChange} />

              <div className="flex items-center gap-4 p-4 bg-amber-50 rounded-2xl border border-amber-200">
                <input 
                  type="checkbox" 
                  id="qe-cncan" 
                  name="isCNCAN" 
                  checked={quickEditForm.isCNCAN} 
                  onChange={handleQuickEditChange}
                  className="w-5 h-5 rounded border-amber-300 text-amber-600 focus:ring-amber-500 cursor-pointer"
                />
                <label htmlFor="qe-cncan" className="flex-1 cursor-pointer">
                  <p className="text-xs font-black text-amber-900 uppercase tracking-tight">CNCAN Regulated</p>
                  <p className="text-[9px] text-amber-600 font-bold uppercase tracking-widest">Radiation safety protocol asset</p>
                </label>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Tip Aparat (Category)</label>
                <div className="relative">
                  <select 
                    name="category" 
                    value={quickEditForm.category} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Manufacturer" name="manufacturer" value={quickEditForm.manufacturer} onChange={handleQuickEditChange} />
                <QuickField label="Model" name="model" value={quickEditForm.model} onChange={handleQuickEditChange} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Serial Number" name="serialNumber" value={quickEditForm.serialNumber} onChange={handleQuickEditChange} />
                <QuickField label="Purchase Date" name="purchaseDate" type="date" value={quickEditForm.purchaseDate} onChange={handleQuickEditChange} />
              </div>

              <QuickField label="Warranty Expiration" name="warrantyExpiration" type="date" value={quickEditForm.warrantyExpiration} onChange={handleQuickEditChange} />

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Department Registry</label>
                <div className="relative">
                   <select 
                     name="department" 
                     value={quickEditForm.department} 
                     onChange={handleQuickEditChange} 
                     className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                   >
                      <optgroup label="Standard Departments">
                        {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      </optgroup>
                      <optgroup label="Your Custom Registry">
                        {uniqueDeptsInData.filter(d => !HOSPITAL_DEPARTMENTS.includes(d as any)).map(dept => (
                          <option key={dept} value={dept}>{dept}</option>
                        ))}
                      </optgroup>
                      <option value="NEW_DEPT">+ ADD NEW DEPARTMENT...</option>
                   </select>
                   <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              {quickEditForm.department === 'NEW_DEPT' && (
                <div className="animate-fade-in bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
                  <div className="flex items-center gap-2 mb-2">
                    <PlusCircle className="w-3 h-3 text-blue-600" />
                    <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest">New Clinical Unit Name</span>
                  </div>
                  <input 
                    name="customDepartment" 
                    type="text"
                    value={quickEditForm.customDepartment} 
                    onChange={handleQuickEditChange} 
                    placeholder="Enter new department name..."
                    className="w-full bg-white border border-blue-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
                  />
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Life Cycle Status</label>
                <div className="relative">
                  <select 
                    name="status" 
                    value={quickEditForm.status} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex gap-4">
              <button type="button" onClick={() => setEditingDevice(null)} className="flex-1 py-4 bg-white text-slate-500 border border-slate-200 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition">Cancel</button>
              <button 
                type="button"
                onClick={handleSaveQuickEdit}
                className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center justify-center gap-2 active:scale-95"
              >
                <Check className="w-5 h-5" /> Update Registry
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const QuickField = ({ label, name, value, onChange, type = "text", placeholder }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      name={name} 
      type={type}
      value={value} 
      onChange={onChange} 
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
    />
  </div>
);

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint, AlertCircle, ShieldOff, RotateCcw } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onAddDevice, onDelete, searchQuery: externalSearch = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');
  const [localSearch, setLocalSearch] = useState('');

  // Combine external search from App.tsx header and local search in this component
  const effectiveSearch = (localSearch || externalSearch).toLowerCase().trim();

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    warrantyExpiration: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const allAvailableDepartments = useMemo(() => {
    const combined = new Set([...HOSPITAL_DEPARTMENTS, ...uniqueDeptsInData]);
    return Array.from(combined).sort();
  }, [uniqueDeptsInData]);

  const filteredDevices = useMemo(() => {
    return devices.filter(d => {
      const matchSearch = !effectiveSearch || 
        (d.name || '').toLowerCase().includes(effectiveSearch) || 
        (d.serialNumber || '').toLowerCase().includes(effectiveSearch) ||
        (d.model || '').toLowerCase().includes(effectiveSearch) ||
        (d.category || '').toLowerCase().includes(effectiveSearch) ||
        (d.manufacturer || '').toLowerCase().includes(effectiveSearch) ||
        (d.department || '').toLowerCase().includes(effectiveSearch);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, effectiveSearch, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const resetFilters = () => {
    setLocalSearch('');
    setFilterStatus('ALL');
    setFilterDept('ALL');
    setFilterCategory('ALL');
    setFilterCNCAN('ALL');
  };

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      warrantyExpiration: device.warrantyExpiration || '',
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      warrantyExpiration: quickEditForm.warrantyExpiration,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['#', 'ASSET NAME', 'TIP APARAT', 'CNCAN', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'WARRANTY EXP', 'INTERNAL ID'];
    const tableRows = filteredDevices.map((d, idx) => [idx + 1, d.name, d.category, d.isCNCAN ? 'YES' : 'NO', d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.warrantyExpiration || 'N/A', d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | CATEGORY: ${filterCategory.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  const isWarrantyExpired = (date?: string) => {
    if (!date) return false;
    return new Date(date) < new Date();
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col gap-6">
        {/* Main Search Row */}
        <div className="flex flex-col lg:flex-row items-center gap-4 w-full">
          <div className="relative flex-1 w-full group">
            <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${effectiveSearch ? 'text-blue-600' : 'text-slate-300'}`} />
            <input 
              type="text"
              placeholder="Search by asset name, serial number, model, manufacturer..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 focus:bg-white rounded-2xl text-sm font-bold focus:outline-none transition-all shadow-inner"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
            {effectiveSearch && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                 <span className="px-2.5 py-1 bg-blue-100 text-blue-600 rounded-lg text-[10px] font-black uppercase tracking-widest">
                   {filteredDevices.length} Results
                 </span>
                 <button onClick={() => setLocalSearch('')} className="p-1.5 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                    <X className="w-4 h-4" />
                 </button>
              </div>
            )}
          </div>
          <div className="flex gap-2 w-full lg:w-auto">
            <button 
              onClick={handleExportExcel} 
              className="flex-1 lg:flex-none px-6 py-4 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl text-[10px] font-black uppercase tracking-widest transition shadow-sm hover:border-blue-200 active:scale-95 flex items-center justify-center gap-2"
            >
              <FileSpreadsheet className="w-5 h-5" /> Export Manifest
            </button>
            <button 
              onClick={resetFilters}
              className="px-4 py-4 bg-slate-50 text-slate-400 rounded-2xl hover:text-blue-600 hover:bg-blue-50 transition-all shadow-inner"
              title="Reset All Filters"
            >
              <RotateCcw className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Filters Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 w-full">
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCNCAN}
              onChange={(e) => setFilterCNCAN(e.target.value as any)}
            >
              <option value="ALL">CNCAN: ALL</option>
              <option value="YES">CNCAN ONLY</option>
              <option value="NO">NON-CNCAN</option>
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterDept}
              onChange={(e) => setFilterDept(e.target.value)}
            >
              <option value="ALL">ALL DEPTS</option>
              {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
            >
              <option value="ALL">ALL CATEGORIES</option>
              {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
            >
              <option value="ALL">ALL STATUSES</option>
              {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center w-12">#</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map((device, index) => {
                const expired = isWarrantyExpired(device.warrantyExpiration);
                return (
                  <tr 
                    key={device.id} 
                    className="hover:bg-blue-50/40 transition-all group"
                  >
                    <td className="px-6 py-6 text-[10px] font-black text-slate-400 uppercase text-center align-middle">
                      {index + 1}
