import React, { useState, useMemo } from 'react';
import { MedicalTask, TaskPriority, TaskStatus, MedicalDevice, HOSPITAL_DEPARTMENTS } from '../types';
import { CheckSquare, Plus, Search, Filter, AlertCircle, Clock, CheckCircle2, MoreHorizontal, Trash2, Edit, X, ArrowRight, User, Info, Building, MessageSquare, StickyNote, Fingerprint } from 'lucide-react';

interface TaskTrackerProps {
  tasks: MedicalTask[];
  devices: MedicalDevice[];
  onAddTask: (task: MedicalTask) => void;
  onUpdateTask: (task: MedicalTask) => void;
  onDeleteTask: (id: string) => void;
}

const TaskTracker: React.FC<TaskTrackerProps> = ({ tasks, devices, onAddTask, onUpdateTask, onDeleteTask }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingTask, setEditingTask] = useState<MedicalTask | null>(null);
  const [filterStatus, setFilterStatus] = useState<TaskStatus | 'ALL'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    deviceId: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    priority: TaskPriority.MEDIUM,
    dueDate: '',
    notes: ''
  });

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchStatus = filterStatus === 'ALL' || t.status === filterStatus;
      const matchSearch = t.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          t.department.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          (t.deviceName && t.deviceName.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchStatus && matchSearch;
    });
  }, [tasks, filterStatus, searchQuery]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const device = devices.find(d => d.id === formData.deviceId);

    if (editingTask) {
      const updatedTask: MedicalTask = {
        ...editingTask,
        title: formData.title,
        description: formData.description,
        deviceId: formData.deviceId || undefined,
        deviceName: device?.name,
        department: formData.department,
        priority: formData.priority,
        dueDate: formData.dueDate,
        notes: formData.notes
      };
      onUpdateTask(updatedTask);
      setEditingTask(null);
    } else {
      const newTask: MedicalTask = {
        id: `TASK-${Date.now()}`,
        title: formData.title,
        description: formData.description,
        deviceId: formData.deviceId || undefined,
        deviceName: device?.name,
        department: formData.department,
        priority: formData.priority,
        status: TaskStatus.PENDING,
        createdAt: new Date().toISOString().split('T')[0],
        dueDate: formData.dueDate,
        notes: formData.notes
      };
      onAddTask(newTask);
      setIsAdding(false);
    }

    resetForm();
  };

  const handleEdit = (task: MedicalTask) => {
    setEditingTask(task);
    setFormData({
      title: task.title,
      description: task.description,
      deviceId: task.deviceId || '',
      department: task.department,
      priority: task.priority,
      dueDate: task.dueDate || '',
      notes: task.notes || ''
    });
  };

  const resetForm = () => {
    setFormData({ 
      title: '', 
      description: '', 
      deviceId: '', 
      department: HOSPITAL_DEPARTMENTS[0], 
      priority: TaskPriority.MEDIUM, 
      dueDate: '', 
      notes: '' 
    });
  };

  const toggleStatus = (task: MedicalTask) => {
    const nextStatus = task.status === TaskStatus.PENDING ? TaskStatus.IN_PROGRESS :
                      task.status === TaskStatus.IN_PROGRESS ? TaskStatus.COMPLETED : 
                      TaskStatus.PENDING;
    onUpdateTask({ ...task, status: nextStatus });
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <div className="bg-white p-6 rounded-[2rem] shadow-lg border border-slate-100 flex flex-col md:flex-row items-center justify-between gap-4">
        <div className="flex items-center gap-4 flex-1">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 w-4 h-4" />
            <input 
              type="text"
              placeholder="Search tasks, departments..."
              className="w-full pl-10 pr-4 py-3 bg-slate-50 border-none rounded-xl text-xs font-bold shadow-inner focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <select 
            className="bg-slate-50 border-none px-4 py-3 rounded-xl text-xs font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:bg-slate-100 transition-colors"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as any)}
          >
            <option value="ALL">All Status</option>
            {Object.values(TaskStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl hover:bg-blue-700 transition flex items-center gap-2 active:scale-95"
        >
          <Plus className="w-4 h-4" /> New Ticket
        </button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {filteredTasks.map(task => {
          const device = devices.find(d => d.id === task.deviceId);
          return (
            <div key={task.id} className="bg-white rounded-[1.5rem] border border-slate-100 shadow-sm hover:shadow-md transition-all overflow-hidden flex items-stretch group">
              <div className={`w-2 ${getPriorityColor(task.priority)} transition-all group-hover:w-3`} />
              <div className="p-6 flex-1 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div className="flex-1 min-w-0">
                  <div className="flex flex-wrap items-center gap-3 mb-2">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${getPriorityText(task.priority)}`}>{task.priority}</span>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1">
                      <Building className="w-3 h-3" /> {task.department}
                    </span>
                    {task.deviceName && (
                      <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2.5 py-1 rounded-md uppercase tracking-tighter flex items-center gap-1.5 border border-blue-100 shadow-sm">
                        <Info className="w-3 h-3 opacity-50" /> {task.deviceName}
                        {device?.serialNumber && (
                          <span className="ml-1 px-1.5 py-0.5 bg-indigo-50 text-indigo-600 rounded font-mono text-[9px] font-black tracking-tight border border-indigo-100">
                            SN: {device.serialNumber}
                          </span>
                        )}
                      </span>
                    )}
                    {task.notes && (
                      <span className="text-[8px] font-black text-amber-600 bg-amber-50 px-1.5 py-0.5 rounded uppercase tracking-tighter flex items-center gap-1 border border-amber-100" title="Technical Notes Available">
                        <StickyNote className="w-2.5 h-2.5" /> Notes
                      </span>
                    )}
                  </div>
                  <h4 className="text-lg font-black text-slate-900 leading-tight truncate">{task.title}</h4>
                  <p className="text-sm text-slate-500 mt-1 line-clamp-2 max-w-3xl font-medium">{task.description}</p>
                  {task.notes && (
                    <div className="mt-3 p-3 bg-slate-50 rounded-xl border border-slate-100">
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1">
                        <MessageSquare className="w-3 h-3" /> Technical Follow-up
                      </p>
                      <p className="text-xs text-slate-600 italic leading-relaxed">{task.notes}</p>
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-4 shrink-0">
                  <div className="text-right hidden xl:block">
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Logged On</p>
                    <p className="text-xs font-bold text-slate-600">{task.createdAt}</p>
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => toggleStatus(task)}
                      className={`px-4 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest border transition-all flex items-center gap-2 shadow-sm active:scale-95 ${getStatusStyles(task.status)}`}
                    >
                      {getStatusIcon(task.status)}
                      {task.status}
                    </button>

                    <div className="flex gap-1 border-l border-slate-100 pl-4 ml-2">
                      <button 
                        onClick={() => handleEdit(task)} 
                        className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                        title="Add Data / Edit Task"
                      >
                        <Edit className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => onDeleteTask(task.id)} 
                        className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                        title="Delete Ticket"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
        {filteredTasks.length === 0 && (
          <div className="py-24 text-center bg-white rounded-[3rem] border-4 border-dashed border-slate-50">
            <div className="p-6 bg-slate-50 w-fit rounded-full mx-auto mb-6">
              <CheckSquare className="w-16 h-16 text-slate-200" />
            </div>
            <p className="text-slate-400 font-black uppercase tracking-[0.2em] text-sm">Task queue is currently clear</p>
            <p className="text-xs text-slate-300 mt-2 font-bold uppercase">All clinical requests handled</p>
          </div>
        )}
      </div>

      {(isAdding || editingTask) && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-2xl animate-fade-in overflow-hidden border-4 border-white">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
               <div>
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">
                    {editingTask ? 'Augment Task Data' : 'Open Service Ticket'}
                  </h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
                    {editingTask ? `Refining ID: ${editingTask.id}` : 'Clinical Engineering Registry'}
                  </p>
               </div>
               <button onClick={() => { setIsAdding(false); setEditingTask(null); }} className="p-3 text-slate-400 hover:bg-white hover:text-slate-900 rounded-2xl transition border border-slate-200 shadow-sm"><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[75vh] overflow-y-auto custom-scrollbar">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Task Title / Fault Type</label>
                <input required className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none transition-all" value={formData.title} onChange={(e) => setFormData({...formData, title: e.target.value})} placeholder="e.g., Ultrasound probe failure" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Requesting Unit</label>
                  <div className="relative">
                    <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.department} onChange={(e) => setFormData({...formData, department: e.target.value})}>
                      {HOSPITAL_DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                    <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Priority</label>
                  <div className="relative">
                    <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.priority} onChange={(e) => setFormData({...formData, priority: e.target.value as any})}>
                      {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Linked Clinical Asset (Optional)</label>
                <div className="relative">
                  <select className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-bold appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 outline-none" value={formData.deviceId} onChange={(e) => setFormData({...formData, deviceId: e.target.value})}>
                    <option value="">No device linked</option>
                    {devices.map(d => <option key={d.id} value={d.id}>{d.name} ({d.serialNumber})</option>)}
                  </select>
                  <ArrowRight className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 rotate-90 pointer-events-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Initial Problem Description</label>
                <textarea className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[100px] focus:ring-4 focus:ring-blue-500/10 outline-none transition-all resize-none" value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} placeholder="Describe the issue reported by the unit..." />
              </div>

              {/* ADDITIONAL DATA FIELD */}
              <div className="space-y-2 p-6 bg-blue-50/50 rounded-3xl border border-blue-100">
                <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <StickyNote className="w-4 h-4" /> Technical Notes & Follow-up Data
                </label>
                <textarea 
                  className="w-full bg-white border border-blue-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[120px] focus:ring-4 focus:ring-blue-500/10 outline-none transition-all resize-none placeholder:text-blue-300" 
                  value={formData.notes} 
                  onChange={(e) => setFormData({...formData, notes: e.target.value})} 
                  placeholder="Append diagnostic results, parts needed, or technical progress..."
                />
                <p className="text-[9px] text-blue-400 font-bold uppercase tracking-widest text-right mt-1 italic">This data is visible only to the engineering team</p>
              </div>

              <div className="pt-4 flex gap-4">
                <button type="button" onClick={() => { setIsAdding(false); setEditingTask(null); }} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition">Discard</button>
                <button type="submit" className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition active:scale-95 flex items-center justify-center gap-2">
                  <CheckCircle2 className="w-5 h-5" /> {editingTask ? 'Commit Data Updates' : 'Authorize Ticket'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const getPriorityColor = (p: TaskPriority) => {
  switch(p) {
    case TaskPriority.CRITICAL: return 'bg-red-600';
    case TaskPriority.HIGH: return 'bg-orange-500';
    case TaskPriority.MEDIUM: return 'bg-blue-500';
    case TaskPriority.LOW: return 'bg-slate-400';
  }
};

const getPriorityText = (p: TaskPriority) => {
  switch(p) {
    case TaskPriority.CRITICAL: return 'bg-red-50 text-red-600 border border-red-100';
    case TaskPriority.HIGH: return 'bg-orange-50 text-orange-600 border border-orange-100';
    case TaskPriority.MEDIUM: return 'bg-blue-50 text-blue-600 border border-blue-100';
    case TaskPriority.LOW: return 'bg-slate-50 text-slate-600 border border-slate-100';
  }
};

const getStatusStyles = (s: TaskStatus) => {
  switch(s) {
    case TaskStatus.PENDING: return 'border-slate-200 text-slate-400 bg-white hover:border-slate-300';
    case TaskStatus.IN_PROGRESS: return 'border-blue-200 text-blue-600 bg-blue-50/50 hover:bg-blue-50';
    case TaskStatus.COMPLETED: return 'border-green-200 text-green-600 bg-green-50/50 hover:bg-green-50';
  }
};

const getStatusIcon = (s: TaskStatus) => {
  switch(s) {
    case TaskStatus.PENDING: return <Clock className="w-3.5 h-3.5" />;
    case TaskStatus.IN_PROGRESS: return <AlertCircle className="w-3.5 h-3.5 animate-pulse" />;
    case TaskStatus.COMPLETED: return <CheckCircle2 className="w-3.5 h-3.5" />;
  }
};

export default TaskTracker;

import React, { useState, useRef, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { X, Save, Wand2, Check, Box, Trash2, FileSpreadsheet, Upload, Camera, Loader2, Layers, Hash, ChevronDown, Activity, Terminal, PlusCircle, ArrowRight, AlertTriangle, Fingerprint, ShieldAlert, History } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

declare var XLSX: any; 

interface AddDeviceFormProps {
  devices: MedicalDevice[];
  onSave: (device: MedicalDevice) => Promise<void>;
  onBulkSave: (devices: MedicalDevice[]) => Promise<void>;
  onCancel: () => void;
}

const COMPRESSION_TARGET = 400 * 1024; 
const AI_BATCH_SIZE = 50; 

interface ProgressState {
  current: number;
  total: number;
  stage: 'READING' | 'MAPPING' | 'PROCESSING' | 'FINALIZING' | 'DEDUPLICATING';
  message: string;
}

interface DuplicateReport {
  existingIds: string[]; // Serial numbers already in the system
  internalDupes: string[]; // Serial numbers repeated in the file
}

const AddDeviceForm: React.FC<AddDeviceFormProps> = ({ devices, onSave, onBulkSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'single' | 'batch' | 'bulk' | 'excel'>('single');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isCompressing, setIsCompressing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [progress, setProgress] = useState<ProgressState | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [previewDevices, setPreviewDevices] = useState<MedicalDevice[]>([]);
  const [duplicateReport, setDuplicateReport] = useState<DuplicateReport | null>(null);
  const excelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '',
    category: DEVICE_CATEGORIES[0] as string,
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: HOSPITAL_DEPARTMENTS[0] as string,
    customDepartment: '',
    purchaseDate: new Date().toISOString().split('T')[0],
    status: DeviceStatus.ACTIVE,
    isCNCAN: false,
    notes: '',
    image: ''
  });

  const [batchData, setBatchData] = useState({
    quantity: 1,
    serialPrefix: 'SN-',
    startNum: 100,
  });

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setFormData(prev => ({ ...prev, [name]: val }));
  };

  const handleBatchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBatchData(prev => ({ ...prev, [name]: name === 'serialPrefix' ? value : parseInt(value) || 0 }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; 
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas context missing"));
          ctx.drawImage(img, 0, 0, width, height);
          let quality = 0.6;
          let dataUrl = canvas.toDataURL('image/jpeg', quality);
          while (dataUrl.length > COMPRESSION_TARGET && quality > 0.1) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL('image/jpeg', quality);
          }
          resolve(dataUrl);
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsCompressing(true);
      try {
        const compressed = await compressImage(file);
        setFormData(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        alert("Image optimization failed.");
      } finally {
        setIsCompressing(false);
      }
    }
  };

  const analyzeDuplicates = (incoming: MedicalDevice[]) => {
    const existingSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
    const incomingSerials = new Map<string, number>();

    const existingIds: string[] = [];
    const internalDupes: string[] = [];

    incoming.forEach(d => {
      const sn = d.serialNumber.toLowerCase();
      if (existingSerials.has(sn)) {
        existingIds.push(d.serialNumber);
      }
      incomingSerials.set(sn, (incomingSerials.get(sn) || 0) + 1);
    });

    incomingSerials.forEach((count, sn) => {
      if (count > 1) internalDupes.push(sn.toUpperCase());
    });

    if (existingIds.length > 0 || internalDupes.length > 0) {
      setDuplicateReport({ existingIds, internalDupes });
    } else {
      setDuplicateReport(null);
    }
  };

  const handlePurgeDuplicates = () => {
    if (!duplicateReport) return;

    const seenSerials = new Set<string>();
    const existingSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));

    const purged = previewDevices.filter(d => {
      const sn = d.serialNumber.toLowerCase();
      if (existingSerials.has(sn)) return false;
      if (seenSerials.has(sn)) return false;
      seenSerials.add(sn);
      return true;
    });

    setPreviewDevices(purged);
    setDuplicateReport(null);
  };

  const handleSingleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;

    // Ensure all required properties of MedicalDevice are present
    const newDevice: MedicalDevice = {
      id: '', 
      name: formData.name,
      category: formData.category,
      manufacturer: formData.manufacturer,
      model: formData.model,
      serialNumber: formData.serialNumber,
      department: finalDept,
      purchaseDate: formData.purchaseDate,
      status: formData.status as DeviceStatus,
      isCNCAN: formData.isCNCAN,
      notes: formData.notes,
      image: formData.image,
      maintenanceHistory: [],
      contracts: [],
      files: [],
      components: []
    };

    try {
      await onSave(newDevice);
    } catch (err) {
      console.warn("Manual registration attempt failed.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleGenerateBatch = (e: React.FormEvent) => {
    e.preventDefault();
    const batch: MedicalDevice[] = [];
    const finalDept = formData.department === 'NEW_DEPT' ? (formData.customDepartment || 'Unassigned') : formData.department;
    for (let i = 0; i < batchData.quantity; i++) {
      batch.push({
        id: `DEV-B-${Date.now()}-${i}`,
        name: formData.name,
        category: formData.category,
        manufacturer: formData.manufacturer,
        model: formData.model,
        serialNumber: `${batchData.serialPrefix}${batchData.startNum + i}`,
        department: finalDept,
        purchaseDate: formData.purchaseDate,
        status: formData.status as DeviceStatus,
        isCNCAN: formData.isCNCAN,
        notes: formData.notes,
        image: formData.image,
        maintenanceHistory: [],
        contracts: [],
        files: [],
        components: []
      });
    }
    analyzeDuplicates(batch);
    setPreviewDevices(batch);
  };

  const handleDeployAssets = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onBulkSave(previewDevices);
    } catch (err) {} finally {
      setIsSubmitting(false);
    }
  };

  const processDataChunks = async (allRows: any[]) => {
    setIsProcessing(true);
    setPreviewDevices([]);
    const totalRows = allRows.length;
    const allParsed: MedicalDevice[] = [];
    // Correctly initialize GoogleGenAI with named parameter apiKey from process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    setProgress({
      current: 0,
      total: totalRows,
      stage: 'PROCESSING',
      message: `Analyzing manifest with ${totalRows} entries...`
    });

    for (let i = 0; i < totalRows; i += AI_BATCH_SIZE) {
      const chunk = allRows.slice(i, i + AI_BATCH_SIZE);
      setProgress(prev => ({ ...prev!, current: i, message: `Synthesizing batch ${Math.floor(i / AI_BATCH_SIZE) + 1}...` }));

      try {
        const response = await ai.models.generateContent({
          model: "gemini-3-flash-preview",
          contents: `Analyze and map this clinical data to a structured device schema: ${JSON.stringify(chunk)}`,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  category: { type: Type.STRING },
                  manufacturer: { type: Type.STRING },
                  model: { type: Type.STRING },
                  serialNumber: { type: Type.STRING },
                  department: { type: Type.STRING },
                  purchaseDate: { type: Type.STRING },
                  status: { type: Type.STRING },
                  isCNCAN: { type: Type.BOOLEAN }
                },
                required: ["name", "serialNumber"]
              }
            }
          }
        });

        const parsed: any[] = JSON.parse(response.text || "[]");
        const transformed = parsed.map(item => ({
          ...item,
          id: `DEV-A-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          isCNCAN: !!item.isCNCAN,
          category: item.category || DEVICE_CATEGORIES[0],
          maintenanceHistory: [],
          contracts: [],
          files: [],
          components: [],
          status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
        }));
        allParsed.push(...transformed);
      } catch (error) { console.error("Batch processing error:", error); }
    }

    analyzeDuplicates(allParsed);
    setPreviewDevices(allParsed);
    setIsProcessing(false);
    setTimeout(() => setProgress(null), 1000);
  };

  const handleBulkTextProcess = async () => {
    if (!bulkText) return;
    setIsProcessing(true);
    setPreviewDevices([]);
    // Correctly initialize GoogleGenAI with named parameter apiKey from process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    setProgress({
      current: 0,
      total: 1,
      stage: 'PROCESSING',
      message: 'Analyzing raw data with AI...'
    });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analyze the following text and extract all clinical assets. Return a JSON array of objects with these fields: name, category, manufacturer, model, serialNumber, department, purchaseDate (YYYY-MM-DD), status (Active, In Maintenance, Broken, Retired), isCNCAN (boolean).

        Text to analyze:
        ${bulkText}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                category: { type: Type.STRING },
                manufacturer: { type: Type.STRING },
                model: { type: Type.STRING },
                serialNumber: { type: Type.STRING },
                department: { type: Type.STRING },
                purchaseDate: { type: Type.STRING },
                status: { type: Type.STRING },
                isCNCAN: { type: Type.BOOLEAN }
              },
              required: ["name", "serialNumber"]
            }
          }
        }
      });

      const parsed: any[] = JSON.parse(response.text || "[]");
      const transformed = parsed.map(item => ({
        ...item,
        id: `DEV-AI-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
        isCNCAN: !!item.isCNCAN,
        category: item.category || DEVICE_CATEGORIES[0],
        maintenanceHistory: [],
        contracts: [],
        files: [],
        components: [],
        status: (Object.values(DeviceStatus).includes(item.status as DeviceStatus) ? item.status : DeviceStatus.ACTIVE) as DeviceStatus
      }));

      analyzeDuplicates(transformed);
      setPreviewDevices(transformed);
    } catch (error) {
      console.error("Smart extract error:", error);
      alert("AI extraction failed. Please check the text format.");
    } finally {
      setIsProcessing(false);
      setProgress(null);
    }
  };

  const handleExcelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const wb = XLSX.read(evt.target?.result, { type: 'binary' });
        const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);
        await processDataChunks(data);
      } catch (err) { setIsProcessing(false); }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden max-w-5xl mx-auto animate-fade-in mb-20 relative">
      {(isProcessing || isSubmitting) && (
        <div className="absolute inset-0 bg-slate-900/95 z-[200] flex flex-col items-center justify-center p-8 animate-fade-in">
          <div className="w-full max-w-md space-y-8">
            <div className="flex flex-col items-center text-center">
              <div className="p-5 bg-blue-600 rounded-3xl shadow-2xl shadow-blue-500/20 mb-6 animate-pulse">
                {isSubmitting ? <Save className="w-10 h-10 text-white" /> : <Activity className="w-10 h-10 text-white" />}
              </div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tight">{isSubmitting ? 'Syncing Global Cloud' : 'Clinical Sync'}</h3>
            </div>
            {progress && (
              <div className="space-y-4">
                <div className="h-4 w-full bg-white/5 rounded-full overflow-hidden border border-white/10 p-0.5">
                  <div className="h-full bg-gradient-to-r from-blue-600 to-indigo-500 rounded-full transition-all duration-500 ease-out" style={{ width: `${(progress.current / progress.total) * 100}%` }}></div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {duplicateReport && (
        <div className="absolute inset-0 bg-slate-900/95 z-[210] flex flex-col items-center justify-center p-8 animate-fade-in overflow-y-auto">
          <div className="w-full max-w-2xl bg-white rounded-[2.5rem] p-10 shadow-2xl">
            <div className="flex items-center gap-6 mb-8">
              <div className="p-4 bg-amber-100 text-amber-600 rounded-2xl">
                <ShieldAlert className="w-10 h-10" />
              </div>
              <div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Redundancy Detected</h3>
              </div>
            </div>
            <div className="flex flex-col sm:flex-row gap-4">
              <button onClick={handlePurgeDuplicates} className="flex-1 py-5 bg-amber-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-3">
                <Trash2 className="w-4 h-4" /> Purge Redundancies
              </button>
              <button onClick={() => setDuplicateReport(null)} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black uppercase tracking-widest">
                Keep & Override
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
        <div>
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Clinical Asset Intake</h2>
          <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Register individual or mass fleet items</p>
        </div>
        <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition shadow-sm"><X className="w-6 h-6" /></button>
      </div>

      <div className="flex border-b border-slate-100 bg-white overflow-x-auto no-scrollbar">
        <TabButton active={activeTab === 'single'} onClick={() => setActiveTab('single')} label="Manual Record" icon={<Box className="w-4 h-4" />} />
        <TabButton active={activeTab === 'batch'} onClick={() => setActiveTab('batch')} label="Batch Generator" icon={<Layers className="w-4 h-4" />} />
        <TabButton active={activeTab === 'bulk'} onClick={() => setActiveTab('bulk')} label="AI Smart Extract" icon={<Wand2 className="w-4 h-4" />} />
        <TabButton active={activeTab === 'excel'} onClick={() => setActiveTab('excel')} label="Fleet Spreadsheet" icon={<FileSpreadsheet className="w-4 h-4" />} />
      </div>

      <div className="p-10">
        {previewDevices.length > 0 ? (
          <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center bg-blue-50 p-8 rounded-[2.5rem] border border-blue-100">
               <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-blue-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-blue-200">
                    {previewDevices.length}
                  </div>
                  <div>
                    <h3 className="font-black text-blue-900 uppercase tracking-tight text-lg">Verify Global Deployment</h3>
                  </div>
               </div>
               <button onClick={() => { setPreviewDevices([]); setDuplicateReport(null); }} className="px-6 py-3 bg-white text-blue-600 border border-blue-100 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-blue-100 transition">Cancel</button>
             </div>

             <div className="max-h-[400px] overflow-y-auto rounded-3xl border border-slate-100 divide-y divide-slate-50 shadow-inner bg-slate-50/50 p-4">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {previewDevices.map((d, i) => (
                   <div key={i} className="p-5 bg-white border border-slate-100 rounded-2xl flex items-center justify-between hover:border-blue-300 transition-all shadow-sm">
                     <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center relative">
                         <Box className="w-5 h-5 text-slate-300" />
                         {d.isCNCAN && <div className="absolute -top-1 -right-1 p-0.5 bg-amber-500 rounded-full"><ShieldAlert className="w-2 h-2 text-white" /></div>}
                       </div>
                       <div>
                         <p className="font-bold text-slate-900 text-xs truncate max-w-[150px]">{d.name}</p>
                         <div className="flex items-center gap-1.5 mt-0.5">
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{d.category}</span>
                            <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                            {/* EYE FRIENDLY SERIAL BADGE IN PREVIEW */}
                            <span className="px-1.5 py-0.5 bg-indigo-50 text-indigo-700 rounded font-mono text-[9px] font-bold border border-indigo-100">
                              {d.serialNumber}
                            </span>
                         </div>
                       </div>
                     </div>
                     <div className="text-[9px] font-black text-slate-400 uppercase tracking-tighter bg-slate-50 px-2.5 py-1 rounded-md">{d.department}</div>
                   </div>
                 ))}
               </div>
             </div>
             <button onClick={handleDeployAssets} className="w-full py-6 bg-blue-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-blue-700 transition active:scale-95 text-sm flex items-center justify-center gap-3">
               Commit to Global Registry <ArrowRight className="w-5 h-5" />
             </button>
          </div>
        ) : (
          <>
            {(activeTab === 'single' || activeTab === 'batch') && (
              <form onSubmit={activeTab === 'single' ? handleSingleSubmit : handleGenerateBatch} className="space-y-10">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                  <div className="lg:col-span-4 space-y-4">
                     <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Master Reference Visual</label>
                     <div onClick={() => imageInputRef.current?.click()} className="aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all overflow-hidden group relative">
                       {formData.image ? <img src={formData.image} alt="Preview" className="w-full h-full object-contain" /> : <><Camera className="w-12 h-12 text-slate-300 group-hover:scale-110 transition-transform mb-2" /><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center px-4">Attach Visual ID Record</p></>}
                       <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageChange} />
                     </div>
                  </div>

                  <div className="lg:col-span-8 space-y-8">
                    <div className="flex items-center gap-4 p-6 bg-amber-50 rounded-3xl border border-amber-200 shadow-sm">
                      <input 
                        type="checkbox" 
                        id="form-cncan" 
                        name="isCNCAN" 
                        checked={formData.isCNCAN} 
                        onChange={handleChange}
                        className="w-6 h-6 rounded border-amber-300 text-amber-600 focus:ring-amber-500 cursor-pointer"
                      />
                      <label htmlFor="form-cncan" className="flex-1 cursor-pointer">
                        <p className="text-sm font-black text-amber-900 uppercase tracking-tight">CNCAN Regulated Asset</p>
                        <p className="text-[10px] text-amber-600 font-bold uppercase tracking-widest mt-0.5">Device contains radioactive sources or generates ionizing radiation</p>
                      </label>
                      <ShieldAlert className="w-8 h-8 text-amber-500 opacity-30" />
                    </div>

                    {activeTab === 'batch' && (
                       <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                         <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none"><Hash className="w-32 h-32 text-blue-400" /></div>
                         <h3 className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest mb-6 text-blue-400"><Layers className="w-4 h-4" /> Batch Generator Configuration</h3>
                         <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 relative z-10">
                            <div><label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Quantity</label><input name="quantity" type="number" min="1" max="500" value={batchData.quantity} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" /></div>
                            <div><label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Serial Prefix</label><input name="serialPrefix" type="text" value={batchData.serialPrefix} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" /></div>
                            <div><label className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 block">Start #</label><input name="startNum" type="number" value={batchData.startNum} onChange={handleBatchChange} className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold focus:bg-white/10 outline-none" /></div>
                         </div>
                       </div>
                    )}

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <FormField label="Asset Name" name="name" value={formData.name} onChange={handleChange} placeholder="e.g. X-Ray Machine" required />
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tip Aparat (Category)</label>
                        <div className="relative">
                          <select name="category" value={formData.category} onChange={handleChange} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none appearance-none cursor-pointer">
                            {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                          </select>
                          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                        </div>
                      </div>
                      <FormField label="Manufacturer" name="manufacturer" value={formData.manufacturer} onChange={handleChange} placeholder="e.g. Siemens" required />
                      <FormField label="Model" name="model" value={formData.model} onChange={handleChange} placeholder="Axiom Series" required />
                      {activeTab === 'single' && <FormField label="Unique Serial Number" name="serialNumber" value={formData.serialNumber} onChange={handleChange} placeholder="SN-882910" required />}
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Department Registry</label>
                        <div className="relative">
                          <select name="department" value={formData.department} onChange={handleChange} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-blue-500/10 outline-none appearance-none cursor-pointer">
                            <optgroup label="Hospitals Units">{HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}</optgroup>
                            <optgroup label="Custom Registry">{uniqueDeptsInData.filter(d => !HOSPITAL_DEPARTMENTS.includes(d as any)).map(dept => <option key={dept} value={dept}>{dept}</option>)}</optgroup>
                            <option value="NEW_DEPT">+ ADD NEW DEPARTMENT...</option>
                          </select>
                          <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                        </div>
                      </div>
                      <FormField label="Acquisition Date" name="purchaseDate" type="date" value={formData.purchaseDate} onChange={handleChange} required />
                    </div>
                  </div>
                </div>

                <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
                  <button type="button" onClick={onCancel} className="px-8 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Discard</button>
                  <button type="submit" className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center gap-2 active:scale-95">
                    {activeTab === 'single' ? <><Save className="w-4 h-4" /> Register & Global Sync</> : <><Layers className="w-4 h-4" /> Generate Staging Preview</>}
                  </button>
                </div>
              </form>
            )}

            {activeTab === 'bulk' && (
              <div className="space-y-6">
                <div className="bg-indigo-50 p-8 rounded-[2.5rem] border border-indigo-100 flex gap-6 items-center">
                  <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-lg"><Wand2 className="w-8 h-8" /></div>
                  <div><h3 className="text-lg font-black text-indigo-900 uppercase tracking-tight">AI Smart Extraction</h3></div>
                </div>
                <textarea className="w-full h-80 p-8 bg-slate-50 border border-slate-200 rounded-[2.5rem] focus:ring-8 focus:ring-indigo-500/5 outline-none font-mono text-xs" placeholder="Paste raw data here..." value={bulkText} onChange={(e) => setBulkText(e.target.value)} />
                <button onClick={handleBulkTextProcess} disabled={isProcessing || !bulkText} className="w-full py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl hover:bg-indigo-700 transition disabled:opacity-50 text-sm">Analyze & Staging Record</button>
              </div>
            )}

            {activeTab === 'excel' && (
              <div className="flex flex-col items-center justify-center py-24 border-4 border-dashed border-slate-100 rounded-[3rem] text-center bg-slate-50/50 group hover:border-blue-200 transition-all">
                 <div className="p-10 bg-white rounded-full shadow-2xl mb-8 group-hover:scale-110 transition-transform"><FileSpreadsheet className="w-16 h-16 text-blue-500" /></div>
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-2">Spreadsheet Ingestion</h3>
                 <input type="file" ref={excelInputRef} accept=".xlsx,.xls,.csv" onChange={handleExcelUpload} className="hidden" />
                 <button onClick={() => excelInputRef.current?.click()} className="px-14 py-6 bg-slate-900 text-white rounded-3xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl hover:bg-black transition flex items-center gap-4"><Upload className="w-5 h-5" /> Select Local File</button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

