import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, List, PlusCircle, Settings as SettingsIcon, Stethoscope, Menu, X, QrCode, Cloud, CloudOff, CalendarRange, Camera, Info, ShieldAlert, ArrowRight, WifiOff, RefreshCw, ShieldCheck, Database, Loader2, Search, Zap, AlertCircle, Terminal, Copy, CheckSquare } from 'lucide-react';
