                       className="bg-white/5 border border-white/10 text-white rounded-2xl pl-10 pr-10 py-3 text-[10px] font-black uppercase tracking-widest appearance-none cursor-pointer outline-none focus:ring-2 focus:ring-blue-500/50 transition-all min-w-[240px] disabled:opacity-50"
                       value={bulkCategory}
                       onChange={(e) => setBulkCategory(e.target.value as DeviceCategory)}
                    >
                       <option value="">REASSIGN CATEGORY...</option>
                       {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat} className="text-slate-900">{cat}</option>)}
