                    <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                 </div>

                 <button 
                   onClick={handleBulkCategorize}
                   disabled={!bulkCategory || isProcessingBulk}
                   className="px-6 py-3 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-blue-700 transition active:scale-95 disabled:opacity-30 disabled:pointer-events-none flex items-center gap-2"
                 >
                    {isProcessingBulk ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                    {isProcessingBulk ? 'Processing...' : 'Apply Category'}
                 </button>

                 <div className="w-px h-10 bg-white/10 mx-2" />

                 <button 
                   onClick={() => !isProcessingBulk && setSelectedIds(new Set())}
                   disabled={isProcessingBulk}
                   className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition disabled:opacity-0"
                 >
                    <X className="w-6 h-6" />
                 </button>
              </div>
           </div>
        </div>
      )}

      {editingDevice && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/90" onClick={() => setEditingDevice(null)}></div>
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-lg animate-fade-in border-4 border-white overflow-hidden relative z-10">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
               <div className="flex items-center gap-3">
                 <div className="p-2 bg-blue-100 text-blue-600 rounded-xl"><Edit2 className="w-5 h-5" /></div>
                 <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Quick Edit</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Asset Record Registry</p>
                 </div>
               </div>
               <button type="button" onClick={() => setEditingDevice(null)} className="p-2 text-slate-400 hover:bg-white hover:text-slate-900 rounded-xl transition border border-slate-200"><X className="w-6 h-6" /></button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto max-h-[70vh]">
              <QuickField label="Asset Name" name="name" value={quickEditForm.name} onChange={handleQuickEditChange} />

              <div className="flex items-center gap-4 p-4 bg-amber-50 rounded-2xl border border-amber-200">
                <input 
                  type="checkbox" 
                  id="qe-cncan" 
                  name="isCNCAN" 
                  checked={quickEditForm.isCNCAN} 
                  onChange={handleQuickEditChange}
                  className="w-5 h-5 rounded border-amber-300 text-amber-600 focus:ring-amber-500 cursor-pointer"
                />
                <label htmlFor="qe-cncan" className="flex-1 cursor-pointer">
                  <p className="text-xs font-black text-amber-900 uppercase tracking-tight">CNCAN Regulated</p>
                  <p className="text-[9px] text-amber-600 font-bold uppercase tracking-widest">Radiation safety protocol asset</p>
                </label>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Tip Aparat (Category)</label>
                <div className="relative">
                  <select 
                    name="category" 
                    value={quickEditForm.category} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Manufacturer" name="manufacturer" value={quickEditForm.manufacturer} onChange={handleQuickEditChange} />
                <QuickField label="Model" name="model" value={quickEditForm.model} onChange={handleQuickEditChange} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <QuickField label="Serial Number" name="serialNumber" value={quickEditForm.serialNumber} onChange={handleQuickEditChange} />
                <QuickField label="Purchase Date" name="purchaseDate" type="date" value={quickEditForm.purchaseDate} onChange={handleQuickEditChange} />
              </div>

              <QuickField label="Warranty Expiration" name="warrantyExpiration" type="date" value={quickEditForm.warrantyExpiration} onChange={handleQuickEditChange} />

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Department Registry</label>
                <div className="relative">
                   <select 
                     name="department" 
                     value={quickEditForm.department} 
                     onChange={handleQuickEditChange} 
                     className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                   >
                      <optgroup label="Standard Departments">
                        {HOSPITAL_DEPARTMENTS.map(dept => <option key={dept} value={dept}>{dept}</option>)}
                      </optgroup>
                      <optgroup label="Your Custom Registry">
                        {uniqueDeptsInData.filter(d => !HOSPITAL_DEPARTMENTS.includes(d as any)).map(dept => (
                          <option key={dept} value={dept}>{dept}</option>
                        ))}
                      </optgroup>
                      <option value="NEW_DEPT">+ ADD NEW DEPARTMENT...</option>
                   </select>
                   <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              {quickEditForm.department === 'NEW_DEPT' && (
                <div className="animate-fade-in bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
                  <div className="flex items-center gap-2 mb-2">
                    <PlusCircle className="w-3 h-3 text-blue-600" />
                    <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest">New Clinical Unit Name</span>
                  </div>
                  <input 
                    name="customDepartment" 
                    type="text"
                    value={quickEditForm.customDepartment} 
                    onChange={handleQuickEditChange} 
                    placeholder="Enter new department name..."
                    className="w-full bg-white border border-blue-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
                  />
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Life Cycle Status</label>
                <div className="relative">
                  <select 
                    name="status" 
                    value={quickEditForm.status} 
                    onChange={handleQuickEditChange} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer focus:ring-4 focus:ring-blue-500/10 transition-all"
                  >
                    {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t border-slate-100 flex gap-4">
              <button type="button" onClick={() => setEditingDevice(null)} className="flex-1 py-4 bg-white text-slate-500 border border-slate-200 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition">Cancel</button>
              <button 
                type="button"
                onClick={handleSaveQuickEdit}
                className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition flex items-center justify-center gap-2 active:scale-95"
              >
                <Check className="w-5 h-5" /> Update Registry
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const QuickField = ({ label, name, value, onChange, type = "text", placeholder }: any) => (
  <div className="space-y-1">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      name={name} 
      type={type}
      value={value} 
      onChange={onChange} 
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-blue-500/10 transition-all" 
    />
  </div>
);

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-100 text-slate-700 border-slate-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES, DeviceCategory } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint, AlertCircle, ShieldOff, RotateCcw, Layers, Loader2, FileText } from 'lucide-react';

declare var XLSX: any; // Global from index.html

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onBulkUpdate: (devices: MedicalDevice[]) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onBulkUpdate, onAddDevice, onDelete, searchQuery: externalSearch = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');
  const [localSearch, setLocalSearch] = useState('');

  // Selection & Action State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkCategory, setBulkCategory] = useState<DeviceCategory | ''>('');
  const [isProcessingBulk, setIsProcessingBulk] = useState(false);

  // Combine external search from App.tsx header and local search in this component
  const effectiveSearch = (localSearch || externalSearch).toLowerCase().trim();

  // Quick Edit State
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    warrantyExpiration: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const filteredDevices = useMemo(() => {
    return devices.filter(d => {
      const matchSearch = !effectiveSearch || 
        (d.name || '').toLowerCase().includes(effectiveSearch) || 
        (d.serialNumber || '').toLowerCase().includes(effectiveSearch) ||
        (d.model || '').toLowerCase().includes(effectiveSearch) ||
        (d.category || '').toLowerCase().includes(effectiveSearch) ||
        (d.manufacturer || '').toLowerCase().includes(effectiveSearch) ||
        (d.department || '').toLowerCase().includes(effectiveSearch);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, effectiveSearch, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const toggleAllSelection = () => {
    if (selectedIds.size === filteredDevices.length && filteredDevices.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredDevices.map(d => d.id)));
    }
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleBulkCategorize = async () => {
    if (!bulkCategory || selectedIds.size === 0) return;

    setIsProcessingBulk(true);
    try {
      const devicesToUpdate = devices
        .filter(d => selectedIds.has(d.id))
        .map(d => ({ ...d, category: bulkCategory }));

      await onBulkUpdate(devicesToUpdate);

      setSelectedIds(new Set());
      setBulkCategory('');
    } catch (err) {
      console.error("Bulk categorization failed");
    } finally {
      setIsProcessingBulk(false);
    }
  };

  const handleGenerateSelectedReport = () => {
    if (selectedIds.size === 0) return;

    const selectedDevices = devices.filter(d => selectedIds.has(d.id));
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const reportId = `AUDIT-${Math.floor(1000 + Math.random() * 9000)}`;

    const tableHeader = [
      '#', 
      'CLINICAL ASSET NAME', 
      'SERIAL NUMBER', 
      'TIP APARAT (CATEGORY)', 
      'MANUFACTURER', 
      'MODEL / VERSION', 
      'DEPARTMENT / UNIT', 
      'LIFECYCLE STATUS', 
      'CNCAN REGULATED'
    ];

    const tableRows = selectedDevices.map((d, idx) => [
      idx + 1,
      d.name.toUpperCase(),
      d.serialNumber,
      d.category.toUpperCase(),
      d.manufacturer,
      d.model || 'N/A',
      d.department,
      d.status.toUpperCase(),
      d.isCNCAN ? 'YES' : 'NO'
    ]);

    const aoa = [
      ['MEDITRACK | SELECTIVE ASSET AUDIT REPORT'],
      [`REPORT IDENTIFIER: ${reportId}`],
      [`GENERATION TIMESTAMP: ${dateStr} ${now.toLocaleTimeString()}`],
      [`SELECTED POPULATION: ${selectedDevices.length} ASSETS`],
      ['----------------------------------------------------------------------------------------------------------------------'],
      [],
      tableHeader,
      ...tableRows,
      [],
      ['--- END OF SELECTIVE AUDIT RECORD ---'],
      ['Proprietary Hospital Device Registry Management Data']
    ];

    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();

      // Auto-size columns
      const colWidths = tableHeader.map((h, i) => {
        let maxLen = h.length;
        tableRows.forEach(row => {
          const val = row[i] ? String(row[i]).length : 0;
          if (val > maxLen) maxLen = val;
        });
        return { wch: Math.min(Math.max(maxLen + 4, 15), 50) };
      });
      worksheet['!cols'] = colWidths;

      XLSX.utils.book_append_sheet(workbook, worksheet, "Selected Assets");
      XLSX.writeFile(workbook, `MediTrack_Selection_Audit_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) {
      alert("Spreadsheet synthesis failed.");
    }
  };

  const uniqueDeptsInData = useMemo(() => {
    const set = new Set<string>();
    devices.forEach(d => {
      if (d.department) set.add(d.department);
    });
    return Array.from(set).sort();
  }, [devices]);

  const allAvailableDepartments = useMemo(() => {
    const combined = new Set([...HOSPITAL_DEPARTMENTS, ...uniqueDeptsInData]);
    return Array.from(combined).sort();
  }, [uniqueDeptsInData]);

  const resetFilters = () => {
    setLocalSearch('');
    setFilterStatus('ALL');
    setFilterDept('ALL');
    setFilterCategory('ALL');
    setFilterCNCAN('ALL');
    setSelectedIds(new Set());
  };

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      warrantyExpiration: device.warrantyExpiration || '',
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = async () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      warrantyExpiration: quickEditForm.warrantyExpiration,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    await onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if(window.confirm('Confirm permanent removal of this clinical asset?')) {
      onDelete(deviceId);
    }
  };

  const handleExportExcel = () => {
    if (filteredDevices.length === 0) return alert("No devices to export in current view.");
    const now = new Date();
    const dateStr = now.toLocaleDateString();
    const tableHeader = ['#', 'ASSET NAME', 'TIP APARAT', 'CNCAN', 'MANUFACTURER', 'MODEL', 'SERIAL NUMBER', 'DEPARTMENT', 'CURRENT STATUS', 'PURCHASE DATE', 'WARRANTY EXP', 'INTERNAL ID'];
    const tableRows = filteredDevices.map((d, idx) => [idx + 1, d.name, d.category, d.isCNCAN ? 'YES' : 'NO', d.manufacturer, d.model, d.serialNumber, d.department, d.status.toUpperCase(), d.purchaseDate, d.warrantyExpiration || 'N/A', d.id]);
    const aoa = [['MEDITRACK | CLINICAL INVENTORY MASTER MANIFEST'], [`REPORT DATE: ${dateStr}`], [`DEPT FILTER: ${filterDept.toUpperCase()} | CATEGORY: ${filterCategory.toUpperCase()}`], ['----------------------------------------------------------------------------------------------------------------------'], [], tableHeader, ...tableRows];
    try {
      const worksheet = XLSX.utils.aoa_to_sheet(aoa);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Clinical Assets");
      XLSX.writeFile(workbook, `MediTrack_Inventory_${now.toISOString().split('T')[0]}.xlsx`);
    } catch (err) { alert("Spreadsheet generation failed."); }
  };

  const isWarrantyExpired = (date?: string) => {
    if (!date) return false;
    return new Date(date) < new Date();
  };

  return (
    <div className="space-y-6 pb-24 relative">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col gap-6">
        {/* Main Search Row */}
        <div className="flex flex-col lg:flex-row items-center gap-4 w-full">
          <div className="relative flex-1 w-full group">
            <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${effectiveSearch ? 'text-blue-600' : 'text-slate-300'}`} />
            <input 
              type="text"
              placeholder="Search by asset name, serial number, model, manufacturer..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 focus:bg-white rounded-2xl text-sm font-bold focus:outline-none transition-all shadow-inner"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
            {effectiveSearch && (
              <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                 <span className="px-2.5 py-1 bg-blue-100 text-blue-600 rounded-lg text-[10px] font-black uppercase tracking-widest">
                   {filteredDevices.length} Results
                 </span>
                 <button onClick={() => setLocalSearch('')} className="p-1.5 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
                    <X className="w-4 h-4" />
                 </button>
              </div>
            )}
          </div>
          <div className="flex gap-2 w-full lg:w-auto">
            <button 
              onClick={handleExportExcel} 
              className="flex-1 lg:flex-none px-6 py-4 bg-white border-2 border-slate-100 text-slate-600 rounded-2xl text-[10px] font-black uppercase tracking-widest transition shadow-sm hover:border-blue-200 active:scale-95 flex items-center justify-center gap-2"
            >
              <FileSpreadsheet className="w-5 h-5" /> Export Manifest
            </button>
            <button 
              onClick={resetFilters}
              className="px-4 py-4 bg-slate-50 text-slate-400 rounded-2xl hover:text-blue-600 hover:bg-blue-50 transition-all shadow-inner"
              title="Reset All Filters"
            >
              <RotateCcw className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Filters Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 w-full">
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCNCAN}
              onChange={(e) => setFilterCNCAN(e.target.value as any)}
            >
              <option value="ALL">CNCAN: ALL</option>
              <option value="YES">CNCAN ONLY</option>
              <option value="NO">NON-CNCAN</option>
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterDept}
              onChange={(e) => setFilterDept(e.target.value)}
            >
              <option value="ALL">ALL DEPTS</option>
              {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterCategory}
              onChange={(e) => setFilterCategory(e.target.value)}
            >
              <option value="ALL">ALL CATEGORIES</option>
              {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
          <div className="relative">
            <select 
              className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 focus:outline-none cursor-pointer hover:bg-slate-100 transition shadow-inner uppercase tracking-wider appearance-none"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
            >
              <option value="ALL">ALL STATUSES</option>
              {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
            </select>
            <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-center w-12">
                   <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                      checked={filteredDevices.length > 0 && selectedIds.size === filteredDevices.length}
                      onChange={toggleAllSelection}
                    />
                </th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Department</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
