const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [inventorySearch, setInventorySearch] = useState('');

  const loadAndSync = async (force = false) => {
    if (force) setIsSyncing(true);
    else setIsLoading(true);

    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();

      setDevices(localData.length > 0 ? localData : MOCK_DEVICES);
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        setIsSyncing(true);
        const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
        if (!error && cloudData) {
          const cloudDevices = cloudData as MedicalDevice[];
          await saveDevicesToDB(cloudDevices);
          setDevices(cloudDevices);
        }
      }
    } catch (error) {
      console.error("Clinical fleet index failure:", error);
    } finally {
      setIsLoading(false);
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  /**
   * Main Database Persistence Hub
   */
  const persistDeviceChange = async (changedDevice: MedicalDevice | MedicalDevice[], action: 'UPSERT' | 'DELETE'): Promise<void> => {
    setIsSyncing(true);
    try {
      const currentLocal = await getAllDevicesFromDB();
      const payload = Array.isArray(changedDevice) ? changedDevice : [changedDevice];
      let updatedLocal: MedicalDevice[];

      // 1. Update Local Storage
      if (action === 'DELETE' && !Array.isArray(changedDevice)) {
        updatedLocal = currentLocal.filter(d => d.id !== changedDevice.id);
      } else {
        const map = new Map(currentLocal.map(d => [d.id, d]));
        payload.forEach(p => map.set(p.id, p));
        updatedLocal = Array.from(map.values());
      }

      await saveDevicesToDB(updatedLocal);
      setDevices(updatedLocal);

      // 2. Sync with Cloud
      if (isSupabaseConfigured && supabase) {
        if (action === 'DELETE' && !Array.isArray(changedDevice)) {
          const { error } = await supabase.from('devices').delete().eq('id', changedDevice.id);
          if (error) throw error;
        } else {
          const { error } = await supabase.from('devices').upsert(payload, { onConflict: 'id' });
          if (error) throw error;
        }
      }

      // 3. Post-Action Handling
      if (action === 'DELETE') {
        setSelectedDevice(null);
        if (view === 'DEVICE_DETAIL') setView('INVENTORY');
      }
    } catch (error: any) {
      console.error("Critical Registry Sync Failure:", error);
      alert(`Database error: ${error.message || "Unknown error"}.`);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddTask = async (newTask: MedicalTask) => {
    const updatedTasks = [newTask, ...tasks];
    setTasks(updatedTasks);
    await saveTasksToDB(updatedTasks);
  };

  const handleUpdateTask = async (updatedTask: MedicalTask) => {
    const updatedTasks = tasks.map(t => t.id === updatedTask.id ? updatedTask : t);
    setTasks(updatedTasks);
    await saveTasksToDB(updatedTasks);
  };

  const handleDeleteTask = async (id: string) => {
    const updatedTasks = tasks.filter(t => t.status !== id); // Note: filter logic seems slightly off in original, likely meant filter(t => t.id !== id)
    setTasks(updatedTasks.filter(t => t.id !== id));
    await saveTasksToDB(updatedTasks.filter(t => t.id !== id));
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Task Tracker" count={tasks.filter(t => t.status !== TaskStatus.COMPLETED).length} />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'CONTRACTS'} onClick={() => { setView('CONTRACTS'); setSidebarOpen(false); }} icon={<ShieldCheck className="w-5 h-5" />} label="Contracts" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
