const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDevice, setSelectedDevice] = useState<MedicalDevice | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const hasInitialized = localStorage.getItem('meditrack_initialized') === 'true';

      // Handle initial mock data injection
      if (localData.length === 0 && !hasInitialized) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_initialized', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      // Cloud Sync (Optional background task)
      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData) {
            const cloudDevices = cloudData as MedicalDevice[];
            await saveDevicesToDB(cloudDevices);
            setDevices(cloudDevices);
          }
        } catch (cloudError) {
          console.warn("Could not reach global cloud registry, using local index.");
        }
      }
    } catch (error) {
      console.error("Clinical Index Initialization Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  /**
   * Unified Persistence Core - Refactored for Local-First reliability
   */
  const persistDeviceChange = async (data: MedicalDevice | MedicalDevice[] | string, action: 'UPSERT' | 'DELETE'): Promise<void> => {
    // 1. Identify target IDs
    const payload = Array.isArray(data) ? data : (typeof data === 'string' ? [] : [data as MedicalDevice]);
    const idToDelete = typeof data === 'string' ? data : (Array.isArray(data) ? null : (data as MedicalDevice).id);

    // 2. Perform Immediate Local State Update
    setDevices(prev => {
      if (action === 'DELETE' && idToDelete) {
        return prev.filter(d => d.id !== idToDelete);
      } else {
        const map = new Map(prev.map(d => [d.id, d]));
        payload.forEach(p => { if (p.id) map.set(p.id, p); });
        return Array.from(map.values());
      }
    });

    // Handle View Transition immediately
    if (action === 'DELETE' && selectedDevice?.id === idToDelete) {
      setSelectedDevice(null);
      setView('INVENTORY');
    }

    // 3. Persist to Local Storage (IndexedDB)
    setIsSyncing(true);
    try {
      const freshLocal = await getAllDevicesFromDB();
      let nextLocal: MedicalDevice[];

      if (action === 'DELETE' && idToDelete) {
        nextLocal = freshLocal.filter(d => d.id !== idToDelete);
      } else {
        const map = new Map(freshLocal.map(d => [d.id, d]));
        payload.forEach(p => { if (p.id) map.set(p.id, p); });
        nextLocal = Array.from(map.values());
      }

      await saveDevicesToDB(nextLocal);
      localStorage.setItem('meditrack_initialized', 'true');

      // 4. Background Cloud Sync (Non-blocking)
      if (isSupabaseConfigured && supabase) {
        try {
          if (action === 'DELETE' && idToDelete) {
            await supabase.from('devices').delete().eq('id', idToDelete);
          } else if (payload.length > 0) {
            await supabase.from('devices').upsert(payload, { onConflict: 'id' });
          }
        } catch (cloudSyncError) {
          console.warn("Cloud mirror sync delayed due to connection. Data is saved locally.");
        }
      }
    } catch (error: any) {
      console.error("Critical Registry Write Error:", error);
      alert("Database error: Changes saved to memory but failed to write to disk.");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddTask = async (t: MedicalTask) => {
    setTasks(prev => [t, ...prev]);
    await saveTasksToDB([t, ...tasks]);
  };

  const handleUpdateTask = async (t: MedicalTask) => {
    const updated = tasks.map(tk => tk.id === t.id ? t : tk);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleDeleteTask = async (id: string) => {
    const updated = tasks.filter(t => t.id !== id);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" count={tasks.filter(t => t.status !== TaskStatus.COMPLETED).length} />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-50">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && <div className="flex items-center gap-2 text-blue-600"><Loader2 className="w-4 h-4 animate-spin" /><span className="text-[10px] font-black uppercase">Syncing</span></div>}
            {view === 'INVENTORY' && <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest"> + New Asset</button>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full"><Loader2 className="w-12 h-12 text-blue-600 animate-spin" /></div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && (
                <DeviceList 
                  devices={devices} 
                  onSelectDevice={(d) => { setSelectedDevice(d); setView('DEVICE_DETAIL'); }} 
                  onUpdateDevice={(d) => persistDeviceChange(d, 'UPSERT')} 
                  onBulkUpdate={(devs) => persistDeviceChange(devs, 'UPSERT')}
                  onDelete={(id) => persistDeviceChange(id, 'DELETE')} 
                  onAddDevice={() => setView('ADD_DEVICE')} 
                />
              )}
              {view === 'DEVICE_DETAIL' && selectedDevice && (
                <DeviceDetail 
                  device={selectedDevice} 
                  tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} 
                  onBack={() => setView('INVENTORY')} 
                  onUpdate={(d) => persistDeviceChange(d, 'UPSERT')} 
                  onDelete={() => persistDeviceChange(selectedDevice.id, 'DELETE')} 
                  onAddTask={handleAddTask} 
                />
              )}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await persistDeviceChange(d, 'UPSERT'); setView('INVENTORY'); }} onBulkSave={async (ds) => { await persistDeviceChange(ds, 'UPSERT'); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={(devs) => persistDeviceChange(devs, 'UPSERT')} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

