              ))}
            </tbody>
          </table>
        </div>
        {filteredDevices.length === 0 && (
          <div className="py-32 flex flex-col items-center justify-center text-center">
             <div className="p-8 bg-slate-50 rounded-full mb-6">
               <ShieldOff className="w-16 h-16 text-slate-200" />
