             <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">No Assets Identified</h3>
             <p className="text-sm text-slate-400 mt-2 font-medium max-w-xs">Your fleet registry is empty or no devices match the current filters.</p>
          </div>
        )}
      </div>

      {/* Floating Bulk Action Bar */}
      {selectedIds.size > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] bg-slate-900 text-white px-8 py-5 rounded-[2.5rem] shadow-2xl border border-white/10 flex items-center gap-10 animate-fade-in">
           <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-2xl bg-blue-600 flex items-center justify-center font-black text-sm shadow-lg shadow-blue-500/30">
                {selectedIds.size}
              </div>
              <div>
