import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import TaskTracker from './components/TaskTracker';
import { MedicalDevice, MedicalTask, ViewState, DeviceStatus, MaintenanceType, TaskStatus, TaskPriority } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB, getAllTasksFromDB, saveTasksToDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    category: 'Echipament Imagistica',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    isCNCAN: true,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => 
    devices.find(d => d.id === selectedDeviceId) || null
  , [devices, selectedDeviceId]);

  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const hasInitialized = localStorage.getItem('meditrack_initialized') === 'true';

      if (localData.length === 0 && !hasInitialized) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_initialized', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData) {
            const cloudDevices = cloudData as MedicalDevice[];
            if (cloudDevices.length > 0) {
              await saveDevicesToDB(cloudDevices);
              setDevices(cloudDevices);
              localStorage.setItem('meditrack_initialized', 'true');
            }
          }
        } catch (cloudError) {
          console.warn("Cloud registry unreachable. Running in offline mode.");
        }
      }
    } catch (error) {
      console.error("Clinical Index Initialization Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = async (id: string) => {
    if (!id) return;

    // 1. Immediate UI Transitions
    setDevices(prev => prev.filter(d => d.id !== id));
    if (selectedDeviceId === id) {
      setSelectedDeviceId(null);
      setView('INVENTORY');
    }

    // 2. Persist to Local Storage
    setIsSyncing(true);
    try {
      const freshLocal = await getAllDevicesFromDB();
      const nextLocal = freshLocal.filter(d => d.id !== id);
      await saveDevicesToDB(nextLocal);
      localStorage.setItem('meditrack_initialized', 'true');

      // 3. Cloud Sync
      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().eq('id', id);
      }
    } catch (error) {
      console.error("Deletion Failure:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleUpsertDevices = async (data: MedicalDevice | MedicalDevice[]) => {
    const payload = Array.isArray(data) ? data : [data];
    if (payload.length === 0) return;

    // 1. Optimistic UI Update
    setDevices(prev => {
      const map = new Map(prev.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      return Array.from(map.values());
    });

    // 2. Persist to Local Storage
    setIsSyncing(true);
    try {
      const freshLocal = await getAllDevicesFromDB();
      const map = new Map(freshLocal.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      const nextLocal = Array.from(map.values());

      await saveDevicesToDB(nextLocal);
      localStorage.setItem('meditrack_initialized', 'true');

      // 3. Cloud Sync
      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').upsert(payload, { onConflict: 'id' });
      }
    } catch (error) {
      console.error("Upsert Failure:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleAddTask = async (t: MedicalTask) => {
    const updated = [t, ...tasks];
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleUpdateTask = async (t: MedicalTask) => {
    const updated = tasks.map(tk => tk.id === t.id ? t : tk);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleDeleteTask = async (id: string) => {
    const updated = tasks.filter(t => t.id !== id);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
