    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => 
    devices.find(d => d.id === selectedDeviceId) || null
  , [devices, selectedDeviceId]);

  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const hasBeenInitialized = localStorage.getItem('meditrack_initialized') === 'true';

      // Only load MOCK_DEVICES if the app has NEVER been used before.
      // If hasBeenInitialized is true, we respect the current localData (even if it's empty because user deleted everything).
      if (!hasBeenInitialized && localData.length === 0) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_initialized', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData && cloudData.length > 0) {
            const cloudDevices = cloudData as MedicalDevice[];
            await saveDevicesToDB(cloudDevices);
            setDevices(cloudDevices);
            localStorage.setItem('meditrack_initialized', 'true');
          }
        } catch (cloudError) {
          console.warn("Cloud connection skipped during init.");
        }
      }
    } catch (error) {
      console.error("Initialization failure:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;
    console.log(`[MediTrack] Purge requested for: ${id}`);

    // 1. UI STATE TRANSITION (Immediate)
    // We update local state first to make the app feel instant
    setDevices(prev => prev.filter(d => d.id !== id));
    setSelectedDeviceId(null);
    setView('INVENTORY');

    // 2. PERSISTENCE LAYER (Background)
    setIsSyncing(true);
    try {
      // Set initialized to true to prevent mock data from returning
      localStorage.setItem('meditrack_initialized', 'true');

      // Update IndexedDB
      const currentDevices = await getAllDevicesFromDB();
      const filtered = currentDevices.filter(d => d.id !== id);
      await saveDevicesToDB(filtered);

      // Update Supabase
      if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from('devices').delete().eq('id', id);
        if (error) throw error;
      }
      console.log(`[MediTrack] Successfully purged ${id} from all registries.`);
    } catch (error) {
      console.error("[MediTrack] Deletion failed during background sync:", error);
      // Optional: Re-fetch if deletion failed to keep UI in sync with reality
      loadAndSync();
    } finally {
      setIsSyncing(false);
    }
  }, [isSupabaseConfigured]);

  const handleBulkDelete = useCallback(async (ids: string[]) => {
    if (!ids || ids.length === 0) return;

    setDevices(prev => prev.filter(d => !ids.includes(d.id)));
    if (selectedDeviceId && ids.includes(selectedDeviceId)) {
      setSelectedDeviceId(null);
      setView('INVENTORY');
    }

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      const current = await getAllDevicesFromDB();
      const filtered = current.filter(d => !ids.includes(d.id));
      await saveDevicesToDB(filtered);

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().in('id', ids);
      }
    } catch (error) {
      console.error("Bulk purge failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [selectedDeviceId]);

  const handleUpsertDevices = useCallback(async (data: MedicalDevice | MedicalDevice[]) => {
    const payload = Array.isArray(data) ? data : [data];
    if (payload.length === 0) return;

    setDevices(prev => {
      const map = new Map(prev.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      return Array.from(map.values());
    });

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      const freshLocal = await getAllDevicesFromDB();
      const map = new Map(freshLocal.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      const nextLocal = Array.from(map.values());

      await saveDevicesToDB(nextLocal);

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').upsert(payload, { onConflict: 'id' });
      }
    } catch (error) {
      console.error("Upsert failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  const handleAddTask = async (t: MedicalTask) => {
    const updated = [t, ...tasks];
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleUpdateTask = async (t: MedicalTask) => {
    const updated = tasks.map(tk => tk.id === t.id ? t : tk);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleDeleteTask = async (id: string) => {
    const updated = tasks.filter(t => t.id !== id);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-500/20"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight text-white">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2 overflow-y-auto custom-scrollbar">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" count={tasks.filter(t => t.status !== TaskStatus.COMPLETED).length} />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && (
              <div className="flex items-center gap-2 text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Sync</span>
              </div>
            )}
            {view === 'INVENTORY' && (
              <button 
                type="button"
                onClick={() => setView('ADD_DEVICE')} 
                className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all active:scale-95"
              >
                + New Asset
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/50">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full space-y-4">
              <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Loading Clinical Index</p>
            </div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && (
                <DeviceList 
                  devices={devices} 
                  onSelectDevice={(d) => { setSelectedDeviceId(d.id); setView('DEVICE_DETAIL'); }} 
                  onUpdateDevice={handleUpsertDevices} 
                  onBulkUpdate={handleUpsertDevices}
                  onDelete={handleDeleteDevice} 
                  onBulkDelete={handleBulkDelete}
                  onAddDevice={() => setView('ADD_DEVICE')} 
                />
              )}
              {view === 'DEVICE_DETAIL' && selectedDevice && (
                <DeviceDetail 
                  device={selectedDevice} 
                  tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} 
                  onBack={() => { setView('INVENTORY'); setSelectedDeviceId(null); }} 
                  onUpdate={handleUpsertDevices} 
                  onDelete={handleDeleteDevice} 
                  onAddTask={handleAddTask} 
                />
              )}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await handleUpsertDevices(d); setView('INVENTORY'); }} onBulkSave={async (ds) => { await handleUpsertDevices(ds); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleUpsertDevices} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={handleUpsertDevices} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

