import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import TaskTracker from './components/TaskTracker';
import { MedicalDevice, MedicalTask, ViewState, DeviceStatus, MaintenanceType, TaskStatus, TaskPriority } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB, getAllTasksFromDB, saveTasksToDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    category: 'Echipament Imagistica',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    isCNCAN: true,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => 
    devices.find(d => d.id === selectedDeviceId) || null
  , [devices, selectedDeviceId]);

  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const hasBeenInitialized = localStorage.getItem('meditrack_initialized') === 'true';

      // Load MOCK_DEVICES only if the app has NEVER been used (no initialization flag)
      if (!hasBeenInitialized && localData.length === 0) {
        console.log("[MediTrack] Initializing with mock data...");
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_initialized', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData && cloudData.length > 0) {
            const cloudDevices = cloudData as MedicalDevice[];
            await saveDevicesToDB(cloudDevices);
            setDevices(cloudDevices);
            localStorage.setItem('meditrack_initialized', 'true');
          }
        } catch (cloudError) {
          console.warn("Cloud connection skipped during initialization.");
        }
      }
    } catch (error) {
      console.error("Critical initialization failure:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;

    // Find device for confirmation message
    const deviceToDelete = devices.find(d => d.id === id);
    const confirmMessage = deviceToDelete 
      ? `Confirm Purge: Permanently remove '${deviceToDelete.name}' (SN: ${deviceToDelete.serialNumber}) from clinical inventory?`
      : "Confirm Purge: Permanently remove this asset from clinical inventory?";

    if (!window.confirm(confirmMessage)) return;

    console.log(`[MediTrack] Executing purge for asset: ${id}`);

    // 1. UI TRANSITION (Immediate)
    // We navigate away and clear selection FIRST to prevent component unmounting errors
    setView('INVENTORY');
    setSelectedDeviceId(null);

    // Update local state array
    const updatedDevices = devices.filter(d => d.id !== id);
    setDevices(updatedDevices);

    // 2. PERSISTENCE (Background)
    setIsSyncing(true);
    try {
      // Ensure we mark app as initialized so mock data doesn't return
      localStorage.setItem('meditrack_initialized', 'true');

      // Update IndexedDB
      await saveDevicesToDB(updatedDevices);

      // Update Supabase
      if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from('devices').delete().eq('id', id);
        if (error) console.error("[MediTrack] Supabase delete error:", error);
      }
      console.log(`[MediTrack] Asset ${id} purged successfully.`);
    } catch (error) {
      console.error("[MediTrack] Error during purge persistence:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [devices, isSupabaseConfigured]);

  const handleBulkDelete = useCallback(async (ids: string[]) => {
    if (!ids || ids.length === 0) return;
    if (!window.confirm(`Purge ${ids.length} selected assets from the registry?`)) return;

    const updatedDevices = devices.filter(d => !ids.includes(d.id));
    setDevices(updatedDevices);

    if (selectedDeviceId && ids.includes(selectedDeviceId)) {
      setSelectedDeviceId(null);
      setView('INVENTORY');
    }

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      await saveDevicesToDB(updatedDevices);

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().in('id', ids);
      }
    } catch (error) {
      console.error("Bulk purge failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [devices, selectedDeviceId]);

  const handleUpsertDevices = useCallback(async (data: MedicalDevice | MedicalDevice[]) => {
    const payload = Array.isArray(data) ? data : [data];
    if (payload.length === 0) return;

    setDevices(prev => {
      const map = new Map(prev.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      return Array.from(map.values());
    });

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      const freshLocal = await getAllDevicesFromDB();
      const map = new Map(freshLocal.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      const nextLocal = Array.from(map.values());

      await saveDevicesToDB(nextLocal);

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').upsert(payload, { onConflict: 'id' });
      }
    } catch (error) {
      console.error("Upsert failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, []);

  const handleAddTask = async (t: MedicalTask) => {
    const updated = [t, ...tasks];
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleUpdateTask = async (t: MedicalTask) => {
    const updated = tasks.map(tk => tk.id === t.id ? t : tk);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  const handleDeleteTask = async (id: string) => {
    const updated = tasks.filter(t => t.id !== id);
    setTasks(updated);
    await saveTasksToDB(updated);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-500/20"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight text-white">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2 overflow-y-auto custom-scrollbar">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" count={tasks.filter(t => t.status !== TaskStatus.COMPLETED).length} />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && (
              <div className="flex items-center gap-2 text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Sync</span>
              </div>
            )}
            {view === 'INVENTORY' && (
              <button 
                type="button"
                onClick={() => setView('ADD_DEVICE')} 
                className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all active:scale-95"
              >
                + New Asset
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/50">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full space-y-4">
              <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Loading Clinical Index</p>
            </div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && (
                <DeviceList 
                  devices={devices} 
                  onSelectDevice={(d) => { setSelectedDeviceId(d.id); setView('DEVICE_DETAIL'); }} 
                  onUpdateDevice={handleUpsertDevices} 
                  onBulkUpdate={handleUpsertDevices}
                  onDelete={handleDeleteDevice} 
                  onBulkDelete={handleBulkDelete}
                  onAddDevice={() => setView('ADD_DEVICE')} 
                />
              )}
              {view === 'DEVICE_DETAIL' && selectedDevice && (
                <DeviceDetail 
                  device={selectedDevice} 
                  tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} 
                  onBack={() => { setView('INVENTORY'); setSelectedDeviceId(null); }} 
                  onUpdate={handleUpsertDevices} 
                  onDelete={handleDeleteDevice} 
                  onAddTask={handleAddTask} 
                />
              )}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await handleUpsertDevices(d); setView('INVENTORY'); }} onBulkSave={async (ds) => { await handleUpsertDevices(ds); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleUpsertDevices} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={handleUpsertDevices} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ active, onClick, icon, label, count }: any) => (
  <button onClick={onClick} className={`flex items-center justify-between w-full px-4 py-3 text-sm font-medium rounded-xl transition-all ${active ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
    <div className="flex items-center gap-3">{icon}{label}</div>
    {count !== undefined && count > 0 && (
      <span className="bg-red-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full shadow-sm">
        {count}
      </span>
    )}
  </button>
);

export default App;

import React, { useState } from 'react';
import { MedicalDevice, DeviceStatus, TaskPriority, TaskStatus, MedicalTask, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { 
  Activity, Box, QrCode, Trash2, X, Edit2, 
  Info, CheckSquare, Loader2, Check, ChevronDown, Clock, 
  ShieldAlert, Cpu, Wrench, CheckCircle2, Fingerprint, Save, Camera, RotateCcw
} from 'lucide-react';

interface DeviceDetailProps {
  device: MedicalDevice;
  tasks: MedicalTask[];
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  onAddTask: (task: MedicalTask) => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, tasks, onUpdate, onDelete, onBack, onAddTask }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'components' | 'tasks' | 'qr'>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [taskForm, setTaskForm] = useState({ title: '', description: '', priority: TaskPriority.MEDIUM });

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category,
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: device.department,
    status: device.status,
    isCNCAN: !!device.isCNCAN,
    notes: device.notes || '',
    image: device.image || ''
  });

  const handleCreateQuickTask = () => {
    const newTask: MedicalTask = {
      id: `TASK-${Date.now()}`,
      title: taskForm.title,
      description: taskForm.description,
      deviceId: device.id,
      deviceName: device.name,
      department: device.department,
      priority: taskForm.priority,
      status: TaskStatus.PENDING,
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddTask(newTask);
    setShowTaskModal(false);
    setTaskForm({ title: '', description: '', priority: TaskPriority.MEDIUM });
  };

  const handleDeleteRequest = () => {
    console.log("[DeviceDetail] Purge triggered for asset:", device.id);
    // Directly call the parent's robust deletion handler
    // Defer confirmation logic to App.tsx for better lifecycle management
    onDelete(device.id);
  };

  const handleSaveEdit = async () => {
    const updatedDevice: MedicalDevice = {
      ...device,
      ...editForm
    };
    await onUpdate(updatedDevice);
    setIsEditing(false);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; 
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas missing"));
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.6));
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const compressed = await compressImage(e.target.files[0]);
        setEditForm(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        console.error("Image processing error", err);
      }
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-full relative animate-fade-in">
      {showTaskModal && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-md shadow-2xl border-4 border-white animate-fade-in">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black uppercase tracking-tight">Add Device Ticket</h3>
                <button type="button" onClick={() => setShowTaskModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition text-slate-400"><X className="w-6 h-6" /></button>
             </div>
             <div className="space-y-4">
                <EditField label="Task / Issue" value={taskForm.title} onChange={(e:any) => setTaskForm({...taskForm, title: e.target.value})} />
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Description</label>
                   <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all min-h-[100px]" value={taskForm.description} onChange={(e:any) => setTaskForm({...taskForm, description: e.target.value})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Priority</label>
                   <select className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer" value={taskForm.priority} onChange={(e:any) => setTaskForm({...taskForm, priority: e.target.value as any})}>
                      {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
                   </select>
                </div>
                <button type="button" onClick={handleCreateQuickTask} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-indigo-700 shadow-xl transition active:scale-95">Log Asset Task</button>
             </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-slate-50/50">
        <div>
          <button type="button" onClick={onBack} className="text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest mb-4 flex items-center gap-2 transition group">
            <span className="group-hover:-translate-x-1 transition-transform">←</span> Return to Inventory
          </button>
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase">{device.name}</h1>
          </div>
          <div className="flex flex-wrap items-center gap-4 mt-3">
            <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500"><Box className="w-4 h-4 text-blue-500" /> {device.category}</span>
            <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-full text-[10px] font-mono font-black border border-indigo-100 shadow-sm uppercase tracking-tighter">
              <Fingerprint className="w-3.5 h-3.5 opacity-60" />
              SN: {device.serialNumber}
            </span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex items-center gap-3 w-full lg:w-auto relative z-40">
           {isEditing ? (
             <>
               <button type="button" onClick={handleSaveEdit} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-green-600 text-white rounded-xl transition shadow-lg shadow-green-500/20 font-black text-xs uppercase tracking-widest hover:bg-green-700 active:scale-95"><Save className="w-4 h-4" /> Save Changes</button>
               <button type="button" onClick={() => { setIsEditing(false); setEditForm({...device, notes: device.notes || '', image: device.image || ''}); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-slate-200 text-slate-600 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-slate-300 active:scale-95">Cancel</button>
             </>
           ) : (
             <>
               <button type="button" onClick={() => { setIsEditing(true); setActiveTab('overview'); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl transition shadow-lg shadow-indigo-500/20 font-black text-xs uppercase tracking-widest hover:bg-indigo-700 active:scale-95"><Edit2 className="w-4 h-4" /> Edit Asset</button>
               <button 
                type="button" 
                onClick={handleDeleteRequest} 
                className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-red-600 hover:text-white active:scale-95 shadow-sm"
               >
                  <Trash2 className="w-4 h-4" /> Purge Asset
               </button>
             </>
           )}
        </div>
      </div>

      <div className="flex border-b border-slate-100 px-8 bg-white overflow-x-auto no-scrollbar shadow-sm relative z-10">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Technical Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Wrench className="w-4 h-4" />} label="Service Logs" />
        <TabButton active={activeTab === 'tasks'} onClick={() => setActiveTab('tasks')} icon={<CheckSquare className="w-4 h-4" />} label="Operations" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="Identity (QR)" />
      </div>

      <div className="p-8 overflow-y-auto flex-1 bg-slate-50/30 custom-scrollbar">
        {activeTab === 'overview' && (
           <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 max-w-7xl mx-auto">
              {isEditing ? (
                <div className="xl:col-span-8 space-y-8 animate-fade-in">
                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Core Specifications</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <EditField label="Asset Name" name="name" value={editForm.name} onChange={handleEditChange} />
