                      </div>
                      <EditField label="Serial Number" name="serialNumber" value={editForm.serialNumber} onChange={handleEditChange} />
                      <EditField label="Manufacturer" name="manufacturer" value={editForm.manufacturer} onChange={handleEditChange} />
                      <EditField label="Model Version" name="model" value={editForm.model} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Unit (Department)</label>
                        <select name="department" value={editForm.department} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                          {HOSPITAL_DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                        </select>
                      </div>
                    </div>
                  </div>

                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Registry & Compliance</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                       <div className="space-y-1">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Registry Status</label>
                          <select name="status" value={editForm.status} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                       </div>
                       <div className="flex items-center gap-4 bg-slate-50 p-4 rounded-xl border border-slate-200">
                          <input type="checkbox" name="isCNCAN" checked={editForm.isCNCAN} onChange={handleEditChange} className="w-5 h-5 rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                          <div>
                             <p className="text-xs font-black uppercase tracking-tight text-slate-900">CNCAN Regulatory Status</p>
                             <p className="text-[9px] font-bold text-slate-400 uppercase">Radiation protection monitoring required</p>
                          </div>
                       </div>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Documentation / Notes</label>
                       <textarea name="notes" value={editForm.notes} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[120px] focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all resize-none" />
                    </div>
                  </div>
                </div>
              ) : (
                <div className="xl:col-span-8 space-y-8 animate-fade-in">
                  <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-8">
                     <div className="flex items-center gap-4 mb-2">
                        <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl shadow-sm"><Info className="w-6 h-6" /></div>
                        <h3 className="font-black text-sm uppercase tracking-widest text-slate-400">Asset Identity Card</h3>
                     </div>
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                        <InfoRow label="Manufacturer" value={device.manufacturer} />
                        <InfoRow label="Model Line" value={device.model} />
                        <InfoRow label="Unit Assignment" value={device.department} />
                        <InfoRow label="Registration Date" value={device.purchaseDate} />
                        <InfoRow label="Asset Class" value={device.category} />
                        <InfoRow label="Global Identifier" value={device.serialNumber} badge />
                     </div>
                     <div className="pt-8 border-t border-slate-50">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-3">Clinical Operations Notes</label>
                        <p className="text-sm text-slate-600 font-medium leading-relaxed bg-slate-50/50 p-6 rounded-2xl border border-slate-100 italic">
                          {device.notes || 'No specialized technical or operational notes recorded for this clinical asset in the master registry.'}
                        </p>
                     </div>
                  </div>
                </div>
              )}

              <div className="xl:col-span-4 space-y-8">
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden group">
                   <div className="flex justify-between items-center mb-6">
                      <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400 flex items-center gap-2"><Camera className="w-4 h-4" /> Visual Identity</h3>
                      {isEditing && (
                        <label className="cursor-pointer p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition">
                           <RotateCcw className="w-4 h-4" />
                           <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                        </label>
                      )}
                   </div>
                   <div className="aspect-square bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-center overflow-hidden relative shadow-inner">
                      {(isEditing ? editForm.image : device.image) ? (
                        <img src={isEditing ? editForm.image : device.image} alt="Asset Visual" className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                      ) : (
                        <div className="flex flex-col items-center text-slate-300">
                           <Box className="w-16 h-16 mb-4 opacity-30" />
                           <p className="text-[10px] font-black uppercase tracking-widest">No Visual Record</p>
                        </div>
                      )}
                      {device.isCNCAN && <div className="absolute top-0 right-0 p-3 bg-amber-500 rounded-bl-3xl shadow-xl animate-pulse z-20"><ShieldAlert className="w-6 h-6 text-white" /></div>}
