  Activity, Box, QrCode, Trash2, X, Edit2, 
  Info, CheckSquare, Loader2, Check, ChevronDown, Clock, 
  ShieldAlert, Cpu, Wrench, CheckCircle2, Fingerprint, Save, Camera, RotateCcw
} from 'lucide-react';

interface DeviceDetailProps {
  device: MedicalDevice;
  tasks: MedicalTask[];
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  onAddTask: (task: MedicalTask) => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, tasks, onUpdate, onDelete, onBack, onAddTask }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'components' | 'tasks' | 'qr'>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [taskForm, setTaskForm] = useState({ title: '', description: '', priority: TaskPriority.MEDIUM });

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category,
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: device.department,
    status: device.status,
    isCNCAN: !!device.isCNCAN,
    notes: device.notes || '',
    image: device.image || ''
  });

  const handleCreateQuickTask = () => {
    const newTask: MedicalTask = {
      id: `TASK-${Date.now()}`,
      title: taskForm.title,
      description: taskForm.description,
      deviceId: device.id,
      deviceName: device.name,
      department: device.department,
      priority: taskForm.priority,
      status: TaskStatus.PENDING,
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddTask(newTask);
    setShowTaskModal(false);
    setTaskForm({ title: '', description: '', priority: TaskPriority.MEDIUM });
  };

  const handleDeleteRequest = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    console.log("[DeviceDetail] Purge triggered for asset:", device.id);
    // Defer the execution to ensure the UI has time to acknowledge the click
    onDelete(device.id);
  };

  const handleSaveEdit = async () => {
    const updatedDevice: MedicalDevice = {
      ...device,
      ...editForm
    };
    await onUpdate(updatedDevice);
    setIsEditing(false);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; 
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas missing"));
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.6));
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const compressed = await compressImage(e.target.files[0]);
        setEditForm(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        console.error("Image processing error", err);
      }
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-full relative animate-fade-in">
      {showTaskModal && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-md shadow-2xl border-4 border-white animate-fade-in">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black uppercase tracking-tight">Add Device Ticket</h3>
                <button type="button" onClick={() => setShowTaskModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition text-slate-400"><X className="w-6 h-6" /></button>
             </div>
             <div className="space-y-4">
                <EditField label="Task / Issue" value={taskForm.title} onChange={(e:any) => setTaskForm({...taskForm, title: e.target.value})} />
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Description</label>
                   <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all min-h-[100px]" value={taskForm.description} onChange={(e:any) => setTaskForm({...taskForm, description: e.target.value})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Priority</label>
                   <select className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer" value={taskForm.priority} onChange={(e:any) => setTaskForm({...taskForm, priority: e.target.value as any})}>
                      {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
                   </select>
                </div>
                <button type="button" onClick={handleCreateQuickTask} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-indigo-700 shadow-xl transition active:scale-95">Log Asset Task</button>
             </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-slate-50/50">
        <div>
          <button type="button" onClick={onBack} className="text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest mb-4 flex items-center gap-2 transition group">
            <span className="group-hover:-translate-x-1 transition-transform">←</span> Return to Inventory
          </button>
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase">{device.name}</h1>
          </div>
          <div className="flex flex-wrap items-center gap-4 mt-3">
            <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500"><Box className="w-4 h-4 text-blue-500" /> {device.category}</span>
            <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-full text-[10px] font-mono font-black border border-indigo-100 shadow-sm uppercase tracking-tighter">
              <Fingerprint className="w-3.5 h-3.5 opacity-60" />
              SN: {device.serialNumber}
            </span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex items-center gap-3 w-full lg:w-auto relative z-[60]">
           {isEditing ? (
             <>
               <button type="button" onClick={handleSaveEdit} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-green-600 text-white rounded-xl transition shadow-lg shadow-green-500/20 font-black text-xs uppercase tracking-widest hover:bg-green-700 active:scale-95"><Save className="w-4 h-4" /> Save Changes</button>
               <button type="button" onClick={() => { setIsEditing(false); setEditForm({...device, notes: device.notes || '', image: device.image || ''}); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-slate-200 text-slate-600 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-slate-300 active:scale-95">Cancel</button>
             </>
           ) : (
             <>
               <button type="button" onClick={() => { setIsEditing(true); setActiveTab('overview'); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl transition shadow-lg shadow-indigo-500/20 font-black text-xs uppercase tracking-widest hover:bg-indigo-700 active:scale-95"><Edit2 className="w-4 h-4" /> Edit Asset</button>
               <button 
                type="button" 
                onClick={handleDeleteRequest} 
                className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-red-600 hover:text-white active:scale-95 shadow-sm"
               >
                  <Trash2 className="w-4 h-4" /> Purge Asset
               </button>
             </>
           )}
        </div>
      </div>

      <div className="flex border-b border-slate-100 px-8 bg-white overflow-x-auto no-scrollbar shadow-sm relative z-10">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Technical Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Wrench className="w-4 h-4" />} label="Service Logs" />
        <TabButton active={activeTab === 'tasks'} onClick={() => setActiveTab('tasks')} icon={<CheckSquare className="w-4 h-4" />} label="Operations" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="Identity (QR)" />
      </div>

      <div className="p-8 overflow-y-auto flex-1 bg-slate-50/30 custom-scrollbar">
        {activeTab === 'overview' && (
           <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 max-w-7xl mx-auto">
              {isEditing ? (
                <div className="xl:col-span-8 space-y-8 animate-fade-in">
                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Core Specifications</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <EditField label="Asset Name" name="name" value={editForm.name} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Class (Category)</label>
                        <select name="category" value={editForm.category} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                          {DEVICE_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                      </div>
                      <EditField label="Serial Number" name="serialNumber" value={editForm.serialNumber} onChange={handleEditChange} />
                      <EditField label="Manufacturer" name="manufacturer" value={editForm.manufacturer} onChange={handleEditChange} />
                      <EditField label="Model Version" name="model" value={editForm.model} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Unit (Department)</label>
                        <select name="department" value={editForm.department} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                          {HOSPITAL_DEPARTMENTS.map(d => <option key={d} value={d}>{d}</option>)}
                        </select>
                      </div>
                    </div>
                  </div>

                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Registry & Compliance</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                       <div className="space-y-1">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Registry Status</label>
                          <select name="status" value={editForm.status} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                       </div>
                       <div className="flex items-center gap-4 bg-slate-50 p-4 rounded-xl border border-slate-200">
                          <input type="checkbox" name="isCNCAN" checked={editForm.isCNCAN} onChange={handleEditChange} className="w-5 h-5 rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                          <div>
                             <p className="text-xs font-black uppercase tracking-tight text-slate-900">CNCAN Regulatory Status</p>
                             <p className="text-[9px] font-bold text-slate-400 uppercase">Radiation protection monitoring required</p>
                          </div>
                       </div>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Documentation / Notes</label>
                       <textarea name="notes" value={editForm.notes} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[120px] focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all resize-none" />
                    </div>
                  </div>
                </div>
              ) : (
                <div className="xl:col-span-8 space-y-8 animate-fade-in">
                  <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-8">
                     <div className="flex items-center gap-4 mb-2">
                        <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl shadow-sm"><Info className="w-6 h-6" /></div>
                        <h3 className="font-black text-sm uppercase tracking-widest text-slate-400">Asset Identity Card</h3>
                     </div>
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                        <InfoRow label="Manufacturer" value={device.manufacturer} />
                        <InfoRow label="Model Line" value={device.model} />
                        <InfoRow label="Unit Assignment" value={device.department} />
                        <InfoRow label="Registration Date" value={device.purchaseDate} />
                        <InfoRow label="Asset Class" value={device.category} />
                        <InfoRow label="Global Identifier" value={device.serialNumber} badge />
                     </div>
                     <div className="pt-8 border-t border-slate-50">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-3">Clinical Operations Notes</label>
                        <p className="text-sm text-slate-600 font-medium leading-relaxed bg-slate-50/50 p-6 rounded-2xl border border-slate-100 italic">
                          {device.notes || 'No specialized technical or operational notes recorded for this clinical asset in the master registry.'}
                        </p>
                     </div>
                  </div>
                </div>
              )}

              <div className="xl:col-span-4 space-y-8">
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden group">
                   <div className="flex justify-between items-center mb-6">
                      <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400 flex items-center gap-2"><Camera className="w-4 h-4" /> Visual Identity</h3>
                      {isEditing && (
                        <label className="cursor-pointer p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition">
                           <RotateCcw className="w-4 h-4" />
                           <input type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
                        </label>
                      )}
                   </div>
                   <div className="aspect-square bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-center overflow-hidden relative shadow-inner">
                      {(isEditing ? editForm.image : device.image) ? (
                        <img src={isEditing ? editForm.image : device.image} alt="Asset Visual" className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                      ) : (
                        <div className="flex flex-col items-center text-slate-300">
                           <Box className="w-16 h-16 mb-4 opacity-30" />
                           <p className="text-[10px] font-black uppercase tracking-widest">No Visual Record</p>
                        </div>
                      )}
                      {device.isCNCAN && <div className="absolute top-0 right-0 p-3 bg-amber-500 rounded-bl-3xl shadow-xl animate-pulse z-20"><ShieldAlert className="w-6 h-6 text-white" /></div>}
                   </div>
                   {!isEditing && (
                     <div className="mt-8 p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100 flex items-center gap-4">
                        <QrCode className="w-8 h-8 text-indigo-400 opacity-60" />
                        <div>
                           <p className="text-[10px] font-black text-indigo-900 uppercase tracking-tight">Digital Passport Ready</p>
                           <p className="text-[9px] font-bold text-indigo-400 uppercase">Scan to view digital clinical record</p>
                        </div>
                     </div>
                   )}
                </div>
              </div>
           </div>
        )}

        {activeTab === 'tasks' && (
           <div className="space-y-4 max-w-4xl mx-auto py-10">
              <div className="flex justify-between items-center mb-6 px-4">
                 <h3 className="font-black text-xl text-slate-900 uppercase tracking-tight">Asset Operational Timeline</h3>
                 <button type="button" onClick={() => setShowTaskModal(true)} className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition">Add Ticket</button>
              </div>
              {tasks.length > 0 ? tasks.map(task => (
                <div key={task.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-all">
                   <div className="flex gap-8">
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 shadow-inner ${task.status === TaskStatus.COMPLETED ? 'bg-green-50 text-green-600' : 'bg-indigo-50 text-indigo-600'}`}>
                        {task.status === TaskStatus.COMPLETED ? <CheckCircle2 className="w-7 h-7" /> : <Clock className="w-7 h-7" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-3">
                           <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight leading-none">{task.title}</h4>
                           <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest border ${task.priority === TaskPriority.CRITICAL ? 'bg-red-50 text-red-600 border-red-100' : 'bg-slate-50 text-slate-500 border-slate-100'}`}>{task.priority}</span>
                        </div>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Status: {task.status} • Logged: {task.createdAt}</p>
                        <p className="text-sm text-slate-600 mt-4 font-medium leading-relaxed">{task.description}</p>
                      </div>
                   </div>
                </div>
              )) : (
                <div className="py-24 text-center">
                   <div className="p-8 bg-white border-4 border-dashed border-slate-200 rounded-full w-fit mx-auto mb-6">
                      <CheckSquare className="w-16 h-16 text-slate-200" />
                   </div>
                   <p className="text-sm font-black uppercase tracking-widest text-slate-400">No Operational Tickets Recorded</p>
                </div>
              )}
           </div>
        )}

        {activeTab === 'qr' && (
          <div className="max-w-2xl mx-auto py-20 text-center space-y-10 bg-white rounded-[3rem] shadow-xl border border-slate-100 p-12">
             <div className="bg-slate-900 p-12 rounded-[2.5rem] inline-block shadow-2xl relative group">
                <div className="absolute inset-0 bg-blue-500 opacity-0 group-hover:opacity-10 transition-opacity rounded-[2.5rem]"></div>
                <QrCode className="w-48 h-48 text-white relative z-10" />
             </div>
             <div>
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Asset Digital Passport</h3>
                <p className="text-sm text-slate-500 font-medium max-w-sm mx-auto mt-4 leading-relaxed">Print this identity code and attach it to the asset chassis. Clinical staff can scan this to view real-time status and logs.</p>
             </div>
             <button type="button" className="px-10 py-5 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-black transition active:scale-95 flex items-center justify-center gap-3 mx-auto">
                Download Label Template
             </button>
          </div>
        )}

        {(activeTab === 'maintenance' || activeTab === 'components') && (
           <div className="py-24 text-center">
              <div className="p-8 bg-white border-4 border-dashed border-slate-200 rounded-full w-fit mx-auto mb-6">
                 {activeTab === 'maintenance' ? <Wrench className="w-16 h-16 text-slate-200" /> : <Cpu className="w-16 h-16 text-slate-200" />}
              </div>
              <p className="text-sm font-black uppercase tracking-widest text-slate-400">Section Under Active Monitoring</p>
              <p className="text-xs text-slate-300 font-bold uppercase mt-2">Historical data migration in progress</p>
           </div>
        )}
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-200 text-slate-500 border-slate-300"; break;
  }
  return <span className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border shadow-sm ${styles}`}>{status}</span>;
};

const TabButton = ({ active, onClick, icon, label }: any) => (
  <button type="button" onClick={onClick} className={`flex items-center gap-3 px-8 py-6 text-[10px] font-black uppercase tracking-widest border-b-4 transition-all whitespace-nowrap ${active ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
    {icon} {label}
  </button>
);

const InfoRow = ({ label, value, badge }: any) => (
  <div className="flex flex-col gap-2 py-4 border-b border-slate-50 last:border-0">
    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    {badge ? (
      <span className="text-xs font-mono font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg w-fit border border-indigo-100 shadow-sm">{value || 'N/A'}</span>
    ) : (
      <span className="text-sm font-bold text-slate-900 leading-none">{value || 'N/A'}</span>
    )}
  </div>
);

const EditField = ({ label, name, value, onChange, type = "text" }: any) => (
  <div className="space-y-1 w-full">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input name={name} type={type} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all" value={value} onChange={onChange} />
  </div>
);

export default DeviceDetail;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES, DeviceCategory } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint, AlertCircle, ShieldOff, RotateCcw, Layers, Loader2, FileText } from 'lucide-react';

declare var XLSX: any; 

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onBulkUpdate: (devices: MedicalDevice[]) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onBulkUpdate, onAddDevice, onDelete, searchQuery: externalSearch = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [filterCNCAN, setFilterCNCAN] = useState<'ALL' | 'YES' | 'NO'>('ALL');
  const [localSearch, setLocalSearch] = useState('');

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [bulkCategory, setBulkCategory] = useState<DeviceCategory | ''>('');
  const [isProcessingBulk, setIsProcessingBulk] = useState(false);

  const effectiveSearch = (localSearch || externalSearch).toLowerCase().trim();

  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);
  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    category: '',
    manufacturer: '',
    model: '',
    serialNumber: '',
    department: '',
    customDepartment: '',
    purchaseDate: '',
    warrantyExpiration: '',
    status: DeviceStatus.ACTIVE,
    isCNCAN: false
  });

  const filteredDevices = useMemo(() => {
    return devices.filter(d => {
      const matchSearch = !effectiveSearch || 
        (d.name || '').toLowerCase().includes(effectiveSearch) || 
        (d.serialNumber || '').toLowerCase().includes(effectiveSearch) ||
        (d.model || '').toLowerCase().includes(effectiveSearch) ||
        (d.category || '').toLowerCase().includes(effectiveSearch) ||
        (d.manufacturer || '').toLowerCase().includes(effectiveSearch) ||
        (d.department || '').toLowerCase().includes(effectiveSearch);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;
      const matchCNCAN = filterCNCAN === 'ALL' || (filterCNCAN === 'YES' ? d.isCNCAN : !d.isCNCAN);

      return matchSearch && matchStatus && matchDept && matchCategory && matchCNCAN;
    });
  }, [devices, effectiveSearch, filterStatus, filterDept, filterCategory, filterCNCAN]);

  const toggleAllSelection = () => {
    if (selectedIds.size === filteredDevices.length && filteredDevices.length > 0) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredDevices.map(d => d.id)));
    }
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const handleBulkCategorize = async () => {
    if (!bulkCategory || selectedIds.size === 0) return;

    setIsProcessingBulk(true);
    try {
      const devicesToUpdate = devices
        .filter(d => selectedIds.has(d.id))
        .map(d => ({ ...d, category: bulkCategory }));

      await onBulkUpdate(devicesToUpdate);

      setSelectedIds(new Set());
      setBulkCategory('');
    } catch (err) {
      console.error("Bulk categorization failed");
    } finally {
      setIsProcessingBulk(false);
    }
  };

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name,
      category: device.category || '',
      manufacturer: device.manufacturer,
      model: device.model,
      serialNumber: device.serialNumber,
      department: device.department,
      customDepartment: '',
      purchaseDate: device.purchaseDate,
      warrantyExpiration: device.warrantyExpiration || '',
      status: device.status,
      isCNCAN: !!device.isCNCAN
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setQuickEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleSaveQuickEdit = async () => {
    if (!editingDevice) return;

    const finalDept = quickEditForm.department === 'NEW_DEPT' 
      ? (quickEditForm.customDepartment || 'Unassigned') 
      : quickEditForm.department;

    const updated: MedicalDevice = {
      ...editingDevice,
      name: quickEditForm.name,
      category: quickEditForm.category,
      manufacturer: quickEditForm.manufacturer,
      model: quickEditForm.model,
      serialNumber: quickEditForm.serialNumber,
      department: finalDept,
      purchaseDate: quickEditForm.purchaseDate,
      warrantyExpiration: quickEditForm.warrantyExpiration,
      status: quickEditForm.status,
      isCNCAN: quickEditForm.isCNCAN
    };

    await onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    // Rely on centralized confirmation in App.tsx
    onDelete(deviceId);
  };

  return (
    <div className="space-y-6 pb-24 relative">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col gap-6">
        <div className="flex flex-col lg:flex-row items-center gap-4 w-full">
          <div className="relative flex-1 w-full group">
            <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${effectiveSearch ? 'text-blue-600' : 'text-slate-300'}`} />
            <input 
              type="text"
              placeholder="Search by asset name, serial, model..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 focus:bg-white rounded-2xl text-sm font-bold focus:outline-none transition-all shadow-inner"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setLocalSearch(''); setFilterStatus('ALL'); setFilterDept('ALL'); }}
            className="px-4 py-4 bg-slate-50 text-slate-400 rounded-2xl hover:text-blue-600 hover:bg-blue-50 transition-all shadow-inner"
          >
            <RotateCcw className="w-5 h-5" />
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3 w-full">
          <select 
            className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none appearance-none cursor-pointer uppercase tracking-wider shadow-inner"
            value={filterDept}
            onChange={(e) => setFilterDept(e.target.value)}
          >
            <option value="ALL">ALL DEPTS</option>
            {Array.from(new Set(devices.map(d => d.department))).sort().map(dept => <option key={dept as string} value={dept as string}>{(dept as string).toUpperCase()}</option>)}
          </select>
          <select 
            className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none appearance-none cursor-pointer uppercase tracking-wider shadow-inner"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
          >
            <option value="ALL">ALL CATEGORIES</option>
            {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
          </select>
          <select 
            className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none appearance-none cursor-pointer uppercase tracking-wider shadow-inner"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as DeviceStatus | 'ALL')}
          >
            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-center w-12">
                   <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                      checked={filteredDevices.length > 0 && selectedIds.size === filteredDevices.length}
                      onChange={toggleAllSelection}
                    />
                </th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Unit</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map((device) => (
                <tr 
                  key={device.id} 
                  className={`transition-all group ${selectedIds.has(device.id) ? 'bg-blue-50/60' : 'hover:bg-blue-50/40'}`}
                >
                  <td className="px-6 py-6 text-center align-middle">
                    <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                      checked={selectedIds.has(device.id)}
                      onChange={() => toggleSelection(device.id)}
                    />
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center relative shadow-sm">
                        {device.image ? <img src={device.image} className="w-full h-full object-cover" alt="Asset" /> : <Box className="w-5 h-5 text-slate-300" />}
                        {device.isCNCAN && <div className="absolute top-0 right-0 p-0.5 bg-amber-500 rounded-bl-lg shadow-sm"><ShieldAlert className="w-2.5 h-2.5 text-white" /></div>}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="text-xs font-bold text-slate-700 mb-1">{device.category}</div>
                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-lg font-mono text-[11px] font-bold tracking-tight shadow-sm border border-indigo-100">
                      <Fingerprint className="w-3.5 h-3.5 opacity-60" /> {device.serialNumber}
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all active:scale-90"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { LayoutDashboard, List, Stethoscope, Menu, X, ShieldCheck, Loader2, CheckSquare, Settings as SettingsIcon, CalendarRange } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import ContractManager from './components/ContractManager';
import Settings from './components/Settings';
import TaskTracker from './components/TaskTracker';
import { MedicalDevice, MedicalTask, ViewState, DeviceStatus, MaintenanceType, TaskStatus, TaskPriority } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB, deleteDeviceFromDB, getAllTasksFromDB, saveTasksToDB, deleteTaskFromDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    category: 'Echipament Imagistica',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    isCNCAN: true,
    notes: 'Primary MRI for emergency ward. Requires weekly cooling system check.',
    files: [{ id: 'f1', name: 'User Manual v2.pdf', type: 'manual', url: '#', dateAdded: '2022-03-15' }],
    maintenanceHistory: [
      { id: 'm1', date: '2023-10-10', type: MaintenanceType.PREVENTIVE, technician: 'John Doe', description: 'Annual coil calibration', completed: true, nextScheduledDate: '2024-10-10' }
    ],
    contracts: [
      { id: 'c1', provider: 'Siemens Direct', contractNumber: 'SVC-2022-99', startDate: '2022-03-15', endDate: '2025-03-15', coverageDetails: 'Full parts and labor, 24h response', contactPhone: '555-0192', annualCost: 45000 }
    ],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => 
    devices.find(d => d.id === selectedDeviceId) || null
  , [devices, selectedDeviceId]);

  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const hasBeenInitialized = localStorage.getItem('meditrack_initialized') === 'true';

      // Fix: If initialized but empty, keep it empty. Only load mock if NEVER initialized.
      if (!hasBeenInitialized && localData.length === 0) {
        console.log("[MediTrack] Fresh install: Seeding mock registry.");
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_initialized', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData && cloudData.length > 0) {
            const cloudDevices = cloudData as MedicalDevice[];
            await saveDevicesToDB(cloudDevices);
            setDevices(cloudDevices);
            localStorage.setItem('meditrack_initialized', 'true');
          }
        } catch (cloudError) {
          console.warn("Cloud connection skipped during background sync.");
        }
      }
    } catch (error) {
      console.error("Initialization failure:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;

    // Find device for name in confirm dialog
    const target = devices.find(d => d.id === id);
    const msg = target 
      ? `PERMANENT PURGE: Are you sure you want to remove '${target.name}' from the registry?`
      : "Confirm Purge: Remove this asset from the registry?";

    if (!window.confirm(msg)) return;

    console.log(`[MediTrack] Commencing atomic purge for: ${id}`);

    // 1. UI TRANSITION (Synchronous)
    // We update local state first to make the app feel instant and prevent re-renders in Detail view
    setDevices(prev => prev.filter(d => d.id !== id));
    setSelectedDeviceId(null);
    setView('INVENTORY');

    // 2. PERSISTENCE (Background)
    setIsSyncing(true);
    try {
      // Mark as initialized so mock data doesn't return
      localStorage.setItem('meditrack_initialized', 'true');

      // Update IndexedDB
      await deleteDeviceFromDB(id);

      // Update Supabase
      if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from('devices').delete().eq('id', id);
        if (error) console.error("[MediTrack] Cloud deletion failed:", error);
      }
      console.log(`[MediTrack] Successfully purged asset ${id}.`);
    } catch (error) {
      console.error("[MediTrack] Deletion failed during persistence phase:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [devices, isSupabaseConfigured]);

  const handleBulkDelete = useCallback(async (ids: string[]) => {
    if (!ids || ids.length === 0) return;
    if (!window.confirm(`Purge ${ids.length} selected assets permanently?`)) return;

    setDevices(prev => prev.filter(d => !ids.includes(d.id)));
    if (selectedDeviceId && ids.includes(selectedDeviceId)) {
      setSelectedDeviceId(null);
      setView('INVENTORY');
    }

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      for (const id of ids) {
        await deleteDeviceFromDB(id);
      }

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().in('id', ids);
      }
    } catch (error) {
      console.error("Bulk purge failure:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [selectedDeviceId, isSupabaseConfigured]);

  const handleUpsertDevices = useCallback(async (data: MedicalDevice | MedicalDevice[]) => {
    const payload = Array.isArray(data) ? data : [data];
    if (payload.length === 0) return;

    setDevices(prev => {
      const map = new Map(prev.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      return Array.from(map.values());
    });

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_initialized', 'true');
      const freshLocal = await getAllDevicesFromDB();
      const map = new Map(freshLocal.map(d => [d.id, d]));
      payload.forEach(p => map.set(p.id, p));
      const nextLocal = Array.from(map.values());

      await saveDevicesToDB(nextLocal);

      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').upsert(payload, { onConflict: 'id' });
      }
    } catch (error) {
      console.error("Cloud upsert failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSupabaseConfigured]);

  const handleAddTask = async (t: MedicalTask) => {
    setTasks(prev => [t, ...prev]);
    await saveTasksToDB([t, ...tasks]);
  };

  const handleUpdateTask = async (t: MedicalTask) => {
    setTasks(prev => prev.map(tk => tk.id === t.id ? t : tk));
    const currentTasks = await getAllTasksFromDB();
    await saveTasksToDB(currentTasks.map(tk => tk.id === t.id ? t : tk));
  };

  const handleDeleteTask = async (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
    await deleteTaskFromDB(id);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-500/20"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight text-white">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2 overflow-y-auto custom-scrollbar">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" count={tasks.filter(t => t.status !== TaskStatus.COMPLETED).length} />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && (
              <div className="flex items-center gap-2 text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full border border-blue-100 animate-pulse">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Sync</span>
              </div>
            )}
            {view === 'INVENTORY' && (
              <button 
                type="button"
                onClick={() => setView('ADD_DEVICE')} 
                className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all active:scale-95"
              >
                + New Asset
              </button>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/50">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full space-y-4">
              <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Loading Clinical Index</p>
            </div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && (
                <DeviceList 
                  devices={devices} 
                  onSelectDevice={(d) => { setSelectedDeviceId(d.id); setView('DEVICE_DETAIL'); }} 
                  onUpdateDevice={handleUpsertDevices} 
                  onBulkUpdate={handleUpsertDevices}
                  onDelete={handleDeleteDevice} 
                  onAddDevice={() => setView('ADD_DEVICE')} 
                />
              )}
              {view === 'DEVICE_DETAIL' && selectedDevice && (
                <DeviceDetail 
                  device={selectedDevice} 
                  tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} 
                  onBack={() => { setView('INVENTORY'); setSelectedDeviceId(null); }} 
                  onUpdate={handleUpsertDevices} 
                  onDelete={handleDeleteDevice} 
                  onAddTask={handleAddTask} 
                />
              )}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} onDeleteTask={handleDeleteTask} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await handleUpsertDevices(d); setView('INVENTORY'); }} onBulkSave={async (ds) => { await handleUpsertDevices(ds); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleUpsertDevices} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={handleUpsertDevices} />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ active, onClick, icon, label, count }: any) => (
  <button onClick={onClick} className={`flex items-center justify-between w-full px-4 py-3 text-sm font-medium rounded-xl transition-all ${active ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
    <div className="flex items-center gap-3">{icon}{label}</div>
    {count !== undefined && count > 0 && (
      <span className="bg-red-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full shadow-sm">
        {count}
      </span>
    )}
  </button>
);

export default App;

import React, { useState } from 'react';
import { MedicalDevice, DeviceStatus, TaskPriority, TaskStatus, MedicalTask, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
