                           <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest border ${task.priority === TaskPriority.CRITICAL ? 'bg-red-50 text-red-600 border-red-100' : 'bg-slate-50 text-slate-500 border-slate-100'}`}>{task.priority}</span>
