             </button>
          </div>
        )}

        {(activeTab === 'maintenance' || activeTab === 'components') && (
           <div className="py-24 text-center">
              <div className="p-8 bg-white border-4 border-dashed border-slate-200 rounded-full w-fit mx-auto mb-6">
