      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();
      const isLocked = localStorage.getItem('meditrack_registry_lock') === 'true';

      // If we've never run or have an empty locked registry, don't seed.
      // Only seed if lock is missing AND DB is empty.
      if (!isLocked && localData.length === 0) {
        console.log("[Registry] Seeding initial mock asset.");
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_registry_lock', 'true');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      // Cloud Sync (Optional background sync)
      if (isSupabaseConfigured && supabase) {
        try {
          const { data: cloudData, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && cloudData && cloudData.length > 0) {
            setDevices(cloudData as MedicalDevice[]);
            await saveDevicesToDB(cloudData as MedicalDevice[]);
            localStorage.setItem('meditrack_registry_lock', 'true');
          }
        } catch (csError) {
          console.warn("[Registry] Cloud unreachable, using local index.");
        }
      }
    } catch (error) {
      console.error("[Registry] Core load failure:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;

    // 1. Mandatory Confirmation
    if (!window.confirm("PERMANENT ACTION: Remove this asset from the clinical registry?")) return;

    console.log(`[Registry] Purging asset: ${id}`);

    // 2. IMMEDIATE SYNCHRONOUS UI UPDATES
    // We update view and selection first to prevent "ghosting" in detail view
    setView('INVENTORY');
    setSelectedDeviceId(null);

    // Functional state update ensures we aren't using a stale 'devices' array
    setDevices(current => current.filter(d => String(d.id) !== String(id)));

    // 3. PERSISTENCE (Background)
    setIsSyncing(true);
    try {
      // Lock the registry so mock data never returns
      localStorage.setItem('meditrack_registry_lock', 'true');

      // Remove from IndexedDB
      await deleteDeviceFromDB(id);

      // Remove from Cloud
      if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from('devices').delete().eq('id', id);
        if (error) console.error("[Registry] Cloud delete failed:", error);
      }
      console.log(`[Registry] Successfully purged ${id}.`);
    } catch (error) {
      console.error("[Registry] Persistence error during deletion:", error);
    } finally {
      setIsSyncing(false);
    }
