  const loadAndSync = async () => {
    setIsLoading(true);
    try {
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();

      // Using a versioned and robust lock key
      const isLocked = localStorage.getItem('meditrack_registry_v3_lock') === 'ACTIVE';

      if (!isLocked && localData.length === 0) {
        console.log("[Registry] Initializing first-run master seeder...");
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
      } else {
        setDevices(localData);
      }
      setTasks(localTasks);

      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (!error && data && data.length > 0) {
            setDevices(data as MedicalDevice[]);
            await saveDevicesToDB(data as MedicalDevice[]);
            localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
          }
        } catch (e) {
