    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadAndSync();
  }, []);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;

    // 1. CONFIRMATION DIALOG (Mandatory)
    const deviceName = devices.find(d => String(d.id) === String(id))?.name || 'this asset';
    if (!window.confirm(`PERMANENT ACTION: Purge "${deviceName}" from the clinical registry?`)) return;

    console.log(`[Registry] Initiating atomic purge for: ${id}`);

    // 2. SYNCHRONOUS UI UPDATES (Immediate response)
    // We clear the selection and move view first to unmount any detail components
    setSelectedDeviceId(null);
    setView('INVENTORY');

    // Functional state update ensures the list is cleared immediately
    setDevices(prev => prev.filter(d => String(d.id).trim() !== String(id).trim()));

    // 3. DATABASE PERSISTENCE (Background)
    setIsSyncing(true);
    try {
      // Set the lock immediately to prevent re-seeding
      localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');

      // Purge from IndexedDB
      await deleteDeviceFromDB(id);

