            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden animate-fade-in">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-center w-12">
                   <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                      checked={filteredDevices.length > 0 && selectedIds.size === filteredDevices.length}
                      onChange={toggleAllSelection}
                    />
                </th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Detail</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Specs</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Unit</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredDevices.map((device) => (
                <tr 
                  key={device.id} 
                  className={`transition-all group ${selectedIds.has(device.id) ? 'bg-blue-50/60' : 'hover:bg-blue-50/40'}`}
                >
                  <td className="px-6 py-6 text-center align-middle">
                    <input 
                      type="checkbox" 
                      className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer" 
                      checked={selectedIds.has(device.id)}
                      onChange={(e) => { e.stopPropagation(); toggleSelection(device.id); }}
                    />
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 overflow-hidden shrink-0 flex items-center justify-center relative shadow-sm">
                        {device.image ? <img src={device.image} className="w-full h-full object-cover" alt="Asset" /> : <Box className="w-5 h-5 text-slate-300" />}
                        {device.isCNCAN && <div className="absolute top-0 right-0 p-0.5 bg-amber-500 rounded-bl-lg shadow-sm"><ShieldAlert className="w-2.5 h-2.5 text-white" /></div>}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 text-sm leading-tight">{device.name}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="text-xs font-bold text-slate-700 mb-1">{device.category}</div>
                    <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-lg font-mono text-[11px] font-bold tracking-tight shadow-sm border border-indigo-100">
                      <Fingerprint className="w-3.5 h-3.5 opacity-60" /> {device.serialNumber}
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department}</span>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <StatusBadge status={device.status} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        type="button"
                        className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all active:scale-90"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                   <td colSpan={6} className="py-20 text-center">
                      <div className="flex flex-col items-center gap-3 text-slate-300">
                         <Box className="w-12 h-12 opacity-20" />
                         <p className="text-xs font-black uppercase tracking-widest">No matching clinical assets</p>
                      </div>
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState } from 'react';
import { MedicalDevice, DeviceStatus, TaskPriority, TaskStatus, MedicalTask, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES } from '../types';
import { 
  Activity, Box, QrCode, Trash2, X, Edit2, 
  Info, CheckSquare, Loader2, Check, ChevronDown, Clock, 
  ShieldAlert, Cpu, Wrench, CheckCircle2, Fingerprint, Save, Camera, RotateCcw
} from 'lucide-react';

interface DeviceDetailProps {
  device: MedicalDevice;
  tasks: MedicalTask[];
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  onAddTask: (task: MedicalTask) => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, tasks, onUpdate, onDelete, onBack, onAddTask }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'components' | 'tasks' | 'qr'>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showTaskModal, setShowTaskModal] = useState(false);
  const [taskForm, setTaskForm] = useState({ title: '', description: '', priority: TaskPriority.MEDIUM });

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category,
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: device.department,
    status: device.status,
    isCNCAN: !!device.isCNCAN,
    notes: device.notes || '',
    image: device.image || ''
  });

  const handleCreateQuickTask = () => {
    const newTask: MedicalTask = {
      id: `TASK-${Date.now()}`,
      title: taskForm.title,
      description: taskForm.description,
      deviceId: device.id,
      deviceName: device.name,
      department: device.department,
      priority: taskForm.priority,
      status: TaskStatus.PENDING,
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddTask(newTask);
    setShowTaskModal(false);
    setTaskForm({ title: '', description: '', priority: TaskPriority.MEDIUM });
  };

  const handleDeleteRequest = async () => {
    if (isDeleting) return;

    // Parent handles the actual window.confirm and navigation
    // We just show a local state change until unmount
    setIsDeleting(true);
    try {
       await onDelete(device.id);
    } catch (err) {
       console.error("Purge action failed", err);
       setIsDeleting(false);
    }
  };

  const handleSaveEdit = async () => {
    const updatedDevice: MedicalDevice = {
      ...device,
      ...editForm
    };
    await onUpdate(updatedDevice);
    setIsEditing(false);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          const MAX_DIM = 1000; 
          if (width > height) { if (width > MAX_DIM) { height *= MAX_DIM / width; width = MAX_DIM; } }
          else { if (height > MAX_DIM) { width *= MAX_DIM / height; height = MAX_DIM; } }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error("Canvas missing"));
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.6));
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    });
  };

  const handleImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const compressed = await compressImage(e.target.files[0]);
        setEditForm(prev => ({ ...prev, image: compressed }));
      } catch (err) {
        console.error("Image processing error", err);
      }
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-full relative animate-fade-in">
      {showTaskModal && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 w-full max-w-md shadow-2xl border-4 border-white animate-fade-in">
             <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black uppercase tracking-tight">Add Device Ticket</h3>
                <button type="button" onClick={() => setShowTaskModal(false)} className="p-2 hover:bg-slate-100 rounded-xl transition text-slate-400"><X className="w-6 h-6" /></button>
             </div>
             <div className="space-y-4">
                <EditField label="Task / Issue" value={taskForm.title} onChange={(e:any) => setTaskForm({...taskForm, title: e.target.value})} />
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Description</label>
                   <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all min-h-[100px]" value={taskForm.description} onChange={(e:any) => setTaskForm({...taskForm, description: e.target.value})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Priority</label>
                   <select className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none appearance-none cursor-pointer" value={taskForm.priority} onChange={(e:any) => setTaskForm({...taskForm, priority: e.target.value as any})}>
                      {Object.values(TaskPriority).map(p => <option key={p} value={p}>{p}</option>)}
                   </select>
                </div>
                <button type="button" onClick={handleCreateQuickTask} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-indigo-700 shadow-xl transition active:scale-95">Log Asset Task</button>
             </div>
          </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-slate-50/50">
        <div>
          <button type="button" onClick={onBack} className="text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest mb-4 flex items-center gap-2 transition group">
            <span className="group-hover:-translate-x-1 transition-transform">←</span> Return to Inventory
          </button>
          <div className="flex items-center gap-4">
             <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase">{device.name}</h1>
          </div>
          <div className="flex flex-wrap items-center gap-4 mt-3">
            <span className="flex items-center gap-1.5 text-xs font-bold text-slate-500"><Box className="w-4 h-4 text-blue-500" /> {device.category}</span>
            <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-700 rounded-full text-[10px] font-mono font-black border border-indigo-100 shadow-sm uppercase tracking-tighter">
              <Fingerprint className="w-3.5 h-3.5 opacity-60" />
              SN: {device.serialNumber}
            </span>
            <StatusBadge status={device.status} />
          </div>
        </div>
        <div className="flex items-center gap-3 w-full lg:w-auto relative z-[100]">
           {isEditing ? (
             <>
               <button type="button" onClick={handleSaveEdit} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-green-600 text-white rounded-xl transition shadow-lg shadow-green-500/20 font-black text-xs uppercase tracking-widest hover:bg-green-700 active:scale-95"><Save className="w-4 h-4" /> Save Changes</button>
               <button type="button" onClick={() => { setIsEditing(false); setEditForm({...device, notes: device.notes || '', image: device.image || ''}); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-slate-200 text-slate-600 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-slate-300 active:scale-95">Cancel</button>
             </>
           ) : (
             <>
               <button type="button" onClick={() => { setIsEditing(true); setActiveTab('overview'); }} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl transition shadow-lg shadow-indigo-500/20 font-black text-xs uppercase tracking-widest hover:bg-indigo-700 active:scale-95"><Edit2 className="w-4 h-4" /> Edit Asset</button>
               <button 
                type="button" 
                onClick={handleDeleteRequest} 
                disabled={isDeleting}
                className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl transition font-black text-xs uppercase tracking-widest hover:bg-red-600 hover:text-white active:scale-95 shadow-sm disabled:opacity-50"
               >
                  {isDeleting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                  {isDeleting ? 'Purging...' : 'Purge Asset'}
               </button>
             </>
           )}
        </div>
      </div>

      <div className="flex border-b border-slate-100 px-8 bg-white overflow-x-auto no-scrollbar shadow-sm relative z-10">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Technical Overview" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Wrench className="w-4 h-4" />} label="Service Logs" />
        <TabButton active={activeTab === 'tasks'} onClick={() => setActiveTab('tasks')} icon={<CheckSquare className="w-4 h-4" />} label="Operations" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="Identity (QR)" />
      </div>

      <div className="p-8 overflow-y-auto flex-1 bg-slate-50/30 custom-scrollbar">
        {activeTab === 'overview' && (
           <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 max-w-7xl mx-auto">
              {isEditing ? (
                <div className="xl:col-span-8 space-y-8 animate-fade-in">
                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="font-black text-[10px] uppercase tracking-widest text-slate-400">Core Specifications</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <EditField label="Asset Name" name="name" value={editForm.name} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Class (Category)</label>
                        <select name="category" value={editForm.category} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none">
                          {DEVICE_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                      </div>
                      <EditField label="Serial Number" name="serialNumber" value={editForm.serialNumber} onChange={handleEditChange} />
                      <EditField label="Manufacturer" name="manufacturer" value={editForm.manufacturer} onChange={handleEditChange} />
                      <EditField label="Model Version" name="model" value={editForm.model} onChange={handleEditChange} />
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Unit (Department)</label>
