                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Documentation / Notes</label>
                       <textarea name="notes" value={editForm.notes} onChange={handleEditChange} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-sm font-medium min-h-[120px] focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all resize-none" />
