const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useMemo, useRef } from 'react';
import { MedicalDevice, DeviceStatus, TaskPriority, TaskStatus, MedicalTask, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES, DeviceFile } from '../types';
import { 
  Activity, Box, QrCode, Trash2, X, Edit2, 
  Info, CheckSquare, Loader2, Check, ChevronDown, Clock, 
  ShieldAlert, Cpu, Wrench, CheckCircle2, Fingerprint, Save, Camera, RotateCcw, FileText, Upload, DownloadCloud, Eye, Building2
} from 'lucide-react';

interface DeviceDetailProps {
  device: MedicalDevice;
  tasks: MedicalTask[];
  allDevices?: MedicalDevice[]; // To get fleet-wide depts
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  onAddTask: (task: MedicalTask) => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, tasks, allDevices = [], onUpdate, onDelete, onBack, onAddTask }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'docs' | 'tasks' | 'qr'>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [isPurging, setIsPurging] = useState(false);
  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadType, setUploadType] = useState<'manual' | 'report'>('report');

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category,
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: device.department,
    status: device.status,
    isCNCAN: !!device.isCNCAN,
    notes: device.notes || '',
    image: device.image || '',
    files: device.files || []
  });

  const allAvailableDepartments = useMemo(() => {
    const fleetDepts = allDevices.map(d => d.department);
    return Array.from(new Set([...HOSPITAL_DEPARTMENTS, ...fleetDepts, device.department])).sort();
  }, [allDevices, device.department]);

  const handleFinalPurge = async () => {
    setIsPurging(true);
    try {
      await onDelete(device.id);
    } catch (err) {
      console.error("Purge failure", err);
      setIsPurging(false);
      setShowPurgeConfirm(false);
    }
  };

  const handleSaveEdit = async () => {
    await onUpdate({ ...device, ...editForm });
    setIsEditing(false);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = event.target?.result as string;
        const newFile: DeviceFile = {
          id: `FILE-${Date.now()}`,
          name: file.name,
          type: uploadType,
          url: base64,
          dateAdded: new Date().toISOString().split('T')[0]
        };

        const updatedFiles = [...(editForm.files || []), newFile];
        setEditForm(prev => ({ ...prev, files: updatedFiles }));

        // If not explicitly editing, save immediately
        if (!isEditing) {
           await onUpdate({ ...device, files: updatedFiles });
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error("File upload failed", err);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleRemoveFile = async (fileId: string) => {
    const updatedFiles = editForm.files.filter(f => f.id !== fileId);
    setEditForm(prev => ({ ...prev, files: updatedFiles }));
    if (!isEditing) {
      await onUpdate({ ...device, files: updatedFiles });
    }
  };

  const viewFile = (file: DeviceFile) => {
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-full relative animate-fade-in">
      {showPurgeConfirm && (
        <div className="fixed inset-0 z-[600] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] p-12 max-w-lg w-full text-center shadow-2xl border-4 border-red-100 animate-fade-in">
              <div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-8">
                 <Trash2 className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-4">Confirm Atomic Purge</h3>
              <p className="text-sm text-slate-500 font-medium mb-10 leading-relaxed">
                 You are about to permanently remove <span className="font-black text-slate-900">{device.name}</span> and all associated service history.
              </p>
              <div className="flex gap-4">
                 <button disabled={isPurging} onClick={() => setShowPurgeConfirm(false)} className="flex-1 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Discard Request</button>
                 <button disabled={isPurging} onClick={handleFinalPurge} className="flex-[2] py-5 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-red-700 shadow-xl shadow-red-500/20 transition flex items-center justify-center gap-3">
                    {isPurging ? <Loader2 className="w-5 h-5 animate-spin" /> : <Trash2 className="w-5 h-5" />}
                    {isPurging ? "Purging..." : "Confirm Purge"}
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-slate-50/50">
        <div>
          <button onClick={onBack} className="text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest mb-4 flex items-center gap-2 transition group">
