             <>
               <button onClick={handleSaveEdit} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-green-600 text-white rounded-xl shadow-lg font-black text-xs uppercase tracking-widest active:scale-95 transition"><Save className="w-4 h-4" /> Save Data</button>
               <button onClick={() => setIsEditing(false)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-slate-200 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest active:scale-95 transition">Cancel</button>
             </>
           ) : (
             <>
               <button onClick={() => setIsEditing(true)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl shadow-lg font-black text-xs uppercase tracking-widest active:scale-95 transition"><Edit2 className="w-4 h-4" /> Edit Asset</button>
               <button onClick={() => setShowPurgeConfirm(true)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-red-600 hover:text-white transition active:scale-95"><Trash2 className="w-4 h-4" /> Purge Asset</button>
             </>
           )}
        </div>
      </div>

      <div className="flex border-b border-slate-100 px-8 bg-white overflow-x-auto no-scrollbar shadow-sm z-10">
        <TabButton active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} icon={<Activity className="w-4 h-4" />} label="Technical Details" />
        <TabButton active={activeTab === 'maintenance'} onClick={() => setActiveTab('maintenance')} icon={<Wrench className="w-4 h-4" />} label="Service Logs" />
        <TabButton active={activeTab === 'docs'} onClick={() => setActiveTab('docs')} icon={<FileText className="w-4 h-4" />} label="Archives & Docs" />
        <TabButton active={activeTab === 'tasks'} onClick={() => setActiveTab('tasks')} icon={<CheckSquare className="w-4 h-4" />} label="Operations" />
        <TabButton active={activeTab === 'qr'} onClick={() => setActiveTab('qr')} icon={<QrCode className="w-4 h-4" />} label="Identity" />
      </div>

      <div className="p-8 overflow-y-auto flex-1 bg-slate-50/30 custom-scrollbar">
        {activeTab === 'overview' && (
           <div className="grid grid-cols-1 xl:grid-cols-12 gap-8 max-w-7xl mx-auto">
              <div className="xl:col-span-8 space-y-8 animate-fade-in">
                <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-8">
                   <div className="flex items-center gap-4 mb-2">
                      <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl shadow-sm"><Info className="w-6 h-6" /></div>
                      <h3 className="font-black text-sm uppercase tracking-widest text-slate-400">Master Asset Card</h3>
                   </div>

                   {isEditing ? (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                        <div className="space-y-1">
                           <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Nomenclature</label>
                           <input name="name" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none" value={editForm.name} onChange={handleEditChange} />
                        </div>
                        <div className="space-y-1">
                           <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Serial Number</label>
                           <input name="serialNumber" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none" value={editForm.serialNumber} onChange={handleEditChange} />
