        {activeTab === 'docs' && (
          <div className="max-w-5xl mx-auto py-6 space-y-8 animate-fade-in">
             <div className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm">
                <div>
                   <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Technical Archives</h3>
