             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {(editForm.files || []).length > 0 ? editForm.files.map(file => (
                  <div key={file.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all group">
