  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setQuickEditForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSaveQuickEdit = async () => {
    if (!editingDevice) return;
    const updated: MedicalDevice = { ...editingDevice, ...quickEditForm };
    await onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    onDelete(deviceId);
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  return (
    <div className="space-y-6 pb-24 relative">
      {/* QUICK EDIT OVERLAY */}
      {editingDevice && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-xl shadow-2xl border-4 border-white animate-fade-in">
             <div className="flex justify-between items-center mb-8">
                <div>
                   <h3 className="text-xl font-black uppercase tracking-tight">Registry Quick Update</h3>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">ID: {editingDevice.id}</p>
                </div>
                <button onClick={() => setEditingDevice(null)} className="p-3 hover:bg-slate-100 rounded-2xl transition text-slate-400"><X className="w-6 h-6" /></button>
