import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { LayoutDashboard, List, Stethoscope, Menu, X, ShieldCheck, Loader2, CheckSquare, Settings as SettingsIcon, CalendarRange } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import Settings from './components/Settings';
import TaskTracker from './components/TaskTracker';
import { MedicalDevice, MedicalTask, ViewState, DeviceStatus, MaintenanceType, TaskStatus, TaskPriority } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB, deleteDeviceFromDB, getAllTasksFromDB, saveTasksToDB, deleteTaskFromDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    category: 'Echipament Imagistica',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    isCNCAN: true,
    notes: 'Primary MRI for emergency ward.',
    files: [],
    maintenanceHistory: [],
    contracts: [],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => {
    if (!selectedDeviceId) return null;
    return devices.find(d => String(d.id).trim() === String(selectedDeviceId).trim()) || null;
  }, [devices, selectedDeviceId]);

  const loadAndSync = useCallback(async () => {
    setIsLoading(true);
    try {
      // 1. Load from IndexedDB first for speed
      const localData = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();

      const isLocked = localStorage.getItem('meditrack_registry_v3_lock') === 'ACTIVE';

      let finalDevices = localData;

      if (!isLocked && localData.length === 0) {
        console.log("[Registry] Initializing with mock data.");
        finalDevices = MOCK_DEVICES;
        await saveDevicesToDB(MOCK_DEVICES);
        localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
      }

      setDevices(finalDevices);
      setTasks(localTasks);

      // 2. Try to sync with Supabase if configured
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (error) throw error;

          if (data && data.length > 0) {
            console.log(`[Sync] Found ${data.length} records in cloud.`);
            setDevices(data as MedicalDevice[]);
            await saveDevicesToDB(data as MedicalDevice[]);
            localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
          }
        } catch (e) { 
          console.warn("[Sync] Cloud sync deferred. Operating in local mode.", e); 
        }
      }
    } catch (err) {
      console.error("[Registry] Failed to initialize data engine.", err);
    } finally { 
      setIsLoading(false); 
    }
  }, []);

  useEffect(() => { loadAndSync(); }, [loadAndSync]);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;

    // Force view transition first to avoid hanging components
    setSelectedDeviceId(null);
    setView('INVENTORY');

    // Update local state synchronously for instant UI update
    setDevices(prev => prev.filter(d => String(d.id).trim() !== String(id).trim()));

    // Persistent Background Cleanup
    setIsSyncing(true);
    try {
      await deleteDeviceFromDB(id);
      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().eq('id', id);
      }
    } catch (error) {
      console.error("[Registry] Background purge failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSupabaseConfigured]);

  const handleUpsertDevices = useCallback(async (data: MedicalDevice | MedicalDevice[]) => {
    const payload = Array.isArray(data) ? data : [data];
    if (payload.length === 0) return;

    // Update local state for immediate feedback
    setDevices(prev => {
      const map = new Map(prev.map(d => [String(d.id).trim(), d]));
      payload.forEach(p => map.set(String(p.id).trim(), p));
      return Array.from(map.values());
    });

    setIsSyncing(true);
    try {
      localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
      await saveDevicesToDB(payload);
      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').upsert(payload, { onConflict: 'id' });
      }
    } catch (err) {
      console.error("[Registry] Cloud upsert deferred.", err);
    } finally { 
      setIsSyncing(false); 
    }
  }, [isSupabaseConfigured]);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar navigation */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-bold tracking-tight text-white">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-20">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-3 py-1 rounded-full"><Loader2 className="w-3 h-3 animate-spin" /> Syncing</div>}
            {view === 'INVENTORY' && <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg active:scale-95 transition hover:bg-blue-700">+ New Asset</button>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 relative">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full space-y-4 animate-fade-in">
              <Loader2 className="w-12 h-12 text-blue-600 animate-spin" />
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Booting Data Engine...</p>
            </div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={(d) => { setSelectedDeviceId(d.id); setView('DEVICE_DETAIL'); }} onUpdateDevice={handleUpsertDevices} onBulkUpdate={handleUpsertDevices} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} />}
              {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} allDevices={devices} tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} onBack={() => { setView('INVENTORY'); setSelectedDeviceId(null); }} onUpdate={handleUpsertDevices} onDelete={handleDeleteDevice} onAddTask={(t) => setTasks(prev => [t, ...prev])} />}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={(t) => setTasks(prev => [t, ...prev])} onUpdateTask={(t) => setTasks(prev => prev.map(tk => tk.id === t.id ? t : tk))} onDeleteTask={(id) => setTasks(prev => prev.filter(t => t.id !== id))} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await handleUpsertDevices(d); setView('INVENTORY'); }} onBulkSave={async (ds) => { await handleUpsertDevices(ds); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleUpsertDevices} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={handleUpsertDevices} />}
            </div>
          )}
        </div>
      </main>

      {/* Sidebar Close Overlay (Mobile) */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/40 z-20 lg:hidden backdrop-blur-sm" onClick={() => setSidebarOpen(false)} />
      )}
    </div>
  );
};

const NavItem = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex items-center gap-3 w-full px-4 py-3 text-sm font-medium rounded-xl transition-all ${active ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}>
    {icon}{label}
  </button>
);

export default App;

