  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => {
    if (!selectedDeviceId) return null;
    return devices.find(d => String(d.id).trim() === String(selectedDeviceId).trim()) || null;
  }, [devices, selectedDeviceId]);

  const normalizeDevice = (d: any): MedicalDevice => ({
    ...d,
    id: String(d.id),
    name: d.name || 'Unnamed Asset',
    category: d.category || 'Altele',
    status: d.status || DeviceStatus.ACTIVE,
    department: d.department || 'Unassigned',
    manufacturer: d.manufacturer || 'Unknown',
    model: d.model || 'N/A',
    serialNumber: d.serialNumber || 'N/A',
    maintenanceHistory: Array.isArray(d.maintenanceHistory) ? d.maintenanceHistory : [],
    contracts: Array.isArray(d.contracts) ? d.contracts : [],
    files: Array.isArray(d.files) ? d.files : [],
    components: Array.isArray(d.components) ? d.components : []
  });

  const loadAndSync = useCallback(async () => {
    setIsLoading(true);
    setSyncStatus('local');
    try {
      // 1. Load from IndexedDB
      const localDevices = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();

      let currentDevices = localDevices.map(normalizeDevice);
      setDevices(currentDevices);
      setTasks(localTasks);

      // 2. Cloud Sync Attempt
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (error) throw error;

          if (data && data.length > 0) {
            const cloudDevices = data.map(normalizeDevice);

            // Merge logic: Prioritize Cloud data over local for existing IDs
            const deviceMap = new Map();
            currentDevices.forEach(d => deviceMap.set(d.id, d));
            cloudDevices.forEach(d => deviceMap.set(d.id, d));

            const merged = Array.from(deviceMap.values());
            setDevices(merged);
            await saveDevicesToDB(merged);
            setSyncStatus('cloud');
          } else if (currentDevices.length === 0) {
            // No cloud data and no local data? Use Mocks.
            setDevices(MOCK_DEVICES);
            await saveDevicesToDB(MOCK_DEVICES);
          }
        } catch (e) { 
          console.warn("[App] Cloud sync deferred:", e);
          setSyncStatus('error');
          // If totally empty and cloud failed, ensure mocks exist
          if (currentDevices.length === 0) {
            setDevices(MOCK_DEVICES);
            await saveDevicesToDB(MOCK_DEVICES);
          }
        }
      } else if (currentDevices.length === 0) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
      }
    } catch (err) {
      console.error("[App] Critical load failure:", err);
      setSyncStatus('error');
    } finally { 
      setIsLoading(false); 
      localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
    }
  }, []);

  useEffect(() => { loadAndSync(); }, [loadAndSync]);

