                <div className="flex-1">
                   <p className="text-[9px] font-black uppercase tracking-widest">{syncStatus === 'cloud' ? 'Main Registry' : 'Local Node'}</p>
                   <p className="text-[10px] font-bold">{syncStatus === 'cloud' ? 'Cloud Connected' : syncStatus === 'error' ? 'Sync Deferred' : 'Loading...'}</p>
                </div>
             </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-50">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
            {isSyncing && <div className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-3 py-1 rounded-full"><Loader2 className="w-3 h-3 animate-spin" /> Committing</div>}
            <button onClick={loadAndSync} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" title="Refresh Registry"><RefreshCw className={`w-5 h-5 ${isLoading ? 'animate-spin' : ''}`} /></button>
            {view === 'INVENTORY' && <button onClick={() => setView('ADD_DEVICE')} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 active:scale-95 transition hover:bg-blue-700">+ New Asset</button>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 relative custom-scrollbar">
          {isLoading ? (
            <div className="flex flex-col items-center justify-center h-full space-y-4 animate-fade-in">
              <div className="relative">
                 <Loader2 className="w-16 h-16 text-blue-600 animate-spin" />
                 <Stethoscope className="w-6 h-6 text-blue-400 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
              </div>
              <p className="text-xs font-black uppercase tracking-widest text-slate-400">Booting Data Engine...</p>
            </div>
          ) : (
            <div className="max-w-7xl mx-auto">
              {view === 'DASHBOARD' && <Dashboard devices={devices} tasks={tasks} />}
              {view === 'INVENTORY' && <DeviceList devices={devices} onSelectDevice={(d) => { setSelectedDeviceId(d.id); setView('DEVICE_DETAIL'); }} onUpdateDevice={handleUpsertDevices} onBulkUpdate={handleUpsertDevices} onDelete={handleDeleteDevice} onAddDevice={() => setView('ADD_DEVICE')} />}
              {view === 'DEVICE_DETAIL' && selectedDevice && <DeviceDetail device={selectedDevice} allDevices={devices} tasks={tasks.filter(t => t.deviceId === selectedDevice.id)} onBack={() => { setView('INVENTORY'); setSelectedDeviceId(null); }} onUpdate={handleUpsertDevices} onDelete={handleDeleteDevice} onAddTask={(t) => setTasks(prev => [t, ...prev])} />}
              {view === 'TASKS' && <TaskTracker tasks={tasks} devices={devices} onAddTask={(t) => setTasks(prev => [t, ...prev])} onUpdateTask={(t) => setTasks(prev => prev.map(tk => tk.id === t.id ? t : tk))} onDeleteTask={(id) => setTasks(prev => prev.filter(t => t.id !== id))} />}
              {view === 'ADD_DEVICE' && <AddDeviceForm devices={devices} onSave={async (d) => { await handleUpsertDevices(d); setView('INVENTORY'); }} onBulkSave={async (ds) => { await handleUpsertDevices(ds); setView('INVENTORY'); }} onCancel={() => setView('INVENTORY')} />}
              {view === 'PLANNER' && <MaintenancePlanner devices={devices} onApplyPlan={handleUpsertDevices} />}
              {view === 'SETTINGS' && <Settings devices={devices} onImport={handleUpsertDevices} />}
            </div>
          )}
        </div>
      </main>

      {isSidebarOpen && (
        <div className="fixed inset-0 bg-slate-900/60 z-[90] lg:hidden backdrop-blur-sm animate-fade-in" onClick={() => setSidebarOpen(false)} />
      )}
    </div>
  );
};

