import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { LayoutDashboard, List, Stethoscope, Menu, X, ShieldCheck, Loader2, CheckSquare, Settings as SettingsIcon, CalendarRange, RefreshCw, Cloud, CloudOff, Database } from 'lucide-react';
import Dashboard from './components/Dashboard';
import DeviceList from './components/DeviceList';
import DeviceDetail from './components/DeviceDetail';
import AddDeviceForm from './components/AddDeviceForm';
import MaintenancePlanner from './components/MaintenancePlanner';
import Settings from './components/Settings';
import TaskTracker from './components/TaskTracker';
import { MedicalDevice, MedicalTask, ViewState, DeviceStatus, MaintenanceType, TaskStatus, TaskPriority } from './types';
import { supabase, isSupabaseConfigured } from './services/supabase';
import { getAllDevicesFromDB, saveDevicesToDB, deleteDeviceFromDB, getAllTasksFromDB, saveTasksToDB, deleteTaskFromDB } from './services/storageService';

const MOCK_DEVICES: MedicalDevice[] = [
  {
    id: 'DEV-INITIAL-001',
    name: 'MRI Scanner Elite X',
    category: 'Echipament Imagistica',
    manufacturer: 'Siemens Healthineers',
    model: 'Magnetom Vida',
    serialNumber: 'SN-9982-X2',
    department: 'Radiology',
    purchaseDate: '2022-03-15',
    status: DeviceStatus.ACTIVE,
    isCNCAN: true,
    notes: 'Primary MRI for emergency ward.',
    files: [],
    maintenanceHistory: [],
    contracts: [],
    components: []
  }
];

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'cloud' | 'local' | 'error'>('local');
  const [devices, setDevices] = useState<MedicalDevice[]>([]);
  const [tasks, setTasks] = useState<MedicalTask[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  const selectedDevice = useMemo(() => {
    if (!selectedDeviceId) return null;
    return devices.find(d => String(d.id).trim() === String(selectedDeviceId).trim()) || null;
  }, [devices, selectedDeviceId]);

  const normalizeDevice = useCallback((d: any): MedicalDevice => {
    // Force ID to string and trim to prevent key mismatches in the Map
    const safeId = String(d.id || d.ID || crypto.randomUUID()).trim();
    return {
      ...d,
      id: safeId,
      name: d.name || d.Name || 'Unnamed Asset',
      category: d.category || d.Category || 'Altele',
      status: d.status || d.Status || DeviceStatus.ACTIVE,
      department: d.department || d.Department || 'Unassigned',
      manufacturer: d.manufacturer || d.Manufacturer || 'Unknown',
      model: d.model || d.Model || 'N/A',
      serialNumber: d.serialNumber || d.SerialNumber || 'N/A',
      maintenanceHistory: Array.isArray(d.maintenanceHistory) ? d.maintenanceHistory : [],
      contracts: Array.isArray(d.contracts) ? d.contracts : [],
      files: Array.isArray(d.files) ? d.files : [],
      components: Array.isArray(d.components) ? d.components : []
    } as MedicalDevice;
  }, []);

  const loadAndSync = useCallback(async () => {
    setIsLoading(true);
    setSyncStatus('local');
    try {
      // 1. GATHER ALL SOURCES
      // Source A: IndexedDB (Current Standard)
      const localDevices = await getAllDevicesFromDB();
      const localTasks = await getAllTasksFromDB();

      // Source B: Legacy LocalStorage (Old Versions)
      let legacyDevices: any[] = [];
      try {
        const stored = localStorage.getItem('meditrack_devices');
        if (stored) legacyDevices = JSON.parse(stored);
      } catch (e) { console.warn("Legacy load failed", e); }

      // 2. MERGE LOCAL SOURCES
      const deviceMap = new Map<string, MedicalDevice>();

      // Prioritize IndexedDB, then Legacy
      [...legacyDevices, ...localDevices].forEach(d => {
        const normalized = normalizeDevice(d);
        deviceMap.set(normalized.id, normalized);
      });

      let currentDevices = Array.from(deviceMap.values());
      setDevices(currentDevices);
      setTasks(localTasks);

      // 3. CLOUD SYNC
      if (isSupabaseConfigured && supabase) {
        try {
          const { data, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
          if (error) throw error;

          if (data && data.length > 0) {
            console.log(`[Sync] Merging ${data.length} cloud records.`);
            const cloudDevices = data.map(normalizeDevice);

            // Final Merge: Cloud data wins for the same ID
            cloudDevices.forEach(d => deviceMap.set(d.id, d));

            const finalMerged = Array.from(deviceMap.values());
            setDevices(finalMerged);
            await saveDevicesToDB(finalMerged);
            setSyncStatus('cloud');
          } else {
            // Cloud is empty but we have local? Sync local TO cloud
            if (currentDevices.length > 0) {
              console.log("[Sync] Pushing local data to empty cloud.");
              await supabase.from('devices').upsert(currentDevices);
            } else {
              // Both empty? Load mocks.
              setDevices(MOCK_DEVICES);
              await saveDevicesToDB(MOCK_DEVICES);
              await supabase.from('devices').upsert(MOCK_DEVICES);
            }
            setSyncStatus('cloud');
          }
        } catch (e) { 
          console.warn("[App] Cloud sync deferred. Operating on cached data.", e);
          setSyncStatus('error');
          if (currentDevices.length === 0) {
            setDevices(MOCK_DEVICES);
            await saveDevicesToDB(MOCK_DEVICES);
          }
        }
      } else if (currentDevices.length === 0) {
        setDevices(MOCK_DEVICES);
        await saveDevicesToDB(MOCK_DEVICES);
      }
    } catch (err) {
      console.error("[App] Critical engine failure:", err);
      setSyncStatus('error');
    } finally { 
      setIsLoading(false); 
      localStorage.setItem('meditrack_registry_v3_lock', 'ACTIVE');
    }
  }, [normalizeDevice]);

  useEffect(() => { loadAndSync(); }, [loadAndSync]);

  const handleDeleteDevice = useCallback(async (id: string) => {
    if (!id) return;
    const safeId = String(id).trim();
    setSelectedDeviceId(null);
    setView('INVENTORY');
    setDevices(prev => prev.filter(d => d.id !== safeId));

    setIsSyncing(true);
    try {
      await deleteDeviceFromDB(safeId);
      if (isSupabaseConfigured && supabase) {
        await supabase.from('devices').delete().eq('id', safeId);
      }
    } catch (error) {
      console.error("[Registry] Purge failed:", error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSupabaseConfigured]);

  // FIX: Added explicit type annotations to 'prev' parameter in setDevices and 'payload' array to fix property 'id' access error and ensure assignability to saveDevicesToDB
  const handleUpsertDevices = useCallback(async (data: MedicalDevice | MedicalDevice[]) => {
    const items = Array.isArray(data) ? data : [data];
    const payload: MedicalDevice[] = items.map(normalizeDevice);
    if (payload.length === 0) return;

    setDevices((prev: MedicalDevice[]) => {
      const map = new Map<string, MedicalDevice>(prev.map((d: MedicalDevice) => [d.id, d]));
      payload.forEach((p: MedicalDevice) => map.set(p.id, p));
      return Array.from(map.values());
    });

    setIsSyncing(true);
    try {
      await saveDevicesToDB(payload);
      if (isSupabaseConfigured && supabase) {
        const { error } = await supabase.from('devices').upsert(payload, { onConflict: 'id' });
        if (error) throw error;
      }
    } catch (err) {
      console.error("[Registry] Sync deferred:", err);
    } finally { 
      setIsSyncing(false); 
    }
  }, [isSupabaseConfigured, normalizeDevice]);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <aside className={`fixed lg:static inset-y-0 left-0 z-[100] w-64 bg-slate-900 text-white transform transition-transform duration-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-full flex flex-col">
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-500/20"><Stethoscope className="w-6 h-6 text-white" /></div>
            <h1 className="text-xl font-black tracking-tight text-white uppercase">MediTrack</h1>
          </div>
          <nav className="flex-1 p-4 space-y-2">
            <NavItem active={view === 'DASHBOARD'} onClick={() => { setView('DASHBOARD'); setSidebarOpen(false); }} icon={<LayoutDashboard className="w-5 h-5" />} label="Dashboard" />
            <NavItem active={view === 'INVENTORY'} onClick={() => { setView('INVENTORY'); setSidebarOpen(false); }} icon={<List className="w-5 h-5" />} label="Inventory" />
            <NavItem active={view === 'TASKS'} onClick={() => { setView('TASKS'); setSidebarOpen(false); }} icon={<CheckSquare className="w-5 h-5" />} label="Tasks" />
            <NavItem active={view === 'PLANNER'} onClick={() => { setView('PLANNER'); setSidebarOpen(false); }} icon={<CalendarRange className="w-5 h-5" />} label="Planner" />
            <NavItem active={view === 'SETTINGS'} onClick={() => { setView('SETTINGS'); setSidebarOpen(false); }} icon={<SettingsIcon className="w-5 h-5" />} label="Settings" />
          </nav>

          <div className="p-4 border-t border-slate-800">
             <div className={`p-4 rounded-2xl flex items-center gap-3 ${syncStatus === 'cloud' ? 'bg-green-500/10 text-green-400' : syncStatus === 'error' ? 'bg-red-500/10 text-red-400' : 'bg-blue-500/10 text-blue-400'}`}>
                {syncStatus === 'cloud' ? <Cloud className="w-4 h-4" /> : syncStatus === 'error' ? <CloudOff className="w-4 h-4" /> : <RefreshCw className="w-4 h-4 animate-spin" />}
                <div className="flex-1">
                   <p className="text-[9px] font-black uppercase tracking-widest">{syncStatus === 'cloud' ? 'Main Registry' : 'Local Node'}</p>
                   <p className="text-[10px] font-bold">{syncStatus === 'cloud' ? 'Cloud Connected' : syncStatus === 'error' ? 'Sync Deferred' : 'Loading...'}</p>
                </div>
             </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-50">
          <div className="flex items-center gap-3">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><Menu className="w-6 h-6" /></button>
             <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight">{view.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4">
