/**
 * Verifies if the connection to Supabase is active and the 'devices' table exists.
 */
export const checkConnection = async (): Promise<{ success: boolean; message: string; errorType?: 'auth' | 'table' | 'network' }> => {
  if (!supabase) return { success: false, message: "Supabase client not initialized.", errorType: 'network' };

  try {
    // Attempt to fetch a single row to test table existence and connectivity
    const { error, data } = await supabase.from('devices').select('id').limit(1);

    if (error) {
      if (error.code === '42P01') return { success: false, message: "Table 'devices' does not exist in your database.", errorType: 'table' };
      if (error.code === 'PGRST301') return { success: false, message: "Authentication failed. Check your API Key.", errorType: 'auth' };
      return { success: false, message: error.message, errorType: 'network' };
    }

    return { success: true, message: "Connection established successfully." };
  } catch (err: any) {
    return { success: false, message: err.message || "Unknown connection error.", errorType: 'network' };
  }
};

/**
 * Uploads a file to Supabase Storage if configured, returning the public URL.
 */
export const uploadDeviceFile = async (file: File | Blob, fileName: string): Promise<string | null> => {
  if (!supabase) return null;

  const bucketName = 'device-files';
  const filePath = `${Date.now()}_${fileName}`;

  try {
    const { data, error } = await supabase.storage
      .from(bucketName)
      .upload(filePath, file, {
        cacheControl: '3600',
        upsert: false
      });

    if (error) {
      console.warn("Storage upload failed, likely bucket 'device-files' not found:", error);
      return null;
    }

    const { data: { publicUrl } } = supabase.storage
      .from(bucketName)
      .getPublicUrl(filePath);

    return publicUrl;
  } catch (err) {
    console.error("Critical storage error:", err);
    return null;
  }
};

