      let legacyDevices: any[] = [];
      try {
        const stored = localStorage.getItem('meditrack_devices');
        if (stored) legacyDevices = JSON.parse(stored);
      } catch (e) {}

      const deviceMap = new Map<string, MedicalDevice>();
      [...legacyDevices, ...localDevices].forEach(d => {
        const normalized = normalizeDevice(d);
        deviceMap.set(normalized.id, normalized);
      });

      let currentLocalDevices = Array.from(deviceMap.values());
      setDevices(currentLocalDevices);
      setTasks(localTasks);

      // 2. Deep Connection Diagnostics
      if (isSupabaseConfigured && supabase) {
        const connection = await checkConnection();

        if (!connection.success) {
          console.warn("[App] Supabase offline:", connection.message);
          setSyncStatus(connection.errorType === 'table' ? 'table-missing' : 'error');
          // If local is empty and cloud failed, provide mocks
          if (currentLocalDevices.length === 0) {
            setDevices(MOCK_DEVICES);
            await saveDevicesToDB(MOCK_DEVICES);
          }
          return;
        }

        // 3. Perform Sync if connection is healthy
        try {
          const { data, error } = await supabase.from('devices').select('*').order('id', { ascending: true });
