             <div className={`p-4 rounded-2xl flex items-center gap-3 ${syncStatus === 'cloud' ? 'bg-green-500/10 text-green-400' : syncStatus === 'table-missing' ? 'bg-amber-500/10 text-amber-400' : syncStatus === 'error' ? 'bg-red-500/10 text-red-400' : 'bg-blue-500/10 text-blue-400'}`}>
