                   <p className="text-[10px] font-bold">
                     {syncStatus === 'cloud' ? 'Cloud Connected' : syncStatus === 'table-missing' ? 'Table Missing' : syncStatus === 'error' ? 'Sync Deferred' : 'Loading...'}
