/**
 * Enhanced check to specifically identify "Paused" or "Resuming" states
 */
export const checkConnection = async (): Promise<{ success: boolean; message: string; errorType?: 'auth' | 'table' | 'network' | 'paused' }> => {
  if (!supabase) return { success: false, message: "Supabase client not initialized.", errorType: 'network' };

  try {
    const { error } = await supabase.from('devices').select('id').limit(1);

    if (error) {
      console.error("[Supabase Diagnostic] Error code:", error.code, "Message:", error.message);

      // PGRST301 is usually auth, but 503/404 can happen during pause/resume
      if (error.code === '42P01') return { success: false, message: "Table 'devices' not found. Ensure migration script was run.", errorType: 'table' };
      if (error.code === 'PGRST301') return { success: false, message: "Authentication failed. Check keys.", errorType: 'auth' };

      // Pause detection: Supabase often returns 503 or empty responses when paused
      if (error.message.includes('Service Unavailable') || error.message.includes('paused') || error.code === '503') {
        return { success: false, message: "Project is currently paused or waking up.", errorType: 'paused' };
      }

      return { success: false, message: error.message, errorType: 'network' };
    }

    return { success: true, message: "Cloud connection healthy." };
  } catch (err: any) {
    return { success: false, message: err.message || "Unknown error.", errorType: 'network' };
  }
};

