export default DeviceDetail;

import React, { useState, useMemo } from 'react';
import { MedicalDevice, DeviceStatus, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES, DeviceCategory } from '../types';
import { Search, Eye, Trash2, Box, FileSpreadsheet, Download, Edit2, X, Check, ChevronDown, Calendar, Info, Filter, PlusCircle, ShieldAlert, Hash, Fingerprint, AlertCircle, ShieldOff, RotateCcw, Layers, Loader2, FileText, Save, Building2, Tag, Plus } from 'lucide-react';

declare var XLSX: any; 

interface DeviceListProps {
  devices: MedicalDevice[];
  onSelectDevice: (device: MedicalDevice) => void;
  onUpdateDevice: (device: MedicalDevice) => void;
  onBulkUpdate: (devices: MedicalDevice[]) => void;
  onAddDevice: () => void;
  onDelete: (id: string) => void;
  searchQuery?: string;
}

const DeviceList: React.FC<DeviceListProps> = ({ devices, onSelectDevice, onUpdateDevice, onBulkUpdate, onAddDevice, onDelete, searchQuery: externalSearch = '' }) => {
  const [filterStatus, setFilterStatus] = useState<DeviceStatus | 'ALL'>('ALL');
  const [filterDept, setFilterDept] = useState<string | 'ALL'>('ALL');
  const [filterCategory, setFilterCategory] = useState<string | 'ALL'>('ALL');
  const [localSearch, setLocalSearch] = useState('');

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [editingDevice, setEditingDevice] = useState<MedicalDevice | null>(null);

  const [quickEditForm, setQuickEditForm] = useState({
    name: '',
    serialNumber: '',
    department: '',
    status: DeviceStatus.ACTIVE,
  });

  // Dynamic department list from existing fleet + static list
  const allAvailableDepartments = useMemo(() => {
    const existingDepts = (devices || []).map(d => d.department).filter(Boolean);
    const combined = Array.from(new Set([...HOSPITAL_DEPARTMENTS, ...existingDepts])).sort();
    return combined;
  }, [devices]);

  const effectiveSearch = (localSearch || externalSearch).toLowerCase().trim();

  const filteredDevices = useMemo(() => {
    if (!devices) return [];
    return devices.filter(d => {
      const name = (d.name || '').toLowerCase();
      const sn = (d.serialNumber || '').toLowerCase();
      const mfr = (d.manufacturer || '').toLowerCase();
      const model = (d.model || '').toLowerCase();
      const dept = (d.department || '').toLowerCase();
      const cat = (d.category || '').toLowerCase();

      const matchSearch = !effectiveSearch || 
        name.includes(effectiveSearch) || 
        sn.includes(effectiveSearch) ||
        mfr.includes(effectiveSearch) ||
        model.includes(effectiveSearch) ||
        dept.includes(effectiveSearch) ||
        cat.includes(effectiveSearch);

      const matchStatus = filterStatus === 'ALL' || d.status === filterStatus;
      const matchDept = filterDept === 'ALL' || d.department === filterDept;
      const matchCategory = filterCategory === 'ALL' || d.category === filterCategory;

      return matchSearch && matchStatus && matchDept && matchCategory;
    });
  }, [devices, effectiveSearch, filterStatus, filterDept, filterCategory]);

  const handleOpenQuickEdit = (e: React.MouseEvent, device: MedicalDevice) => {
    e.preventDefault();
    e.stopPropagation();

    setEditingDevice(device);
    setQuickEditForm({
      name: device.name || '',
      serialNumber: device.serialNumber || '',
      department: device.department || HOSPITAL_DEPARTMENTS[0],
      status: device.status || DeviceStatus.ACTIVE,
    });
  };

  const handleQuickEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setQuickEditForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSaveQuickEdit = async () => {
    if (!editingDevice) return;
    const updated: MedicalDevice = { ...editingDevice, ...quickEditForm };
    await onUpdateDevice(updated);
    setEditingDevice(null);
  };

  const handleDeleteClick = (e: React.MouseEvent, deviceId: string) => {
    e.preventDefault();
    e.stopPropagation();
    onDelete(deviceId);
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  return (
    <div className="space-y-6 pb-24 relative animate-fade-in">
      {/* QUICK EDIT OVERLAY */}
      {editingDevice && (
        <div className="fixed inset-0 z-[500] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-xl shadow-2xl border-4 border-white animate-fade-in">
             <div className="flex justify-between items-center mb-8">
                <div>
                   <h3 className="text-xl font-black uppercase tracking-tight">Registry Quick Update</h3>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">ID: {editingDevice.id}</p>
                </div>
                <button onClick={() => setEditingDevice(null)} className="p-3 hover:bg-slate-100 rounded-2xl transition text-slate-400"><X className="w-6 h-6" /></button>
             </div>

             <div className="space-y-6 mb-10">
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Asset Nomenclature</label>
                   <input name="name" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none" value={quickEditForm.name} onChange={handleQuickEditChange} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Serial Identifier</label>
                   <input name="serialNumber" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none" value={quickEditForm.serialNumber} onChange={handleQuickEditChange} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Unit Assignment</label>
                    <div className="relative">
                      <select name="department" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold appearance-none" value={quickEditForm.department} onChange={handleQuickEditChange}>
                          {allAvailableDepartments.map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                      <Building2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 pointer-events-none" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Registry Status</label>
                    <select name="status" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none" value={quickEditForm.status} onChange={handleQuickEditChange}>
                        {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
                    </select>
                  </div>
                </div>
             </div>

             <div className="flex gap-4">
                <button onClick={() => setEditingDevice(null)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Discard</button>
                <button onClick={handleSaveQuickEdit} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-blue-700 shadow-xl shadow-blue-500/20 transition active:scale-95 flex items-center justify-center gap-3">
                   <Save className="w-5 h-5" /> Commit Data
                </button>
             </div>
          </div>
        </div>
      )}

      {/* FILTER CONTROLS */}
      <div className="bg-white p-6 rounded-[2.5rem] shadow-lg border border-slate-100 flex flex-col gap-6">
        <div className="flex flex-col lg:flex-row items-center gap-4 w-full">
          <div className="relative flex-1 w-full group">
            <Search className={`absolute left-5 top-1/2 -translate-y-1/2 w-5 h-5 transition-colors ${effectiveSearch ? 'text-blue-600' : 'text-slate-300'}`} />
            <input 
              type="text"
              placeholder="Search registry by name, category, serial, or unit..."
              className="w-full pl-14 pr-6 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 focus:bg-white rounded-2xl text-sm font-bold focus:outline-none transition-all shadow-inner"
              value={localSearch}
              onChange={(e) => setLocalSearch(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setLocalSearch(''); setFilterStatus('ALL'); setFilterDept('ALL'); setFilterCategory('ALL'); }}
            className="px-4 py-4 bg-slate-50 text-slate-400 rounded-2xl hover:text-blue-600 hover:bg-blue-50 transition-all shadow-inner flex items-center justify-center"
            title="Reset Filters"
          >
            <RotateCcw className="w-5 h-5" />
          </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3 w-full">
          <select className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none uppercase tracking-wider shadow-inner" value={filterDept} onChange={(e) => setFilterDept(e.target.value)}>
            <option value="ALL">ALL DEPTS</option>
            {allAvailableDepartments.map(dept => <option key={dept} value={dept}>{dept.toUpperCase()}</option>)}
          </select>
          <select className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none uppercase tracking-wider shadow-inner" value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)}>
            <option value="ALL">ALL CATEGORIES</option>
            {DEVICE_CATEGORIES.map(cat => <option key={cat} value={cat}>{cat.toUpperCase()}</option>)}
          </select>
          <select className="w-full px-5 py-3.5 bg-slate-50 border-2 border-transparent focus:border-blue-500/20 rounded-xl text-[10px] font-black text-slate-700 outline-none uppercase tracking-wider shadow-inner" value={filterStatus} onChange={(e) => setFilterStatus(e.target.value as any)}>
            <option value="ALL">ALL STATUSES</option>
            {Object.values(DeviceStatus).map(s => <option key={s} value={s}>{s.toUpperCase()}</option>)}
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <div className="px-8 py-5 border-b border-slate-50 flex items-center justify-between bg-white">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 px-3 py-1 rounded-lg text-white font-black text-xs shadow-md shadow-blue-500/20">
              {filteredDevices.length}
            </div>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Assets Identified</span>
          </div>
          {selectedIds.size > 0 && (
            <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">{selectedIds.size} Assets Selected</span>
          )}
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50/50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-6 text-center w-12">
                   <input type="checkbox" className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500" checked={filteredDevices.length > 0 && selectedIds.size === filteredDevices.length} onChange={() => {
                     if (selectedIds.size === filteredDevices.length) setSelectedIds(new Set());
                     else setSelectedIds(new Set(filteredDevices.map(d => d.id)));
                   }} />
                </th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Asset Information</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Unit</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Status</th>
                <th className="px-8 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 bg-white">
              {filteredDevices.map((device) => (
                <tr key={device.id} className={`transition-all group ${selectedIds.has(device.id) ? 'bg-blue-50/60' : 'hover:bg-blue-50/40'}`}>
                  <td className="px-6 py-6 text-center">
                    <input type="checkbox" className="w-4 h-4 rounded border-slate-300 text-blue-600 cursor-pointer" checked={selectedIds.has(device.id)} onChange={() => toggleSelection(device.id)} />
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <div className="flex items-center gap-4">
                      <div className="w-14 h-14 rounded-2xl bg-slate-50 border border-slate-100 overflow-hidden flex items-center justify-center relative shadow-sm">
                        {device.image ? <img src={device.image} className="w-full h-full object-cover" /> : <Box className="w-6 h-6 text-slate-300" />}
                        {device.isCNCAN && <div className="absolute top-0 right-0 p-0.5 bg-amber-500 rounded-bl-lg shadow-sm"><ShieldAlert className="w-2.5 h-2.5 text-white" /></div>}
                      </div>
                      <div className="min-w-0">
                        <div className="font-black text-slate-900 text-sm leading-tight truncate">{device.name || 'Unnamed Asset'}</div>
                        <div className="flex flex-wrap items-center gap-2 mt-1">
                          <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{device.manufacturer || 'Unknown Manufacturer'}</span>
                          <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                          <span className="text-[10px] text-blue-600 font-black uppercase tracking-tight flex items-center gap-1">
                            <Tag className="w-3 h-3" /> {device.model || 'N/A'}
                          </span>
                        </div>
                        <div className="flex items-center gap-1.5 mt-1">
                           <span className="flex items-center gap-1 text-[9px] font-black text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100 uppercase tracking-tighter">
                             <Layers className="w-2.5 h-2.5" /> {device.category || 'Altele'}
                           </span>
                           <span className="text-[9px] font-mono text-slate-400 font-bold tracking-tighter">SN: {device.serialNumber || 'N/A'}</span>
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-500 uppercase">{device.department || 'N/A'}</span>
                  </td>
                  <td className="px-8 py-6 cursor-pointer" onClick={() => onSelectDevice(device)}>
                    <StatusBadge status={device.status || DeviceStatus.ACTIVE} />
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-blue-600 hover:bg-blue-50 shadow-sm border border-slate-100 rounded-xl transition-all"
                        onClick={(e) => handleOpenQuickEdit(e, device)}
                        title="Quick Edit"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        className="p-3 bg-white text-slate-400 hover:text-red-600 hover:bg-red-50 shadow-sm border border-slate-100 rounded-xl transition-all"
                        onClick={(e) => handleDeleteClick(e, device.id)}
                        title="Purge Asset"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredDevices.length === 0 && (
                <tr>
                  <td colSpan={5} className="py-24 text-center">
                    <Box className="w-16 h-16 text-slate-100 mx-auto mb-4" />
                    <p className="text-slate-400 font-black uppercase tracking-widest text-xs mb-6">No matching assets found in the registry</p>
                    <button 
                      onClick={onAddDevice}
                      className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-blue-700 transition flex items-center gap-2 mx-auto active:scale-95"
                    >
                      <Plus className="w-4 h-4" /> Register New Asset
                    </button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const StatusBadge = ({ status }: { status: DeviceStatus }) => {
  let styles = "bg-slate-100 text-slate-700 border-slate-200";
  switch(status) {
    case DeviceStatus.ACTIVE: styles = "bg-green-100 text-green-700 border-green-200"; break;
    case DeviceStatus.MAINTENANCE: styles = "bg-amber-100 text-amber-700 border-amber-200"; break;
    case DeviceStatus.BROKEN: styles = "bg-red-100 text-red-700 border-red-200"; break;
    case DeviceStatus.RETIRED: styles = "bg-slate-200 text-slate-500 border-slate-300"; break;
  }
  return <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider border shadow-sm ${styles}`}>{status}</span>;
};

export default DeviceList;

import React, { useState, useMemo, useRef } from 'react';
import { MedicalDevice, DeviceStatus, TaskPriority, TaskStatus, MedicalTask, HOSPITAL_DEPARTMENTS, DEVICE_CATEGORIES, DeviceFile } from '../types';
import { 
  Activity, Box, QrCode, Trash2, X, Edit2, 
  Info, CheckSquare, Loader2, Check, ChevronDown, Clock, 
  ShieldAlert, Cpu, Wrench, CheckCircle2, Fingerprint, Save, Camera, RotateCcw, FileText, Upload, DownloadCloud, Eye, Building2, Tag, Layers
} from 'lucide-react';

interface DeviceDetailProps {
  device: MedicalDevice;
  tasks: MedicalTask[];
  allDevices?: MedicalDevice[]; // To get fleet-wide depts
  onUpdate: (updatedDevice: MedicalDevice) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  onAddTask: (task: MedicalTask) => void;
}

const DeviceDetail: React.FC<DeviceDetailProps> = ({ device, tasks, allDevices = [], onUpdate, onDelete, onBack, onAddTask }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'maintenance' | 'docs' | 'tasks' | 'qr'>('overview');
  const [isEditing, setIsEditing] = useState(false);
  const [isPurging, setIsPurging] = useState(false);
  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadType, setUploadType] = useState<'manual' | 'report'>('report');

  const [editForm, setEditForm] = useState({
    name: device.name,
    category: device.category,
    manufacturer: device.manufacturer,
    model: device.model,
    serialNumber: device.serialNumber,
    department: device.department,
    status: device.status,
    isCNCAN: !!device.isCNCAN,
    notes: device.notes || '',
    image: device.image || '',
    files: device.files || []
  });

  const allAvailableDepartments = useMemo(() => {
    const fleetDepts = allDevices.map(d => d.department);
    return Array.from(new Set([...HOSPITAL_DEPARTMENTS, ...fleetDepts, device.department])).sort();
  }, [allDevices, device.department]);

  const handleFinalPurge = async () => {
    setIsPurging(true);
    try {
      await onDelete(device.id);
    } catch (err) {
      console.error("Purge failure", err);
      setIsPurging(false);
      setShowPurgeConfirm(false);
    }
  };

  const handleSaveEdit = async () => {
    await onUpdate({ ...device, ...editForm });
    setIsEditing(false);
  };

  const handleEditChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as any;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : value;
    setEditForm(prev => ({ ...prev, [name]: val }));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = event.target?.result as string;
        const newFile: DeviceFile = {
          id: `FILE-${Date.now()}`,
          name: file.name,
          type: uploadType,
          url: base64,
          dateAdded: new Date().toISOString().split('T')[0]
        };

        const updatedFiles = [...(editForm.files || []), newFile];
        setEditForm(prev => ({ ...prev, files: updatedFiles }));

        // If not explicitly editing, save immediately
        if (!isEditing) {
           await onUpdate({ ...device, files: updatedFiles });
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error("File upload failed", err);
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleRemoveFile = async (fileId: string) => {
    const updatedFiles = editForm.files.filter(f => f.id !== fileId);
    setEditForm(prev => ({ ...prev, files: updatedFiles }));
    if (!isEditing) {
      await onUpdate({ ...device, files: updatedFiles });
    }
  };

  const viewFile = (file: DeviceFile) => {
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${file.url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden flex flex-col h-full relative animate-fade-in">
      {showPurgeConfirm && (
        <div className="fixed inset-0 z-[600] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] p-12 max-w-lg w-full text-center shadow-2xl border-4 border-red-100 animate-fade-in">
              <div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto mb-8">
                 <Trash2 className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tight mb-4">Confirm Atomic Purge</h3>
              <p className="text-sm text-slate-500 font-medium mb-10 leading-relaxed">
                 You are about to permanently remove <span className="font-black text-slate-900">{device.name}</span> and all associated service history.
              </p>
              <div className="flex gap-4">
                 <button disabled={isPurging} onClick={() => setShowPurgeConfirm(false)} className="flex-1 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition">Discard Request</button>
                 <button disabled={isPurging} onClick={handleFinalPurge} className="flex-[2] py-5 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-red-700 shadow-xl shadow-red-500/20 transition flex items-center justify-center gap-3">
                    {isPurging ? <Loader2 className="w-5 h-5 animate-spin" /> : <Trash2 className="w-5 h-5" />}
                    {isPurging ? "Purging..." : "Confirm Purge"}
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="p-8 border-b border-slate-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 bg-slate-50/50">
        <div>
          <button onClick={onBack} className="text-slate-400 hover:text-slate-900 text-[10px] font-black uppercase tracking-widest mb-4 flex items-center gap-2 transition group">
            <span className="group-hover:-translate-x-1 transition-transform">←</span> Inventory Index
          </button>
          <div className="flex flex-wrap items-center gap-4">
             <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase">{device.name}</h1>
             <span className="flex items-center gap-2 px-4 py-1.5 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-600/20">
               <Layers className="w-4 h-4" /> {device.category}
             </span>
          </div>
        </div>
        <div className="flex items-center gap-3 w-full lg:w-auto z-[100]">
           {isEditing ? (
             <>
               <button onClick={handleSaveEdit} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-green-600 text-white rounded-xl shadow-lg font-black text-xs uppercase tracking-widest active:scale-95 transition"><Save className="w-4 h-4" /> Save Data</button>
               <button onClick={() => setIsEditing(false)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-slate-200 text-slate-600 rounded-xl font-black text-xs uppercase tracking-widest active:scale-95 transition">Cancel</button>
             </>
           ) : (
             <>
               <button onClick={() => setIsEditing(true)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-indigo-600 text-white rounded-xl shadow-lg font-black text-xs uppercase tracking-widest active:scale-95 transition"><Edit2 className="w-4 h-4" /> Edit Asset</button>
               <button onClick={() => setShowPurgeConfirm(true)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 px-8 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-red-600 hover:text-white transition active:scale-95"><Trash2 className="w-4 h-4" /> Purge Asset</button>
             </>
           )}
        </div>
      </div>

      <div className="flex border-b border-slate-100 px-8 bg-white overflow-x-auto no-scrollbar shadow-sm z-10">
