                                {DEVICE_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                              </select>
                              <Layers className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 pointer-events-none" />
                           </div>
                        </div>
                        <div className="space-y-1">
                           <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Manufacturer</label>
                           <input name="manufacturer" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-indigo-300 transition-colors" value={editForm.manufacturer} onChange={handleEditChange} />
