                   </select>
                   <button 
                      onClick={() => fileInputRef.current?.click()}
                      disabled={isUploading}
                      className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 hover:bg-blue-700 transition shadow-lg shadow-blue-500/20 active:scale-95 disabled:opacity-50"
                   >
                      {isUploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
                      Register File
                   </button>
                   <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                </div>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {(editForm.files || []).length > 0 ? editForm.files.map(file => (
                  <div key={file.id} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-md transition-all group">
                     <div className="flex items-center gap-4">
                        <div className={`p-4 rounded-2xl ${file.type === 'manual' ? 'bg-indigo-50 text-indigo-600' : 'bg-green-50 text-green-600'}`}>
                           <FileText className="w-6 h-6" />
                        </div>
                        <div className="flex-1 min-w-0">
                           <div className="flex items-center gap-2 mb-1">
                              <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest border ${file.type === 'manual' ? 'bg-indigo-50 border-indigo-100 text-indigo-700' : 'bg-green-50 border-green-100 text-green-700'}`}>
                                 {file.type}
                              </span>
                              <span className="text-[9px] font-bold text-slate-400">{file.dateAdded}</span>
                           </div>
                           <h4 className="text-sm font-black text-slate-900 truncate pr-4">{file.name}</h4>
                        </div>
                        <div className="flex items-center gap-1">
                           <button onClick={() => viewFile(file)} className="p-2 text-slate-400 hover:text-blue-600 transition" title="View"><Eye className="w-4 h-4" /></button>
                           <button onClick={() => handleRemoveFile(file.id)} className="p-2 text-slate-400 hover:text-red-600 transition" title="Delete"><Trash2 className="w-4 h-4" /></button>
                        </div>
                     </div>
                  </div>
                )) : (
                  <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border-4 border-dashed border-slate-100 flex flex-col items-center">
                     <FileText className="w-16 h-16 text-slate-100 mb-4" />
                     <p className="text-slate-400 font-black uppercase tracking-widest text-xs">No registered documents</p>
                  </div>
                )}
             </div>
          </div>
        )}

        {(activeTab === 'maintenance' || activeTab === 'qr' || activeTab === 'tasks') && (
          <div className="py-20 text-center animate-fade-in bg-white rounded-[3rem] shadow-sm border border-slate-100">
             <div className="p-8 bg-slate-50 w-fit rounded-full mx-auto mb-6">
                <Box className="w-12 h-12 text-slate-200" />
             </div>
             <p className="text-xs font-black uppercase tracking-widest text-slate-400">Clinical Data Stream Pending</p>
          </div>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex items-center gap-3 px-8 py-6 text-[10px] font-black uppercase tracking-widest border-b-4 transition-all whitespace-nowrap ${active ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
    {icon} {label}
  </button>
);

const InfoRow = ({ label, value, badge }: any) => (
  <div className="flex flex-col gap-2 py-4 border-b border-slate-50 last:border-0">
    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    {badge ? (
      <span className="text-xs font-mono font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg w-fit border border-indigo-100">{value}</span>
    ) : (
      <span className="text-sm font-bold text-slate-900 leading-none">{value}</span>
    )}
  </div>
);

export default DeviceDetail;
